HNW.a("sam",{"id":"sam","title":"SAMUEL Keynotes, Arzneimittellehre","short":"Samuel Keynotes","sub":"Leit- und Schlüsselsymptome von über 350 Arzneien","cap":"Samuel Keynotes (Megens, Rutten; dt. Kauf)"},[{"label":"Vorwort und Abkürzungen","short":"Vorwort und Abkürzungen","group":"Einleitung","paras":[{"t":"SAMUEL"},{"t":"Vorwort"},{"t":"Hergestellt für die \"Cooperative Computerassociation SAMUEL\" von"},{"t":"Gerard Megens, M.D. und Lex Rutten, M.D. , Copyright 1988."},{"t":"Ins Deutsche übersetzt und erweitert von Dr. Christian Kauf, Starnberg."},{"t":"Die deutschen \"Samuel-Keynotes\" enthalten die wichtigsten Essenzen, Leit- und Schlüsselsymptome von über 350 homöopathischen Arzneien."},{"t":"Beim Einsatz während der Konsultation mit dem Patienten haben Sie schnellen Zugriff zu Punkten, die Ihre Arzneiwahl bestätigen kann."},{"t":"Dies ist kein Ersatz für eine komplette Materia Medica oder ein Repertorium und erhebt keinerlei Anspruch auf Vollständigkeit."},{"t":"Abkürzungen:"},{"t":"Sz - Schmerz Agg.: - Verschlechterung"},{"t":"Szen - Schmerzen Amel.: - Besserung"},{"t":"KSz - Kopfschmerz HM - Hauptmittel"},{"t":"AP - Angina pectoris WL - Wasserlassen"}],"m":1,"orig":"Vorwort und Abkürzungen"},{"label":"Abies canadensis","short":"Abies canadensis","group":"Arzneimittellehre","paras":[{"t":"Abies canadensis, Schierlingstanne. Nervöse Schwäche und Schwächegefühl; möchte sich ständig hinlegen. Ißt weit über seine Verdauungskapazität hinaus. Als ob nasses Handtuch auf dem Magen liegt."},{"t":"Roemheld-Syndrom.: Auftreibung von Magen und Abdomen mit Herzklopfen. Überproduktion von Verdauungssäften. Duodenalulzera, Gastritis, Hypoglykämie. Nagendes Schwächegefühl im Epigastrium."},{"t":"Gebärmutterverlagerung (Sep.). Als ob Gebärmutter weich wäre. Rechte Lunge und Leber fühlen sich klein und hart an. Gefühl von kaltem Wasser zwischen den Schultern."},{"t":"Verlangen: Pickles; Rettich; Artischocken; deftige Speisen; Fleisch."}],"rem":1,"orig":"Abies canadensis"},{"label":"Abies nigra","short":"Abies nigra","group":"Arzneimittellehre","paras":[{"t":"Abies nigra, Schwarzfichte. Gefühl eines Klumpens, wie hartgekochtes Ei, in der der Magengrube oder in der Lunge, den der Patient aushusten möchte. Tachy- oder Bradykardie."},{"t":"Benommenheit tagsüber, nachts hellwach. Unfähig zu denken oder zu lernen."},{"t":"Dyspepsie alter Menschen mit funktionellen Herzerkrankungen."},{"t":"Verdauungsschwäche durch Mißbrauch von Tee und Tabak. Appetitlosigkeit morgens, aber Hunger am Mittag oder nachts. Magenschmerz nach dem Essen. Verstopfung."},{"t":"Dyspnoe, Agg.: hinlegen. Als ob Lunge sich nicht richtig ausdehnen kann; wie zusammengedrückt."}],"rem":1,"orig":"Abies nigra"},{"label":"Abrotanum","short":"Abrotanum","group":"Arzneimittellehre","paras":[{"t":"Abrotanum, Eberraute. Abmagerung der unteren Extremitäten. Metastasierung, abwechselnd Hämorrhoiden/Rheumatismus. TBC in Anamnese."},{"t":"Gefühl, als ob der Magen in Wasser schwimmt oder hängt. Auftreibung des Abdomens. Nabelabsonderungen bei Neugeborenen. Lymphadenitis mesenterialis. Schmerz in Handgelenk, Sprunggelenk."},{"t":"Verlangen: Brot, in Milch gekocht."},{"t":"Agg.: Kälte; unterdrückte Absonderungen."},{"t":"Amel.: Bewegung; Durchfall."},{"t":"Erscheinung: Hippokratisches Gesicht bei Babies, die trotz guten Appetits nicht wachsen."},{"t":"Hämangiom, Naevus flammeus."}],"rem":1,"orig":"Abrotanum"},{"label":"Absinthium","short":"Absinthium","group":"Arzneimittellehre","paras":[{"t":"Artemisia absinthium, Wermut. ZNS-Wirkung, sehr dynamisches Mittel. Schwäche des ZNS. Schwindel mit Gefühl, nach hinten zu fallen, Agg.: Aufstehen. Dumpfer Hinterkopfschmerz. Epileptischer Schwindel, Petit Mal-Absence."},{"t":"Konvulsionen, vorher nervöses Zittern einzelner Körperteile (Hände, Lippen, Zunge, Arrhythmien)."},{"t":"Beginn mit spastischem Gesichtszucken, dann Rumpf und Extremitäten, erst steif, dann Kloni.@ Grand Mal-Anfall. Danach retrograde Amnesie mit dummem Gesichtsausdruck."},{"t":"Delirium mit Ruhelosigkeit, muß ständig umhergehen; erschreckende Visionen. Delirium tremens der Alkoholiker; bestimmte Pilzvergiftungen."},{"t":"Halluzinationen. Stimmenhören."},{"t":"Plötzliche Bewußtlosigkeit. Danach extrem erregt, brutal, geistige Betäubung, abwechselnd mit gefährlicher Gewalttätigkeit. Nervöse Erregung und Schlaflosigkeit bei Kindern (Tarent.)."},{"t":"Mental/emotional: abweisend, mit Sehnsucht nach Frieden und Trost. Weinerliche Stimmung oder empfindungsunfähig. Imbezillität, undeutliche Sprache, dicke Zunge."},{"t":"Kleptomanie. Verfolgungswahn. Angst, ermordet zu werden."}],"rem":1,"orig":"Absinthium"},{"label":"Aceticum acidum","short":"Aceticum acidum","group":"Arzneimittellehre","paras":[{"t":"Essigsäure. Voranschreitende Schwächung, Kraftlosigkeit, Erschöpfung und Verfall, präfinal.@ Gewichtsverlust, Anämie, Abmagerung; Nachtschweiße, brennender Durst, übermäßige Blässe. Kurzer, trockener, chronischer Husten, chronische Diarrhoe, Erbrechen, Ödeme, Aszites."},{"t":"Kollaps, Schock, postoperativer, nach Wurstvergiftung."},{"t":"Alle auszehrenden Krankheiten (Magenkrebs, Leukämie, Hirntumor, Aids)."},{"t":"Verlust von Körperflüssigkeiten: Blutung aus jeder Körperöffnung: Nase, Lunge, Magen, Därme und Uterus; Erbrechen nach jeder Art Nahrung; Speichelfluß, Tag und Nacht; heftiger Brennschmerz im Magen und Brustkorb, danach Kälte der Haut und kalter Schweiß auf der Stirn. Gefühl im Magen, als ob der Patient eine große Menge Essig zu sich genommen hätte."},{"t":"Große Mengen blassen Urins; schwächende nächtliche Pollutionen, auch beim Stuhlgang, reichliche (Nacht-)Schweiße. Daher unstillbarer Durst, trinkt große Mengen. Durstlosigkeit bei Fieber, kalte Getränke liegen bei Fieber wie Gewicht im Magen."},{"t":"Kondylome, Warzen, Naevi. Hautfarbe wächserne Blässe, wie Alabaster."},{"t":"Kinder (z. B. Darmentzündung): kümmerlich, appetitlos, blaß, reizbar, mögen es nicht, wenn Kopf berührt wird, beklagen sich, wollen getragen werden; starke Abmagerung, chronische Diarrhoe."},{"t":"Amel.: Liegen auf dem Bauch bessert viele Beschwerden (Ars. auf Rücken)."},{"t":"Gemütssymptome, nachdem körperlich erkrankt. Krebsangst, wird mit Krankheit nicht fertig, mürrisch sich beklagend, besorgt. Jede emotionale Erregung bringt sie aus der Fassung, nervös, reizbar. Angstanfälle, daß er kaum noch atmen kann. Deprimiert, Kopf dumpf und schwer, Verwirrung, erkennt eigene Kinder nicht. Stupor, zwischendurch delirant, springt brüllend vor Schmerz aus dem Bett und wälzt sich auf dem Boden. Aufgetriebenes Abdomen, hartnäckige Obstipation."}],"rem":1,"orig":"Aceticum acidum"},{"label":"Acetanilidum","short":"Acetanilidum","group":"Arzneimittellehre","paras":[{"t":"Acetanilidum, Antifebrinum, Allopathikum aus Essigsäure und Anilin mit Aspirinwirkung, toxisch bei Überdosierung."},{"t":"Zyanose und Kollaps. Anämie. Erschöpfung. Hypotonie. Schwacher Puls, leicht abdrückbar. Hypothermie."},{"t":"Fortschreitende Anämie: Atembeklemmungen, Schwindel, Schwäche, Müdigkeit, Angina pectoris mit Gefühl, als stehe Tod bevor; Fuß-/Knöchelödem."},{"t":"Akutes Nierenversagen, Hämaturie, Urin bräunlich, Albuminurie, interstitielle Nephritis. Erweiterte Pupillen. Schlaflosigkeit, Appetitmangel, Ikterus."}],"rem":1,"orig":"Acetanilidum"},{"label":"Aconitum napellus","short":"Aconitum napellus","group":"Arzneimittellehre","paras":[{"t":"Sturmhut, Eisenhut. Emotional ausdrucksstark, extrovertiert, mitfühlend, sensitiv (bis hellsichtig), Abneigung Trost; Beschwerden durch schlechte Nachrichten."},{"t":"Folge von eisiger Kälte (schockartig); von Schreck / Schock: Todesangst (Uhrzeit [Arg-n.; Agn.]), Hitzewallungen, Herzklopfen, Arrhythmien, Taubheit einzelner Körperteile, Dyspnoe, Hyperventilation, Schwindel. Überempfindlich auf Geräusch / Berührung / Schmerz. Reizbarkeit."},{"t":"Klaustrophobie (Aufzug, Tunnel), Agoraphobie."},{"t":"Furcht: Unfälle, Dunkelheit, Erdbeben, Menschenmengen, Flugzeuge, Herzerkrankungen, Apoplexie, hochgelegene Orte, aus dem Haus zu gehen, die Straße zu überqueren. Stärkste nervöse, ängstliche Ruhelosigkeit, wirft sich gepeinigt herum. Furcht, 15 Min. nach dem Einschlafen zu ersticken. Beim Erwachen Lähmung einzelner Glieder, die Decke fällt herunter. Einseitige Taubheit (Gesicht, Lippen, Hände). Einseitige Röte im Gesicht (Cham.)."},{"t":"Plötzliches hohes Fieber mit Ruhelosigkeit, Todesfurcht, trockener, heißer Haut, großer Durst; oder: hohes Fieber mit Gleichgültigkeit, Erschöpfung, Schläfrigkeit, Durstlosigkeit und benommenem Gesichtsausdruck."},{"t":"\"Kochendes Gefühl im Kopf\", dabei Glieder kalt."},{"t":"Hellrote Ohren bei Grippe. Todesangst bei einfacher Grippe. Gesichtsneuralgien. Krupp-Husten beim Ausatmen (Einatmen: Spong.). Plötzliche Pneumonie mit Hämoptyse hellroten Blutes."},{"t":"Gebärende mit großer Angst, während der Wehen zu sterben. Harnretention der Mutter nach Geburt, beim Neugeborenen wegen Geburtstrauma oder Kälte. Amenorrhoe nach Schreck."},{"t":"Alles schmeckt bitter, außer Wasser."},{"t":"Kind: Konvulsionen nach nervlichen Schocks, bei Zahnung."},{"t":"Agg.: Trockenheit; Kälte (oder Überhitzung); Dämmerung; 0-4 Uhr;"},{"t":"Musik; Liegen auf erkrankter Seite; beim Erheben vom Bett."},{"t":"Verlangen: Fleisch; große Mengen (kalte) Getränke."},{"t":"Komplementär: Coff. bei Schlaflosigkeit im Fieber, Intoleranz gegen Schmerz;"},{"t":"Arnica bei Verletzungen;"},{"t":"Sulfur ist \"chronisches Acon.\"."}],"rem":1,"orig":"Aconitum napellus"},{"label":"Actaea spicata","short":"Actaea spicata","group":"Arzneimittellehre","paras":[{"t":"Actea spicata, Christophskraut. Rheumatismus der Handgelenke, Knöchel, der kleinen Hand- und Fußknochen, der Finger/Zehen. Reißende Schmerzen, plötzliche enorme Schwellungen von geringen Anstrengungen; Gichtarthritis; druckempfindlich. Schwäche der Hände, (rechts) Arm. Finger entfärbt, kalt, taub."},{"t":"Kombination Rheuma-Magenbeschwerden. Kapriziöser Magen."},{"t":"Gegenstände erscheinen blau. Brustbeklemmung; Dyspnoe durch kalte Luft."},{"t":"(Häufiger bei Männern, Actaea racemosa ist Cimicifuga, mehr Frauen)"}],"rem":1,"orig":"Actaea spicata"},{"label":"Adonis vernalis","short":"Adonis vernalis","group":"Arzneimittellehre","paras":[{"t":"Adonis, Frühlingsteufelsauge. Herz: Peri-/Myo-/Endokarditis; Herzinsuffizienz mit beginnender Dekompensation; Aortitis; Herzasthma. Herzkrankheiten nach rheumatischer Erkrankung, Influenza oder nach Nierenerkrankung (Brightsche Nephritis). Herz vergrößert, Perikarderguß, Arrhythmie, schwacher, schneller Puls. Präkordialschmerz. Beklemmung, Dyspnoe zwingt zu langen tiefen Atemzügen."},{"t":"Nierenfunktion beeinträchtigt, Albuminurie. Ödeme. Hydrothorax, Aszites. Schwindel, Agg.: Umdrehen im Bett, Aufstehen aus dem Bett."},{"t":"Kopfschmerz vom Hinterkopf, über die Schläfen, zu den Augen."},{"t":"AZ besorgniserregend, große Schwäche, morgens erschöpft mit geschwollenen Extremitäten. Ängstlich und ruhelos. Fühlt sich besser nach Belastung."},{"t":"Schlaflos oder schreckliche Träume."},{"t":"Wirkt diuretisch und hat sedativen Effekt."},{"t":"Agg.: Ruhe, Liegen."},{"t":"Amel.: Spazierengehen an der frischen Luft."}],"rem":1,"orig":"Adonis vernalis"},{"label":"Adrenalinum","short":"Adrenalinum","group":"Arzneimittellehre","paras":[{"t":"Maligne Hypertonie. Plethorisch. Blutunterlaufene Skleren. Bräunlich-rotes Gesicht. Arteriosklerose junger Menschen. Lebhaft. Morbus Addison."},{"t":"Angina pectoris; Engegefühl in der Brust mit qualvollem Schmerz, Schwindel und Übelkeit/Erbrechen."},{"t":"Puls schnell/unregelmäßig. Blutungen überall möglich, mit Hypertonie."},{"t":"Hyperämie der Lungen. Heuschnupfen mit Urtikaria (und Hypertonie)."},{"t":"Zusammenschnürender Schmerz in den Därmen."},{"t":"Folge von konstantem Streß; hält zurück, keine Ausbrüche."}],"rem":1,"orig":"Adrenalinum"},{"label":"Aesculus hippocastanum","short":"Aesculus hippocastanum","group":"Arzneimittellehre","paras":[{"t":"Aesculus hippocastanum, Roßkastanie. Schmerzhafte Hämorrhoiden, prallgefüllt, purpurfarben, mit Rückenschmerz. Qualvoller Schmerz in Lumbal- / Iliosakralregion. Venöse Stauung und Trägheit, voller \"hämorrhoidaler\" Venen. Augen schwer und heiß, tränend mit erweiterten Gefäßen."},{"t":"Ösophagusvarizen bei Leberzirrhose, Pfortaderstauung."},{"t":"Alte Männer, die zu gut leben, beleibt, mit kurzem Nacken. Unglücklich und verdrießlich, schwer mit ihnen auszukommen."},{"t":"Heiße Augen mit vergrößerten Blutgefäßen. Eingeatmete Luft fühlt sich in der Nase kalt an. Empfindung von Nadeln, kleinen Stöckchen im Rektum."},{"t":"Brennen des Anus mit Frostschauern den Rücken hinauf und hinunter. Schmerz hinter dem Schambeinhügel. Husten bei Leberkrankheiten. Rheumatismus des Sakroiliakalgelenks. Arthritis, Morbus Bechterew, Agg.: Aufstehen vom Sitzen oder Bücken."},{"t":"Völlegefühl in verschiedenen Körperteilen."},{"t":"Ösophagusvarizen bei Leberzirrhose, Pfortaderstauung."},{"t":"Agg.: im und nach Schlaf; Liegen; warmer, stickiger Raum."},{"t":"Amel.: Bluten der Hämorrhoiden; fortgesetzte Anstrengung, körperlich und geistig; Kälte, frische Luft; Baden."}],"rem":1,"orig":"Aesculus hippocastanum"},{"label":"Aethusa cynapium","short":"Aethusa cynapium","group":"Arzneimittellehre","paras":[{"t":"Aethusa cynapium, Hundspetersilie. Einzelgänger. Starke Gefühle können nicht ausgedrückt werden, kann nicht schreien/schimpfen/weinen."},{"t":"Nach (relativ geringer) Enttäuschung desillusioniert, verschließt sich zunehmend, \"fühle mich anders als die anderen\", emotionale Entwicklung stehengeblieben. Extreme Tierliebe/Furcht, Sprechen mit Tieren. Wahnvorstellungen von Tieren (sieht Mäuse durchs Zimmer laufen). Schlafwandeln. Selbstgespräche."},{"t":"Unfähig zu denken, sich zu konzentrieren; dadurch Prüfungsangst."},{"t":"Beim Augenschließen: Furcht, nicht wieder zu erwachen; vor Narkose. Gefühl der Erstickung. Beschwerden durch Ärger/Zorn."},{"t":"Schwindel mit Benommenheit und Herzklopfen. Danach heißer Kopf."},{"t":"Prämenstruelles Syndrom: Gesteigerte Reizbarkeit und Kopfschmerz 2 Tage vor und an den ersten 2 Tagen während Menses; Entspannung gegen Ende der Menses, dann gesteigertes sexuelles Verlangen, das vor den Menses völlig verschwindet. Fluor albus macht gelbe Flecken. Müde nach Erbrechen oder Stuhlgang. Erwacht häufig mit Atemnot, möchte Türen und Fenster öffnen. Speichelfluß im Schlaf."},{"t":"Haar fühlt sich wie gezogen an. Lymphknotenschwellungen."},{"t":"Ausschlag an Gelenken. Handflächen gerötet. Ausschlag auf der Nasenspitze. Blässe der Oberlippe."},{"t":"Völlig durstlos im Fieber, möchte zugedeckt sein. Körper kaltschweißig."},{"t":"Epileptische Spasmen mit eingeschlagenen Daumen, rotem Gesicht und nach unten gedrehten Augen, Pupillen starr und geweitet, Schaum vor dem Mund."},{"t":"Babies mit lebensbedrohlichem Brechdurchfall."},{"t":"Erbrechen geronnener Milch (Sil.) 1 Std. nach der Mahlzeit. Unverträglichkeit von Milch. Cholera. Durchfall (grünlich) mit Meningismus bei Zahnung; Verdauungsstörungen bei Zahnung bei heißem Sommerwetter."},{"t":"Verlangen: Käse; Salz; Wein; Stärkehaltiges (Nudeln)."},{"t":"Abneigung: Milch; Obst; Fett."},{"t":"Amel.: Umhergehen in frischer Luft."},{"t":"Agg.: nach Essen, Trinken; nach Erbrechen; nach Stuhl; nach Krampfanfall; Sommerhitze; Milch."}],"rem":1,"orig":"Aethusa cynapium"},{"label":"Agaricus muscarius","short":"Agaricus muscarius","group":"Arzneimittellehre","paras":[{"t":"Agaricus muscarius, Fliegenpilz. Macht einen verrückt mit seiner Ängstlichkeit. Findet immer etwas zum Erleiden, ewiges Opfer. Ängstlich, schutzbedürftig (Bar-c.), abhängig, unsicher. Krebsangst, magisch angezogen von Krebskranken, will Todkranken beistehen; meint, daß Gott ihn dafür vor Krebs bewahrt; abergläubisch. Tod, Särge, Leichen, Tragödien. Spricht in Versen. Zittern, glaubt, vernichtet zu werden, daß der Tod bevorsteht. Nervös, ruhelos. Abwechselnd Niedergeschlagenheit und Erregung. Alberne Heiterkeit. Geschwätzigkeit. Stottern. Verrückte Furchtlosigkeit bei objektiver Gefahr. Ekstase, Hexerei. Geringe Willenskraft. Ungeschickt, läßt Dinge fallen. Diagonal."},{"t":"Gefühl kalter Stellen auf dem Kopf, auf Nasenspitze."},{"t":"Ohrjucken bei Heuschnupfen."},{"t":"Heiße Flatus. Urin fühlt sich kalt an beim Wasserlassen. Nachuntendrängende Schmerzen. Husten endet in Niesen. Lumbago, Ischias mit Ängstlichkeit, Agg.: Sitzen und Amel.: Liegen. Wirbelsäule berührungsempfindlich."},{"t":"Erfrierungen, Frostbeulen. Brennen, Jucken, Röte, Schwellung der Haut."},{"t":"Stechen wie Eisnadeln. Metastasierung von der Haut zum ZNS."},{"t":"Abwechselnd körperliche / emotionale Beschwerden (Hauptmittel: Plat.)."},{"t":"Hysterie/Ohnmacht nach Sex. Zuckungen überall möglich (Augenlider, Gesichtsmuskeln). Kombination Zuckungen und Angst um Gesundheit."},{"t":"Zuckungen vor Gewitter. Nach Koitus Spasmen und Konvulsionen."},{"t":"Kinder: plump, unbeholfen, schüchtern. Spätes Sprechen- und Laufenlernen, Stottern. Entwicklung verlangsamt. Chorea nach Tadel, Amel.: im Schlaf."},{"t":"Bei Meningitis Kopfrollen, Versuch, sich selbst zu verletzen. Sieht beim Lesen Fliegen in Augen. Hysterische Mädchen vor Menarche; viele Ideen schwirren im Kopf, kann keine Sätze bilden, dumm, verwirrt."},{"t":"Verlangen: Eier; Salz."},{"t":"Amel.: abends; Schlaf; langsame Bewegung."},{"t":"Agg.: nach Koitus; nahender Sturm/Gewitter (Phos.; Psor.); geistige Beschäftigung; kalte Luft."}],"rem":1,"orig":"Agaricus muscarius"},{"label":"Agnus castus","short":"Agnus castus","group":"Arzneimittellehre","paras":[{"t":"Agnus castus, Mönchspfeffer-Keuschlamm. Aids. Zusammenbruch nach Ausschweifungen, Alkohol- und Drogenmißbrauch, sexuelle Exzesse, Schlafmangel, unregelm. Ernährung. Leicht erregbar; viele Abenteuer in kurzer Zeit."},{"t":"Anämisch; blaß; energielos; zerstreut. Kann sich beim Lesen nicht konzentrieren. Geistesabwesend, fühlt sich geistig und körperlich alt. Verfall erzeugt Angst, Schwermut, Hoffnungslosigkeit. Angst um Gesundheit, meint sie ruiniert zu haben. Vorahnung frühen Todes (gibt Todesstunde an). Inn. Zittern wie inn. Frost. Exzessive Masturbation als einziges Ventil. Selbstverachtung. Fühlt sich wertlos, nutzlos."},{"t":"Oder: hält sich für besonders (wohlhabend, wichtig...)."},{"t":"Manisch-depressiv. Hypochondrische Angst."},{"t":"Geist wird dumpf, schwach; vergeßlich. Glaubt sich kurz vor Nervenzusammenbruch. Verlust des Sexualtriebes, aber vorher exzessive Libido. Ejaculatio praecox. Ejakulation bei Umarmung, erektionslose Spermatorrhoe. Alter Mann, von junger Frau angezogen, aber impotent. Impotenz trotz geiler Gedanken. Impotenz nach unterdrückter GO oder bei chronischer Urethritis."},{"t":"Nach wiederholten Geschlechtskrankheiten."},{"t":"Kalte, erschlaffte Genitalien; sieht nach, ob Hose offen steht."},{"t":"Leicht verdorbener Magen mit Übelkeit. Erschlaffung, Nachuntendrängen innerer Organe, Prolapsneigung. Schwäche im Bauch. Obstipation, Stuhl gleitet zurück (Sil.)."},{"t":"Stillende Mütter, wenn Milchproduktion versiegt oder Milch nicht einschießt. Pupillen erweitert. Eingebildete Gerüche. Folgen von Verstauchungen; Zerrung und Verspannungen vom Überheben."}],"rem":1,"orig":"Agnus castus"},{"label":"Agraphis nutans","short":"Agraphis nutans","group":"Arzneimittellehre","paras":[{"t":"Agraphis nutans, Sternhyazinthe. Erkältungsneigung im kalten Wind. Katarrhe. Neigung zu reichlicher Absonderung von den Schleimhäuten."},{"t":"Ohr- und Rachenprobleme mit viel Absonderung. Verstopfte Nase."},{"t":"Vergrößerte Tonsillen und Adenoide mit Taubheit."},{"t":"Stummheit seit der Kindheit, nicht durch Taubheit bedingt."},{"t":"Schleimige Diarrhoe durch Kälte."}],"rem":1,"orig":"Agraphis nutans"},{"label":"Ailanthus glandulosa","short":"Ailanthus glandulosa","group":"Arzneimittellehre","paras":[{"t":"Ailanthus glandulosa, Götterbaum. Niedriges Fieber mit Sepsis und purpurfarbener Haut. Gesicht dunkelrot, heiß, wie Mahagoni oder purpurfarben. Bläulich-rote Flecken. Scharlach. Morbus Pfeiffer. Große Schwäche. Stupor und Malignität."},{"t":"Bösartig verlaufende Infektionskrankheiten: Scharlach, Diphtherie, Meningitis, follikuläre Angina, Typhus, infektiöse Mononukleose, Kindbettfieber. Bei partiell unterdrückten Exanthemen."},{"t":"Plötzlicher und ernsthafter Verfall der Lebenskräfte."},{"t":"Rasche zerebrale Intoxikation mit Stupor, murmelndem Delirium und Gleichgültigkeit (Bapt.). Vergißt alles, was vor der Krankheit gewesen ist, schließlich Bewußtlosigkeit. Gedächtnisverfall, Alzheimer."},{"t":"Zunge trocken und braun. Schwellungen von Hals und Rachen. Schluckschmerz, zu den Ohren ausstrahlend. Dyspnoe von verstopfter Nase."},{"t":"Stinkende Absonderungen und Atem."},{"t":"Dunkle Ausschläge verschwinden auf Druck und kehren allmählich zurück; jährliches Wiederauftreten."}],"rem":1,"orig":"Ailanthus glandulosa"},{"label":"Aletris farinosa","short":"Aletris farinosa","group":"Arzneimittellehre","paras":[{"t":"Aletris farinosa, Sternwurzel. Schwache, müde Frauen mit Anämie, Uterusprolaps, Leukorrhoe, schlimmer Verstopfung (Alum.);"},{"t":"Symptome von Reflexio@ uteri. Schweregefühl. Möchte immerzu liegen, ständige Müdigkeit. Ohnmacht. Schwangerschaftserbrechen mit Völlegefühl im Rektum."},{"t":"Kolik, Amel.: Flatulenz, Diarrhoe, Rückwärtsbeugen."},{"t":"Habitueller Abort."},{"t":"Menses reichlich, zu früh, schwarz, klumpig; mit wehenartigen Schmerzen;"},{"t":"vor Menopause. Uterusblutungen nachts, morgens völlig erschöpft, so daß sie kaum sprechen kann. Kreuzschmerz bei Leukorrhoe."},{"t":"Beschwerden durch Blut- und Flüssigkeitsverlust."},{"t":"Kombination Genitalien und Magen: appetitlos bei Zyklusstörungen. Ekel vor Speisen. Schaumiger Speichelfluß, schaumiges Aufstoßen."},{"t":"Trockener, harter Husten vor den Menses, Amel.: mit Eintreten der Menses."}],"rem":1,"orig":"Aletris farinosa"},{"label":"Allium cepa","short":"Allium cepa","group":"Arzneimittellehre","paras":[{"t":"Allium cepa, Küchenzwiebel. Benommenheit des Kopfes, schwierige Konzentration und große Schläfrigkeit mit Gleichgültigkeit."},{"t":"Schnupfen mit starkem mildem Tränenfluß und scharfem, brennendem Nasensekret. Heuschnupfen im Hochsommer mit Niesanfällen. Erkältungen."},{"t":"Stirnkopfschmerz bei Schnupfen, breitet sich aus: Schläfen, Augen, Gesicht. Schnupfen greift auf Kehlkopf und Bronchien über. Laryngitis mit Heiserkeit, Schneiden/Reißen im Kehlkopf, als ob Husten Kehlkopf zerreißt. Nasenpolypen aufgrund nasaler Allergie; allergisches Asthma."},{"t":"Kinder bei Keuchhusten mit Kehlkopfschmerz; zugleich verdorbener Magen mit Erbrechen und viel Flatulenz."},{"t":"Neuralgischer Schmerz wie ein Faden. Unerträglicher Phantomschmerz, traumatische, meist chronische Neuritis. Fazialisparese links."},{"t":"Plötzliche Geisteskrankheit: erkennt niemanden, gleichgültig."},{"t":"Geht auf Zehenspitzen oder Seitenkanten."},{"t":"Agg.: nachts; warmes Zimmer; August; Frühjahr; feuchtkaltes Wetter."},{"t":"Amel.: im kalten Zimmer und im Freien."},{"t":"Verlangen: extrem nach Zwiebeln, roh, in Olivenöl."},{"t":"Abneigung: Gurken (Übelkeit von Gurken)."}],"rem":1,"orig":"Allium cepa"},{"label":"Allium sativum","short":"Allium sativum","group":"Arzneimittellehre","paras":[{"t":"Allium sativum, Knoblauch. Arteriosklerose, Hypertonie, Hypercholesterinämie, Diabetes mellitus, Magen/Darmstörungen vom \"Guten Leben\" mit viel Fleischkonsum."},{"t":"Magenbrennen, Agg.: Druck; drückender Schmerz wie von einem Stein. Sodbrennen mit reichlich süßlichem Speichelfluß nach den Mahlzeiten und nachts."},{"t":"Kolitis. Flatulenz; Meteorismus; Blähungskolik. Verstopfung mit dumpfem Dauerschmerz. Stuhl wässerig, heiß. Analprolaps. Zunge blaß, rote Papillen."},{"t":"Stockschnupfen, drückender Schmerz über der Nasenwurzel, Sinusitis frontalis. Rachenverschleimung, Heiserkeit. Chronische Bronchitis mit Dyspnoe, extremer Auswurf am Morgen. Stinkender Atem beim Husten. Lungentuberkulose. Bluthusten."},{"t":"Schwere des Kopfes."},{"t":"Verklebte Lider, brennender Tränenfluß durch Überanstrengung der Augen. Blase druckempfindlich; Harndrang für wenige Tropfen. Blasensteine."},{"t":"Pruritus vulvae, hellrote Flecken. Mammae empfindlich, geschwollen."},{"t":"Hüftschmerz rheumatisch, in Ileopsoassehne, beim Versuch, Beine übereinanderzuschlagen, beim Umdrehen im Bett."},{"t":"Aloe socotrina"},{"t":"socotrina. Durchfall, aus dem Bett treibend; sofort nach dem Essen, Trinken, mit Flatulenz. Kann seinem Schließmuskel nicht trauen. Unzufriedenheit durch Verstopfung. Unzufrieden mit sich selbst. Haßt die Menschen, stößt jeden zurück. Möchte niemanden in der Nähe haben, wenn er krank ist."},{"t":"Viel Lebenswärme, Agg.: Wärme, Amel.: Kälte und kalte Anwendungen (Sulph.). Stirnkopfschmerz mit Schwere in Augen, muß sie schließen. Schmerz in Augenhöhlen. Gelbsehen. Röte der Augen. Kopfschmerz, Amel.: Eiskalte Umschläge (Hauptmittel)."},{"t":"Abwechselnd Kopfschmerz und Hämorrhoiden. Lumbago abwechselnd mit Kopfschmerz und Hämorrhoidalbeschwerden."},{"t":"Hämorrhoiden purpur, wie rote Weintrauben, Amel.: Baden in eiskaltem Wasser. Rote Lippen. Unfreiwillger Stuhl bei Flatus, \"falsche Freunde\", durch Schließmuskelschwäche. Geleeartiger Stuhl. Durchfall von Bier. Heiße Flatus. Schmerz im Abdomen, Amel.: nach Stuhlgang. Gefühl eines Pfropfens zwischen Symphyse und Steißbein, mit Stuhldrang. Meteorismus, Agg.: nach dem Essen. Amel.: Stimmung besser abends; (Eis-)kalte Anwendungen."},{"t":"Agg.: nach dem Essen; Bier; Sommer, heiße Tage mit kühlen Abenden."},{"t":"Abneigung: Fleisch."},{"t":"Verlangen: Saftiges; Obst, vor allem Äpfel."}],"rem":1,"orig":"Allium sativum"},{"label":"Alumina silicata","short":"Alumina silicata","group":"Arzneimittellehre","paras":[{"t":"Langsam fortschreitende Paralyse, zunehmende Schwere. Ziehen und Brennen in der Wirbelsäule. Treppensteigen wird unmöglich. Chronische ZNS-Leiden: Epilepsie; Multiple Sklerose; lokomotorische Ataxie. Neuritis. Zittern und Zucken. Paralyse der unteren Körperhälfte, paralytische Blasenschwäche."},{"t":"Chronischer, hartnäckiger Kopfschmerz. lähmt geistige Fähigkeiten; wird dadurch wie benebelt, reizbar, jähzornig, unzufrieden. Kopfschmerz mit Gallenbeschwerden. Stauungsleber. Verstopfung."},{"t":"Speisen geschmacklos. Wasser schmeckt verdorben."},{"t":"Gesteigerter Appetit mit Übelkeit beim ersten Bissen."},{"t":"Konstriktion der Körperöffnungen."},{"t":"Nägel brüchig; Hände aufgesprungen; kalte Hände und Füße; Ulzeration um Nägel. Wunden heilen langsam."},{"t":"Alpträume; häufiges Erwachen; Sprechen/Weinen im Schlaf."},{"t":"Mag am Körper warm, am Kopf kalt haben."},{"t":"Amel.: Ruhe; Wärme (Kopfschmerz besser durch kalte Anwendungen); Fasten."},{"t":"Agg.: Aufregung; Anstrengung aller Art; Erschütterungen; morgens nach dem Erwachen besonders verwirrt; frische Luft (obwohl Verlangen); Kälte; kalte Getränke."}],"rem":1,"orig":"Alumina silicata"},{"label":"Alumina","short":"Alumina","group":"Arzneimittellehre","paras":[{"t":"Alumina, Tonerde, geglühtes Aluminiumoxyd. Verwirrung, als ob er träumt. Furcht vor Geisteskrankheit. Verzweiflung an der Genesung. Wie geistige Obstipation. Starre des Geistes. Beschwerden wenn zur Eile getrieben."},{"t":"Psychose: Wenn er spricht, meint er, jemand anders würde sprechen; durch jemand anderes Ohren zu hören. Verliert Identität. Wortfindungsstörungen. Langsamkeit geistig und körperlich. Zeit vergeht zu langsam. Innerliche Eile, kann Dinge nicht schnell genug erledigen, Vorhaben nicht zu Ende bringen, gerät in unproduktive Hektik. Beschwerden von Überarbeitung oder Enttäuschung. Furcht beim Anblick eines Messers, Blut, Küchenschaben. Suizidimpuls."},{"t":"Schwindel, Agg.: Schließen der Augen. Strabismus divergens bei Multipler Sklerose. Trockene Augen. Haar- und Wimpernausfall. Gefühl wie von Eiweiß/Spinnwebe auf dem Gesicht. Zusammenschnürungsgefühl des Ösophagus beim Schlucken."},{"t":"Trägheit des Rektums, Verstopfung bei weichem Stuhl, Entleerung mit großer Anstrengung. Stuhl kann erst abgehen, wenn sich große Kotmasse angesammelt hat. Verstopfung von Kleinkindern durch künstliche Babynahrung. Impotenz. Husten beim Essen."},{"t":"Juckreiz ohne Ausschlag. Weiche Schwielen auf der Fußsohle."},{"t":"Schläfrigkeit morgens (Hauptmittel)."},{"t":"Erkältungsneigung. Trockenheit der Haut, Schleimhäute, Rektum. Multiple Sklerose, amyotrophe Lateralsklerose, Ataxie, Kontrollverlust über die Extremitäten, Blase, Rektum, Auge."},{"t":"Verlangen: Kartoffeln, Reis, Stärke; Wein; Gewürze, Salz und Pfeffer; Obst; trockene Nahrung, Kreide, Dreck, Beton, obwohl verstopft."},{"t":"Amel.: nach Sonnenuntergang; Wärme allgemein; warme Getränke bessern Halstrockenheit; auch: Kaltbaden, Schnee."},{"t":"Agg.: morgens beim Aufwachen; 16-20 Uhr; Kälte; Schwäche in Sommerhitze; Hitze und Bettwärme verschlimmern Hautjucken; Alkohol."},{"t":"Kartoffeln verschlechtern allgemein; verursachen Magenschmerz, Druck im Magen, Übelkeit, Sodbrennen, Blähungen, Kolik, Diarrhoe oder Husten."}],"rem":1,"orig":"Alumina"},{"label":"Alumen","short":"Alumen","group":"Arzneimittellehre","paras":[{"t":"Alaun. Trockenheit von Haut und Schleimhäuten. Katarrhe."},{"t":"Infiltration, Induration, Ulzeration, Blutung, Krebs: Zunge, Magen, Rektum, Nase, Lungen, Mammae, Uterus. Schließlich paralytische Schwäche."},{"t":"Kalte Hände, Füße immer kalt bis zum Knie. Haut rauh und rissig in kalter Luft."},{"t":"Schwindel mit Schwäche in der Magengrube und Übelkeit, Agg.: Liegen auf Rücken; beim Nachuntensehen, Amel.: Öffnen der Augen, Liegen auf rechter Seite."},{"t":"Kopfschmerz: Brennen wie von einem Gewicht in der Scheitelgegend, Amel.: starker Druck; eiskalte Anwendungen."},{"t":"Zungenkrebs. Vergrößerte und verhärtete Mandeln. Jede Erkältung setzt sich im Hals fest. Heiserkeit. Aphonie."},{"t":"Lungenkrebs. Brustschwäche. Starker, zäher Morgenauswurf alter Menschen morgens. Herzklopfen in Rechtslage. Konstriktion des Ösophagus, Schlucken fast unmöglich."},{"t":"Plötzlich auftretende, todesartige Schwäche und Blässe, blaue Lippen. Kraftverlust, kalter Schweiß, kalte Extremitäten."},{"t":"Bluterbrechen bei Trinkern. Blutende Ulzera."},{"t":"Extreme Verstopfung. Schafskotstuhl mit größten Schwierigkeiten und Schmerzen. Strikturen. Pochender Schmerz nach Stuhlgang, der lange anhält,"},{"t":"Jucken im Anus. Hämorrhoiden. Stuhl gelb wie von Kleinkindern. Darmblutung. Paralytische Blasenschwäche. Chronische oder unterdrückte GO, Ulzera, Verhärtungen, Striktur der Urethra."},{"t":"Extremitäten: Gefühl, als ob Kordel oder ein Band um die Arme oder Beine gebunden sei. Paralytische Muskelschwäche der Arme und Beine."},{"t":"Kinder: ungeheuer vergrößerte und verhärtete Mandeln; vergrößerte Uvula; Obstipation; dünn, nervös; kein Appetit; infektlabil."},{"t":"Agg.: Kälte allgemein, nur Kopfschmerz wird gebessert durch kalte Anwendungen."},{"t":"Verlangen: kaltes Wasser in großen Mengen wegen Trockenheit."}],"rem":1,"orig":"Alumen"},{"label":"Ammonium carbonicum","short":"Ammonium carbonicum","group":"Arzneimittellehre","paras":[{"t":"Schwäche des Herzens und der Atmungsorgane. Kollaps. Empfindlich auf Kälte. Schwere in allen Körperteilen. Unordentlich, Abneigung gegen Waschen, möchte jedoch parfümiertes Taschentuch riechen. Heuschnupfen."},{"t":"Dauerschnupfen mit verstopfter Nase, hauptsächlich nacht, muß durch den Mund atmen. Nasenbluten nach Waschen und Essen."},{"t":"Choleraartige Symptome bei Beginn der Regel."}],"rem":1,"orig":"Ammonium carbonicum"},{"label":"Ammonium muriaticum","short":"Ammonium muriaticum","group":"Arzneimittellehre","paras":[{"t":"Körper groß und fett, Beine dünn. Beschwerden durch Kummer. Möchte weinen, kann aber nicht. Durst auf Limonade. Schnupfen mit heißer, wässeriger Absonderung, ätzt die Lippen; Geruchsverlust."},{"t":"Menses stärker nachts."},{"t":"Eiseskälte zwischen den Schulterblättern."},{"t":"Lumbago und Ischias, Agg.: Sitzen, Amel.: Liegen, Gehen."},{"t":"Schmerzhaftes Verkürzungsgefühl in den Kniesehnen."},{"t":"Neuralgische Schmerzen in amputierten Körperteilen."},{"t":"Chronische Bronchitis alter Leute, ähnlich Ant-t."},{"t":"Diarrhoe und Erbrechen, Darmblutung während Menses."},{"t":"Leukorrhoe nach jedem Harnlassen."},{"t":"Stinkender Fußschweiß."},{"t":"Verlangen: Limonade."},{"t":"Agg.: morgens (Kopf/Brust); nachmittags (Bauch); abends (Haut, Fieber, Gliedmaßen); chronische Verstauchungen. Periodizität."},{"t":"Amel.: frische Luft; schnelle Bewegung."}],"rem":1,"orig":"Ammonium muriaticum"},{"label":"Ambra grisea","short":"Ambra grisea","group":"Arzneimittellehre","paras":[{"t":"Ambra grisea, Pottwalsekret. Erschöpft, dabei äußerst beeindruckbar. Hysterie. Zuckungen. Geschäftlicher Fehlschlag oder Tod von Verwandten. Geringe Ursachen beeinträchtigen die Atmung, das Herz, die Menses. Versagergefühl."},{"t":"Geschwätzigkeit. Geisteszustand wie im Traum. Sprunghaft bei Unterhaltung, stellt Fragen, ohne Antwort abzuwarten. Händezittern, Gesichtszuckungen. Vorzeitige Senilität. Vergeßlichkeit, Alzheimer-Frühstadium."},{"t":"Stuhlhemmung in Anwesenheit anderer Menschen (kann nicht loslassen)."},{"t":"Sorgen um die Meinung, die andere von ihm haben. Empfindlich auf Musik, die Husten, Rückenschmerz, etc. verursacht. Ängstlichkeit in der Dämmerung, sieht Gesichter/Geister/Fratzen. Abneigung gegen lächelnde Gesichter/gegen Lachen."},{"t":"Schwindel, Agg.: Gehen. Heftige Erektionen ohne sexuelles Verlangen."},{"t":"Asthmatische Atmung/Husten mit Aufstoßen. Husten, Agg.: Gesellschaft. Schlaflosigkeit durch Sorgen und Konversation."},{"t":"Symptome wechseln plötzlich den Ort."},{"t":"Kältegefühl oder Taubheit an vereinzelten Stellen."},{"t":"Geringfügige Ursachen: kleine Unfälle, Stuhlerschöpfung, längerer Spaziergang."},{"t":"Agg.: warmes Zimmer; warme Getränke; Gesellschaft; Unterhaltung."}],"rem":1,"orig":"Ambra grisea"},{"label":"Ambrosia artemisiaefolia","short":"Ambrosia artemisiaefolia","group":"Arzneimittellehre","paras":[{"t":"Ambrosia artemisiaefolia, Beifuß-Ambrosie, Traubenkraut. Heuschnupfen mit wäßrigem Katarrh, Niesen, brennenden Augen, Tränenfluß und unerträglichem Jucken der Augenlider und Gefühl, als sei der ganze Atmungstrakt verstopft und blockiert. Tendenz, abwärts zu ziehen; keuchender Husten mit Atemnot, muß sich aufsetzen."},{"t":"Tendenz zu Asthma, nach anderen Mitteln."},{"t":"Sommerdiarrhoe bei Patienten mit Atemnot oder Heuschnupfen, allergische Patienten, bei denen Dulc. versagt hat."}],"rem":1,"orig":"Ambrosia artemisiaefolia"},{"label":"Anacardium orientale","short":"Anacardium orientale","group":"Arzneimittellehre","paras":[{"t":"Semecarpus anacardium, Elefantenlaus, ostindischer Tintenbaum. Kind lebt in Unsicherheit, mangelndes Selbstvertrauen. Jd.@ hat Druck auf Kind ausgeübt, ständig vermittelt, es sei nichts wert etc.. Gefühl, niemals Liebe empfangen zu haben, nicht angenommen worden zu sein. Inn. Frustration. Reizbarkeit. Verhärtung. Boshafte Streiche verschaffen Befriedigung; Fluchen, \"schmutzige\" Worte, Kraftausdrücke. Übelste Tierquälerei (Med.). Erscheint oft sehr weich, kriecherisch, unterwürfig, nett. Nach zwischenmenschlichem Konflikt, bei dem höhergestellte Person ihn runtermacht \"du taugst nichts\", ist er davon felsenfest überzeugt. Sehr fähig. Diskrepanz zum verlorenen Selbstvertrauen; mag nicht befördert werden. Innerer Konflikt, innere Kämpfe, Arbeit wird schließlich wirklich schlechter."},{"t":"Muß sich etwas beweisen, wechselt Arbeitsplatz nicht. Angst um Zukunft. Beim Lernen geht nichts mehr hinein, Examensängste."},{"t":"Wegen Minderwertigkeitskomplex muß er sich beweisen, der Beste zu sein. Fühlt sich nicht gewürdigt. Durch Probleme wird Gedächtnis schlechter, schließlich entstehen Ängste. Schwäche der Sinneswahrnehmungen (Geruch, Sehen, Hören). Geruchssinn pervertiert. Glaubt nicht an Liebe, glaubt an Stärke und Härte; alles was pos. gemeint war, wird negativ aufgefaßt. Depression. Reizbarkeit; leicht beleidigt; verliert Selbstkontrolle; wird gewalttätig. Emotional verhärtet. Verfolgungswahn, glaubt, beim Gehen verfolgt zu werden."},{"t":"Schizophrenie, glaubt, er hätte zwei Willen. Fixe Ideen; sieht Teufel und Engel. Verlangen zu fluchen. Pseudoreligiosität. Brutale Grausamkeit, Sadist, Folterer."},{"t":"Wenn Grausamkeit einsetzt, ist Minderwertigkeitsgefühl verschwunden."},{"t":"Bandgefühl, Pflockgefühl innerer Organe, auch bei Kopfschmerz; Agg.: geistige Arbeit und leerer Magen, Amel.: nach Frühstück, kommt nach 2-3 Stunden zurück. Nervöse Dyspepsie. Rektum: erfolgloser Drang, wie zugepfropft. Stumpfheit. Frösteln, zugluftempfindlich. Erysipelartige Dermatitis, wird großflächig wie Scharlach; Bläschendermatitis. Neurodermitis. Lichen planus. Warzen an Handflächen/Händen. Jucken. Brennen. Gliederschmerz ziehend, reißend, Steifigkeit. Juckreiz im Anus, nässend."},{"t":"Agg.: geistige Anstrengung; Emotionen; Erschütterung."},{"t":"Amel.: Essen (alle Symptome)."}],"rem":1,"orig":"Anacardium orientale"},{"label":"Angustura vera","short":"Angustura vera","group":"Arzneimittellehre","paras":[{"t":"Angustura vera, getrocknete Zweigrinde südamerikanische Rautengewächse. Sehr schwere Krankheit, lebensbedrohlich."},{"t":"Verlangen: unwiderstehliches Verlangen nach Kaffee, seltener nach Suppe oder anderen heißen Flüssigkeiten."},{"t":"Konvulsionen, Tetanie, Agg.: Berührung; Lärm. Kiefersperre. Schmerz in Kiefergelenk und Kaumuskeln. Steifheit und Verspannungen von Muskeln und Gelenken. Knieschmerz. Knacken in allen Gelenken."},{"t":"Rheumatische und paralytische Beschwerden."},{"t":"Überempfindlichkeit. Elektrische Schläge entlang der Wirbelsäule."}],"rem":1,"orig":"Angustura vera"},{"label":"Antimonium crudum","short":"Antimonium crudum","group":"Arzneimittellehre","paras":[{"t":"Antimonium crudum, Grauspießglanzerz. Sehr sensibel, introvertiert und sentimental; Belastungen, Kummer, verletzte Gefühle: Magenbeschwerden. Zieht sich zurück, wird launisch, lebt mehr in Vorstellungen, als in Realität; starke Vorstellungskraft; starke Erregung. Ängstlichkeit im Liegen nachts. Sentimentalität, auch prämenstruell, im Mondlicht, bei Diarrhoe. In Kirche ängstlich und emotional, Gefühle geraten außer Kontrolle, tut törichte Dinge, macht sich lächerlich."},{"t":"Kinder wie Cham.: ängstlich, unzufrieden, klagen, schlaflos, verzagt, noch mit 4 oder 5 Jahren macht es psychisch den Eindruck, als ob es noch zahnt; irgendwie beunruhigt, weiß nicht, wovon. Emotional unterentwickelt, unreif. Große Schwäche (Stann.); Abneigung gegen das Leben; Wunsch, nicht mehr zu leben (Erschießen; Ertränken) wegen Schwäche; durstlos trotz Hitze."},{"t":"Agg.: nachts im Bett; unerwiderte Zuneigung, Liebeskummer ganz schlimm. Furcht vor plötzlichen Geräuschen; Reizbarkeit (vor allem bei Kopfschmerz); Empfindsamkeit; Gefühle sehr stark, sehr verwundbar. Mag nicht berührt und nicht angeschaut werden; emotional wie wund (Caust.), als ob die Haut weg wäre, Misanthrop wegen Verwundbarkeit; launisch; zurückgezogen. Gedichte. Augenwinkel rauh, Fissuren. Chronische Blepharitis."},{"t":"Nasenflügel aufgesprungen und bedeckt mit Krusten. Ekzem der Naseneingänge, wund, aufgesprungen und schorfig."},{"t":"Rissige Mundwinkel. Sehr anfällig für Aphthen. Zunge dick weiß belegt. Magenbeschwerden von Überessen, schwacher Magen, dauerndes Aufstoßen. Ständiger Abgang von Gasen nach oben oder unten; jahrelang. Aufgestoßenes schmeckt nach Gegessenem. Durchfall wechselt mit Verstopfung. Durchfall nach Saurem, Bädern, Überessen. Schleimige Hämorrhoiden; Juckreiz; Katarrhalische Proktitis. Empfindliche Hühneraugen auf den Fußsohlen."},{"t":"Agg.: Sonnen- oder Feuerhitze, Überhitzung; Extreme von Hitze und Kälte; Kaltbaden (heftige Kopfschmerzen); Essig; saurer Wein; warm trinken; Alkohol; Überessen."},{"t":"Amel.: frische Luft; Ruhe; nach warmem Bad."},{"t":"Verlangen: Gurken (dazu Cham.-Psyche - ist Ant-c.); Essiggurken (davon aber Beschwerden); Saures."},{"t":"Abneigung: Kaltbaden."}],"rem":1,"orig":"Antimonium crudum"},{"label":"Antimonium tartaricum","short":"Antimonium tartaricum","group":"Arzneimittellehre","paras":[{"t":"Antimonium tartaricum, Tartarus emeticus, Brechweinstein. Beschwerden nach Wut. Pyromanie. Kind klammert sich an die Umgebenden, möchte getragen werden; schreit bei Berührung. Ernsthafte Entzündungen der Atemwege. Arthritis des Auges (Reiter-Syndrom). Zittern des Unterkiefers. Übelkeit und Erbrechen (Verat.) mit Leichenblässe: kalt, blau, blaß, mit kaltem Schweiß bedeckt. Bitterer Geschmack nachts. Bei Schnupfen Geschmacksverlust. Reichlich Schleim, aber wenig Auswurf. Rasselnde Atmung, Nasenflügelatmung, Ikterus bei Pneumonie. Dyspnoe, Amel.: Liegen rechte Seite. Bronchiolitis."},{"t":"Große Schwäche, Abhusten schwierig, schwere Pneumonie oder Krebs, Neugeborene mit Asphyxie; wie beim Ertrinken; durch Schleim in Bronchien."},{"t":"Überwältigende Schläfrigkeit und Koma. Gähnen nach Husten."},{"t":"Heftige Lumbosakralschmerzen; als ob Gewicht am Steißbein nach unten zieht. Impetigo. Varizellen. Metastasierung von der Haut ins ZNS. Konvulsionen nach unterdrücktem Ekzem. Großer Durst auf kaltes Wasser."},{"t":"Verlangen: Äpfel; Obst; Säuren."},{"t":"Agg.: feuchtkaltes Wetter; Hinlegen nachts; warmes Zimmer, Wetterwechsel im Frühjahr (Kali-s.; Nat-s.); Aufenthalt in feuchten Kellerräumen."},{"t":"Amel.: kalte, frische Luft; Aufsitzen; Expektoration; Liegen auf der rechten Seite."}],"rem":1,"orig":"Antimonium tartaricum"},{"label":"Anthracinum","short":"Anthracinum","group":"Arzneimittellehre","paras":[{"t":"Milzbrandnosode. Hauptmittel: Furunkel; Geschwüre; Abszesse; Ekzeme; Ulzera. Brennschmerz wie gebranntmarkt."},{"t":"1. Mittel des brennenden Hautausschlages (Apis; Ars.). Verfärbung purpur, livide, beinahe schwarz."},{"t":"AZ des Patienten kann recht gut sein."},{"t":"Ödematöses, verhärtetes Zellgewebe. Bindegewebsentzündung mit Eiterherd. Erysipel, schwarze, blaue Blasen; Sektionsverletzungen. Insektenstiche. Böse Folgen von Einatmen fauler Gerüche. Gangränöse Parotitis. Rezidivierende Furunkel. Gangrän; faulriechende Ausscheidungen, stinken nach Käse. Frischluftverlangen, unentschlossen (Puls.)."},{"t":"Müdigkeit des Geistes (Nat-m.)."},{"t":"Differentialdiagnose: Tarent-c. auch Brennschmerz, hat kleinere Geschwüre und Furunkel, Anthraci. stärker verfärbt."}],"rem":1,"orig":"Anthracinum"},{"label":"Apium graveolens","short":"Apium graveolens","group":"Arzneimittellehre","paras":[{"t":"Apium graveolens, Sellerie. Beschwerden durch Sellerie. Deprimiert; energisch; Gefühl von Zuckungen; kann nicht schlafen vor Gedanken."},{"t":"Kopfschmerz, pulsierend, Amel.: Essen. Jucken und Brennen im inneren Augenwinkel links. Heftiges Zusammenschnürungsgefühl oberhalb des Brustbeins, mit Ziehen durch den Rücken beim Hinlegen. Rachen, Gesicht und Hände geschwollen, Atemnot. Kitzelnder, trockener Husten."},{"t":"Abdomen: scharfer Schmerz, als ob Stuhlgang kommen würde; Diarrhoe, scharfer Schmerz linkes Iliakalregion, der nach rechts hinübergeht. Übelkeit mit Schmerz zunehmend."},{"t":"Hartnäckiger Urinverhalt. Wiederkehrende Ulzera. Urtikaria."},{"t":"Rheumatische Schmerzen. in den Nackenmuskeln, im Kreuzbein. Zunehmende Schmerzen."},{"t":"Dysmenorrhoe mit scharfen, kurzen Schmerzen., Amel.: angezogene Beine."},{"t":"Schlaflosigkeit 1-3 Uhr."},{"t":"Verlangen: Äpfel; Orangen."},{"t":"Apis mellifica"},{"t":"mellifica, Honigbiene. Ödeme (rosigrot) von Haut (Urtikaria, nachts, rosig/rot) und Schleimhäuten (Rachenring, Bindehaut, Darm, Blase). Schwellung und Gedunsensein. Stechende Schmerzen und ausschwitzende Prozesse der serösen Häute (Meningen, Pleura, Perikard, Peritoneum, Synovia der Gelenke und dergleichen). Brennende Hitze mit Verlangen nach Abkühlung und Unerträglichkeit von Berührung und Druck. Agg.: nachmittags. Zusammenschnürungsgefühl."},{"t":"Witwen; Kinder und Mädchen, lassen Dinge fallen, obwohl sonst sorgfältig (Bov.). Folgen von Eifersucht, Schreck, Zorn, schlechten Nachrichten, unterdrückten Ausschlägen."},{"t":"Reizbar; nervös; zappelig; schwer zufriedenzustellen; muß weinen, mutlos, verzagt (Puls.)."},{"t":"Konzentrationsstörungen beim Lesen. Kreislaufstörungen bis Raynaud-Syndrom. Fieber und Frösteln 15 Uhr (Bell.), mit Durst, Agg.: Bewegung und Hitze."},{"t":"Schwellung um/unter Augen; kann Augen kaum öffnen; Anschwellen der Bindehaut, Amel.: Kälte."},{"t":"Unterdrückter Hautausschlag führt zu Meningitis mit Cri encéphalique. Kopfschmerz beginnt hinter dem linken Ohr, zieht zur linken Schläfe, zum linken Auge."},{"t":"Quincke-Ödem. Glottisödem. Stridor. Asphyxie, Anaphylaxie. Angina mit hochroten Mandeln (rechts); Rachen glänzend und gedunsen. Zäpfchen hängt wie Wassersack herunter."},{"t":"Verbrühungen, Erysipel (sieht aus wie Verbrühung)."},{"t":"Pneumonie: Schmerz beim tiefen Einatmen; als ob er keinen weiteren Atemzug mehr tun könnte. Hydrothorax. Erstickungsgefühl."},{"t":"Peritonitis, Aszites. Anasarka (Schwellung des ganzen Körpers, Skrotum, Penis). Schmerzhafte Hydrozele, Druckdellen bei Ödem."},{"t":"Zystitis mit brennendem Schmerz bei den letzten Tropfen (häufig, schmerzhaft, spärlich, blutig). Glomerulonephritis. Albuminurie; nephrotisches Syndrom mit Durstlosigkeit. Akutes Nierenversagen. Große Ovarialzysten rechts. Fehlgeburt im ersten Trimenon."},{"t":"Gefühl, als ob der Anus offensteht. Diarrhoe bei Säufern; bei exanthematische Erkrankungen."},{"t":"Agg.: Berührung; Druck und Wärme; geschlossener Raum; besonders wenn überheizt völlig unerträglich; 3-5 Uhr; nach Schlaf; rechts."},{"t":"Amel.: kalte Umschläge; Entblößen; Aufdecken; Luftzufuhr."},{"t":"Verlangen: (stark) Milch; Essig."}],"rem":1,"orig":"Apium graveolens"},{"label":"Apocynum cannabinum","short":"Apocynum cannabinum","group":"Arzneimittellehre","paras":[{"t":"Apocynum cannabinum, Indianerhanf. Nierenversagen, nephrotisches Syndrom mit enormer Ödembildung. Riesige Schwellung, Anasarka (Ars.; Apis; Merc.) von Knöchel, Hodensack, Genitalien; Hydrothorax, Aszites; ganzer Körper voll; Mitral- und Trikuspidalinsuffizienz. Chronischer wässeriger Durchfall mit viel Blähungen und Wundheit. Nach Typhus, Scharlach, Zirrhose, Chininabusus."},{"t":"1. Mittel bei Durchfall mit Ödemen. Harnausscheidung spärlich (bei Diuretikaverordnung natürlich mehr Ausscheidung). \"Frösteliges Apis\". Gastritis; \"Paralyse des Magens\", Gefühl, Magen sei ein leerer Sack, funktioniert nicht. Plötzlicher Magenschmerz (mit Durst)."},{"t":"Erbrechen im Augenblick, da Flüssigkeit in Magen gelangt (Bismutum); ein Schluck genügt, um Erbrechen auszulösen."},{"t":"Amenorrhoe junger Mädchen mit Auftreibung und Ödemen. Metrorrhagie: dauernder/anfallsartiger Blutfluß, flüssig oder klumpig; mit Übelkeit / Erbrechen."},{"t":"Agg.: kaltes Wetter; kalte Getränke; Abdecken; Liegen."},{"t":"Amel.: Wärme."},{"t":"Differentialdiagnose: Phos. erbricht, wenn sich kaltes Wasser in Magen erwärmt hat."},{"t":"Differentialdiagnose: Ars. behält Flüssigkeit länger bei sich; Apoc. großer Durst, trinkt viel auf einmal."}],"rem":1,"orig":"Apocynum cannabinum"},{"label":"Aralia racemosa","short":"Aralia racemosa","group":"Arzneimittellehre","paras":[{"t":"Aralia racemosa, Narde. Dyspnoe, Asthma mit Husten, Agg.: Hinlegen; eine Stunde nach dem Einschlafen; 22 Uhr. Sehr zugluftempfindlich. Schwitzen im Schlaf."},{"t":"Furcht vor Lungenerkrankung."},{"t":"Trockener Husten nach dem ersten Schlaf. Asthma nachts im Liegen mit spastischem Husten. Zusammenschnürungsgefühl der Brust; als ob Fremdkörper im Rachen."},{"t":"Heuschnupfen mit häufigem Niesen und verstopfter Nase, Agg.: geringster Luftzug; Frühling. Reichlich wässeriger, ätzender Schleim aus der Nase, von salzigem, scharfem Geschmack."},{"t":"Schmerz von der Leber zum rechten Schulterblatt. Rektumprolaps; Durchfall. Unterdrückte Menses, Lochien. Leukorrhoe mit nach unten ziehenden Schmerzen."},{"t":"Agg.: Zugluft; 22 Uhr; kurzer Schlaf."},{"t":"Amel.: Liegen mit erhöhtem Kopf; Aufsetzen."}],"rem":1,"orig":"Aralia racemosa"},{"label":"Aranea diadema","short":"Aranea diadema","group":"Arzneimittellehre","paras":[{"t":"Aranea diadema, Kreuzspinne. Alle Spinnengifte beeinflussen stark das Nervensystem (Tarent.; Mygal.)."},{"t":"Kälte bis auf die Knochen. Periodizität, täglich zur selben Stunde. Malaria. Empfindliche Teile sind vergrößert und schwerer. Schwäche nach Fieber. Während Frost Schmerz in verschiedenen Körperteilen. Neuralgische Schmerzen von der Peripherie nach innen (Trigeminusschmerz, Interkostalregion)."},{"t":"Magenkrämpfe nach wenig Essen. Milzvergrößerung."},{"t":"Extremitäten: Schwellungsgefühl, als ob Teile einschliefen."},{"t":"Fieber mit Kälte und Schmerz in den langen Knochen und Gefühl eines Steines im Bauch (täglich zur selben Stunde). Frösteln Tag und Nacht."},{"t":"Verwirrung, Amel.: Rauchen an der frischen Luft. Traurigkeit; Verlangt nach dem Tod."},{"t":"Menses zu häufig, zu stark."},{"t":"Agg.: Kälte; Regenwetter; Kaltbaden."},{"t":"Amel.: Rauchen."}],"rem":1,"orig":"Aranea diadema"},{"label":"Argentum metallicum","short":"Argentum metallicum","group":"Arzneimittellehre","paras":[{"t":"Argentum met., Silber. Große, dünne, trockene, reizbare Menschen. Beschwerden nach Quecksilberabusus, nach Masturbation. Wirkt auf Knochen, Bänder und Knorpel im Lid-, Ohren-, Nasenbereich, Tuba Eustachii, Knochen-Apophysen. Sehnenkontraktionen."},{"t":"In Eile, Zeit vergeht zu langsam. Vergeßlich. Ruhelose Ängstlichkeit."},{"t":"Schwindel beim Anblick von fließendem Wasser. Kopf wie leer, hohl."},{"t":"Neurologische Erkrankungen. Empfindung wie elektrischer Schlag, auch im Schlaf oder beim Einschlafen; Knorpelschwellung; rheumatische Beschwerden von Ellbogen und Knie, der Rippen (Tietze-Syndrom) und des Rückens; Lumbago, muß gebeugt gehen. Geschwollene Knöchel."},{"t":"Samenverlust nach Masturbation; ohne Erektion, fast jede Nacht. Schmerz rechter Hoden wie gequetscht. Prolaps und Schmerz linkes Ovar und im Rücken. Erodierte, schwammige Zervix. Leukorrhoe, übelriechend, ätzend. Szirrhus uteri. Klimakterische Blutung. Gefühl von Wundheit im Bauch, Agg.: Schock."},{"t":"Uterus-Erkrankung und Gliederschmerz."},{"t":"Erschöpfender Fließschnupfen mit Niesen."},{"t":"Husten, Amel.: Hinlegen nachts. Große Schwäche der Brust (links). Heiserkeit bei Berufssängern. Klangfarbe verändert. Stimmverlust. Laryngitis, Heiserkeit, durch Überbeanspruchung der Stimme."},{"t":"Hals und Larynx rauh und wund beim Schlucken oder Husten. Rauhe Stelle in Suprasternalregion. Lachen erregt Husten. Morgens viel Schleim im Kehlkopf. Reichliches, leichtes Abhusten von gelatinösem Schleim, wie gekochte Stärke, morgens. Frischluftverlangen."},{"t":"Symptome erscheinen/verschwinden plötzlich: Schwindel, neuralgische Schmerzen. in Kopf und Gesicht."},{"t":"Agg.: mittags; Gebrauch der Stimme; geistige Anstrengung; Fahren im Wagen; Berührung; Druck."},{"t":"Amel.: Bewegung im Freien; vom Husten nachts; im Liegen; Ruhe."}],"rem":1,"orig":"Argentum metallicum"},{"label":"Argentum nitricum","short":"Argentum nitricum","group":"Arzneimittellehre","paras":[{"t":"Argentum nitricum, Silbernitrat. Impulsiv, extrovertiert; nervös; leicht erregbar; schreckhaft; beeinflußbar; mitfühlend; ausdrucksstark: hochgradig glücklich/zornig; starker Sexualtrieb. Viel im öffentlichen Rampenlicht. In Eile (beim Gehen). Geistige Schwäche durch ständige Überanstrengung. Folge von Schock, Todesfall. Krankheit in Umgebung führt zu Hypochondrie. Angst um Gesundheit (Hauptmittel): Krebsangst. Aussehen frühzeitig gealtert. Probleme in Erwartung von Verpflichtungen (Hauptmittel). Klaustrophobie, haßt Fahrstühle, im Kino nahe Ausgang, Panik im Krankenhaus. Melancholie. Fixe Ideen: \"Was wäre wenn\", sehr lebhafte Vorstellungen. Furcht: hochgelegene Plätze; hohe Gebäude; Fenster, wegen Impuls zu springen; schmale Holzbrücke, unter der Wasser fließt. Abergläubisch. Kein Selbstvertrauen. Lampenfieber. Aufregung verursacht Diarrhoe, auch bei freudiger Erwartung."},{"t":"Heiserkeit, Stimmverlust unmittelbar vor Premiere (wegen Nervosität). Heiserkeit wegen Papillomen an den Stimmbändern (Sänger, Prediger). Stechende Rachenschmerzen. Splittergefühl. Strangulationsgefühl."},{"t":"Nervensystem in Unordnung: Schwäche, Schwere in Lumbalregion; Rückenschmerz, Amel.: Stehen; Lähmung; Ataxie; multiple Sklerose; amyotrophe Lateralsklerose; Herzklopfen, als wolle es herausspringen,"},{"t":"Agg.: Liegen auf rechter Seite."},{"t":"Kopfschmerz: langsamer Beginn, plötzlich weg; mit Zittern; vom Tanzen; Vergrößerungsgefühl, Amel.: Binden des Kopfes (Apis; Puls.)."},{"t":"Konjunktivitis mit viel Eiter; roter Fleck auf Bindehaut schmerzhaft/-los, wie rohes Fleisch. Ulzera der Cornea. Müde Augen. Sehschwäche."},{"t":"Haut muß nicht heiß sein trotz innerlicher Hitze (Secale kälter, auch"},{"t":"Agg.: Hitze). Kondylome am ganzen Körper, Warzen, Wucherungen."},{"t":"Periodische Schwäche (Hauptmittel), wie Anfall um Menses. Kälte der Unterarme während Menses. Impotenz beim Koitusversuch."},{"t":"Magen: Übelkeit; Würgen; Erbrechen; Ulkus mit ausstrahlendem Schmerz, Rülpsen und Blähungen wie Kanonenschläge, bessert nicht. Durchfall nach Trinken von Wasser. Stuhl grün, wie gehackter Spinat."},{"t":"Hitzewallungen. Hitzeunverträglichkeit."},{"t":"Verlangen: Süßes; Salz; Fett; kräftiger Käse; Eiscreme wegen Süße (Phos. wegen Kälte)."},{"t":"Abneigung: Fett; Schweinefleisch."},{"t":"Agg.: Hitze; rechte Seitenlage; Zucker."},{"t":"Amel.: Frische Luft; kalte Bäder und Anwendungen."}],"rem":1,"orig":"Argentum nitricum"},{"label":"Arnica montana","short":"Arnica montana","group":"Arzneimittellehre","paras":[{"t":"Arnica montana, Bergwohlverleih. Verletzungen mit Extravasat, wenn viel Blut ins Gewebe ausgetreten ist; rhinoplastischer Operation; \"Veilchen\" (Schlag auf Augapfel: Symph.). Lebhaft, rotes Gesicht; Reizbarkeit, wenn angesprochen. Behauptet, ihr fehle nichts, schickt den Arzt fort. Will Ruhe; Abneigung Gesellschaft."},{"t":"Angst vor Berührung, weil schmerzhaft; sogar Kissen zu hart. Sehr unruhig im Bett, findet keine bequeme Lage."},{"t":"Wundes, gequetschtes Gefühl im ganzen Körper, wie zerschlagen;"},{"t":"große Empfindlichkeit bei geringfügiger Berührung (Wehenbeginn)."},{"t":"Schock, Arthritis, Epilepsie als chronische Folge von Verletzung."},{"t":"Akute Verstauchungen, Verrenkungen, Zerrungen. Komplizierte Frakturen mit folgender reichlicher Eiterung (Calen.). Muskelschmerz infolge sportlicher Überanstrengung."},{"t":"Chronische Arthritis, Rheumatismus, Gicht, wenn Agg.: Feuchtigkeit und Kälte; Gelenkschmerz, Agg.: Stoß, Schlag, Erschütterung (Bell.)."},{"t":"Herzstörungen, Angina pectoris mit Schmerz im linken Ellbogen, Furcht vor Herzkrankheit, rheumatischer Brustschmerz macht Todesangst. Apoplexie. Linksseitige Lähmung mit vollem Puls."},{"t":"Symmetrische Hautausschläge, außerordentlich empfindlich gegen Druck."},{"t":"Haut schwarz-blau. Kleine, extrem schmerzhafte Furunkel (Akne)."},{"t":"Bei Fieber Kopf sehr heiß und Körper sehr kalt."},{"t":"Hitze Oberkörper, Kälte Unterkörper."},{"t":"Commotio: kurzzeitig ansprechbar und weckbar (Bapt.)."},{"t":"Nasenbluten beim Gesichtwaschen."},{"t":"Geruch von faulen Eiern bei Aufstoßen oder Durchfall."},{"t":"Unfreiwilliger Urinabgang beim Laufen."},{"t":"Husten vom Weinen. Keuchhusten: Kind schreit vor Hustenanfall."},{"t":"Beschwerden nach Alkohol, nach CO-Intoxikation."},{"t":"Agg.: kaltes, feuchtes Wetter (Rhus-t.); Berührung; in Ruhe; nach Wein."},{"t":"Amel.: Kontakt; Bewegung; Hinlegen mit flachem Kopfteil."}],"rem":1,"orig":"Arnica montana"},{"label":"Arsenicum iodatum","short":"Arsenicum iodatum","group":"Arzneimittellehre","paras":[{"t":"Arsenicum-Symptome bei warmblütiger Person. Ruhelosigkeit noch stärker; zwanghafter Impuls, sich mit einem Messer zu verletzen. Kinder nehmen Praxis auseinander: Bücher auf Fußboden, Tische werden umgeworfen, totales Chaos; kann nicht an sich halten und seine Kräfte zügeln. Hyperaktivität erinnert an Tarent. und Verat.."},{"t":"Schleimhäute rot, geschwollen, juckend, brennend. Absonderung wässerig, ätzend, übelriechend."},{"t":"Chronischer Schnupfen mit ätzender Absonderung. Heuschnupfen, Asthma wie Ars.. Tuberkulose mit Nachtschweiß, trockenem Husten, schwierigem und spärlichem Auswurf."},{"t":"Schuppender Ausschlag mit großen Schuppen. Epitheliom auf der Lippe. Ichthyosis. Bartekzem. Psoriasis."},{"t":"Großer Durst auf kaltes Wasser, das sofort erbrochen wird."},{"t":"Pfeiffer. Lymphknotenschwellung."},{"t":"Agg.: trockenes, kaltes Wetter; Nebel."},{"t":"Amel.: frische Luft."}],"rem":1,"orig":"Arsenicum iodatum"},{"label":"Arsenicum album","short":"Arsenicum album","group":"Arzneimittellehre","paras":[{"t":"Arsenicum album, Weißarsenik. Syphilitisches destruktives Miasma. Erscheinung: dünn, ausgemergelt, eingefallenes Gesicht, blaß; Kleidung \"wie aus dem Ei gepellt\". Schutzlosigkeit und Verwundbarkeit in einer feindseligen Welt. Fühlt sich beobachtet. Bezieht alles auf sich. Besitzgier. Geiz. Selbstsüchtig. Intoleranz. Zwanghaft ordentlich; Übergenauigkeit in Kleinigkeiten; Perfektionist."},{"t":"Alles genau geplant, um Kontrolle zu haben."},{"t":"Angst (Hauptmittel), aus dem Bett treibende Angstanfälle 0-2 Uhr. Angst um Gesundheit, hält sich für unheilbar; vor dem Alleinsein, vor Einbrechern; vor dem Tod (sehr beherrschend), kann den Anblick Verstorbener nicht ertragen. Selbstmordgedanken. Impuls, sich mit dem Messer Pulsadern zu durchschneiden; mit einem Messer zu töten. Getrieben. Rapides Sinken der Lebenskräfte. Schwäche. Psychisch unruhig, aber physisch zur Bewegung zu schwach. Anorexia nervosa. Extrem frostig; alles besser durch heiße Anwendungen. (Ausnahme: akuter Kopfschmerz mit Fieber); Brennender Schmerz, wie Feuer, als ob heiße Kohlen darauf gelegt würden (Antraci.) Amel.: Hitze (Led. kalte Schmerzen, Amel.: Kälte). Periodizität. Rechtsseitigkeit."},{"t":"Krebsartige Leiden, Epitheliom, Hirntumor, Lupus, Hämangiom, Szirrhus, Seminom. Grippe, wenn der Patient kein Fieber bekommen kann (Carb-v.). Iritis; Schwellungen unter Unterlid. Heuschnupfen; Fließschnupfen rechts. Absonderung wundmachend mit Brennschmerz."},{"t":"Asthma 0-2 Uhr, muß aufstehen, Hinlegen unmöglich wegen Furcht zu ersticken; empfindet Atemluft voller Staub oder Rauch."},{"t":"Ulzera im gesamten Verdauungstrakt mit Brennschmerz, Amel.: warme Getränke (manchmal kalte). Erbrechen, wenn Getrunkenes im Magen warm geworden ist (Phos.). Durst auf häufige kleine Mengen kalten Wassers. Lebensmittelvergiftung. Durchfall von Eiskrem, Obst, mit Schwäche. Hämorrhoiden. Übelriechende, faulige Ausdünstungen; Leberzirrhose."},{"t":"Raynaud-Syndrom. Ulzera der Haut, im Knöchelbereich, an den Beinen mit brennendem Schmerz. Haut trocken, schuppig. Kalter, klebriger Schweiß. Ekzeme mit extrem trockener Haut. Pergamentartig. Weiß und teigig. Schwarze Blasen. Intensives Brennen und Jucken gleichzeitig. Jucken bei Psoriasis, Agg.: Kratzen, auch Jucken ohne Ausschlag (Alum.; Dol.; Mez.; Sulph.); Amel.: wenn es blutet. Fingernägel hart, deformiert, schwarz."},{"t":"Klimakterium: Erbrechen, gefolgt von (Todes-)Angst, sehr frostig."},{"t":"Verlangen: Zitronen; Fleischfett; Öl, vor allem Olivenöl; Schweineschmalz; (Roggen-)Brot; Alkohol."},{"t":"Abneigung: Bohnen, Erbsen; Mehlspeisen (Nudeln)."},{"t":"Agg.: 0-2 Uhr; 13-14 Uhr; Kälte; kalte Speisen und Getränke; Belastung; an der Seeküste; rechts."},{"t":"Amel.: Heiße Anwendungen, Essen, Getränke; Liegen mit erhöhtem Kopf; Gesellschaft."},{"t":"(Differentialdiagnose: Ruhelosigkeit: Rhus-t.: Bewegung bessert; Verat. körperl.@ Strg.@, keine Angst [Verat. auch: fröstelig, durstig])"},{"t":"Komplementär: Phos.; Thuja; Sulph.; Nat-m.; seltener Carbo-v."}],"rem":1,"orig":"Arsenicum album"},{"label":"Artemisia vulgaris","short":"Artemisia vulgaris","group":"Arzneimittellehre","paras":[{"t":"Artemisia vulgaris, Beifuß. Epilepsie mit generalisierten Krampfanfällen. In der Kindheit Petit Mal, entwickelt sich zu Grand Mal."},{"t":"Auslöser: Schreck; heftige Gefühlsausbrüche, Flimmerlicht. \"Epilepsie durch Anblick farbigen Lichts\"."},{"t":"Drehschwindel, wenn der Patient durch bunte Fensterscheiben sieht, durch die Sonnenlicht fällt. Lichtempfindlichkeit; keine Aura."},{"t":"Schlafwandeln, arbeitet nachts, kann sich morgens an nichts erinnern."},{"t":"Profuse Schweiße, Geruch wie Knoblauch."}],"rem":1,"orig":"Artemisia vulgaris"},{"label":"Arum triphyllum","short":"Arum triphyllum","group":"Arzneimittellehre","paras":[{"t":"Arum triphyllum, Zehrwurzel. Infekte, allergische Erkrankungen der oberen Atemwege. Scharfer Fließschnupfen, der die Oberlippe angreift; Rötung um den Mund und Rötung der Nase; Nase verstopft. Gaumen wie roh und juckt. Inn. Hals: geschwollener, brennender Rachen mit Zusammenschnürungsgefühl. Heiserkeit und veränderliche Stimme. Heuschnupfen. Linksseitigkeit."},{"t":"Lippen trocken und aufgerissen. Beißt Lippen. Brennen, Prickeln, Jucken in Lippe oder Nase. Reizung zwingt zum Zupfen an Lippen oder Bohren in Nase bis es blutet. Mundwinkelrhagaden."},{"t":"Symptomkombinationen: Risse in Lippen und Mundwinkeln bei Heiserkeit;"},{"t":"Zupfen an der Nase und Einrisse der Lippen."},{"t":"Agg.: Sprechen; Nordwestwind; Liegen."},{"t":"Amel.: Wärme."}],"rem":1,"orig":"Arum triphyllum"},{"label":"Arundo mauritanica","short":"Arundo mauritanica","group":"Arzneimittellehre","paras":[{"t":"Arundo donax, Wasserrohr, Pfeilschilf. Heuschnupfen mit Juckreiz am Gaumendach, am Naseneingang und der Bindehaut. Geruchsverlust. Geschwüre im Mund; Zahnfleischbluten. Fissur der Zunge."},{"t":"Verlangen: Säure; saure Speisen."}],"rem":1,"orig":"Arundo mauritanica"},{"label":"Asa foetida","short":"Asa foetida","group":"Arzneimittellehre","paras":[{"t":"Asa foetida, Teufelsdreck. Stimmung wechselhaft; Hysterie durch unterdrückten Ausschlag oder unterdrückte Leukorrhoe. Übertreibt. Außerordentlich schmerzempfindlich. Verlangen nach Mitleid. Gesamter Magen-Darm-Trakt betroffen: lautes Aufstoßen, riecht wie Knoblauch; Gefühl, wie Luftblase oder ein Klumpen im Magen, zum Hals aufsteigend; dann Völle im Kehlkopf oder Gefühl, erwürgt zu werden. Globus hystericus."},{"t":"Peristaltik in umgekehrter Richtung. Aufstoßen von Flüssigkeiten. Pulsieren in der Magengrube. Bläuliche Verfärbung um den Anus. Flatulenz (Aufstoßen mehr im Vordergrund). Übelriechender Durchfall. Alle Absonderungen stinken. Zusammenschnürungsgefühl der Brust."},{"t":"Ulzera können überall auftreten, Geschwürsrand ist bläulich verfärbt."},{"t":"Knochenkaries, extrem schmerzhaft, mit dünnem, stinkendem Eiter."},{"t":"Kopfschmerz, von innen nach außen drückend. Erkrankung des Mastoids mit nach außen drückendem Gefühl in der Schläfe. Iritis. Taubheit im Gesicht um die Augen. Karies der Nasenknochen. Ozaena."},{"t":"Agg.: nachts; unterdrückter Hautausschlag oder Absonderung; Berührung."},{"t":"Amel.: frische Luft; Bewegung; Druck."}],"rem":1,"orig":"Asa foetida"},{"label":"Asarum europaeum","short":"Asarum europaeum","group":"Arzneimittellehre","paras":[{"t":"Asarum europaeum, Haselwurz. \"Die Nerven\"; hochneurotisch. Geistiger Zusammenbruch nach andauernder Überforderung. Geistesabwesend. Unfähig zu studieren, Agg.: Tadel. Völlig hysterisch, abwechselnd Kichern und Weinen, Schluchzen, Entschuldigen. Enorme Lärmempfindlichkeit, Kratzen auf Seide, Leinen oder Papier unerträglich. Läuten des Telefons führt zu Nervenzusammenbruch (Ther.). Ringt die Hände, zappelige Finger. Frostschauer jagen hinauf und hinunter, Agg.: Gemütserregungen. Fühlt sich immer kalt. Gefühl zu Schweben, dabei Drehschwindel bei Kopfbewegung. Ehrgeiziger als Nux-v.; kann seine Aufgaben nicht erfüllen. Chronische Konjunktivitis, Blepharitis. Photophobie. Auge empfindlich auf Wind, Amel.: kalte Luft, kaltes Wasser. Gesichtstics links."},{"t":"Durchfall nach dem Essen, unverdauter Stuhl. Dysmenorrhoe mit Lumbago. Starke Abneigung gegen Sex. Kinder mögen nicht geküßt werden. Nach Abstinenz der Alkoholiker. Allergisch auf Gerüche, Essen."},{"t":"Verlangen: Alkohol; Nüsse (Hauptmittel: Cubeba)."},{"t":"Abneigung: Fisch; Fett; Zwiebeln; Knoblauch."},{"t":"Agg.: Kälte; Nässe; Geräusche."},{"t":"Amel.: Baden betroffener Körperteile; Regen."}],"rem":1,"orig":"Asarum europaeum"},{"label":"Asterias rubens","short":"Asterias rubens","group":"Arzneimittellehre","paras":[{"t":"Asterias rubens, roter Seestern. Sykotisch. Schlaff mit gerötetem Gesicht. Furcht vor Apoplexie, Gehirntumor."},{"t":"Brustkrebs. Gefühl, linke Brust wie nach innen gezogen. Schmerz von Mamma in Arm und Finger ausstrahlend; Taubheit. Achsellymphknoten hart, geschwollen. Herzklopfen und Pulsationen im ganzen Körper. Brüste geschwollen, knotig und schmerzhaft. Brustkrebs, auch ulzeratives Stadium; akuter, lanzinierender Schmerz."},{"t":"Verträgt keinen Widerspruch. Zum Weinen geneigt."},{"t":"Hitzegefühl im Kopf, wie umgeben von heißer Luft. Neigung zu Pickel in der Jugend. Heftiges sexuelles Verlangen, durch Verkehr nicht vermindert. Gang unsicher. Muskeln gehorchen dem Willen nicht mehr. Vorher Zucken über den ganzen Körper. Verstopfung."},{"t":"Haut: juckende Stellen. Ulzera mit jauchigem Gestank. Akne, Psoriasis, Herpes zoster, Agg.: am linken Arm, am Thorax."},{"t":"Agg.: Kaffee; nachts; kaltes, feuchtes Wetter; linke Seite."}],"rem":1,"orig":"Asterias rubens"},{"label":"Aurum arsenicum","short":"Aurum arsenicum","group":"Arzneimittellehre","paras":[{"t":"Depression mit Unruhe, viel schlechter nach Mitternacht und an der frischen Luft (aber Verlangen). Gewissensangst; muß aufstehen, um sich zu beruhigen. Wütend, kritisch und hart mit sich selbst und anderen. Hart arbeitend, genau, gewissenhaft. Gefühlswelt stark reduziert und verhärtet. Malignes Auftreten im Kontakt mit Mitmenschen, keine Wärme für sich selbst und andere. Krebs."},{"t":"Zurückgezogenes Schmollen, weigert sich zu sprechen. Alles, was geschieht, ist seine Schuld. Selbstzerstörerisch. Wut. Suizidgedanken (aber Suizidimpuls nur Aur.)."},{"t":"Beschwerden durch Kummer. Hysterie abwechselnd mit Fröhlichkeit. Eile."},{"t":"Lärmempfindlich. Mangelndes Selbstvertrauen. Hohe sexuelle Energie, ausgedrückt in Masturbation oder oberflächlichen Kontakten, um tiefe Beziehung zu vermeiden. Herzklopfen nachts bei Angstzuständen; während Menses. Angst in der Brust. \"Herzflattern\". Angina pectoris. Schlaf: leicht; Träume vom Tod und Sterbenden."},{"t":"Zervikale Lymphknotenschwellung. Abmagerung bei gutem Appetit. Rechtsseitigkeit."},{"t":"Menses zu spät, spärlich; Amenorrhoe."}],"rem":1,"orig":"Aurum arsenicum"},{"label":"Aurum bromatum","short":"Aurum bromatum","group":"Arzneimittellehre","paras":[{"t":"Depression und Akne. Unzufriedenheit mit der Umgebung, erstickt an bestehenden Verhältnissen, will ständig andere Situation; \"wenn ich könnte\". Geisteskrankheit; Depression; findet immer Entschuldigung; die anderen sind an allem Schuld. Analysiert und kritisiert pausenlos; Borderline-Schizophrenie."},{"t":"Umgebung stimuliert zum Analysieren und Kritisieren; paranoide Depression. Spielt mit der Idee des Todes; \"wozu leben\", die anderen verstehen nicht. Kein Vertrauen, keine Kommunikation. Schwäche, Erschöpfung, Epilepsie."}],"rem":1,"orig":"Aurum bromatum"},{"label":"Aurum iodatum","short":"Aurum iodatum","group":"Arzneimittellehre","paras":[{"t":"Schilddrüse und Herz. Eines der größten Herzmittel (Klappen, -itis@, Sklerose...); Herzbeklemmung; Herzklopfen vor allem nachts, bei der geringsten Belastung (Calc.). Gerötetes Gesicht, kalte Extremitäten (Bell.). Unruhe; vergrößerte SD. Rechtsseitiger Ischias; Schmerz mit Taubheit (nach Gnaph. und Coloc.)."},{"t":"Agg.: Hitze."},{"t":"Amel.: frische Luft."}],"rem":1,"orig":"Aurum iodatum"},{"label":"Aurum muriaticum kalinatum","short":"Aurum muriaticum kalinatum","group":"Arzneimittellehre","paras":[{"t":"Aurum muriaticum kalium. Uterusblutung mit Aurum-Element. Chronische Adnexitis. Sehr verschlossen; vermeidet Gesellschaft (Thuja). \"Gebrochenes Herz.\""},{"t":"Haarausfall während der Stillzeit. Menses: zu früh; reichlich mit hellrotem Blut und Klumpen in Erdnußgröße. Trockenheit und Brennen der Vagina mit Kohabitationsschmerz. Abneigung Sex."}],"rem":1,"orig":"Aurum muriaticum kalinatum"},{"label":"Aurum muriaticum natronatum","short":"Aurum muriaticum natronatum","group":"Arzneimittellehre","paras":[{"t":"Aurum muriaticum natronatum. Ähnlich Aur-m.. Kongestion und Schrumpfung. Plötzlicher Stopp in sexueller Aktivität. Entwickelt dadurch geschwollene Ovarien oder großen fibroiden Uterustumor. Ängste können manchmal wie Phos. erscheinen. Das sympathischste, mitfühlendste Aur.; nicht so offen wie Phos., aber magnetisch; Wärme in Kommunikation, jedoch nicht ganz so offen."},{"t":"Hypertonie; Arteriosklerose. Periostale Schwellung am Unterkiefer. Zahnfleisch löst sich von den Zähnen. Hodenschwellung. Kälte im Abdomen. Prolaps und chronische Metritis; Sterilität. Habitueller Abort. Verhärtete Zervix. Ulzeration von Zervix und Vagina."},{"t":"Menses: spärlich oder Amenorrhoe bei Anorexie."},{"t":"Extremitätenschmerz, Amel.: Bewegung."},{"t":"Bohrender Schmerz im linken Auge, Brust, Knochen. Psoriasis syphilitica;"},{"t":"syph. Ataxie."},{"t":"Verlangen: Saures; Salz."},{"t":"Agg.: Kälte; nasses Wetter."}],"rem":1,"orig":"Aurum muriaticum natronatum"},{"label":"Aurum muriaticum","short":"Aurum muriaticum","group":"Arzneimittellehre","paras":[{"t":"Tub. Diathese; intensive Gefühlswelt, vor allem erotisch (Staph.); klammert sich in Liebesaffäre an Partner; nach Abbruch der Beziehung intensives Einsamkeitsgefühl, Sehnsucht; Depression; Nostalgie, hängt Gefühlen nach, besonders Erotik; romantisches Gefühl. Energieverlust (Tub. innerlich ruheloser, Stann.-Schwäche ausgeprägter). \"Kameliendame\", mißverstanden von ihren Liebhabern fällt sie in Depression; ernste Fälle von enttäuschter Liebe. Kein Appetit, keinerlei Verlangen. Keine Suizidtendenz. Depression in Zurückgezogenheit, ähnelt Anorexia nervosa. Angst um Gesundheit, nicht speziell Herz (Aur.), wird aber nicht zugegeben. Mag nicht nach Gesundheit befragt werden, Herz kann aber wegen der intensiven Empfindungen betroffen sein; Leidenschaft und Treue (Aur. Pflichten); freiere Gefühle als Aur."},{"t":"Elemente von Tub. und Stann. Kinder mit schwächlicher, spröder Konstitution; verfeinert, Kopf \"degeneriert\". Strahlend und glücklich, gelegentlich depressiv, nie in der \"Mitte\"."},{"t":"Amel.: Bewegung an der frischen Luft (ausgeprägter als bei Puls.),"},{"t":"will von Luft umarmt werden, intensives romantisches Gefühl; Meer."},{"t":"Agg.: Meer."},{"t":"Heftiges Herzklopfen. Schlucken während Konsultation."},{"t":"Periodische Ruhelosigkeit. Abneigung gegen Arbeit. Empfindlich gegen Kritik und Negativität. Meint, jede Krankheit zu haben."},{"t":"Ausfall der Augenbrauen. Allergien; Heuschnupfen. Krustiger Ausschlag in der Nase, überall möglich. Warzen, Kondylome auf der Zunge, Vagina, etc. Metallischer Geschmack im Mund. Abdomen empfindlich auf Berührung und Kleidung. Abneigung gegen warmen Schlafanzug. Fistel im Rektalbereich. Leukorrhoe, läuft die Beine hinunter. Albuminurie und geschwollene Knöchel während der Schwangerschaft. Heisere, rauhe Stimme. Schlaflosigkeit wegen Herzklopfen. Warmblütig. Exostosen."}],"rem":1,"orig":"Aurum muriaticum"},{"label":"Aurum sulphuratum","short":"Aurum sulphuratum","group":"Arzneimittellehre","paras":[{"t":"Starke Elemente von Aur. und Sulph. Kombination von Depression und Hochmut. Unzufrieden. Kritisch, meint immer, Antworten finden zu müssen. Schlimme Gewissensangst, etwas falsch gemacht zu haben. Faul, mag nicht arbeiten; andere müssen arbeiten und ihn unterstützen. Abneigung Gesellschaft, antisozial; Abneigung, mit anderen zu kommunizieren. Kritisiert sich selbst und andere; bleibt ganze Nacht auf, um über sein Problem nachzudenken. Sehr fordernd aber hintenherum; bitten ohne zu bitten. Reizbarkeit des gesamten Nervensystems. Beginnender Parkinson. Zurückgezogen."},{"t":"Anamnese von emotionalem oder physischem Mißbrauch der Kinder durch die Eltern. Beschwerden durch Kummer oder enttäuschte Liebe. Versteckte Wut, jedoch Wutanfälle, die nicht erleichtern. Furcht vor Menschenmengen, Räubern, hohen Plätzen. Arbeitstier, braucht intellekt. Stimulation."},{"t":"Kinder leben in Phantasiewelt und halten sie für Realität. Wettbewerbsmensch. Diktatorisch. Mißtrauisch. Sehr empfindlich auf Kritik. Fortwährendes Nicken beim Sprechen. Wallungen und Röte des Gesichts."},{"t":"Gefühl, ein Ball bewege sich im Bauch. Berührungsempfindlich, besonders Uterus. Nachuntendrängen während Menses; Brennen in Vagina. Schmerzhaft geschwollene Mammae vor den Menses. Impotenz; niedriges sexuelles Verlangen. Erwachen um 5 Uhr mit Herzklopfen. Deckt Füße auf."},{"t":"Schlaflosigkeit durch Traurigkeit. Erwacht 5 Uhr mit/ohne Stuhldrang."},{"t":"Träume: erotisch; Tod; prophetisch; angenehm."},{"t":"Starker Nachtschweiß."},{"t":"Verlangen: Süßigkeiten; Alkohol."},{"t":"Agg.: abends; nach Schwitzen durch Belastung."}],"rem":1,"orig":"Aurum sulphuratum"},{"label":"Aurum metallicum","short":"Aurum metallicum","group":"Arzneimittellehre","paras":[{"t":"Aurum met., gefälltes Gold. Intellektuell brillant, kompetent. Workaholic. Meint, seine Meinung sei mehr wert als die von anderen. Starker Sinn für Verantwortung. Reagiert mit Zorn auf Kritik, Kränkung, Widerspruch. Keine Freude an sozialem und emotionalem Kontakt. Verlassenheitsgefühl. Lärm- und Geruchsempfindlichkeit. Emotional vergiftender Prozeß: Reizbarkeit; knallhart, gefühllos, wirkt grausam."},{"t":"Tiefe Depressionen. Lebensüberdruß. Suizidneigung mit Impuls, aus großer Höhe (in die Freiheit) herabzuspringen; mit Auto an eine Mauer zu fahren. Auslöser: Kummer, verletzte Ehre, Bankrott, Aktienverfall; Schmerz. Nach außen alles prima, inn. hoffnungslos. Destruktiv, wenn Zorn nach innen; Zwang zu beten statt Suizidgedanken. Furcht an hohen Plätzen."},{"t":"Furcht vor Herzkrankheit. Unterdrückung (z.B. Rheuma) führt zu HK. Hypertonie; Arteriosklerose; Angina pectoris, Agg.: Treppensteigen; rheumatische Herzklappenerkrankungen, Endo- und Perikarditis. Gefühle sterben ab, dann erkrankt das Herz; Herzklopfen, Agg.: nachts; Gemütserregung.; Anstrengung. Als ob Herz 2 Sekunden aufhört zu schlagen, danach 1 harter Schlag."},{"t":"Kopfschmerz, Agg.: nachts. nach außen drückend; Dröhnen; zum Gesicht ausstrahlend. Augen: obere Hälfte der Gegenstände wird nicht gesehen. Lichtscheu. Keratitis. Gefäßreichtum der Hornhaut. Schmerz stechend innen. Heft. Schmerzen der Orbita."},{"t":"Knochenkaries der Nasen-, Gaumenknochen, des Mastoids, der Gehörknöchelchen; stinkende Otorrhoe. Exostosen mit nächtlichem Schmerz."},{"t":"Rheumatische Schmerzen wandern im Körper hin und her. Stöhnen im Schlaf."},{"t":"Geschmack faulig oder bitter; Ulzeration des Zahnfleisches."},{"t":"Nase: ulzeriert, schmerzhaft, verstopft; bestialisch stinkende Rhinitis. Gesicht: reißende Schmerzen Jochbein, Mastoid und auch entzündet."},{"t":"Hodenschmerz bei Epididymitis (rechts). Chronische Verhärtung. Hydrozele. Kryptorchismus und Depression."},{"t":"Ernste, introvertierte Kinder; die besten in der Schule; altklug. Hauptmittel des syph. Miasmas. Große Lebenswärme. Folge von Quecksilbervergiftung."},{"t":"Verlangen: Alkohol; Milch; Brot; Feingebäck."},{"t":"Abneigung: Fleisch (seltener)."},{"t":"Agg.: Nachts; in kalter Luft, beim Kaltwerden; Hinlegen; Gemütserregung; Berührung; geistige Anstrengung; Winter; Sonnenauf- bis Untergang."},{"t":"Amel.: abends Hauptmittel (Med.; Sep.); in warmer Luft, beim Warmwerden; morgens; Sommer; kalt Baden; klassische Musik; Mondlicht; frische Luft."},{"t":"Interesse an Metaphysischem, Heilerischem; sensitive Erfahrungen. Legt eher Bomben als Caust.; liebt Rache (Nit-ac.; Lach.)."}],"rem":1,"orig":"Aurum metallicum"},{"label":"Bacillinum burnett","short":"Bacillinum burnett","group":"Arzneimittellehre","paras":[{"t":"Bacillinum. Chronische Katarrhe der Lunge alter Menschen mit Dyspnoe; Beklemmung. Feuchtes Asthma. Gurgelnde Atemzüge. Rasseln und schleimig-eitriger Auswurf. Erstickungsanfälle nachts; schweres Abhusten. Tuberkulöse Meningitis. Erkältungsneigung."},{"t":"Gereizt, deprimiert. Kopfschmerz tief innen liegend. Kopfgrind. Ekzem der Augenlider."},{"t":"Tropenringwurm. Pityriasis. Geschwollene zervikale Lymphknoten. Alopecia areata des Bartes."},{"t":"Bauchschmerz; tabes mesenterica. Plötzliche Diarrhoe vor dem Frühstück. Hartnäckige Verstopfung mit übelriechenden Blähungen."},{"t":"Verlangen: Senf."},{"t":"Agg.: nachts; früher Morgen; kalte Luft."}],"rem":1,"orig":"Bacillinum burnett"},{"label":"Badiaga","short":"Badiaga","group":"Arzneimittellehre","paras":[{"t":"Badiaga, Spongilla fluviatilis, Flußschwamm. Wundheit von Muskeln und serösen Häuten, wie nach Schlägen; Agg.: Bewegung und Reibung an der Bekleidung."},{"t":"Kopfschmerz ausstrahlend in die Augäpfel. Zucken des linken Oberlides."},{"t":"Schnupfen; Heuschnupfen mit asthmatischer Atmung und erstickendem Husten. Schleim fliegt aus Mund- und Nasenöffnung. Husten von Süßigkeiten, Amel.: warmes Zimmer. Pleuritische Stiche in Rücken, Genick und Brust."},{"t":"Herzklopfen, Agg.: Liegen auf rechte Seite; durch unangenehme Gefühle."},{"t":"Brustkrebs. Metrorrhagie, Agg.: nachts mit Vergrößerungsgefühl des Kopfes."},{"t":"Sommersprossen. Rhagaden."},{"t":"Folgt gut nach Merc."},{"t":"Agg.: Kälte; Abkühlung."},{"t":"Amel.: bei Hitze."}],"rem":1,"orig":"Badiaga"},{"label":"Baptisia tinctoria","short":"Baptisia tinctoria","group":"Arzneimittellehre","paras":[{"t":"Baptisia, wilder Indigo. Delirium: antwortet korrekt, wenn man zu ihm spricht, schläft aber sofort wieder ein; Melancholie mit Stupor; Koma. Gleichgültigkeit. Denkunfähigkeit."},{"t":"Furcht, schlafen zu gehen wegen Alpträumen und Erstickungsgefühl."},{"t":"Denkt, er ist auseinandergebrochen oder doppelt, wirft sich im Bett herum und versucht, die Stücke wieder zusammenzusetzen."},{"t":"Kopfhaut scheint zum Hinterkopf gezogen zu werden; Gefühl, Kopf sei zu groß, schwer, taub. Schwere der Lider. Gesicht glühend, dunkelrot mit stierigem Gesichtsausdruck wie betrunken (Gels). Lippen dick; Zunge dick, schwer, wie verbrannt; Sprache undeutlich; Zungenulzera."},{"t":"Schmerzlose Halsentzündung; Tonsillen, weicher Gaumen dunkelrot, geschwollen, roh, geschwürig; eitrige, stinkende Absonderung. Schluckschwierigkeiten, kann nur Flüssigkeiten schlucken, würgt bei fester Nahrung."},{"t":"Sepsis. Alles stinkt: Atem, Schweiß, Stühle, Urin, Ulzera (Psor.; Pyrog.). Blähungen. Lochien ätzend, stinkend. Kindbettfieber."},{"t":"Gefühl des Absackens im Magen. Gastroenteritis. Dysenterie alter Menschen, bei Kindern; Stuhl dünn, dunkel, blutig. Dauerndes Verlangen nach Wasser."},{"t":"Zerschlagenheitsschmerz am ganzen Körper \"wie gequetscht\" (Arn.); Wundliegen. Findet keine bequeme Lage (Arn.; Pyrog.). Dekubitus."},{"t":"Grippale Infekte, wenn schläfrig mit Foetor ex ex ore;"},{"t":"Grippe kann plötzlich zu Mastoiditis führen. Bösartige Fieber. Fleckfieber. Bordfieber. Schüttelfrost (11 Uhr) mit rheumatischem Schmerz des ganzen Körpers. Hitze."},{"t":"Agg.: feuchte Hitze; Nebel; im Zimmer; Druck; beim Erwachen."}],"rem":1,"orig":"Baptisia tinctoria"},{"label":"Baryta carbonica","short":"Baryta carbonica","group":"Arzneimittellehre","paras":[{"t":"Entwicklungshemmung körperlich, mental, emotional. Spät gelaufen und gesprochen. Langsam. Zwergenhaft. Kindlich. Abhängig. Braucht Schutz; Angst um Familienmitglieder. Keine Willenskraft. Ernst. Schüchtern. Ängstlich. Kein Selbstvertrauen. Argwohn; meint, ausgelacht zu werden; daß andere über ihn sprechen. Unentschlossen. Schwaches Gedächtnis, Kind kann nicht unterrichtet werden, weil es nichts behält, drohende Idiotie. Große Unsicherheit, Ungeschicklichkeit. Kinder mit Furcht und Abneigung gegen Fremde, verstecken sich. Will nicht erwachsen werden, kann keine Verantwortung tragen, zu große Belastung."},{"t":"Retardation als Folge von Schock; wegen Eifersucht (z. B. Neugeborenes in Familie). Beißt Fingernägel. Gefühl, Rauch einzuatmen."},{"t":"Mundatmer; dummer Gesichtsausdruck. Infektlabilität: neigt zu Tonsillitis mit Eiterungstendenz (Hep.; Psor.) im Kleinkindalter und Alter. Geschwollene, verhärtete Lymphknoten retroaurikulär, zervikal, inguinal. Schwäche, Erschöpfung."},{"t":"Alte, arteriosklerotische Patienten mit kindlichem Verhalten; Alzheimer; vorzeitige Demenz (Hauptmittel). Alte Männer: Prostataverhärtung oder Hypertrophie. Apoplexneigung alter Menschen. Beschwerden alter Säufer. Spezifisch für Aortenaneurysma."},{"t":"Abdomen hart, aufgetrieben. Koliken. Hat Appetit, bringt nichts hinunter, außer Flüssigkeiten schluckweise. Schlundkrämpfe. Hämorrhoiden treten beim Wasserlassen hervor (Mur-ac.)."},{"t":"Verzögerte Genitalentwicklung. Späte Menarche. Wenig sexuelles Verlangen, keine/späte Beziehungen. Impotenz."},{"t":"Halsbeschwerden durch unterdrückten Fußschweiß. Widerlicher Fußschweiß, wundmachend; Empfindliche Schwielen auf der Fußsohle. Grützbeutel."},{"t":"Will sich hinlegen. Frostig. Profuse Schweiße in Anwesenheit Fremder. Verlangen: Eier; Süß. Abneigung: Obst."},{"t":"Agg.: Gesellschaft; Kälte; unterdrückter Fußschweiß; Liegen auf schmerzhaftem Körperteil."},{"t":"Amel.: warm einhüllen; kaltes Essen; alleine."},{"t":"Differentialdiagnose: Alumina: Langsamkeit wie in Wolke, alles langsam."}],"rem":1,"orig":"Baryta carbonica"},{"label":"Baryta muriatica","short":"Baryta muriatica","group":"Arzneimittellehre","paras":[{"t":"Willkürliche Muskelbewegung unmöglich, aber Sensibilität intakt."},{"t":"Lähmung nach Influenza. Allgemeine Mattigkeit morgens, besonders Schwäche, Muskel- und Gelenksteifigkeit der Beine, Agg.: morgens. Multiple Sklerose. Manie mit gesteigerter Libido."},{"t":"Schwere des Kopfes mit Schwindel wegen Zerebralanämie."},{"t":"Ohrgeräusche beim Kauen. Ohrenschmerz. Amel.: Schlürfen von kaltem Wasser. Stinkende Otorrhoe. Blähung des Mittelohres beim Naseputzen."},{"t":"Tonsillen, Adenoide geschwollen; Mund offen. Stimme nasal. Gefühl des Zu-weit-Seins in den Gehörgängen. Zervikale Lymphknotenschwellung."},{"t":"Hinfälliges Gefühl im Oberbauch. Verengung der Kardia sofort nach dem Essen und Oberbauch-Empfindlichkeit. Würgen und Erbrechen."},{"t":"Bronchialbeschwerden alter Leute bei Herzerweiterung mit viel Schleim."},{"t":"Schwieriges Abhusten. Aortenaneurysma."},{"t":"Empfindung wie elektrischer Schlag (Arg-m.). Krämpfe. Eiseskälte des Körpers mit Paralyse. Haut feucht-warm, Agg.: nachts."}],"rem":1,"orig":"Baryta muriatica"},{"label":"Bellis perennis","short":"Bellis perennis","group":"Arzneimittellehre","paras":[{"t":"Bellis perennis, Gänseblümchen. Verletzungen der tieferen Gewebe, Operationen. Nervenverletzung. Unverträglichkeit von kaltem Baden. Neuralgien."},{"t":"Unverträglichkeit von eiskalten Getränken bei Erhitzung."},{"t":"Kopfschmerz wie geprellt, vom Hinterkopf bis zum Scheitel. Schwindel bei älteren Menschen."},{"t":"Gefühl von Wundheit und Prellung im Beckengebiet, der Bauch- und Uteruswände, wie gequetscht. Stiche in der Milz, schmerzhaft vergrößert. Gelbe, schmerzlose Diarrhoe, fauliger Geruch, Agg.: nachts."},{"t":"Furunkel überall."},{"t":"\"Eisenbahnrückgrat\". Verstauchungen mit starken Schmerzen. Unfähig zu gehen. Varikose; venöse Stase. Exsudate und Schwellungen. In der Schwangerschaft unfähig zum Spazierengehen. Bauchmuskeln lahm. Linksseitig; Verletzungen; Verstauchungen; Berührung; Kaltbaden; kalte Getränke; kalter Wind; Abkühlung nach Überhitzung."}],"rem":1,"orig":"Bellis perennis"},{"label":"Belladonna","short":"Belladonna","group":"Arzneimittellehre","paras":[{"t":"Atropa belladonna, Tollkirsche. Ausdrucksstark. Äußerste Heftigkeit aller Erscheinungen; Schmerz, Kopfschmerz mit starkem Blutandrang zum Kopf, mit hochrotem Gesicht und Augen; klopfende Karotiden; abstrahlende Hitze bei Kälte der Extremitäten."},{"t":"Kopfschmerz klopfend, vor allem Stirn; bohrt Kopf ins Kissen, Amel.: Bandagieren; Druck; während der Regel. Wilde Delirien mit großer Unruhe."},{"t":"Hirn(-nerven)reizung. Wutanfälle mit Schlagen, Beißen, Spucken, zerreißt Dinge. Lacht laut und unnatürlich. Lebhafte Wahnvorstellungen, sieht Fratzen, Tiere. Furcht vor Hunden. Schwindel, Agg.: Bücken; Aufrichten; Lagewechsel."},{"t":"Überempfindlichkeit auf Schmerz, Erschütterung, Berührung, Licht, Geräusche, Geschmack. Pupillen erweitert, Augen starrend, glänzend. Heiße, rote, scharlachähnliche Haut; Scharlach (Ail.). Frostgefühl. Großer Durst. Bei Fieber durstlos. Dampfende Schweiße, die keine Erleichterung bringen. Hitze, Röte. Brennen und klopfende Schmerzen in den entzündeten Teilen. Brechreiz, Krämpfe während der Zahnung mit Fieber, kommen plötzlich."},{"t":"Kitzelnder, kurzer, trockener Husten, bellend, Agg.: nachts. Keuchhusten mit Magenschmerzen vor dem Anfall; fürchtet zu ersticken; kein Auswurf; Kehlkopf sehr schmerzhaft; Niesen nach der Hustenkrise; Otitis media mit pulsierendem Schmerz, Kind schreit im Schlaf; Tubenkatarrh. Zähneknirschen."},{"t":"Hals trocken, rot, rechts, geschwollene Tonsillen. Einschnürungsgefühl mit Schluckreiz, Schluckschmerz. Spasmen in der Kehle. Koliken an allen Hohlorganen, besonders am Hals, Magen und Darm, Gallenblase, Harnblase und Gebärmutter. Schmerz periodisch, plötzlicher Beginn und Ende. Schmerz rechte Ileözäkalregion, Agg.: Berührung (Bettdecke). Großer Durst auf kalte Getränke. Furcht vorm Trinken, vor Wasser. Aufgetriebenes Querkolon. Metrorrhagie im Klimakterium: sehr heißes Gefühl in den Genitalien, Blut läuft Beine hinunter. Exophthalmischer Kropf."},{"t":"Verlangen: Limonade; Zitronen; Saures; Süßes; Gemüse."},{"t":"Abneigung: Fett; Fisch; Fleisch; Milch."},{"t":"Amel.: Ausstrecken und Rückwärtsbeugen des Rumpfes, auch durch Zusammenkrümmen; Ruhe; aufrechtes Stehen oder Sitzen; warmes Zimmer."},{"t":"Agg.: Kälte; Zugwind; Entblößung; Haareschneiden; Sinneseindrücke wie Licht, Geräusche, Berührung, Erschütterung; Blicken auf glänzende Objekte (Lyss.; Stram.); Aufregung; direkte Sonnenhitze; Niederlegen; Bücken; durch jede Bewegung; nach 15 Uhr; nachts; nach Mitternacht."}],"rem":1,"orig":"Belladonna"},{"label":"Benzoicum acidum","short":"Benzoicum acidum","group":"Arzneimittellehre","paras":[{"t":"Benzoesäure. Harnsäurediathese mit Gicht-Arthropathie und stinkendem Urin; alle Gelenke, speziell Knie knacken bei Bewegung; Knotenbildung. Schmerz in Achillessehne. Exostosen; Überbein; Schwellung Handgelenk; reißender Schmerz in Großzehe."},{"t":"Urin dunkelbraun, sehr intensiver, scheußlicher Geruch. Wechselnde Farbe; sauer. Übelriechender Urin alter Männer. Zuviel Harnsäure. Blasenkatarrh infolge unterdrückter GO. Sykose. Nierensteine. Einnässen nachts."},{"t":"Stiche und Engegefühl, Zusammenziehen des Rektums; juckender und wässeriger Ausschlag um Anus. Stuhl schaumig, übelriechend, flüssig."},{"t":"Zunge schwammig, dick, ulzeriert mit rheumatischen Herzproblemen bei unterdrückter Gicht."},{"t":"Gichtbeschwerden abwechselnd mit Urin- oder Herzsymptomen."},{"t":"Rheumatismus schlechter, wenn Urin besser und umgekehrt."},{"t":"Schmerzen wechseln plötzlich ihren Ort."},{"t":"Profuse Schweiße, Agg.: nachts; Essen."},{"t":"Brütet über unangenehme Dinge der Vergangenheit."},{"t":"Frostig. Amel.: Wärme."}],"rem":1,"orig":"Benzoicum acidum"},{"label":"Berberis vulgaris","short":"Berberis vulgaris","group":"Arzneimittellehre","paras":[{"t":"Berberis vulgaris, Berberitze, Sauerdorn. Arthritis, Gicht, Lumbago: Brennen und Empfindlichkeit in Nierengegend. Koliken bei Nephrolithiasis (vgl. Hyper. Schmerz strahlt aus zur Körpermitte, Kalm. den Arm hinunter); Nierenkolik: stechender, schneidender Schmerz von der linken Niere, den Verlauf des Ureters entlang zur Blase und in die Harnröhre (rechts: Lyc.), ausstrahlend zu Oberschenkel und Hoden; kommt und geht plötzlich. Sprudelndes Gefühl in Nieren (Med.). Zystitis mit Schmerzen, die in verschiedene Richtungen ausstrahlen; Schmerz, Agg.: nach dem Wasserlassen; Sedimentbeimengung. Urin: grünlich, blutrot, mit dickem Schleim; durchsichtig, rötlicher oder gallertartiger Satz."},{"t":"Gallensteinkolik: Cholestase mit Ikterus; lehmfarbige Stühle. Analfistel mit Gallensymptomen und Jucken der entsprechenden Körperteile; kurzer Husten und Brustbeschwerden, besonders nach Fisteloperation. Arthritis, die von einer Körperseite zur anderen wandert. Blasser Teint mit eingesunkenen Wangen und hohlen Augen."},{"t":"Gefühl einer engen Kappe, die auf die Kopfhaut preßt."},{"t":"Übelkeit vor dem Frühstück."},{"t":"Neuralgie unter den Fingernägeln mit Schwellung der Fingergelenke."},{"t":"Flache Warzen, juckend, brennend. Polypen in Larynx, Stimmbänder."},{"t":"Agg.: Bewegung; Gehen; Fahren; Erschütterung; Aufstehen vom Sitzen; vor Stuhlgang; bei Dunkelheit; vor und bei Menses."}],"rem":1,"orig":"Berberis vulgaris"},{"label":"Bismuthum-sn. (+ -o.) (old abbr.)","short":"Bismuthum-sn. (+ -o.) (old abbr.)","group":"Arzneimittellehre","paras":[{"t":"Bismuthum subnitricum, basisches Wismutnitrat. Magenmittel. Sehr heftige Magenschmerzen und Alleinsein ist unerträglich. Viel Durst auf Kaltes. Erbrechen, wenn Getrunkenes im Magen warm geworden ist (Apoc. erbricht sofort, Phos.-Schmerz nicht so heftig). Schmerz im Solarplexusgebiet, an einer Stelle; zuerst Sodbrennen, dann krampfartige, heftige Magenschmerzen; tagelange Attacken ohne Unterbrechung; periodisch alle 14, 30, 45 d.@ \"Schütten des Kindes\", Erbrechen bald nach dem Trinken. Wenn Schmerz weg, können sie alles verdauen, sogar Steine. Spasmolytika helfen nicht."},{"t":"Choleraähnliche Sommerdurchfälle, wenn Erbrechen vorherrscht. Stühle faulig, wässerig, stinkend, sehr erschöpfend."},{"t":"Amel.: Rücken reiben; massieren; kalte Getränke und Applikationen; Zurückbeugen; Bewegung."},{"t":"Agg.: Bauch reiben; Essen, Überessen."},{"t":"Differentialdiagnose: Phos. ist nicht so heftig, gewaltsam und extrem. Wenn Phos. versagt hat."},{"t":"Blatta orientalis"},{"t":"orientalis, Küchenschabe. Asthma mit Dyspnoe und Bronchitis mit reichlichem eitrig-schleimigem Auswurf und schweren Hustenanfällen. Mit Calc. zu verwechseln: beleibte Patienten, fett. Dyspnoe durch geringe Anstrengung; gerötetes Gesicht (Ferrum); fühlt sich sehr schwach. Asthma schlimmer in der Nähe von schimmeligem Laub. Generalisierte Ödeme."},{"t":"Agg.: nachts; Niederlegen."},{"t":"Amel.: Expektoration."}],"rem":1,"orig":"Bismuthum-sn. (+ -o.) (old abbr.)"},{"label":"Borax veneta","short":"Borax veneta","group":"Arzneimittellehre","paras":[{"t":"Borax, Natrium boracicum. Wie andere Natriumverbindungen Neigung zu Kopfschmerz, Herpes, Schlaflosigkeit; speziell verwandt mit Nat-m. und Nat-s.."},{"t":"Nervös. Sehr lärmempfindlich auf plötzliche Geräusche (Husten, Niesen)."},{"t":"Furcht vor Abwärtsbewegung (Seilbahn, Aufzug, treppab), schreit Kind, wenn es hingelegt wird. Furcht, sich zu infizieren; zu fallen, Treppe hinunterzustürzen; Geschwüre und Aphthen in der ganzen Mundhöhle, sehr schmerzhaft, leicht blutend, halten Kind vom Saugen ab (Calc. häufiger). Soor. Bitterer, muffiger Geschmack. Heißer Mund mit Trockenheit und Durst; rissige und blutende Zunge; Speichelfluß bei Zahnung. Gebißträger (Alumen). Stinkender Stuhl bei Kindern; schleimiger Durchfall mit Aphthen. Rote Nasen junger Frauen (Nat-c.). Harnwegsinfekte der Kinder: Reizbarkeit oder Weinen vor dem Wasserlassen. Haut: Herpes überall. Pavor nocturnus: Ängstlichkeit bis 23 Uhr. Entropion der Augenlider. Lidrandentzündung. Trockene, klebrige Exsudation; morgens verklebte Lider. Leukorrhoe, wie Hühnereiweiß. Dysmenorrhoe. Muttermilch von schlechtem Geschmack und Qualität. Schmerz in der anderen Brust beim Stillen. Stiche in der Brust bei Einatmung; Stiche in der Fußsohle. Schmerz Daumenspitze. Nagelverlust. Psoriasis."},{"t":"Kombination: Schreckhaftigkeit und Probleme beim Wasserlassen."},{"t":"Agg.: Essig; Wein; Abwärtsbewegung; plötzlicher Lärm; vor Wasserlassen."},{"t":"Amel.: nach Stuhlgang; 23 Uhr; Druck; Halten der schmerzhaften Seite mit der Hand."}],"rem":1,"orig":"Borax veneta"},{"label":"Bothrops lanceolatus","short":"Bothrops lanceolatus","group":"Arzneimittellehre","paras":[{"t":"Bothrops lanceolatus, gelbe Buschmeister. Große Mattigkeit und Schlaffheit. Blutung aus jeder Körperöffnung; schwarze Flecken. Thrombose. Hemiplegie mit Aphasie. Nervöses Zittern, Schmerz in rechter Großzehe. Diagonalverlauf der Symptome. Blindheit wegen Netzhautblutung. Tagblindheit. Gesicht geschwollen, gedunsen, törichter Ausdruck. Rachen rot, trocken, eingeschnürt, kann Flüssigkeiten nicht hinunterbringen. Bluterbrechen. Blutige Stühle. Rechtsseitigkeit."}],"rem":1,"orig":"Bothrops lanceolatus"},{"label":"Bovista lycoperdon","short":"Bovista lycoperdon","group":"Arzneimittellehre","paras":[{"t":"Bovista lycoperdon, Riesenbovist. Trockene und feuchte Flechten. Stammelnde Sprache, Stottern. Absonderungen aus Nase und allen Schleimhäuten zäh, fadenziehend, klebrig (Kali-bi.). Enge Kleidung unerträglich an der Taille. Blutungen nach Zahnextraktionen (Ham.), aus Wunden; Epistaxis. Gelenkschwäche Hände und Füße. Alles fällt aus den Händen. Ungeschicklichkeit. Juckreiz an Steißbeinspitze. Kolikschmerz abdominal, Amel.: Zusammenkrümmen; Essen. Mit rotem Urin. Durchfall vor/während Menses. Menses fließt nur nachts (Mag-c.). Menses zwischen den Menstruationen. Ovarialzysten. Menstruationsstörungen mit Störungen im Gemütsbereich: Stottern, hysterisches Lachen. Leukorrhoe dick, zäh, grünlich, nach Menses. Akne nach Anwendung von Kosmetika, Agg.: Sommer, baden. Vergrößerungsgefühl in Kopf und Herz. Stumpfe Instrumente hinterlassen tiefe Delle in Haut."},{"t":"Urtikaria bei Erregung mit Herzklopfen und Durchfall; Jucken beim Warmwerden. Feuchtes Ekzem mit dicken Krusten."},{"t":"Agg.: Menses; Vollmond; Warmwerden."},{"t":"Amel.: Zusammenkrümmen."},{"t":"Verlangen: Brot; kalte Getränke."}],"rem":1,"orig":"Bovista lycoperdon"},{"label":"Bromium","short":"Bromium","group":"Arzneimittellehre","paras":[{"t":"Bromum, Brom. Blonder Typ; rotbackige, skrofulöse Mädchen. Vergrößerung von Parotis und Kropf. Linksseitiger Mumps. Schmerz wie Spinnweben im Gesicht. Drüsenschwellung im Sommer, steinhart; an Unterkiefer und Hals; dabei keine Eiterungsneigung. Diphtherie mit Membranen im Pharynx, Bronchien, Larynx. Brustschmerz zieht aufwärts, brennend. Membranöser, trockener diphtherischer Krupphusten mit viel Schleimrasseln im Kehlkopf und Heiserkeit. Dyspnoe; kann nicht tief genug einatmen; atmet wie durch Schwamm oder als ob Luftwege voller Rauch wären. Kaltes Gefühl beim Einatmen. Erstickungsgefahr durch Schleim im Kehlkopf. Nasenflügelatmung (Ant-t.; Lyc.)."},{"t":"Herzhypertrophie bei übertriebenem Sport bei Heranwachsenden. Akne, knotenförmig."},{"t":"Asthma: Matrosen bei Landgang. Chronische Lungenerkrankungen, Agg.: Sommer. Hodenschwellung, und -verhärtung, Agg.: Erschütterung. Ovarialschwellung. Schüttelfrost, verlangt nach Wärme, die nicht erleichtert."},{"t":"Agg.: vor Mitternacht; Überhitzung im Zimmer; schwülwarmes Wetter; Staub; Zugluft."},{"t":"Amel.: Nasenbluten (Schwindel, Kopf- und Brustbeschwerden); am Meer; Bewegung; Neurodermitis, Amel.: am Meer."},{"t":"Differentialdiagnose: Iod., Chlor. und Spong. haben Beziehung zu Drüsen, auch Schilddrüse, Hodeninduration, Husten, der sich im Sommer in der Hitze verschlimmert."},{"t":"Differentialdiagnose: alle Bromverbindungen, z. B. Kali-br., gut bei Akne (tiefsitzende, große, harte rote Knoten, sehr schmerzhaft: Bell.; Brennschmerz.: Tarent.; Aknenarben: Sil.)."}],"rem":1,"orig":"Bromium"},{"label":"Bryonia alba","short":"Bryonia alba","group":"Arzneimittellehre","paras":[{"t":"Bryonia alba, weiße Zaunrübe. Bewegung verschlechtert geistig, emotional und körperlich. Druck bessert (außer Magen), Liegen auf der schmerzhaften Seite bessert. Spricht und träumt vom Geschäft. Furcht vor Armut, Zukunft. Reizbarkeit bei Hitze; wenn er etwas gefragt wird. Frost nach Ärger, mit heißem Kopf und rotem Gesicht. Weist Dinge zurück, um die er gebeten hat. Will nicht gestört werden, Abneigung Gesellschaft. Unsicherheit und Einsamkeit."},{"t":"Unzufriedenheit. Einbildung, von zu Hause weg zu sein; verlangt, nach Hause zu gehen."},{"t":"Schwindel, als ob er durch das Bett sinke. Kopfschmerz über dem linken Auge, zum Hinterkopf ausstrahlend und die ganze Wirbelsäule hinunter, Agg.: geringste Bewegung, sogar Augenbewegung; Amel.: Ruhe, Liegen auf schmerzhafter Seite. Fettiges Haar. Nasenbluten 3-4 Uhr. Nasenbluten anstatt Menses. Blässe bei Pleuritis/Peritonitis, rotes Gesicht bei Gelenkerkrankungen. Empfindlicher Bauch; Appendizitis. Verstopfung; harter, trockener Stuhl."},{"t":"Mastitis. Schmerzhafter Husten, hält die Brust und den Kopf, Agg.: Eintreten in warmes Zimmer. Durst auf große Mengen in großen Intervallen. Trockene Schleimhäute. Entzündete Synovialhäute der Gelenke, geschwollen."},{"t":"Agg.: warmes Wetter nach kalten Tagen; kalte Getränke/Eis an heißen Tagen; nach Erkälten oder Erhitzen im Sommer; Frösteln nach Überhitzung; Zugluft, kalter Wind; unterdrückte Ausscheidungen (Menses, Milch, Ausschläge); Bewegung; Anstrengung; Berührung; kann nicht aufsitzen, wird ohnmächtig, Wärme, warme Getränke."},{"t":"Amel.: Liegen auf der schmerzhaften Seite (Ptel.; Puls.); Druck, außer bei Magenschmerz; Ruhe; Kälte, Essen von kalten Speisen."},{"t":"Bufo rana"},{"t":"rana, Erdkröte. Neurologische und Hautprobleme. Dumpfheit des Geistes, Schwachsinn. Exzessiv starke Libido, mag alleine sein, um ungestört onanieren zu können; ist aber egal, ob jemand zuschaut. Überhaupt keine Schuldgefühle, hat etwas Tierhaftes; dicke Lippen, um Lippen süffisantes Lächeln: \"Ich will nur Sex, nichts als Sex\". Promiskuität; Sucht nach Pornographie. Wütend, wenn er sich unverstanden fühlt. Beißen. Autismus. Kinder sehr intelligenter Eltern. Ruhelosigkeit und Ungeduld. Nägelbeißen. Furcht vor Tieren; Fremden. Stottern; lautes Heulen. Empfindlich auf Licht, Lärm, Musik. Epilepsie. Ataxie und unsicherer Gang. Parkinson."},{"t":"Impotenz. Pollutionen; E. praecox. Brustkrebs. Uterustumoren. Eitern bei jeder Verletzung. Nagelbettentzündung. Panaritium, Schmerz läuft Arme hoch; Schwellung der axillaren Lymphknoten. Lymphangitis sept. Ursprungs. Erysipel."},{"t":"Verlangen: süße Getränke; berauschende Getränke; Delikatessen."},{"t":"Agg.: warmes Zimmer; Erwachen."},{"t":"Amel.: Baden; in kalter Luft; Eintauchen der Füße in heißes Wasser."}],"rem":1,"orig":"Bryonia alba"},{"label":"Cactus grandiflorus","short":"Cactus grandiflorus","group":"Arzneimittellehre","paras":[{"t":"Cactus grandiflorus, Königin der Nacht. Melancholie; Schweigsamkeit; schlechte Laune; Angst; Todesfurcht; schreit vor Schmerz; kalter Schweiß; rotes Gesicht. Der ganze Körper fühlt sich wie in einem Käfig eingesperrt, bei dem jeder Draht enger gezogen wird. Konstriktion in: Kehle, Brust (eiserner Reifen, Schnur), Herz (eiserne Faust auf und zu; \"keinen Platz zum Schlagen\"), Blase, Rektum, Uterus, Vagina, Agg.: Berührung. Herz: Angina pectoris mit Schwellung oder Taubheit des linken Armes, Infarkt, Myokarditis. Konstriktionen. Blutungen mit Koagulationsneigung aus Nase, Blase, Rektum. Periodizität (täglich zu genau der gleichen Stunde). Kopfschmerz wie schweres Gewicht auf Scheitel; klimakterisch (Glon.; Lach.). Kongestiver Kopfschmerz und Trigeminusneuralgie rechts, periodisch, scharf, pulsierend, Agg.: Anstrengung, drohende Apoplexie. Karotiden erweitert. Zusammenschnürender Kopfschmerz, gefolgt von Epistaxis. Dysmenorrhoe mit Konstriktionsgefühl, Amel.: Uterusblutung in Klumpen. Menses hören beim Hinlegen auf zu fließen (mit Herzsymptomen). Vaginismus. Abortus imminens. Dyspnoe, schwierige Atmung, Amel.: Liegen (Hauptmittel: Psor.)."},{"t":"Agg.: 11/23 Uhr, Kopfschmerz mehr 23 Uhr, Agg.: Fasten; Palpitationen, Agg.: Liegen auf der linken Seite; Belastung."},{"t":"Cadmium metallicum"},{"t":">GR:samkn>Cadmium. Wie bei Ars.: Entkräftung, Durchfall, starkes Frieren, üble Gerüche, aber nicht ruhelos wie Ars.."}],"rem":1,"orig":"Cactus grandiflorus"},{"label":"Caladium seguinum","short":"Caladium seguinum","group":"Arzneimittellehre","paras":[{"t":"Caladium seguinum, Schweigrohr. Geräuschempfindlichkeit. Niedergeschlagenheit. Keine Erektion trotz sexueller Erregung (Agn.; Lyc.; Sel.; Graph.). Penis klein und kalt, wie aus Knetmasse wie alter Waschlappen. Pollutionen auch ohne sexuelle Träume, ohne Erektion. Pruritus vulvae et vaginae in Schwangerschaft veranlaßt Lüsternheit. Kleine Mädchen masturbieren wegen Juckreiz von Würmern. Hinken. Extreme Raucher. Folge von Tabakabusus."},{"t":"Schläft ein während abendlichen Fiebers; erwacht, wenn Fieber sinkt. Süße Schweiße ziehen Fliegen an. Brennende und juckende Insektenstiche. Furcht vor Bewegung. Kehlkopf wie zugeschnürt. Katarrh. Asthma; Schleim löst sich nicht. Furcht, einzuschlafen. Juckender Ausschlag alternierend mit Asthma. Brennen. Erysipelartige Entzündung."},{"t":"Agg.: Bewegung; sexuelle Exzesse; Geräusche; beim Einschlafen; Tabak."},{"t":"Amel.: kühle Luft; Schweißausbruch; kurzer Schlaf."}],"rem":1,"orig":"Caladium seguinum"},{"label":"Calcarea arsenicosa","short":"Calcarea arsenicosa","group":"Arzneimittellehre","paras":[{"t":"Epilepsie von Herzklappenfehler mit Blutandrang zum Kopf vor dem Anfall; die Aura wird in Herzgegend gefühlt. Klimakterische Beschwerden von dicken Frauen. Chronische Malaria. Leber- / Milzvergrößerung bei Kindern. Nephritis mit großer Druckempfindlichkeit der Nierengegend; Albuminurie. Wassersucht. Trinkerbeschwerden bei Abstinenz. Frösteln."},{"t":"Illusionen; Gefühl des Fliegens. Selbsttäuschungen. Depression. Suizidgedanken. Ruhelosigkeit wie Ars.. Furcht vor Vögeln und Insekten. Verlangen nach Gesellschaft. Geringste Erregung verursacht Herzklopfen. Atemnot bei schwachem Herzen. Schwindel bei Kopfbewegung. Gesichtsakne."},{"t":"Kopfschmerz durch leichtesten Diätfehler, durch geistige Anstrengung, Amel.: Liegen auf schmerzhaften Seite. Brennender Schmerz bei Krebs; Uteruskrebs."},{"t":"Verlangen: Alkohol; Suppe."},{"t":"Abneigung: Hühnerfleisch."},{"t":"Agg.: geringste Anstrengung."}],"rem":1,"orig":"Calcarea arsenicosa"},{"label":"Calcarea fluorica","short":"Calcarea fluorica","group":"Arzneimittellehre","paras":[{"t":"Große Angst um Gesundheit; Furcht vor dem Ruin; vor nahender Krankheit (Kali-c.); vor dem Tod. Keine Hoffnung, jemals wieder zu genesen. Starke Anhänglichkeit an andere Menschen (Ars.), braucht viele enge Beziehungen. Abhängig. Manipulativ. Seufzen."},{"t":"Warmblütig, Agg.: Kälte, kalte Luft. Hitzewallungen, auch mit Herzklopfen oder Arrhythmie. Rheumatische Beschwerden mit Modalitäten wie Rhus-t.: Arthritis, Agg.: naßkaltes Wetter, Amel.: Wärme; Bewegung. Skoliose; Knochenkaries. Schmerzhafte Exostosen von Knochen: Wirbelsäule, Gelenke, Fersensporn, etc. Geschwürs- und Eiterungsneigung. Hautrisse und Fissuren. Analfissur. Fisteln. Steinharte Drüsenverhärtungen, Hoden, Zunge, Uterus (fibröser Tumor), Mamma. Zähne und Nägel hart und sehr zerbrechlich. Kongenitale Syphilis. Arteriosklerose."},{"t":"Keratitis, Konjunktivitis, Katarakt. Funkensehen. Subkutane Lidzysten. Otitis media mit chronischer Eiterung. Weißliche Ablagerung auf Trommelfell. Otosklerose. Ulzera im Mund. Lumbago, Amel.: heiße Anwendungen; Ischias. Osteoporose. Erweiterte Blutgefäße, Angiome; Aneurysma; Varizen."},{"t":"Verlangen: Süßes; Ei; Pikantes; Saures; Pickles; Geräuchertes."},{"t":"Abneigung: Milch; Kaffee."},{"t":"Agg.: Kälte und Nässe. Amel.: Wärme; Bewegung."}],"rem":1,"orig":"Calcarea fluorica"},{"label":"Calcarea iodata","short":"Calcarea iodata","group":"Arzneimittellehre","paras":[{"t":"Vergrößerte Tonsillen mit vielen kleinen Krypten. Vergrößerte Schilddrüse zur Pubertätszeit. Dickliche Kinder, empfindlich gegen Erkältungen. Sekretionen reichlich und gelb. Adenoide. Fibrom des Uterus. Kopfschmerz beim Fahren im kalten Wind. Krupp. Pneumonie."},{"t":"Extrem traurig. Große Schwäche."},{"t":"Leukorrhoe reichlich, gelb, wundmachend. Mammatumoren mit Schmerz, Agg.: Druck, Bewegung der Arme. Schmerzlose Ulzera bei Varikose. Milchschorf, Drüsenschwellungen, Haut rissig, Haarausfall. Schweißneigung."},{"t":"Starkes Verlangen nach frischer Luft, die verschlechtert. Krämpfe. Chorea. Zittern, Zucken."},{"t":"Agg.: Anstrengung; Fasten."}],"rem":1,"orig":"Calcarea iodata"},{"label":"Calcarea phosphorica","short":"Calcarea phosphorica","group":"Arzneimittellehre","paras":[{"t":"Anämische Kinder, dicklich, unzufrieden, ablenkbar, mit kalten Extremitäten und schwacher Verdauung. Spätes Stehen-/Laufenlernen. Spätes Sprechenlernen. Lernschwierigkeiten. Fehler beim Schreiben. Gedächtnisschwäche. Suppenkasper: keinen Appetit, abgemagert, bleich und wächsern. Schlaffes Abdomen. Kolikschmerz bei jedem Versuch zu essen. Verspäteter Fontanellen/Epiphysenschluß. Wachstumsschmerzen. Karies der Milchzähne. Schulkopfschmerzen. Baby fürchtet sich, wenn es aus Wiege gehoben wird."},{"t":"Zusammenbruch nach schwächenden Krankheiten, Liebeskummer, Ärger, schlechten Nachrichten: apathisch, gleichgültig, Abneigung gegen Gesellschaft. Seufzen. Innere Unzufriedenheit. Unglücklich. Beklagt sich. Andere sind an allem schuld. Mangelndes Durchhaltevermögen (vorher athletisch). Schwäche. Muskelschlaffheit, besonders Bauchmuskeln. Vorgewölbter Bauch, Rachitis und Skoliose. Akute Nackensteifigkeit mit Kummer und Seufzen. Will seine Ruhe haben und allein sein."},{"t":"Schmerz in Augen von künstlichem Licht; verschwommenes Sehen; Wundheitsgefühl der Augäpfel. Chronische Halsbeschwerden; vergrößerte Mandeln, fauliger Geschmack. Pubertätsbeschwerden der Mädchen bei verzögerter Reifung. Frösteln, das den Rücken hochsteigt. gesteigertes sexuelles Verlangen bis Nymphomanie. Kryptorchismus."},{"t":"Empfindung von elektrischen Schlägen. Rheumatismus mit Steifigkeit bei kaltem Wetter (Rhus-t.). Schmerz mit taubem, kaltem Gefühl und Kribbeln. Schmerz in Sakroiliakalgelenken, wie gebrochen. Gelenk- und Knochenschmerzen. Glieder schlafen ein. Exostosen. Langsame Frakturheilung. Schmerz an kleinen Stellen (z. B. nach Fraktur). Knochenmarkserkrankungen. Schwieriges Aufwachen. Stöhnen im Schlaf."},{"t":"Verlangen: Salziges; Geräuchertes; Schinken und Speck; Salami."},{"t":"Amel.: Essen; Wärme und warme Jahreszeit."},{"t":"Agg.: Wetterwechsel, naßkaltes Wetter; Schneeschmelze; Zugluft; morgens; Kummer; schlechte Nachrichten; körperliche und geistige Anstrengung; Denken an Beschwerden."}],"rem":1,"orig":"Calcarea phosphorica"},{"label":"Calcarea sulphurica","short":"Calcarea sulphurica","group":"Arzneimittellehre","paras":[{"t":"Streitsüchtig; eifersüchtig (sehr eifersüchtige Kinder); verträgt keinen Widerspruch. Haß auf Personen, die nicht seiner Meinung sind. Beklagt sich, weil nicht genug beachtet. Furcht vor Vögeln (Calc-ar., Ign.)."},{"t":"Jede Art von Gesichtsakne, normalerweise mit relativ kleinen Pickeln, Fisteln. Furunkel bricht auf; endlose chronische Eiterung, dick, gelblich, sahneartig: Tonsillen (mit Drüsenschwellung), aus Mundhöhle, Ohren, Nase, Augen, eitriger Durchfall, perirektaler Abszeß. Nach Schnitten, Wunden, Prellungen. Trockenes Ekzem bei Kindern."},{"t":"Hautrisse im Winter. Brennende, juckende Fußsohlen."},{"t":"Verlangen: unreife Früchte (Med.); Süßigkeiten."},{"t":"Agg.: Wärme; warmes Zimmer."},{"t":"Amel.: Kaltbaden."}],"rem":1,"orig":"Calcarea sulphurica"},{"label":"Calcarea silicata","short":"Calcarea silicata","group":"Arzneimittellehre","paras":[{"t":"Langsamer Beginn der Beschwerden und langdauernde Entwicklung."},{"t":"Beschwerden von geistiger Überforderung. Spricht mit Toten und träumt von Toten. Schwierige Konzentration beim Zuhören oder Lesen. Verwirrung von geistiger Überforderung. Gedächtnisschwäche für was er gesagt hat. Mangelndes Selbstvertrauen. Unentschlossen. Chronischer Reizung der Luftwege. Reichlicher gelbgrüner Schleim. Husten mit Kälte, Schwäche, Abmagerung, Empfindlichkeit und Unzufriedenheit, Agg.: kalte Luft. Interkostalschmerz."},{"t":"Reizbarkeit nach Koitus. Hauptmittel Gesichtsakne: rote Pickel, bereit, reif zu werden, werden's aber nicht. Obstipation. Frostig, aber Agg.: Überhitzung. Füße kalt, schweißig, @einw. Zehennägel; Schwer von Sil. zu unterscheiden."},{"t":"Agg.: nach Koitus; Überhitzung."}],"rem":1,"orig":"Calcarea silicata"},{"label":"Calcarea carbonica","short":"Calcarea carbonica","group":"Arzneimittellehre","paras":[{"t":"Baby wimmert und stöhnt; Kopfkissen naß; stößt Bettdecke weg; riecht sauer; Stuhl sauer; erbricht Milch. Appetitlos. Schwierige und verzögerte Zahnung mit Kopfschweißen und offenen Fontanellen. Drüsen Hals/Nackenbereich hart und geschwollen; wirkt unterernährt. Aufgeblähter Bauch, dickbäuchig. Mangelhafte Ossifikation. Ungenügende Assimilation."},{"t":"Kinder: spätes Stehen- und Gehenlernen. Neigung zum Dickwerden. Plump, weich, blaß; alles langsam, spät, schwer, schwach, vermeidet Anstrengung. Starke Schweiße am Kopf während des Schlafes. Das Kissen wir rundherum naß (Sil.; Sanic.). Füße kalt, schweißig, klamm. Dickliche, zu schnell wachsende Mädchen. Lungenerkrankungen bei großen und schlanken, schnell wachsenden Jugendlichen am rechten Oberlappen (links: Sulph.). Herzklopfen; Dyspnoe. Schmerzlose Heiserkeit, Agg.: morgens. Schleimeitrige Otorrhoe, Ausschlag hinter Ohr (Petr.)."},{"t":"Schulschwierigkeiten, Legasthenie. Händedruck schlaff und schweißig. Will nicht konkurrieren. Wehrt sich nicht, wenn Klassenkameraden ihn prügeln oder hänseln, obwohl er größer ist als seine Angreifer. Frostig (3-6 J. Hitze), Socken im Bett. Schlaf produziert Wärme, Füße brennen, werden herausgestreckt. Schläft auf der linken Seite. Magen wie umgedrehte Untertasse, sehr druckempfindlich. Schulbauchschmerz. Halsstarrig, stur; Nörgeln; Weinen; unzufrieden, weiß nicht, was er will, beklagt sich, mit 6-12 J. Interesse an Gott und Engeln."},{"t":"Erwachsener: Fühlt sich für alles verantwortlich, von ihm hängt alles ab; muß immer arbeiten und produktiv sein, Lebenszweck ist Arbeit, Angst, nicht mehr zu funktionieren, jedem zur Last zu fallen; häufig \"kopflastige\" Menschen. Voller Sorgen, Agg.: gegen Abend. Kann sich nicht an Gegenwart freuen, Kummer. Vergeßlich, konfus, mißgestimmt."},{"t":"Angst/Furcht: Dunkelheit, Gewitter, Zukunft, hochgel. Plätze, Armut; daß Verstandeskontrolle versagen könnte, verrückt zu werden, um Gesundheit, Krankheiten aller Art, Tod, furchtgetrieben, Hysterie, weiß nicht, was er will, immer erregter, will Dinge zerreißen, aus dem Fenster springen, Schreien, Weinen, am Rande des Wahnsinns. Furcht, andere könnten Verwirrung bemerken. Gefühl zu schweben, den Körper zu verlassen. Epileptische Aura, die vom Magen zum Kopf steigt, \"was Böses\" im Magen (Lyc.)."},{"t":"Verlangen, magnetisiert zu werden (Phos.)."},{"t":"Auster ohne Schale: ungeformte Persönlichkeit, empfindlich auf Kritik, wenig Selbstvertrauen. Grübelt wie Puls.; Resignation ohne Groll."},{"t":"Die Schale: Zuhause ist Schutz und Geborgenheit; tierlieb; Heimweh; sollte sich emotional mehr aus der Enge seines Muscheldaseins wagen. Eigensinn als Widerstand. Kopfschmerz nach Verausgabung, Amel.: Hinlegen linke Seite."},{"t":"Höhenschwindel und beim Kopfdrehen. Schlaflosigkeit ab 3 Uhr."},{"t":"Nasenlöcher wund, ulzeriert. Polypen. Erkältung bei jedem Wetterwechsel."},{"t":"Geschwollene Mandeln und Drüsen. Kropf. Parotisfistel. Abneigung gegen einengende Kleidung, besonders am Bauch (Lyc.). Inguinal- und Mesenterialdrüsen geschwollen. Leib aufgetrieben und hart. Gallensteinkolik."},{"t":"Feuchte Hände und Füße. Rheuma; Skoliose; Arthritis der Wirbelsäule, dann Extremitäten. Scharfes Stechen wie verrenkt. Fußsohlen rauh. Reißende Muskelschmerzen. Wadenkrämpfe. Hautausschläge; Allergien."},{"t":"Regel zu früh, zu reichlich, zu lange dauernd."},{"t":"Klimax: Osteoporose, Knochenbrüche, Nägel brechen, Nackenschweiß, Süßverlangen, Wallungen und kalte Extremitäten, Zahnfleischbluten, Gewichtszunahme."},{"t":"Agg.: Streß und Überanstrengung; kaltes Wetter; Feuchtigkeit; im Bett liegen (Schmerz); Milch; Treppensteigen."},{"t":"Amel.: Linksliegen; Wärme; trockene Hitze; bei Verstopfung; Gesellschaft."},{"t":"Verlangen: Süßes; Salz; Eier; Unverdauliches (Alum.); kalte Getränke."},{"t":"Abneigung: Fett; Fleisch."}],"rem":1,"orig":"Calcarea carbonica"},{"label":"Calendula officinalis","short":"Calendula officinalis","group":"Arzneimittellehre","paras":[{"t":"Calendula officinalis, Gartenringelblume. Fördert gesunde Granulation, beugt Eiterungen und verunstalteten Narben vor. Langsame Wundheilung."},{"t":"Infizierte Wunden; \"natürliche Wunden\" wie Gewebszerreißungen; schmerzhaft. Erysipelneigung. Nach chirurgischen Eingriffen. Traumatisches und idiopathisches Neurilemom (All-c.). Erschöpfung nach Blutverlust und starken Schmerzen."},{"t":"Ulzera: gereizt, schorfig; Ulcus varicosum; schmerzhaft, wie zerschlagen."},{"t":"Nervös, leicht schreckhaft."},{"t":"Ohren: Taubheit. Hört am besten im Zug und entfernte Geräusche. Erkältungsneigung bei feuchtem Wetter."},{"t":"Agg.: feuchtes, wolkiges Wetter."}],"rem":1,"orig":"Calendula officinalis"},{"label":"Camphora officinalis","short":"Camphora officinalis","group":"Arzneimittellehre","paras":[{"t":"Camphora, Kampferbaum. Schwäche und Reizbarkeit. Manie zu streiten, streitet gerne. Risus sardonicus. Verlassenheitsgefühl. Geschwätzigkeit, Kontrollverlangen. Großes Leiden, glaubt, in der Hölle zu sein. Komatöser Schlaf. Sonnenallergie."},{"t":"Extrem zugluftempfindlich. Furcht: nachts alleine; vor eigenen Gedanken."},{"t":"Starke Schmerzen mit gleichzeitigem Kältegefühl. Kalt anzufassen, kann aber Zudecken nicht ertragen. Wirft alle Hüllen von sich. Kalter Atem, Zunge, Nasenspitze. Eiskalte Hände, mag aber keine Handschuhe."},{"t":"Dauerhafte Epistaxis. Nieren/Blasenentzündung, wie Canth."},{"t":"Anfallsartiger Brechdurchfall. Cholera mit Kollaps und eisiger Kälte,"},{"t":"Agg.: Zudecken (Carb-v.). Schock mit kleinem, schwachen Puls, Blässe, lividen Lippen, Schwäche. Schmerz mit Kältegefühl an bestimmten Stellen. Fehlender Ausschlag bei Masern oder Scharlach. Folgen von Masern. Krämpfe. Tetanische Spasmen. Rheumatische Schmerzen zwischen den Schultern; Kälte, Vibrieren, Taubheit in Gelenken."},{"t":"Agg.: Kontakt; Zugluft; Kälte; Halbschlaf; Unterdrückung."},{"t":"Amel.: warme Luft; Trinken von kaltem Wasser; Absonderungen; Schweiß; Denken an Beschwerden."},{"t":"Komplementär zu Cantharis. Wenn Phos. versagt, an Camph. denken."}],"rem":1,"orig":"Camphora officinalis"},{"label":"Cannabis indica","short":"Cannabis indica","group":"Arzneimittellehre","paras":[{"t":"Cannabis indica, Haschisch. Typ 1: \"Flower-Power\". Freundlich, lieb, lacht, sanft und nachgiebig; nach Haschisch keine Aggressionen mehr, \"rund\" geworden, keine Ecken mehr am Charakter. Geistige Arbeit eher lästig. Ekstatisch, schwebend, \"spaced out\", nicht mit den Füßen auf der Erde. Gefühl, als sei der Kopf voller Luft. Sinneswahrnehmungen verzerrt. Zeit vergeht zu langsam. Lacht unkontrolliert über Kleinigkeiten. Verirrt sich auf bekannten Straßen (Glon.). Hellsichtigkeit, die der Patient loswerden möchte. (Beim Einschlafen) Gefühl, den Körper zu verlassen (ist Todesprozeß, fühlt sich dem Tode nahe); hat große Angst davor, alles erscheint unwirklich (Nux-m.; Alum.). Unwillkürliches Kopfschütteln."},{"t":"Typ 2: schnell, intelligent, viele Aspekte gleichzeitig, hochgebildet und belesen aber unfähig zu geistiger Arbeit. Geschwätzigkeit. Ideen sprunghaft (Lach.); relativiert jedes Symptom; kritisch."},{"t":"Große Angst, Kontrolle zu verlieren; wahnsinnig zu werden (Ars.; Nit-ac.). Theoretisieren: will bis in die letzte Einzelheit wissen, was der Homöopath tut, liest genau nach, stellt dann Fachfragen; oder: ständig besorgt, das Mittel antidotiert haben zu können."},{"t":"Beruflich bergab, kein Interesse mehr. Starker Durst. Angst vor dem Tod (Phos.; Ars.). Geistig übererregt; als ob jemand in seinem Kopf denkt. Unglücklich. Spürt Angst in Magen und Brust. Empfindung, eine Gliedmaße schwebe frei in der Luft. Folge von \"bad trips\" (Angstzustände durch Halluzinogene). Psychose: hält sich für wiedererschienenen Jesus Christus. Gynäkomastie. Heißhunger. Gehör verschärft. Starkes Sexverlangen; masturbiert viel; nicht wählerisch; akute GO. Blasen-/Harnröhren-/Niereninfekt. Neurologische Ausfälle; taube, schwache Extremitäten; Lähmungsvorstadien. Nach völligem Kontrollverlust Lähmung bis in den Verstand; keine Konzentration. Kann mit Augen nichts fixieren. Schwindel. Dumpfer Kopfschmerz (rechts), Gefühl als ob sich Schädeldecke öffnet und schließt (Cimic.), wie Elektroschocks im Gehirn. Müdigkeit; Urinabgang; muß immer liegen, keine Energie mehr (Ph-ac. auch aether. Trennung aber keine Panik). Alpträume im ersten Schlaf, Herzklopfen beim Erwachen."},{"t":"Stumpfsinn: benebelt, zerstreut (Hauptmittel: Ph-ac.)."},{"t":"Amel.: Ruhen; leichte Bewegung."},{"t":"Agg.: Urinieren; Dunkelheit; Überanstrengung; Sprechen; Gehen; GO."}],"rem":1,"orig":"Cannabis indica"},{"label":"Cannabis sativa","short":"Cannabis sativa","group":"Arzneimittellehre","paras":[{"t":"Cannabis sativa, Hanf. Akute Urethritis mit Absonderung aus der Harnröhre;"},{"t":"Schmerz in Urethra, erstreckt sich der Öffnung nach hinten, \"sengend\", brennend, beißend, in Pars posterior mehr Stechen, beim Wasserlassen. Häufig bei Zystitis der Frauen (eines der fünf Hauptmittel). Schmerz hauptsächlich in Urethra (wenn Blase schmerzhaft: anderes Mittel). Urethra sehr empfindlich auf Druck, kann nur breitbeinig gehen. Ziehende Schmerzen, zickzackartig Harnröhre entlang."},{"t":"Hartnäckige Obstipation, die Harnverhaltung verursacht; Konstriktion des Anus. Kontraktion der Finger nach Verstauchung. Dyspnoe oder Asthma, kann nur atmen, wenn er aufsteht. Verschlucken (Anac.). Akute GO."},{"t":"Empfindung, als fielen Wassertropfen auf einzelne Körperteile."},{"t":"(Cubeba: 2. Stadium der GO mit Brennen nach Harnlassen und dicker, gelber Absonderung)."}],"rem":1,"orig":"Cannabis sativa"},{"label":"Cantharis vesicatoria","short":"Cantharis vesicatoria","group":"Arzneimittellehre","paras":[{"t":"Cantharis, Spanische Fliege. Überempfindlich. Gemütszustand gewalttätig und heftig; Raserei (Stram.), Agg.: Berührung der Kehle, Wassertrinken. Akute Manie (sexuelle) mit Wut, Schreien, Bellen. Plötzlicher Bewußtseinsverlust mit rotem Gesicht. Ängste: Hydrophobie; vor glitzernden, Gegenständen; Spiegeln."},{"t":"Heftiges sexuelles Verlangen. Nymphomanie. Schmerzhafter Priapismus, zwingende Befriedigung bis es aus der Harnröhre blutet (Merc-c.). Zystitis mit enorm brennenden, ätzenden Schmerzen während Wasserlassens; Unerträglicher dauernder Harndrang, dann nur zwei Tropfen. Tenesmus. Strangurie. Hämorrhagie. Zystitis. Akute GO. Zäher Schleim in den Luftwegen mit Blasensymptomen."},{"t":"Brennen im Mund, Schlund, Rachen, beim Schlucken von Flüssigkeiten."},{"t":"Brennen in Ösophagus, Magen; brennender Durst mit Abneigung gegen Flüssigkeit."},{"t":"Brennen im Rektum mit Tenesmus und Schaudern nach dem Stuhl, schleimige, blutige Stühle, wie Abgeschabtes. Stark brennende Hautausschläge bei geringster Berührung, Folgen von Verbrennungen (Urt-u.). Erysipel. Bläschenausschläge über ganzen Körper, entzündet und eitrig. Erythem bei Sonnenbrand. Ergüsse bei Pleuritis und Perikarditis."},{"t":"Agg.: Wasserlassen; kalte Getränke; helle Objekt; Geräusch fließenden Wassers; Berührung des Kehlkopfs; Kaffee."},{"t":"Differentialdiagnose: Merc-c.: auch Tenesmus und Blutung aus Urethra, ebenso Darmtenesmus mit @hämorrh. Diarrhoe mit Brennschmerz, Merc-c. aber mehr Darmmittel."},{"t":"Differentialdiagnose: Petros.: plötzlicher Harndrang mit kräftigem Jucken in Urethra."}],"rem":1,"orig":"Cantharis vesicatoria"},{"label":"Capsicum annuum","short":"Capsicum annuum","group":"Arzneimittellehre","paras":[{"t":"Capsicum, Cayenne-Pfeffer. Träge, unbeholfen, fett, schlaff, unreinlich. Mangel an Lebenskraft und Lebenswärme. Indolent. Fürchtet jede Anstrengung."},{"t":"Kinder launenhaft, eigensinnig, widerspenstig; unbeholfen, fett, schmutzig. Fürchten frische Luft; immer fröstelnd; Abneigung gegen Arbeiten und Denken."},{"t":"Gibt sich heiter, nimmt Kleinigkeiten übel. Sehr empfindlich, leicht beleidigt. Reizbar und zornig. Delirium tremens; \"trockene\" Alkoholiker. Angst vor Polizei obwohl unschuldig (Merc.). Möchte alleine sein, sich hinlegen und schlafen. Nostalgie, unzufrieden mit dem Gegenwärtigen (Calc-p.); Heimweh (bei indolenten Melancholikern) mit roten Backen und Schlaflosigkeit 3-4 Std. nach dem Einschlafen. Rote Nase/Gesicht mit Hautgefäßen wie Alkoholiker. Diffuse Gesichtsröte."},{"t":"Rachenenge mit Hitze. Schmerz und Trockenheit im Rachen, in Ohren ausstrahlend. Brennende Zungenspitze. Stomatitis. Stinkender Mundgeruch. Magen schlaff wie ein Sack (kann in 1 Wo. 10 kg zunehmen). SW träge; Meteorismus. Stuhl blutig, schleimig mit Brennen und Tenesmus. Ziehender Schmerz im Rücken nach Stuhlgang. Durstig nach Stuhl, dabei Zittern. Blutende Hämorrhoiden. Stechender Schmerz beim Stuhl. Viel Durst, aber Trinken verursacht Schaudern. Frostschauer laufen Rücken hinauf und hinunter. Muß etwas Warmes im Rücken haben. Geräuschempfindlich während Schüttelfrost und bei akuter Erkrankung."},{"t":"Schmerzen brennen wie Pfeffer. Zusammenschnürung der Brust; Dyspnoe; Heiserkeit. Bei Husten Schmerz in entfernten Körperteilen (Knie, Blase, Rektum). Widerlicher Mundgeruch während des Hustens."},{"t":"Magengeschwüre. Empfindung kalter Luftzug durch Rektum. Durst nach Stuhlgang. Brennendrote Mundhöhle, Rachen; Mastoiditis mit Brennschmerz."},{"t":"Verlangen: starke Stimulanzien: Kaffee, Bier, Whisky, Pfeffer, Salz."},{"t":"Agg.: im Freien; Aufdecken; Zugluft; Kälte; Amel.: Essen; Hitze."},{"t":"Gesichtsröte: Ferr. und Puls. kleines abgegrenztes Areal."}],"rem":1,"orig":"Capsicum annuum"},{"label":"Carbolicum acidum","short":"Carbolicum acidum","group":"Arzneimittellehre","paras":[{"t":"Karbolsäure. Schreckliche Schmerzen kommen und verschwinden plötzlich (Bell.; Mag-p.). Anstrengung führt zu Abszeß irgendwo (meist rechtes Ohr). Äußerste Schwäche; Kollaps mit kaltem Schweiß (Camph.; Carb-v.; Verat.). Geruch stinkend/eitrig. Malignes, sept. Fieber. Sehr verfeinertes Geruchsempfinden. Vermehrte Geruchsempfindlichkeit. Stinkende, eitrige Absonderungen aus Nase, Mund, Rachen, Rektum, Vagina (Anthraci.; Psor.; Pyrog.). Toxische Zustände bei akuten Infektionskrankheiten, Diphtherie mit Gaumensegellähmung. Malig. Scharlach. Verstopfung mit stark stinkendem Atem (Pyrog.; Op.). Brennen von Mund bis Magen. Geblähtes Abdomen. Schmerzhafte Blähungen. Dyspepsie mit Gärung. Stuhl blutig, wie Abschabsel von Eingeweiden. Starker Tenesmus (Canth.). Stühle dünn, schwarz, eitrig. Urin fast schwarz. Diabetes. Reizblase bei alten Männern (Prostata). Erbrechen bei Trinkern, in Schwangerschaft, Seekrankheit, Krebs, von dunkler, olivgrüner Flüssigkeit (Pyrog.). Stirnkopfschmerz dumpf, schwer, als ob ein Gummiband eng über die Stirn gespannt wäre, von Schläfe zu Schläfe (Gels.; Plat.; Sulph.). Schock bei Bienen- und Wespenstich. Anaphylaxie. Blässe um Nase und Gesicht. Schwarzwerden betroffener Teile."},{"t":"Agg.: Whisky; Tabak; Stimulanzien; Lärm; Lesen; Schwangerschaft; Haarekämmen."}],"rem":1,"orig":"Carbolicum acidum"},{"label":"Carbo animalis","short":"Carbo animalis","group":"Arzneimittellehre","paras":[{"t":"Carbo animalis, Tierkohle. Schwäche während Menses."},{"t":"Verrenkung und Überheben verursacht große Schwäche; schwache Gelenke, leicht verstaucht (Led.)."},{"t":"Kopfschmerz, als wäre Kopf explodiert; muß nachts aufsitzen und Kopf zusammenhalten. Gehör verwirrt, kann Geräusche nicht räumlich orten. Stagnierender Blutfluß. Furcht vor der Dunkelheit."},{"t":"Schwäche stillender Mütter, sie weinen während des Essens, unfähig, durch das Zimmer zu gehen. Verlangen, alleine zu sein."},{"t":"Gefühl, als ob das Auge locker ist."},{"t":"Schlechte Verdauung. Blähsucht. Folge von verdorbenem Fisch und verfaultem Gemüse."},{"t":"Menses nur morgens. Krebs von Mammae, Ovarien, Uterus mit Brennschmerz."},{"t":"Nach Auftreten der Menses so schwach, daß sie kaum reden kann."},{"t":"Brennschmerz des Steißbeines bei Berührung. Schwache Gelenke, leicht verrenkt."},{"t":"Schmerzhafte Narben, Agg.: Wetterwechsel. Alte Narben brechen auf. Drüsenschwellung und -verhärtung, steinhart. Fröstelig; Frösteln, auch nachts im Bett. Krebs in Familienanamnese."},{"t":"Unvollständig Verbrennung. Unterdrückte emotionale Prozesse üben Druck aus. Nimmt die Forderung des Altwerdens nicht an. Isolation, Steifigkeit, Ängstlichkeit. Ablehnend, Sklaven ihrer starren Ansichten."},{"t":"Introvertiert, zurückgezogen. Hager. Dunkel."},{"t":"Verlangen: Alleinsein, Abneigung: Menschen, unbeholfen in Gesellschaft. Romantischer Wunsch nach Veränderung (nicht wie Tub.); Melancholie, Sehnsucht nach Freiheit, nach Vergangenheit, Heimweh."},{"t":"Abneigung und Unfähigkeit, mit Veränderungen fertig zu werden; entmutigt, verlassen, reizbar, hoffnungslos, Todesgedanken."},{"t":"Angst: Dunkelheit; beim Einschlafen. Beschwerden durch Meditation."}],"rem":1,"orig":"Carbo animalis"},{"label":"Carboneum sulphuratum","short":"Carboneum sulphuratum","group":"Arzneimittellehre","paras":[{"t":"Carboneum sulfuratum. Reizbar, ängstlich, intolerant; Stupor. Schwerfälligkeit. Leicht beleidigt. Gesichts- und Gehörshalluzinationen. Verwirrung, als ob vergiftet. Vergißt, was er mit Gegenstand, den er in der Hand hat, tun wollte; zerbricht ihn, wenn angesprochen. Starrt auf seine Finger. Demenz wechselnd mit Erregung."},{"t":"Tränenfluß. Kurzsichtig; Sehschwäche; Farbenblindheit; Zentralskotom bei Neuritis nervi optici, Atrophie; bei neurologischen Erkrankungen wie Multipler Sklerose. Alles scheint im Nebel. Sehkraft Amel.: Zwielicht; Essen. Spinnweben vor dem Auge. Gehör geschwächt. Plötzlicher Schwindel, Agg.: Sitzen. Menière mit Ohrgeräuschen (summend, singend wie äolische Harfe)."},{"t":"Diarrhoe alle 4-6 Wochen. Zusammenschnürungsgefühl des Herzens (überall möglich, Bandgefühl). Intoleranz von Kleidungsstücken."},{"t":"Chronischer Rheumatismus, sensibel und kalt. Verringerte Sensibilität in Armen, Händen und Füßen. Periphere Neuritis. Lähmung; Tabes; sensorische Störung; Ischias. Chronischer Bleischaden. Impotenz bei Atrophie."},{"t":"Agg.: Kälte und Hitze; Wetterwechsel nach schwül; Zugluft; kalte Füße; warmes Essen."}],"rem":1,"orig":"Carboneum sulphuratum"},{"label":"Carbo vegetabilis","short":"Carbo vegetabilis","group":"Arzneimittellehre","paras":[{"t":"Carbo vegetabilis, Holzkohle. Benommenheit durch feuchte Luft. Plötzlicher und periodischer Gedächtnisverlust. Fixe Ideen. Trägheit des Kreislaufs (venöse Stase), der Reaktionskraft, auch geistig/emotional. Große Gleichgültigkeit (zwischen Ph-ac. und Sep.); schlechte Laune (Sep.);"},{"t":"Angst: Gesundheit; Geister; Unfälle; Dunkelheit; die Augen zu schließen. Plötzlicher Gedächtnisverlust."},{"t":"Schlimme Folgen erschöpfender Krankheiten (auch Schock). Kachexie und Schwäche. Nach Säfteverlust; Hämorrhagien. Kälte durch ganzen Körper: Atem, Nase, Gesicht, Extremitäten. Plötzlicher kollapsartiger Zustand mit Facies hippocratica: blaß; graugelb, grünlich, kalt mit kaltem Schweiß. Plötzliches gewaltsames Erbrechen."},{"t":"Häufige, unfreiwillige, kadaverartig riechende Stühle mit nachfolgendem Brennen; weicher Stuhl wird mit Schwierigkeit entleert (Alum.)."},{"t":"Gastritis, Kolitis, extreme Blähungen, Amel.: Aufstoßen, Agg.: Überessen, Fett, Butter. Die einfachste Speise bekommt schlecht; Roemheld."},{"t":"Asthma oder Dyspnoe von Meteorismus; nach dem Essen."},{"t":"Häufiges Erwachen wegen kalter Glieder; nachts kalte Knie (Apis)."},{"t":"Heiserkeit, Agg.: abends; feuchte Abendluft; feuchtwarmes Wetter; Stimme versagt, wenn er sie anstrengt."},{"t":"Atmung erschwert im Liegen, schläft mit mehreren Kissen im Rücken, beinahe im Sitzen."},{"t":"Kopfschmerz, zusammenschnürend, Agg.: Überhitzung; Hinlegen."},{"t":"Dünne, alte Menschen mit schlecht heilenden indolenten Ulzera."},{"t":"Verlangen: Salz; süß (Arg-n.); Dinge, die er nicht verträgt (Kaffee)."},{"t":"Abneigung: Fett (Gallenkoliken)."},{"t":"Agg.: Hinlegen (trotz Schwäche); abends; üppiges Essen; Folge von Chininbehandlung; Quecksilberabusus; Salz; verdorbenem Fisch, Fleisch oder Fetten; nach Überhitzung (Ant-c.)."},{"t":"Amel.: Aufstoßen; Flatus; Luftzufächeln; Liegen mit erhöhtem Kopf."},{"t":"\"Eingewickelt in Heizdecke, Ventilator ins Gesicht, sitzt sie im Bett und liest Horrorromane\". Sucht nach Stimulus, um System anzuregen; kann daher auch promiskuitiv sein."}],"rem":1,"orig":"Carbo vegetabilis"},{"label":"Carcinosinum","short":"Carcinosinum","group":"Arzneimittellehre","paras":[{"t":"Carcinosinum, Krebsnosode. Erbbelastung: krebsartige Erkrankungen; Tuberkulose; Diabetes; Perniziosa. Folgen von Mononukleose."},{"t":"Auftreten von Kinderkrankheiten (Masern; Mumps) nach der Pubertät."},{"t":"Schwerer Keuchhusten, Pneumonie, rezidivierende Infekte in frühester Kindheit."},{"t":"Säuglinge mit Milchkaffeeteint, blauen Skleren, zahlreichen Naevi."},{"t":"Kinder übertrieben ängstlich, schüchtern, die sich nicht zu verteidigen wissen; Weinen bei der geringsten Schwierigkeit; liebt Rhythmus und Tanz, sobald es Musik hört; Freude an Gewittern (Sep.)."},{"t":"Kinder sehen aus wie Sepia: dünn, erregbar, sprühend vor Energie, Verlangen zu tanzen, frühreif, überbegabt, \"kleine Erwachsene\", mit Asthma oder Neurodermitis. Lernschwierigkeiten, geistige Behinderung. Gleichgültigkeit. Geschwisterneidsyndrom."},{"t":"Furcht: Hunde, Tiere; Dunkelheit; Examensängste; Ängste bis Panik; Störungen durch Schockerlebnisse (Acon.; Op.); Kollaps durch Schock. Mitfühlend (Phos.), sehr liebesbedürftig, übertrieben empfindlich auf Vorwürfe (Sep.). Abneigung gegen Trost. Große Liebe zur Natur."},{"t":"Zwangsneurose. Übertrieben genau, ordentlich, Perfektionismus, Neigung zum Intellektuellen; Schwermut, Melancholie, Reizbarkeit; Suizidneigung; starker Geschlechtstrieb. Café-au-lait-Teint, Muttermale."},{"t":"Komplizierte und seltene Tics: reißt sich Haut um Nägel ab; zwanghafter Lidschlag. Abneigung gegen jede Tätigkeit, selbst Lieblingsbeschäftigung. Ausgeprägtes Wohlbefinden kurz vor Ausbruch einer Krankheit (Psor.; Nux-v.). Wechselnde Symptome (Lac-c.; Sep.; Tub.). Häufige Kombination von Tub.- und Med.-Symptomen."},{"t":"Verlangen: Geräuchertes (Calc-p.; Caust.; Kreos.; Tub.); Salz; Eier; Obst; fettes Fleisch (Ars.; Hep.; Nit-ac.; Nux-v.; Sulph.); Butter; Süßigkeiten; Zucker."},{"t":"Abneigung: Salz; Obst; Milch."},{"t":"Agg.: Meeresluft; Hitze oder Kälte; nach dem Aufstehen; 13-18 Uhr; Trost; Unterhaltung."},{"t":"Amel.: Meeresluft; Hitze oder Kälte; Gewitter."},{"t":"Verwandtschaft: die vier klassischen Nosoden (Med.; Syph.; Psor.; Tub.);"},{"t":"die fünf klassischen tuberkulinischen Mittel (Calc-p.; Nat-m.; Phos.; Puls; Sep.);"},{"t":"Alum.; Ars.; Ars-j.; Lyc.; Staph.; Op.; Sanic.; Sulph.; Thuj.."},{"t":"Infektlabilität; Niesanfälle; Heuschnupfen."},{"t":"Starker drückender Hinterkopfschmerz mit Ausstrahlung zur Schädelbasis und zum Nacken, Agg.: beim Aufstehen morgens."},{"t":"Schlaflosigkeit: Einschlafstörungen, Ideenandrang. Knie-Ellenbogen-Lage (Calc-p.; Lyc.; Med.; Phos.; Sep.; Tub.)."},{"t":"Haut: Naevi; Gesichtsakne; Keloidbildung; Ausschläge bevorzugt axillar mit Achselschweiß, in Kniekehlen, an Füßen. Neurodermitis."},{"t":"Mund: Schmerz Gaumen, Agg.: Wärme, Amel.: Kälte. Keine Papillen an Zungenspitze."},{"t":"Herz: Herzklopfen so stark, daß er es im ganzen Körper hört. Einschnürungsgefühl; Angina pectoris. Druck in Brust mit Verlangen, tief einzuatmen (Ign.). Lippenzyanose. Pulsieren und Klopfen einzelner Körperteile. Kollaps durch Schock."},{"t":"Husten: Kitzelhusten suprasternal, Agg.: Lachen, Sprechen. Asthma am Meer."},{"t":"Appetitlosigkeit. Morgenerbrechen. Angstgefühl in Magengrube. Chronische Hepatitis, Lebervergrößerung mit @diff. Empfindlichkeit. Verstopfung ohne Drang, Stuhl schaftskotartig. Obstipation abwechselnd mit Durchfall. Schwimmender Stuhl. Azetonämie."},{"t":"Carduus marianus"},{"t":"Carduus marianus, Mariendistel."},{"t":"Pfortaderstauung. Alkoholismus. Varizen. Aszites. Leberzirrhose. Empfindlichkeit des linken Leberlappens. Gallensteine. Asthma bei Minenarbeitern. Hüftschmerz. Appetitlosigkeit. Bitterer Geschmack. Gestörter Zuckerstoffwechsel. Erbrechen saurer, grüner Flüssigkeit. Influenza, Lungenerkrankungen zusammen mit Leberproblemen. Ikterus. Stiche in Leber und Milz."},{"t":"Verstopfung abwechselnd mit Durchfall. Blutende Hämorrhoiden."},{"t":"Schmerz der unteren Rippen, Agg.: Husten, Atmung, Bewegung. Brustschmerz strahlt aus zu Schultern, Rücken, Abdomen, mit Harndrang. Schmerz vom rechten Schulterblattwinkel zur rechten Brust."},{"t":"Hüftschmerz strahlt aus zum Gesäß, Schenkeln, Agg.: Bücken. Variköse Ulzera."},{"t":"Blutungen und Aszites bei Leberkrankheiten."},{"t":"Abneigung: Salz; Fleisch."},{"t":"Agg.: Bier; Druck; rechts liegen. Amel.: Druck, Zusammenkrümmen (bei Gallenkolik)."}],"rem":1,"orig":"Carcinosinum"},{"label":"Cascarilla","short":"Cascarilla","group":"Arzneimittellehre","paras":[{"t":"Cascarilla. Hunger nach den Mahlzeiten. Verlangen nach heißen Getränken. Übelkeit und Erbrechen. Magenschmerz wie von einem Schock. Pressende Kolik. Gefühl, als sei Abdomen voll mit heißem Wasser."},{"t":"Verstopfung; Stühle hart, schleimbedeckt (Graph.). Helles Blut beim Stuhlgang. Durchfall wechselnd mit hartem, klumpigem Stuhl mit Rückenschmerz und Mattigkeit, vorher kneifender Schmerz. Dauernder Stuhldrang mit nagendem Schmerz hoch oben im Rektum."},{"t":"Verlangen: heiße Getränke."},{"t":"Abneigung: Tabakrauch."},{"t":"Amel.: heiße Getränke."}],"rem":1,"orig":"Cascarilla"},{"label":"Castor equi","short":"Castor equi","group":"Arzneimittellehre","paras":[{"t":"Castor equi, \"rudimentäre Pferdezehe\", warzenähnlich. Splitternde Nägel, fallen aus. Rissige und ulzerierte Brustwarzen; sehr berührungsempfindlich, auch auf Kleiderdruck. Schwellung der Brüste. Heftiges Jucken in der Brust; Hof gerötet."},{"t":"Lachen bei ernsten Angelegenheiten."},{"t":"Psoriasis der Zunge. Schmerz in Mammae, Agg.: Treppabgehen. Steißbeinverletzung, sehr schmerzhaft; Schmerz im rechten Schienbein. Warzen auf Stirn und Mammae. Rissige Hände. Pferdeallergie."}],"rem":1,"orig":"Castor equi"},{"label":"Castoreum canadense","short":"Castoreum canadense","group":"Arzneimittellehre","paras":[{"t":"Castoreum, Bibergeil, Sekret der Bauchdrüsen des Bibers. Hysterische Symptome. Nervöse Frauen, die sich nach schwerer Krankheit nicht völlig erholen, sondern dauernd reizbar sind und an schwächenden Schweißen leiden. Spastische Beschwerden nach schwächenden Krankheiten. Dauerndes Gähnen. Ruheloser Schlaf mit schrecklichen Träumen und Hochfahren."},{"t":"Erbsengroße Erhebungen in der Mitte der Zunge mit Ziehen vom Zentrum zum Zungenbein. Zungenschwellung."},{"t":"Traurigkeit während der Menses. Weinen wegen Kleinigkeiten. Dysmenorrhoe; Blutung tropfenweise, mit Tenesmus. Amenorrhoe mit schmerzhaftem Blähleib."},{"t":"Tagblindheit; kann Licht nicht ertragen."},{"t":"Großer Durst nach dem Abendessen."},{"t":"Frostig mit Eiseskälte des Rückens."},{"t":"Amel.: Druck; Krümmen."}],"rem":1,"orig":"Castoreum canadense"},{"label":"Caulophyllum thalictroides","short":"Caulophyllum thalictroides","group":"Arzneimittellehre","paras":[{"t":"Caulophyllum, Blauer Cohosch, Frauenwurzel. Arthritis. Uterusbeschwerden. Schwerer, ziehender, wandernder Schmerz und Steifheit. Schneidende Schmerzen beim Händeschließen. Unregelm. Schmerzen, alle paar Minuten den Ort wechselnd. Arthritis der Hände oder Füße, besonders Arthritis der Finger, vornehmlich der letzten beiden Fingerglieder, Zeige- und Mittelfinger, entsprechend Glieder der Fußzehen; Hand- und Sprunggelenke."},{"t":"Außerordentliche Starrheit des Muttermundes (Bell.; Gels.; Verat-v.). Starke, spastische Schmerzen, in alle Richtungen strahlend. Falsche Wehen. Habitueller Abort wegen Uterusschwäche (Helo.; Puls.; Sabin.). Nadelartige Schmerzen in Zervix. Persistierende Lochien. Schwere Atonie. Menses und Leukorrhoe reichlich."},{"t":"Mundfäule. Verfärbung der Haut bei Frauen mit Menstrual- und Uterusbeschwerden."},{"t":"Chorea, Epilepsie, Hysterie in der Pubertät."},{"t":"Differentialdiagnose: Act-s.: kleine Handknochen."},{"t":"Differentialdiagnose: Caust.: auch Fingerarthritis. Caul., wenn der Patient außerdem keine Beschwerden hat, sonst eher Caust."}],"rem":1,"orig":"Caulophyllum thalictroides"},{"label":"Causticum","short":"Causticum","group":"Arzneimittellehre","paras":[{"t":"Causticum Hahnemanni. Gelber, blasser Teint; Erkrankung des Respirations- und Harntrakts. Empfindsam, leicht erregbar, sehr aufgeschlossen; rege Wahrnehmung (Phos. schneller, gewandter);"},{"t":"Kind: an anderen Menschen interessiert, offen, beteiligt, sensitiv wie Sep., offen wie Phos., verletzlich. Kinder lernen spät laufen (Calc-p.)."},{"t":"Schwankendes Gehen und leichtes Fallen kleiner Kinder."},{"t":"Sinn f. soziale Gerechtigkeit; Ungerechtigkeit wird höher gestellt als die Menschlichkeit, (Phos. niemals). Weinen aus Mitgefühl für Schmerz anderer. Weinen aus geringstem Anlaß. Duldet keine Unterdrückung. Tief und leicht verletzbar; idealistisch, ernst."},{"t":"Folge von Schreck, Furcht, Enttäuschung, Beleidigung, andauerndem Kummer (Nat-m.; Ign.; Aur.; Ph-ac.; Phos.; Staph.), andauernden Sorgen (Ph-ac.), Schlafmangel, Nachtwachen, unterdrückten Hautausschlägen. Energie nach innen: Schwäche auf allen Ebenen. Allmählich fortschreitende Paralyse (Con.). Lähmung nach psychischem. Schock. Glaubt, etwas vergessen zu haben. Weinen bei TV-Nachrichten."},{"t":"Furcht, daß etwas schlimmes passiert; Dunkelheit; Alleinsein nachts; Hunde. Emotional verfeinert; starke Gefühle, aber schwacher Ausdruck. Geist müde. Verwirrung beginnt; zuerst Hypersensibilität und Hyperaktivität ZNS und PNS; Ataxie; Myopathie; Multiple Sklerose; Myasthenie."},{"t":"Lähmung einzelner Körperteile: Stimmapparat; Schluckapparat; Zunge; Augenlider (hängen schlaff herab); Gesicht; Blase; Extremitäten: Schwäche rechter Deltoideus, Muskelschwäche durch Überanstrengung und Kaltwerden, (Regen)-nässe, Urs. oft unterdrückter Ausschlag. Schmerz in gelähmten Gliedmaßen wie Stromstöße (Arg-n.; Alum.);"},{"t":"Rheumatisches Reißen in den Gliedmaßen, Amel.: Wärme, besonders Bettwärme. Brennen in Gelenken. Gelenksteifigkeit, Kniekehle; Spannung und Verkürzung der Muskeln (Cimex; Guaj.; Nat-m.); krampfartiger Schmerz; entzündete Sehnen (Hauptmittel); Muskelzuckungen; Kontrakturen; Dupuytren; Zittern; Konvulsionen; Chorea; Torticollis; nervöse Ruhelosigkeit in Beinen;"},{"t":"Warzen im Gesicht, an Fingern in Nagelnähe; Fissuren Anus, Damm. Ausschlag um Nase, Nasenflügel, -spitze (Aeth.). Heuschnupfen mit Jucken der Nasenflügel, Niesen beim Erwachen, mit zähem Rachenschleim."},{"t":"Verstopfte Nase."},{"t":"Stimmbeschwerden bei Sängern und öffentlichen Rednern. Heiserkeit mit Brustschmerz; Aphonie, Agg.: morgens."},{"t":"Bronchitis wie roh, muß sich die Brust halten; gewaltiger, tiefer, hohler Husten mit Urinabgang beim Niesen, Lachen; Amel.: Trinken von kaltem Wasser. Kann sich nachts nicht hinlegen. Spärlicher Auswurf. Schleim hinter Brustbein, kann nicht tief genug atmen, um Schleim zu lösen. Steingefühl (überall möglich). Husten mit Hüftschmerz. Schleim muß geschluckt werden (Arn.; Kali-c.). Stimme hallt wider. Urethra empfindungslos. Enuresis. Vermindertes sexuelles Verlangen; Impotenz (Phos. mehr Verlangen), kein Vergnügen am Sex."},{"t":"Obstipation mit häufigem, erfolglosem Drang (Nux-v.), Amel.: im Stehen."},{"t":"Stuhl zäh, glänzt wie Fett; bei Kindern mit Bettnässen."},{"t":"Alte Narben, v. allem Verbrennungen und Verbrühungen brechen wieder auf."},{"t":"Abneigung: Süßigkeiten."},{"t":"Verlangen: salzig; Geräuchertes (Calc-p.; Tub.; Kreos.)."},{"t":"Agg.: trockenkaltes Wetter; kalte Bäder; Naßwerden; Zwielicht; nachts; Zug; Darandenken. Kann sich nicht warm genug zudecken, aber Wärme erleichtert nicht."},{"t":"Amel.: feuchtkaltes Wetter; Regen; Nebel; kalte Getränke (Gastritisschmerz und Husten)."},{"t":"Differentialdiagnose: Lähmung Oberlid: Caul.; Gels.; Graph.; Sep."}],"rem":1,"orig":"Causticum"},{"label":"Ceanothus americanus","short":"Ceanothus americanus","group":"Arzneimittellehre","paras":[{"t":"Ceanothus americanus, Seckelblume. Enorme Milzvergrößerung. Splenitis; Schmerz in linker Rippenbogengegend, die ganze linke Seite hinauf. Leber- und Milzvergrößerung durch Malaria. Schmerz in Leber und Rücken. Leukämie. Linksseitigkeit."},{"t":"Heftige Atemnot. Menses reichlich, gelber, schwächender Ausfluß. Unfähig, auf der linken Seite zu liegen."},{"t":"Durchfall. Nachuntenziehen in Bauch und Rektum."},{"t":"Dauernder Harndrang. Urin grün, schaumig, gallig, enthält Zucker."},{"t":"Einbildung, arbeitsunfähig zu werden."}],"rem":1,"orig":"Ceanothus americanus"},{"label":"Cedron","short":"Cedron","group":"Arzneimittellehre","paras":[{"t":"Quassia cedron, Bitteresche. Periodizität, täglich zur selben Stunde. Neuralgische Schmerzen; Malaria; Kopfschmerz 9 Uhr; Kopfschmerz quer über Stirn zum Verrücktwerden."},{"t":"Schmerz im Augapfel mit ausstrahlenden Schmerzen um das Auge."},{"t":"Ganzer Körper erscheint taub von Kopfschmerz."},{"t":"Periodische Supraorbitalneuralgie. Iritis. Chorioiditis."},{"t":"Lanzinierender Schmerz in Gelenken, vor allem Händen und Füßen. Plötzlicher Schmerz in rechtem Daumenballen, in Arm und Schulter ausstrahlend. Herpes Zoster."},{"t":"Taubheit der Extremitäten während Fieber."},{"t":"Besonders nützlich in tropischen Ländern. Schlangenbisse."},{"t":"Agg.: Koitus; 9 Uhr."}],"rem":1,"orig":"Cedron"},{"label":"Cenchris contortrix","short":"Cenchris contortrix","group":"Arzneimittellehre","paras":[{"t":"Cenchris contortrix, Gift der Mokassinschlange."},{"t":"Atemnot; körperliche und geistige Ruhelosigkeit (Ars.). Durst auf kleine Mengen Wasser, muß Kleidung locker tragen (Lach.). Stimmungsschwankungen. Vermehrte Libido. Schmerz rechte Eierstockgegend."},{"t":"Träumt schlecht und lebhaft (von Schlangen und Räubern)."},{"t":"Geistesabwesend, falsche Handlungen, ohne es zu merken."},{"t":"Leerschlucken schwierig."},{"t":"Als ob das Herz die ganze Brust ausfüllt; Flattern unter dem linken Schulterblatt."}],"rem":1,"orig":"Cenchris contortrix"},{"label":"Chamomilla","short":"Chamomilla","group":"Arzneimittellehre","paras":[{"t":"Matricaria chamomilla, Echte Kamille. \"Zu widerwärtig und zu garstig, als daß man mit so einem Menschen leben könnte\" (Ghegas). Folge von Kaffee- und Narkotikaabusus (auch Marihuana). Große Reizbarkeit; Jammern; quengelige Ruhelosigkeit; launisch, ungeduldig, trotzig, schnippisch. Wut und Zorn und deren Folgen; Sich-Beklagen. Kinder möchten getragen werden, oder: mag nicht berührt, angefaßt oder angesprochen werden. Kinder mit Zahnungsbeschwerden, Bauchkoliken, Mittelohrentzündungen."},{"t":"Große Licht-, Geräusch-, Lärm- und Schmerzempfindlichkeit. Schnell verzweifelt durch Schmerz. Schmerz mit Taubheit der befallenen Körperteile. Heiße Nachtschweiße. Zahnschmerz, Agg.: warme Getränke; Kaffee; Luftzug; Wärme; während Menses oder Schwangerschaft. Im Gesicht eine Wange gerötet und heiß, die andere blaß und kühl."},{"t":"Ohrenschmerz mit Wundheit, Schwellung, Hitze, stechend, Verstopfungsgefühl."},{"t":"Rauheit des Kehlkopfes. Trockener, kitzelnder Reizhusten; erstickende Enge mit rasselndem Schleim."},{"t":"Drückender Magenschmerz, wie von einem Stein. Gallenkolik. Duodenitis."},{"t":"Diarrhoe wie gehackte Eier mit Spinat: grün, wässerig, wundmachend, heiß, stinkend wie faule Eier, Agg.: Zahnung; Kälte; Zorn; Tabak; Kindbett; Abwärtsbewegung. Wehen, zur Verzweiflung treibend."},{"t":"Krämpfe bei Kindern vom Stillen nach Wutausbruch der Mutter."},{"t":"Brustwarzen berührungsempfindlich. Gelber, scharfer Weißfluß. Metrorrhagie mit wehenartigem Schmerz. Im Klimakterium: Blutung durch Ärger."},{"t":"Lumbago. Halswirbelsäule-Syndrom. Sprunggelenke geben nachmittags nach. Lähmungsartige Kraftlosigkeit in den Füßen. Rheumatische Schmerzen, treiben nachts aus dem Bett, zwingen zum Umhergehen."},{"t":"Viel Lebenswärme, Agg.: Wärme und Hitze; streckt die Füße unter der Bettdecke hervor. Fieber 9 Uhr, Agg.: Zorn (Nux-v.)."},{"t":"Verlangen: kaltes Wasser; saure Getränke."},{"t":"Abneigung: Kaffee; warme Getränke; verabscheut Wind."},{"t":"Agg.: Wut/Zorn; Zahnung; Kaffee; 9/21 Uhr; Hitze; im Freien, Wind; Luftzug; Aufstoßen."},{"t":"Amel.: Getragenwerden; Schweiß; mildes Wetter."},{"t":"Differentialdiagnose: Anth.: alles wie Cham., aber Mangel an Lebenswärme; auch an Cina denken."}],"rem":1,"orig":"Chamomilla"},{"label":"Chelidonium majus","short":"Chelidonium majus","group":"Arzneimittellehre","paras":[{"t":"Chelidonium majus, Schöllkraut. Leber: Vergrößerung, Hepatitis, Gallensteine, Cholestase@, Ikterus, Juckreiz. Zunge gelb, Zahneindrücke. Geschmack bitter, pappig, schlechter Mundgeruch. Dauerschmerz unter unterem Winkel des rechten Schulterblatts. Übelkeit, Erbrechen, Amel.: sehr heißes Wasser (Milch)."},{"t":"Schmerz durch Magen zum Rücken und rechtem Schulterblatt, Amel.: Essen. Schmerz bandförmig quer über Abdomen, zusammenschnürend. Stuhl schafkotartig; abwechselnd Durchfall und Verstopfung. Gärung und träge Darmtätigkeit. Juckreiz, Brennen des Anus. Urin gelb wie Bier."},{"t":"Kopf: Schweregefühl wie von Blei, mit eiskaltem Hinterkopf, vom Nacken aus. Schwindel mit Leberstörung. Neuralgie über rechtem Auge, Wange, Ohr, bei Leberstörung; Tränenfluß. Kopfschmerz hinter Ohren, in das Schulterblatt ausstrahlend. Nackenschmerz, steifer Nacken, Kopf nach links gezogen."},{"t":"Pneumonie rechts. Krampfartiger Husten; Schmerz beim tiefen Einatmen. Schleimklumpen fliegen beim Husten aus dem Mund."},{"t":"Arthritisschmerz nach Leberkrankheit. Rheumatische Hüft- und Oberschenkelschmerzen. Knieschmerz, 2 QF subpatellar, Agg.: Umhergehen (Hauptmittel). Fersenschmerz wie eingeschnürt. Parese der unteren Gliedmaßen mit Härte der Muskeln."},{"t":"Eiskalte Fingerspitzen, schmerzhafte Handgelenke. Schlaf unerquicklich."},{"t":"Agg.: rechte Seite; 4/16 Uhr; Kälte allgemein; Wetterwechsel; Berührung; Umhergehen; Übelkeit und Blähungen nach Käse und Milch; frische Luft, Licht (Kopfschmerz)."},{"t":"Amel.: heiße Getränke und Speisen; Essen; Druck; Liegen auf der linken Seite mit angezogenen Beinen; Zurückbeugen."},{"t":"Verlangen: heiße Nahrung und Getränke; Käse; Pikantes; heiße Milch."},{"t":"Ähnlich Lyc. (ohne Lyc.-Feigheit). Fordernd, pragmatisch, kraftvoll, will überzeugen. Kämpft für seine Meinung. Erwartet Zuneigung von anderen, kann seine Gefühle aber schlecht ausdrücken. Realistisch; eigensinnig, wegen Kleinigkeit beleidigt; anti-intellektuell; große Abneigung gegen geistige Arbeit; apathisch. Angst um andere (aus Schuldgefühl); Gewissensangst; um Gesundheit. Gute Geschäftsleute, Makler. Kann seine Gefühle schwer ausdrücken."},{"t":"Differentialdiagnose: Card-m. Leberschmerz, Agg.: Liegen auf der linken Seite."}],"rem":1,"orig":"Chelidonium majus"},{"label":"Chimaphila umbellata","short":"Chimaphila umbellata","group":"Arzneimittellehre","paras":[{"t":"Chimaphila umbellata, Dolden-Winterlieb. Prostatavergrößerung; akute Prostatitis. Harnverhaltung mit Ballgefühl im Damm (Cann-i.). Harndrang. Urin trübe, stinkend, mit fädigem, blutigem Schleim, reichlich Sediment. Glykosurie. Brennen beim Wasserlassen. Muß pressen, bevor Urin kommt. Zum Wasserlassen muß er stehen, die Füße weit auseinander, den Kopf vorgeneigt."},{"t":"Chronische Alkoholiker. Katarakt."},{"t":"Brusttumoren mit Milchabsonderung. Rasche Atrophie. Frauen mit sehr großen Brüsten und Tumor mit heftigem Schmerz."},{"t":"Zahnschmerz, Agg.: nach dem Essen und Anstrengung, Amel.: kaltes Wasser. Schmerz, als ob ein Zahn vorsichtig gezogen würde."},{"t":"Agg.: bei feuchtem Wetter; durch Sitzen auf kalten Steinen; linke Seite."}],"rem":1,"orig":"Chimaphila umbellata"},{"label":"Chininum arsenicosum","short":"Chininum arsenicosum","group":"Arzneimittellehre","paras":[{"t":"Chininum arsenicosum, Chininarsenit. Müdigkeit und Entkräftung. Diphtherie mit Entkräftung, in langwierigen Fällen und bei malariaartigen Beschwerden. Eiskalte Haut. Druck im Solarplexus mit Empfindlichkeit der Wirbelsäule dahinter."},{"t":"Schwierige Atmung. Asthma- und Erstickungsanfälle, periodisch auftretend, morgens bis Mittag, Amel.: vorgebeugtes Sitzen am offenen Fenster. Kardiale Atemnot."},{"t":"Möchte Ruhe haben und alleine sein. Reizbarkeit. Große Angst."},{"t":"Schwindel, Agg.: Nachobensehen. Dumpfer, schwerer Kopfschmerz in Stirn- und Hinterkopf. Pulsieren. Stechen. Sehr ermüdend."},{"t":"Heftiger Durst auf kaltes Wasser, was belästigt. Anorexie."},{"t":"Durchfall von Fisch und Eiern."},{"t":"Kälte der Hände und Füße, Knie, Arme und Beine. Schwache Gliedmaßen, reißende Schmerzen."},{"t":"Beschwerden nach Cholezystektomie. Neuralgien."}],"rem":1,"orig":"Chininum arsenicosum"},{"label":"Chininum sulphuricum","short":"Chininum sulphuricum","group":"Arzneimittellehre","paras":[{"t":"Chininum sulfuricum, Chininsulfat. Periodizität: Beschwerden täglich zur selben Stunde, jeden 2. , 14. , 21. Tag. Menière. Heftiges Klingeln, Summen und Dröhnen in den Ohren mit Taubheit. Migräneartiger Kopfschmerz, der um 3 Uhr aufweckt, dauert die ganze Nacht und hält wach. Orbitalneuralgie, Amel.: Druck."},{"t":"Kopfschmerz, von Malaria herrührend, in Stirn und Schläfen, nimmt mittags zu."},{"t":"Kopfschmerz vom 7. Halswirbel aufwärts. Wirbelsäule (7. Halswirbel und Brustwirbelsäule) enorm empfindlich, Stuhllehne zu schmerzhaft, Agg.: Schüttelfrost."},{"t":"Chronische interstitielle Nephritis. Albuminurie. Urin blutig, fettig."},{"t":"Plötzliche Erblindung bei Retrobulbärneuritis."},{"t":"Furcht vor Unheil und Katastrophen."},{"t":"Häufiges Gähnen mit Hinfälligkeit und Erschöpfung."},{"t":"Akuter Gelenkrheumatismus. Polyartikuläre Gicht. Frösteln täglich um 15 Uhr."},{"t":"Agg.: Periodizität; Berührung; Kälte; 3/15 Uhr; 10-11 Uhr."},{"t":"Amel.: Gähnen; Druck; Vorbeugen."}],"rem":1,"orig":"Chininum sulphuricum"},{"label":"China officinalis","short":"China officinalis","group":"Arzneimittellehre","paras":[{"t":"Chinarindenbaum. Verdauungsstörungen und Migräne. Physische Ursache für Leiden; Ausgelaugt, Schwäche, Erschöpfung, mit (und ohne) Säfteverlust (Blutungen; Durchfall; Stillen; starkes Schwitzen; sexuelle Exzesse; lange Krankheit; Operation)."},{"t":"Diabetes. Anämie. Gesichtsfarbe gelbgrün."},{"t":"Schwierige Kinder: introvertiert, in eigener Welt, lieben Natur,"},{"t":"mag nicht mitmachen, empfindlich; Arzt ärgert sich über China;"},{"t":"Apathisch; schwermütig; ohne Lebenslust, Amel.: tiefe, warme Gefühle. Denken und Empfinden sehr intensiv, aber Schwierigkeiten, Gefühle mitzuteilen (Hauptmittel). Glücklich. Heldenphantasien. Luftschlösser. Science fiction. Idealismus. Künstlerisch; Dichtermittel; Furcht vor Gewalt."},{"t":"Bei allgemeiner Entkräftung berührungsempfindlich auf allen Ebenen: anspruchsvoll, starrsinnig, beleidigend, aggressiv wie Stram.; völlig überreizt, empfindlich gegen Lärm, Geruch, Zugluft, Kälte; verletzende Ausbrüche (Nux-v.). Paranoia: \"Ein Feind verfolgt mich\" (Hauptmittel)."},{"t":"Furcht vor eigenen Trieben; vor Hunden; Kühen; Schafen; Schlangen. Wandernde Neuralgien."},{"t":"Appetitlosigkeit bei Nebel. Lustloser Hunger, Nahrung bleibt unverdaut. Gärungsprozesse, Abgang v. Winden bessert nicht, Amel.: Liegen auf dem Bauch, kann aber keinen Kleiderdruck ertragen. Innere Kälte des Magens. Chronischer Durchfall, Agg.: Obst, Milch, Fisch. Gallenkolik, Kolitis durch Gallensteine (Hauptmittel). Schmerzhafte Blähungen nach Teetrinken; schaler Geschmack."},{"t":"Leber- und Milzvergrößerung. Ikterus. Ödeme Abdomen, Beine. Thrombose der Hüftvenen. Glieder- und Gelenkschmerz wie verstaucht; Gefühl wie Schnur um die Glieder; geschwollen."},{"t":"Periodizität: 0/3 Uhr, alle 2/7/14 Tage."},{"t":"Kopfschmerz, Migräne 3 Uhr (Chinin-s.) mit Übelkeit, als ob Schädel bersten wollte; starkes Pulsieren in Kopf und Karotiden, Agg.: Sonne (allgemeine Amel.: Sonne); Auftreten; Luftzug; Amel.: fester Druck."},{"t":"Verlangen: süß; sauer; pikant."},{"t":"Abneigung: Fett; Brot; Butter."},{"t":"Agg.: leichte Berührung; Kleiderdruck; Bewegung; Lärm; Kälte; Zugluft; Herbst; nebliges Wetter; Gemütserregung; jeden 2. Tag; Obst; Milch; Tee; Folgen von Chloroquin-Einnahme."},{"t":"Amel.: fester Druck."}],"rem":1,"orig":"China officinalis"},{"label":"Chloralum hydratum","short":"Chloralum hydratum","group":"Arzneimittellehre","paras":[{"t":"Chloralum hydratum; Chloralhydrat. Hypnotikum. Schwere Schlaflosigkeit und Ausschläge. Rote Flecken wie Masern. Erythem. Purpura. Ekchymosen."},{"t":"Urtikaria, Agg.: Alkohol; Amel.: Wärme. Schmerz in Sehnen und Streckmuskeln. Eisige Kälte der Haut. Intensives Jucken."},{"t":"Atemnot mit Zusammenschnürungsgefühl; Asthma mit Schlaflosigkeit."},{"t":"Erregung und Halluzinationen. Alpdrücken bei Kindern. Schwere Muskelschwäche."},{"t":"Agg.: Alkohol; heiße Getränke; nachts; Anstrengung."}],"rem":1,"orig":"Chloralum hydratum"},{"label":"Chlorum","short":"Chlorum","group":"Arzneimittellehre","paras":[{"t":"Chlorum, Chlorwasser. Gedächtnisschwäche, besonders für Namen. Zusammenschnürung mit Erstickungsgefühl; Asthma mit Stimmritzenkrampf; Reizung von Kehldeckel, Kehlkopf und Bronchien. Plötzliche Atemnot durch Stimmbandkrampf mit starren, herausquellenden Augen, blauem Gesicht, kaltem Schweiß und kleinem Puls. Einatmung frei, Ausatmung behindert. Anhaltend laute, pfeifende Atemzüge. Äußerste Trockenheit der Zunge."}],"rem":1,"orig":"Chlorum"},{"label":"Cicuta virosa","short":"Cicuta virosa","group":"Arzneimittellehre","paras":[{"t":"Cicuta virosa, Wasserschierling. Delirium mit absonderlichem, kindischem Verhalten. Verwechselt Gegenwart mit Vergangenheit. Ängstlich, schreckhaft, ergriffen von traurigen Geschichten. Nervensystem: Spastik; Tetanus; Konvulsionen puerperal und während der Schwangerschaft. Epilepsie, (Grand und Petit Mal); mit Zwerchfellspasmen, Stöhnen, Winseln, Schreien, Kieferstarre, Bewußtseinsverlust. Heftig. Schreckliche Verzerrungen und Verdrehungen. Rücken gebeugt wie ein Bogen. Opisthotonus. Torticollis. Zerebrospinale Meningitis. Pupillen erweitert; Strabismus, der nicht empfunden wird. Doppelbilder."},{"t":"Schwindel mit Sehstörungen. Beim Lesen scheinen sich Buchstaben zu drehen oder auf- und abzuwandern. Elektroschockgefühl. Blutung aus den Ohren. Gerötetes Gesicht. Zähneknirschen. Trockenheit des Halses. Durst; Schluckauf. Pulsieren in Magengrube."},{"t":"Ekzem ohne Juckreiz. Exsudat mit zitronenfarbener, harter Borke."},{"t":"Kombination von Epilepsie und Strabismus; Ausschlag-Epilepsie."},{"t":"Verlangen: unverdauliche Dinge, wie Kohle, Kreide."},{"t":"Agg.: Berührung; Zugluft; Erschütterung; Tabakrauch; Folge von Schädel-Hirn-Trauma, Rückenmarksstauchung; Verletzung der ins Gewebe eingedrungene Splitter."}],"rem":1,"orig":"Cicuta virosa"},{"label":"Cimicifuga racemosa","short":"Cimicifuga racemosa","group":"Arzneimittellehre","paras":[{"t":"Cimicifuga racemosa, Actaea racemosa, Wanzenkraut. Rheumatische, nervöse Frauen mit Ovarreizung, Uteruskrämpfen und schweren Gliedern. Erregung und Schmerz. Muskel- und Krampfschmerz neurotischen Ursprungs in fast allen Körperteilen. Starke Depression mit Träumen von bevorstehendem Unheil."},{"t":"Furcht vor dem Fahren in geschlossener Kutsche; verrückt zu werden; Tod; Ratten. Weigert sich, Medizin zu nehmen."},{"t":"Manie: Geschwätzigkeit. Erscheinungen von Ratten, Mäusen, Delirium tremens. Versucht, sich zu verletzen. Mißtrauisch. Seufzen. Gefühl, von einer schwarzen Wolke eingehüllt zu sein. Hysterie."},{"t":"Migräne: Gefühl von Öffnen und Schließen; Wogen-, Vergrößerungsgefühl; nach außen pressender Schmerz; wildes Gefühl im Kopf. Kopfschmerz mit Benommenheit und Nackensteifigkeit. Ohren überempfindlich."},{"t":"Ziliarneuralgie: Schmerz von den Augen zur Scheitelhöhle. Schießende Schmerzen mit Lichtscheu."},{"t":"Schmerz, krampfartig oder schießend wie elektrische Schläge, besonders Nacken und Rücken; Lumbalgie, Agg.: Zugluft; Rückenschmerz, Agg.: Nähen; Tippen."},{"t":"Überempfindlich auf Schmerz. Muskelschmerz in Bauchmuskeln, Bewegungen wie Chorea mit Rheumatismus. Gliederzucken. Steifheit der Achillessehne. Schwere der Beine."},{"t":"Schwangerschaft: Übelkeit, falsche Wehen; scharfe Schmerzen mitten durch den Bauch. Nagender Schmerz. Erbrechen durch Druck auf WIRBELSÄULE."},{"t":"Schießender Schmerz von der Ovarialregion an Oberschenkeloberfläche hinunter; prämenstrueller Schmerz. Menses reichlich, dunkel, klumpig, übelriechend mit Rückenschmerz, Nervosität; immer unregelmäßig. Dysmenorrhoe: je reichlicher der Fluß, desto stärker die Beschwerden. Schmerz quer durch das Becken, von Hüfte zu Hüfte. Flecken im Gesicht junger Frauen."},{"t":"Husten, Agg.: Sprechen; nachts."},{"t":"Herz setzt plötzlich aus; drohende Erstickung; Herzklopfen von der kleinsten Bewegung (Dig.)."},{"t":"Manie nach Verschwinden von Neuralgie."},{"t":"Alternierend Gemütssymptome mit Neuralgie, Rheumatismus, Durchfall und Menses oder Kombination von Geschwätzigkeit mit Rheumatismus."},{"t":"Agg.: Menses; Alkohol; Erregung; feuchtkalte Luft; Zugluft; Wind; Wehen; Sitzen; Pubertät und Klimax."},{"t":"Amel.: Wärme; frische Luft; Druck; fortgesetzte Bewegung; Essen."}],"rem":1,"orig":"Cimicifuga racemosa"},{"label":"Cina maritima","short":"Cina maritima","group":"Arzneimittellehre","paras":[{"t":"Artemisia cina, Zitwerblüten. Darmreizung, z. B. durch Würmer. Abneigung gegen Trost, Berührung, Annäherung, Angesehenwerden. Verträgt keinen Widerspruch. Ärgerlich, trotzig, ruhelos und reizbar. Schlägt oder kratzt Eltern, boshaft. Möchte geschaukelt werden. Verlangt Dinge, lehnt Angebotenes ab. Schreien im Schlaf, beim Erwachen, vor/während Konvulsionen. Zähneknirschen. Schmerz in Schockwellen. Haut berührungsempfindlich. Beschwerden durch Gähnen."},{"t":"Kopfschmerz wechselnd mit Bauchschmerz. Juckende Nase, reibt ständig. Bohren in Nase, Ohren. Heißhunger kurz nach dem Essen, mit Auszehrung."},{"t":"Lehnt Muttermilch ab. Erbrechen mit sauberer Zunge. Jucken am Anus. Koliken Neugeborener, Amel.: Druck. Drehender Schmerz um den Nabel. Enuresis bei Vollmond."},{"t":"Krampfartiger Husten morgens; Keuchhusten. Kind fürchtet sich zu sprechen oder sich zu bewegen aus Angst, Hustenanfälle zu erregen. Husten mit Tränenfluß und Brustbeinschmerz, als ob etwas abgerrissen wäre; endet in Spasmus. Gurgeln v. Rachen bis zum Magen nach dem Husten. Zucken und Verdrehung der Glieder. Kind wirft Arme von einer Seite zur anderen. Plötzliches Nach-innen-Zucken mit den Fingern der rechten Hand. Spastisches Strecken der Füße bei Kindern."},{"t":"Blaß, heiß mit dunklen Ringen um die Augen. Weiß und bläulich um den Mund. Gesichtszuckungen. Zucken der Augenbraue."},{"t":"Verlangen: Süßes; Brot."},{"t":"Agg.: Würmer; Gähnen; Berührung; Schlaf; in der Sonne; Sommer."},{"t":"Wenn Cham. versagt hat. An Santonin denken bei Wurmbefall."}],"rem":1,"orig":"Cina maritima"},{"label":"Cinnabaris","short":"Cinnabaris","group":"Arzneimittellehre","paras":[{"t":"Mercurius sulfuratus ruber, Zinnober. Ziliarneuralgie auf syphilitischer Basis. Gesicht purpurrot. Schießender Schmerz im Augapfel, vom inneren zum äußeren Winkel im Knochen laufend. Schmerz vom Tränenkanal um die Augen herum zur Schläfe, vom inneren Winkel über die Brauen zum Ohr."},{"t":"Rötung des ganzen Auges."},{"t":"Drückender Schmerz in der Nasenwurzel, wie von schwerer Brille. Epistaxis. Schmutzig gelber, klumpiger Schleim von den hinteren Nasenmuscheln. Sinusitis mit Schmerzen um den Orbitalrand."},{"t":"Feurig rote Ulzera in Mund und Rachen. Trockenheit von Mund und Rachen; muß Mund spülen."},{"t":"Feuerrote Ulzera auf der Haut. Knoten auf Schienbeinen. Bubonen. Leicht blutende Kondylome. Vorhaut geschwollen; Balanitis; Phimose. Hoden vergrößert; bösartig erscheinender Schanker."},{"t":"Kälte der Gelenke. Schmerz in den Langknochen, Agg.: Wetterwechsel, wenn Barometer fällt."}],"rem":1,"orig":"Cinnabaris"},{"label":"Cistus canadensis","short":"Cistus canadensis","group":"Arzneimittellehre","paras":[{"t":"Cistus canadensis, Ziströschen. Extrem empfindlich auf kalte Luft, auf Einatmen kalter Luft. Kälteempfinden verschiedener Körperteile."},{"t":"Verhärtung, bösartige Entzündung der (Hals-) Lymphknoten."},{"t":"Gewöhnliche Erkältungen jeden Winter."},{"t":"Skorbutartig geschwollenes Zahnfleisch. Kalte Zunge, schmerzhaftes Herausstrecken. Chronische Rhinitis, Sinusitis. Schmerz und Kälte der Nase, häufiges Niesen durch Einatmen kalter Luft. Gelbe Absonderung; retronasales Tropfen."},{"t":"Wunder, brennender, trockener, kalter Rachen. Schwammgefühl."},{"t":"Kältegefühl im Magen. Durchfall auf Obst, Kaffee."},{"t":"Herpesartiger Ausschlag. Jucken ohne Ausschlag hält vom Schlafen ab."},{"t":"Verstauchungsschmerz am Handgelenk; Fingerspitzen kälteempfindlich."},{"t":"Ulzera auf unteren Gliedmaßen mit harter Schwellung darum."},{"t":"Kombination: Chronischer Schnupfen und Käseverlangen."},{"t":"Verlangen: Käse; Gewürztes."},{"t":"Agg.: Winter; Kälte; Luftzug; geistige Anstrengung."},{"t":"Amel.: nach dem Essen."}],"rem":1,"orig":"Cistus canadensis"},{"label":"Clematis erecta","short":"Clematis erecta","group":"Arzneimittellehre","paras":[{"t":"Clematis erecta, Aufrechte Waldrebe. Bohrender Schläfenkopfschmerz. Verwirrung, Amel.: im Freien. Augen sehr luftempfindlich, muß sie schließen. Chronische Blepharitis. Iritis. Große Kälteempfindlichkeit."},{"t":"Empfindung von Hitze, die aus den Augen dampft. Gefühl Zähne wie verlängert. Zahnschmerz, Agg.: nachts; Rauchen; warme Getränke; Amel.: kaltes Wasser, Einatmen kalter Luft. Ileo-Skrotalneuralgie. Verhärtete Hoden mit Prellungsgefühl, Orchitis (rechts). Gefühl, der Hoden wird nach oben gezogen. Folgen unterdrückter GO. Erektion mit Stechen entlang Samenstrang. Schmerz entlang der Urethra zur Glans penis. Einschnürungsgefühl der Harnröhre. Kribbeln während Wasserlassen, einige Zeit anhaltend; Brennende Harnröhrenöffnung. Verzögerter, nachtröpfelnder Harnfluß. Zystitis. Geschwollene inguinale Lymphknoten. Verhärtungen. Brusttumoren."},{"t":"Ausschläge: juckend; brennend; stechend; kleine Bläschen, vor allem Gesicht, Hinterkopf und Hände, Agg.: Waschen mit kaltem Wasser. Starke Abmagerung. Große Schläfrigkeit. Unklares Pulsieren im ganzen Körper."},{"t":"Neuralgische Schmerzen. Rheumatismus durch unterdrückte GO."},{"t":"Agg.: Bettwärme; Kaltwaschen; Tabak; Neumond."},{"t":"Amel.: Frischluft; Schwitzen; Kälte."}],"rem":1,"orig":"Clematis erecta"},{"label":"Cobaltum metallicum","short":"Cobaltum metallicum","group":"Arzneimittellehre","paras":[{"t":"Cobaltum metallicum, Kobalt. Schmerz im Rücken und Kreuzbein, Agg.: Sitzen. Kombination: Pollutionen mit Rückenschmerzen. Ergüsse ohne Erektion. Erotische Träume."},{"t":"Schmerz im rechten Hoden, Amel.: Wasserlassen."},{"t":"Schwache Knie."},{"t":"Jucken von der Bettwärme."},{"t":"Ischialgie, Amel.: Liegen, Agg.: Sitzen."},{"t":"Kopfschmerz, Agg.: Vorbeugen."},{"t":"Einschießender Leberschmerz, Milzschmerz."}],"rem":1,"orig":"Cobaltum metallicum"},{"label":"Coccus cacti","short":"Coccus cacti","group":"Arzneimittellehre","paras":[{"t":"Coccus cacti, Conchenillelaus. Reichlich dickfädiger, zäher, klebriger, Schleim, der mit großer Schwierigkeit ausgeworfen wird. Kitzeln im Kehlkopf. Gefühl eines Krümels dahinter, muß dauernd schlucken. Husten mit Würgen und Erbrechen durch Rachenreizung, Agg.: warme Speisen und Getränke; ins warme Zimmer kommend.; 6/23.30 Uhr. Zähneputzen verursacht Husten. Erstickender Husten, Agg.: beim ersten Aufwachen. Kinder laufen blau an bei Hustenanfall."},{"t":"Keuchhustenanfälle, Amel.: kalte Luft, enden mit Erbrechen von zähem, glasigem Schleim mit purpurrotem Gesicht und Hitzegefühl."},{"t":"Traurigkeit abwechselnd mit Geschwätzigkeit."},{"t":"Gefühl eines Fremdkörpers zwischen Auge und Oberlid."},{"t":"Viel Durst auf große Mengen."},{"t":"Nierensteine. Klumpige Blutungen."},{"t":"Gefühl eines feinen Splitters unter den Fingernägeln."},{"t":"Agg.: periodisch; Wärme; Reizung des Rachens; Zähneputzen."},{"t":"Amel.: kalte Getränke; Kaltbaden."}],"rem":1,"orig":"Coccus cacti"},{"label":"Coca","short":"Coca","group":"Arzneimittellehre","paras":[{"t":"Erythroxylum coca, göttliche Pflanze der Inkas. Bergsteigermittel."},{"t":"Agg.: hohe Plätze: Kopfschmerz, Atemnot, Herzklopfen, Angst, Schlaflosigkeit. Erschöpftes Nervensystem durch körperliche und geistige Anspannung."},{"t":"Melancholisch; schüchtern, unfrei in Gesellschaft, reizbar, findet Gefallen an Einsamkeit und Verborgenheit. Sinn für Recht und Unrecht verloren."},{"t":"Heiserkeit, Agg.: nach Sprechen. Atemnot, Kurzatmigkeit, bei älteren Sportlern und Alkoholikern. Emphysem. Hämoptyse. Asthma. Nächtliche Ruhelosigkeit während Zahnens. Zahnkaries. Stimmverlust. Enuresis nocturna. Diabetes mit Impotenz."},{"t":"Verlangen: Süßes; Alkohol; Tabak."},{"t":"Agg.: beim Hochsteigen, in großen Höhen."},{"t":"Amel.: schnelle Bewegung im Freien; Wein."}],"rem":1,"orig":"Coca"},{"label":"Cocculus indicus","short":"Cocculus indicus","group":"Arzneimittellehre","paras":[{"t":"Anamirta cocculus, Indische Kockelskörner. In Träumereien versunken. Ernst, introvertiert. Leicht beleidigt; ärgerlich über jede Kleinigkeit. Spricht hastig."},{"t":"Beschwerden durch Schlafmangel und von der Sorge um andere:"},{"t":"Schwindel, Kopfschmerz, Schwäche, Geistesverwirrung. Zeit vergeht zu schnell. Langsames Begriffsvermögen; Geistig betäubt. Tiefe Traurigkeit. Verlangsamte Reflexe; Multiple Sklerose; amyotrophe Lateralsklerose; Demenz."},{"t":"Schwindel, Übelkeit, besonders beim Fahren oder Aufsitzen. Kopfschmerz im Hinterkopf und Nacken, Agg.: Liegen auf dem Hinterkopf. Gefühl von Öffnen und Schließen. Zittern des Kopfes. Wie Hohl im Kopf und anderen Körperteilen. Augenschmerz wie Herausreißen. Fazialisparese. Schmerz im Masseter, Agg.: Mundöffnen. Weit ausstrahlende Trigeminusneuralgie. Schlimme Reiseübelkeit (Auto, Boot), schon beim Anblick eines sich bewegenden Schiffes, Agg.: Kaltwerden. Übelkeit mit Schwäche und Erbrechen. Metallischer Geschmack. Schlucklähmung. Abdomen aufgetrieben, wie gefüllt mit scharfen Steinen. Schmerz im Leistenring, als ob etwas hindurchgezwängt würde, Bauchmuskeln schwach, als ob Bruch entsteht."},{"t":"Dysmenorrhoe. Menses reichlich, dunkel, zu früh, klumpig, schwächend, kann kaum stehen. Sehr schwächende Leukorrhoe; serös, jauchig, blutig, auch anstelle der Menses. Hämorrhoiden nach jeder Periode."},{"t":"Lumbalgie; Schmerz in Schultern und Armen wie bei Prellung."},{"t":"Gliederschmerz, Lahmheit und Zittern. Arme schlafen ein. Einseitige Lähmung, Agg.: nach Schlaf. Knieknacken. Hält Glieder ausgestreckt, Schmerz bei Beugung."},{"t":"Verlangen: Bier, kalte Getränke."},{"t":"Abneigung: Essen."},{"t":"Agg.: beim Essen; nach Schlafmangel; im Freien; Rauchen; Fahren; Schwimmen; Berührung; Geräusch; Stoß; nachmittags; bei den Menses; nach emotioneller Störung."}],"rem":1,"orig":"Cocculus indicus"},{"label":"Coffea cruda","short":"Coffea cruda","group":"Arzneimittellehre","paras":[{"t":"Coffea cruda, Rohkaffee. Ideenfülle. Leichtes Begriffsvermögen. Eindrucksfähig. Reizbarkeit, leicht erregt. Sinne geschärft (Hören, Riechen, Schmecken, Sehen). Schreckhaft. Euphorisch. Beschwerden durch plötzliche Erregung, Überraschung, Freude."},{"t":"Äußerst empfindlich. Neuralgien überall möglich. Schmerzunverträglichkeit treibt zur Verzweiflung. Weinen abwechselnd mit Lachen."},{"t":"Kopfschmerz \"eng\", als ob Hirn in Stücke gerissen würde. Kopfschmerz wie von einem Nagel, Agg.: Lärm, durch fast alles, Amel.: Kälte. Empfindliches Gehör."},{"t":"Zahnschmerz, Amel.: Kälte. Trigeminusneuralgie."},{"t":"Hastiges Essen und Trinken. Außerordentlicher Hunger. Kann enge Kleidung nicht ertragen."},{"t":"Überempfindliche Vagina/Vulva."},{"t":"Herzklopfen durch Erregung und Freude."},{"t":"Schlaflosigkeit durch geistige Erregung, tagsüber schläfrig."},{"t":"Agg.: Lärm; Freude; Gerüche; Alkohol; Wut; plötzliche Gemütserregung."},{"t":"Amel.: Wärme; Hinlegen; Eis im Munde halten."}],"rem":1,"orig":"Coffea cruda"},{"label":"Colchicum autumnale","short":"Colchicum autumnale","group":"Arzneimittellehre","paras":[{"t":"Colchicum autumnale, Herbstzeitlose. Kombination Arthritis mit Meteorismus oder mit Übelkeit. Gichtanfälle. Gelenke rot, heiß, geschwollen, steif. Schmerzen ziehend, reißend, pressend, Agg.: abends, nachts, Berührung, kalte Luft. Scharfer Schmerz, den linken Arm hinunter. Reißen in Gliedern bei warmem, Stechen bei kaltem Wetter. Ameisenlaufen in Händen, Fingerspitzen taub. Schmerz mit wanderndem Rheumatismus, Agg.: Bewegung. Gicht in Ferse, großer Zehe, Agg.: Berührung, Bewegung. Ödematöse Schwellung und Kälte der Beine und Füße."},{"t":"Große Erschöpfung, innere Kälte und Kollapsneigung."},{"t":"Folge von Nachtwachen und intensivem Studium. Elektrische Schockwellen durch eine Körperhälfte. Folge von unterdrücktem Schweiß. Träume von Mäusen."},{"t":"Unerträgliche Leiden. Wutanfälle durch schlechte Manieren, Berührung, Licht, Lärm, starke Gerüche (Nux-v.). Beschwerden durch Kummer und Untaten anderer (Staph.)."},{"t":"Geruch von Nahrung erregt Übelkeit bis zur Ohnmacht (Fisch, Eier, fettes Fleisch). Verabscheut Anblick von Speisen, trotz Appetits. Auftreibung des Bauches mit Gas, Unfähigkeit, Beine auszustrecken. Kollern. Leberschmerz. Zäkum und Querkolon sehr aufgetrieben. Aszites. Brennen oder eisige Kälte im Magen."},{"t":"Stuhl schmerzhaft; schleimig; reichlich weiße, fädige Partikel; als ob Anus aufgerissen würde, mit Prolaps. Herbstruhr; fühlt Kot im Rektum, kann nicht entleeren. Durchfall, gefolgt von Gicht-Rheumatismus."},{"t":"Urin blutig, fast schwarz wie Tinte, enthält Klumpen fauligen, zersetzen Blutes. Nephritis; Nierensteine."},{"t":"Agg.: feuchtkaltes Wetter; Wetterwechsel; Herbst; Berührung; Bewegung; Frühjahr; seelische Erregung oder Erschöpfung; anstrengende Studien Essensgerüche."},{"t":"Amel.: Wärme; Ruhe."}],"rem":1,"orig":"Colchicum autumnale"},{"label":"Collinsonia canadensis","short":"Collinsonia canadensis","group":"Arzneimittellehre","paras":[{"t":"Collinsonia canadensis, Grießwurzel. Becken- und Pfortader-kongestion. Hämorrhoiden und Verstopfung, vor allem bei Frauen. Kinder mit atonischer Verstopfung. Verstopfung abwechselnd mit Durchfall."},{"t":"Chronischer Katarrh von Nase, Magen und Kehlkopf infolge Pfortaderstauung. Abwechselnd Brustschmerz / Herzklopfen mit (blutenden) Hämorrhoiden (Agg.: in Schwangerschaft)."},{"t":"Gefühl von scharfen Holzstücken im Rektum. Einschnürungsgefühl. Jucken des Anus."},{"t":"Gefühl von Schwellung der Labien und der Klitoris. Jucken der Vulva."},{"t":"Husten von Überanstrengung der Stimme; chronische Heiserkeit; scharfer Schmerz im Kehlkopf. Quälender, trockener Husten."}],"rem":1,"orig":"Collinsonia canadensis"},{"label":"Colocynthis","short":"Colocynthis","group":"Arzneimittellehre","paras":[{"t":"Citrullus colocynthis, Koloquinte. Kolik, Krämpfe, Zucken, Muskelverkürzung, wie gefesselt mit eisernen Bändern, Amel.: Druck und Zusammenkrümmen. Beschwerden nach Wut mit Entrüstung, Widerspruch, Kränkung. Äußerst reizbar, wenn gezwungen zu antworten. Wirft mit Gegenständen. Kränkung durch Beleidigung."},{"t":"Schwindel beim Kopfdrehen nach links. Seitlich schneidender, zerrender, schießender Kopfschmerz mit Gesichtsschmerz, Neuralgie mit Frösteln, Agg.: Berührung;"},{"t":"Amel.: Druck, Wärme, Kaffee. Töne hallen wider in den Ohren."},{"t":"Bitterer Geschmack. Bauchkolik mit Wadenkrämpfen. Quälender, schneidender Schmerz im Abdomen nach Ärger, Amel.: Druck; Zusammenkrümmen. Gefühl von mahlenden Steinen im Bauch; als ob er platze. Quetschungsgefühl in den Eingeweiden. Allgemeine Erregung und Frösteln in den Wangen, vom Unterbauch aufsteigend. Schmerz an kleiner Stelle unterhalb des Nabels. Koliken Neugeborener. Durchfall durch Wut, Ängstlichkeit, Fasten, Kartoffeln; Wiederauftreten durch geringstes Essen/Trinken. Geleeartige Stühle. Zäher Urin; bei Wasserlassen Schmerz über gesamtes Abdomen. Menstruationskrämpfe. Brennender Schmerz im Ovar."},{"t":"Zusammenschnürung der Muskeln. Schmerz im rechten Deltoideus. Ischias mit Taubheit, Agg.: Kälte; Liegen; Bewegung; Gehen; Berührung; Bettwärme. Amel.: Bein an Bauch heranziehen; Liegen auf schmerzhafter Seite. Krampfschmerz in der Hüfte. Spontane Hüftluxation."},{"t":"Agg.: Emotionen; Nacht; Liegen auf schmerzloser Seite; Wut; Berührung."},{"t":"Amel.: fester Druck; Krümmen; Wärme; Ausruhen; Kaffee."}],"rem":1,"orig":"Colocynthis"},{"label":"Comocladia dentata","short":"Comocladia dentata","group":"Arzneimittellehre","paras":[{"t":"Comocladia dentata, Sumachgewächse. Ziliarneuralgie mit Gefühl, als ob rechtes Auge zu groß wäre und nach außen gepreßt würde, Agg.: beim warmen Ofen. Sieht links nur Lichtschimmer. Glaukom. Gefühl, als sei Augapfel zu groß, Agg.: Bewegung der Augen. Gesicht geschwollen mit hervorstehenden Augen."},{"t":"Haut juckt, rot, Stippen. Röte überall wie bei Scharlach. Erysipel."}],"rem":1,"orig":"Comocladia dentata"},{"label":"Conium maculatum","short":"Conium maculatum","group":"Arzneimittellehre","paras":[{"t":"Conium maculatum, Gefleckter Schierling. Verhärtungen. Fixe Ideen wie \"Schwiele im Hirn\". Abergläubisch; Rituale. Brust-/Uteruskrebs (Hauptmittel). Samenverluste nachts, während Stuhlgang. Starker Sexualtrieb bei wenig -vermögen. Ejaculatio praecox."},{"t":"Unterdrückte Menstruation durch Kälte und Hände-in-kaltes-Wasser-Halten."},{"t":"Klimax: Krebs nach unterdrückter Sexualität. Erwacht von Wallungen nachts mit Schweiß. Zystitis mit anhaltendem Harndrang, unfähig, mehr als einen Tropfen zu lassen (Krebsverdacht). Blasenschwäche, unterbrochener Harnstrahl; Prostata vergrößert (Hauptmittel); preßt vergeblich zum Harnlassen, Harnfluß in Entspannung."},{"t":"Schwindel beim Hinlegen und Umdrehen im Bett, beim Drehen des Kopfes zur linken Seite. Arthritis, Amel.: Herunterhängenlassen der Füße. Verstopfung auf Reisen. Husten, Agg.: Liegen; Schwangerschaft; Sprechen; Lachen; wie von trockenem Fleck im Kehlkopf."},{"t":"Empfindlichkeit für künstliches Licht. Photophobie ohne Augenentzündung. Beschwerden von Nachtarbeit. Lippenkrebs der Raucher. Verhärtete Lymphknotenschwellung; Stechen. Nachtschweiß."},{"t":"Allmählich fortschreitende Schwäche und Lähmung; über Jahre. Verhärtungen. Bodenständig. Materialistisch. Sexualität gehört zum Leben wie Essen und Trinken. Sehr starker Trieb; Orgasmus beim Flirten ohne Berührung. Pathologie setzt nach plötzlichem Verlust des Partners ein: Zittern, fühlt sich wie gelähmt; Schwäche von Körper und Geist. Unfähig, Pflichten nachzukommen. Anfangs Sorge um Gesundheit, möchte jemanden bei sich haben; dann allmähliche Lähmung der Gefühlswelt, Gleichgültigkeit, interesselos, kann sich nicht mitteilen, will keine Gesellschaft, aber alleine ängstlich. Gedächtnis schwach, Sinne nicht mehr scharf, vorzeitige Senilität; nach Drogen/Alkoholkonsum über Jahre."},{"t":"Folgen unterdrückten sexuellen Verlangens; unterdrückter Menses."}],"rem":1,"orig":"Conium maculatum"},{"label":"Convallaria majalis","short":"Convallaria majalis","group":"Arzneimittellehre","paras":[{"t":"Convallaria majalis, Maiglöckchen. Schwäche, Herzklopfen durch geringste Anstrengung. Tabakherz von Zigarettenrauchern. Angina pectoris. Höchste Atemnot, Agg.: Gehen. Hitzegefühl im Hals. Schwacher, unregelm. Pulsierendes Gefühl, als ob das Herz mit dem Schlagen aufhöre, dann plötzlich wieder anfinge. Herzdilatation ohne Hypertrophie."},{"t":"Bewegung im Bauch wie die Faust eines Kindes."},{"t":"Schmerzhaftigkeit im Uterusgebiet mit Herzklopfen."},{"t":"Schmerz in Sakroiliakalregion, in die Beine ausstrahlend."},{"t":"Agg.: warmes Zimmer."},{"t":"Amel.: im Freien."}],"rem":1,"orig":"Convallaria majalis"},{"label":"Copaiva officinalis","short":"Copaiva officinalis","group":"Arzneimittellehre","paras":[{"t":"Harz von Copaifera off., Kopaivabalsam. Wirkt auf Schleimhäute der Harn- und Atemwege mit reichlicher, übelriechender Absonderung."},{"t":"Chronische Urtikaria bei Kindern mit Fieber und Verstopfung. Ausschlag mit Blasen. Erysipelartige Entzündung, besonders am Bauch."},{"t":"Brennende Trockenheit der Nase. Schleimige Kolitis mit Kolik und Frösteln. Blasenkatarrh; Urin riecht nach Veilchen."},{"t":"Husten mit reichlichem, grauem, übelriechendem, eitrigem Auswurf. Kitzeln in Kehlkopf, Trachea, Bronchien."}],"rem":1,"orig":"Copaiva officinalis"},{"label":"Corallium rubrum","short":"Corallium rubrum","group":"Arzneimittellehre","paras":[{"t":"Corallium rubrum. Mürrisch; schimpft und flucht. Abgedeckt zu kalt, zugedeckt zu warm, Amel.: künstliche Hitze."},{"t":"Als ob kalte Luft durch Schädel und Atemwege ginge. Schleimhautulzera mit zähen Absonderungen. Schnupfen; Nasenbluten; Zwiebelgeruch. Sinusitis. Retronasaler Katarrh. Reichliche Schleimabsonderung, durch den Nasenrachenraum tropfend. Räuspern von reichlich Schleim. Rachen sehr empfindlich, besonders gegen Luft. Keuchhusten: sehr heftige, trockene, spastische Hustenanfälle in sehr rascher Folge, kurz, bellend. Vorher Erstickungsgefühl, danach Erbrechen von zähem Schleim, eventuell blutig, große Erschöpfung. Husten mit großer Empfindlichkeit der Atemwege. Kältegefühl beim tiefen Einatmen. Gesicht wird purpurrot. Anfälle beim Essen. Essen schmeckt wie Sägemehl, Bier schmeckt süß."},{"t":"Rote, flache Hautulzera. Korallenfarbige, dann dunkelrote, schließlich kupferfarbene Hautflecken. Psoriasis an Handflächen und Fußsohlen. Ulzera auf Eichel und Vorhaut. Reichlich Schweiß der Genitalien."},{"t":"Schläft mit dem Kopf unter der Decke. Kombination: Schnupfen und Sauerverlangen."},{"t":"Verlangen: Saures; Salz."},{"t":"Abneigung: Salz."},{"t":"Agg.: Einatmen kalter Luft; Aufdecken."}],"rem":1,"orig":"Corallium rubrum"},{"label":"Crocus sativus","short":"Crocus sativus","group":"Arzneimittellehre","paras":[{"t":"Crocus sativus, Safran. Häufig und extremer Stimmungswechsel: vergnügte Manie, singt, lacht, tanzt und springt - dann zornig oder melancholisch (Ign; Nux-m.). Lebhafte Erinnerung an Musik, die Patient gehört hat (Lyc)."},{"t":"Gefühl in den Augen wie nach heftigem Weinen; als ob die Augen im Rauch wären; als ob kalte Luft durch das Auge strömte. (Drohendes Glaukom; Zentralarterienverschluß)."},{"t":"Blutung aus irgendeiner Körperöffnung: dunkel, fädig, klumpig, fädenziehend. Nasenbluten bei Mädchen in Pubertät. Uterusblutung mit drohendem Abort. Menses häufig, stark, zäh, klebrig. Scheinschwangerschaft. Zuckender Schmerz in der linken Brust, als ob sie mit Schnur zum Rücken gezogen würde. Wie Hüpfen von etwas Lebendigem in der rechten Brust."},{"t":"Plötzliches Kältegefühl im Rücken, wie von kaltem Wasserguß; eiskalte Extrem. Chorea und Hysterie (Tarent.). Zuckungen. Knacken in Knien."},{"t":"Hartnäckige Verstopfung, bei Kindern. Gefühl von etwas Lebendigem in: Magen, Abdomen, Uterus, Armen; mit Übelkeit und Ohnmacht."},{"t":"Agg.: Niederlegen; heißes Wetter; warmes Zimmer; morgens; vor Frühstück; Bewegung; Pubertät; Schwangerschaft; Neu- und Vollmond."},{"t":"Amel.: im Freien."}],"rem":1,"orig":"Crocus sativus"},{"label":"Crotalus cascavella","short":"Crotalus cascavella","group":"Arzneimittellehre","paras":[{"t":"Crotalus cascavella. Dunkle, passive Blutungen. Wahnideen und Angst vor Geistern und Stimmen. Linksseitig. Kleiderdruck unerträglich."},{"t":"Zungenlähmung, schwierige Sprache."},{"t":"Urtikaria einzelner Körperteile, die sich in große, rote, juckende Flecken ausbreitet. Rechtsseitige Parese."},{"t":"Amel.: Menses."}],"rem":1,"orig":"Crotalus cascavella"},{"label":"Crotalus horridus","short":"Crotalus horridus","group":"Arzneimittellehre","paras":[{"t":"Crotalus horridus, Waldklapperschlange. Sepsis, Blutzersetzung. Dunkle Blutungen ohne Klumpenbildung. Darniederliegen der Lebenskraft. Weinerlich; getrübte Wahrnehmung. Ungeduldig, redselig, Abneigung gegen seine Familie, möchte fliehen. Wahnideen als Folge des geistigen Verfalls. Hört Stimmen."},{"t":"Sehr empfindlich auf Lampenlicht. Gelbe Skleren. Ziliarneuralgie mit reißendem, bohrendem Schmerz. Kopfschmerz mit Herzschmerz bei Linkslage, Agg.: Erschütterung. Angina pectoris. Hypertonie. Intraokuläre Blutungen. Nasenbluten, Stinknase."},{"t":"Zunge rot, glatt, glänzend (Pyrog.), stark geschwollen, Zungenkrebs. Sektionsverletzung. Heftiges Erbrechen gallig, blutig; nach Menses. Kleiderdruck unerträglich. Alkoholismus."},{"t":"Purpura haemorrhagica, Blutung aus jeder Körperöffnung, vom Fingernagel, blutiger Schweiß. Alte Narben brechen auf. Impffolgen. Lymphangitis und Septikämie (Pyrog.). Erysipel. Maligner Scharlach. Gelbfieber. Apoplexie. Rechtsseitige Lähmung. Karbunkel, Furunkel. Uteruskarzinom."},{"t":"Verlangen: Zucker; Alkohol; Stimulanzien."},{"t":"Agg.: rechtsseitig; im Freien; Frühling, Aufkommen warmen Wetters; Aufwachen; Nässe und Feuchtigkeit; Erschütterung."},{"t":"Amel.: Licht, Bewegung."}],"rem":1,"orig":"Crotalus horridus"},{"label":"Croton tiglium","short":"Croton tiglium","group":"Arzneimittellehre","paras":[{"t":"Croton tiglium, Purgierbaum. Explosionsartiger, herausschießender Durchfall, gewaltsame Entleerung, Agg.: während und nach dem Essen, (sofort) nach dem Trinken, Sommer, mit Ausschlägen. Gurgeln, Plätschern und Krämpfe im Abdomen, Amel.: warme Milch. (Durchfall ähnlich Ars., aber viel Lebenswärme.)"},{"t":"Augen fühlen sich an wie nach hinten gezogen. Spannungsschmerz über der rechten Augenhöhle. Brennen im Ösophagus."},{"t":"Urin dunkelorange."},{"t":"Husten, sobald der Kopf das Kissen berührt."},{"t":"Schmerz in Mamma/Brustwarze während des Stillens, zum Schulterblatt ausstrahlend. Mastitis. Als ob Körperteile zurückgezögen würden (Augen, Brustwarzen). Brustschmerz links, ausstrahlend in den Rücken."},{"t":"Engegefühl in der Haut. Schrecklich juckende Haut (Gesicht, Skrotum), aber Kratzen verursacht schmerzhaftes Brennen, Amel.: Reiben. Ausschläge, Pusteln, Bläschen, Erysipel mit Blasenbildung, Herpes zoster; Ekzeme."},{"t":"Anhaltend stechende Schmerzen durch den Ausschlag."},{"t":"Agg.: Trinken; Essen; Sommer; Berührung; nachts und morgens; Kratzen; Waschen."}],"rem":1,"orig":"Croton tiglium"},{"label":"Cubeba officinalis","short":"Cubeba officinalis","group":"Arzneimittellehre","paras":[{"t":"Piper cubeba, Cubebenpfeffer. Schleimhautkatarrh. Zystitis. Urethritis mit viel Schleim, besonders bei Frauen. Schneidender Schmerz nach dem Wasserlassen mit Zusammenschnürung. Hämaturie. Häufiges Wasserlassen nervösen Ursprungs. Weißfluß kleiner Mädchen. Prostatitis mit dicker, gelber Absonderung."},{"t":"Katarrh von Nase und Hals, stinkend, Auswurf. Schleim sickert aus hinteren Nasenöffnungen. Ständiges Speichelschlucken wegen Trockenheit des Rachens. Heiserkeit, rauher Hals."},{"t":"Mund zieht sich auf eine Seite beim Lächeln oder Sprechen."},{"t":"Verlangen: Orangen; Nüsse; Zwiebeln."}],"rem":1,"orig":"Cubeba officinalis"},{"label":"Cundurango","short":"Cundurango","group":"Arzneimittellehre","paras":[{"t":"Cundurango. Mammakarzinom mit eingezogenen Brustwarzen und heftigen Tumorschmerz über die ganze Brust. Schmerzhafte Risse der Mundwinkel. Chronische Gastritis; Magenkrebs. Ösophagusstriktur. Erbrechen; Gefühl, als ob Nahrung hinter dem Sternum steckenbleibt."}],"rem":1,"orig":"Cundurango"},{"label":"Cuprum metallicum","short":"Cuprum metallicum","group":"Arzneimittellehre","paras":[{"t":"Cuprum met., Kupfer. Erschöpfung durch geistige Überanstrengung und Schlafmangel."},{"t":"Zwanghaft, geistig verkrampft, alles sehr ernst; fixe Ideen, boshaft, mürrisch; langsames Begreifen und Antworten. Unterdrückte Gefühle und Triebe; verschlossen. Kann Gefühle schlecht ausdrücken, Schuldgefühle. Beziehungen \"ein Krampf\"; Anfälle unüberwindlicher Angst."},{"t":"Krämpfe periodisch, in Muskelgruppen. Konvulsionen. Epilepsie: Aura beginnt in Knien, steigt zum Unterbauch, in Hände oder Füße; bewußtlos, Kieferkrämpfe, Schaum vor dem Mund. Krampfanfälle nach unterdrücktem Hautausschlag, durch unterdrückte Absonderungen (Fußschweiß). Daumen einwärts gedreht, tonisch-klonische Spasmen breiten sich auf ganzen Körper aus. Überempfindlichkeit."},{"t":"Gesicht und Lippen blau. Züngeln wie Schlange (Lach.). Grimassen. Stottern. Geschmack schleimig, metallisch nach Kupfer."},{"t":"Asthma, Agg.: 3 Uhr. Krampfhafter Husten mit blauem Gesicht. Keuchhusten, Agg.: 23/1 Uhr; Amel.: Trinken kalten Wassers. Zäher, schleimiger, blutiger Auswurf."},{"t":"Schmerz im Solarplexus zieht zum Rücken; Messerstichgefühl; Bauchkrämpfe; Exzessiver Durst auf kaltes Wasser. Gurgelndes Geräusch beim Trinken. Hitzegefühl im Hypogastrium. Gastroenteritis. Brechdurchfall. Schlimmste Übelkeit. Hepatitis. Leibschneiden, Kolikschmerzen mit Abwehrspannung; heft. Durchfälle; Krämpfe während und nach Durchfall, kleinste Bewegung verursacht Durchfall. Durchfall mit Frostgefühl."},{"t":"Haut bläulich, marmoriert. Ekzeme."},{"t":"Muskulatur schwach. Wadenkrämpfe nachts. Schießende, neuralgische Schmerzen; Eiskalte Hände und Füße; Kälte; klebriger kalter Schweiß. Krämpfe im Wochenbett. Krämpfe nach Metastasierung (Zinc.). Muskelzuckungen."},{"t":"Schlaflosigkeit alter Menschen. Tiefer Schlaf mit Schockwellen durch den Körper. Im Schlaf dauerndes Rumoren im Bauch."},{"t":"Jedes Mittel wirkt, aber keines heilt. Chorea durch Schreck. Beschwerden seit der Pubertät."},{"t":"Verlangen: kalte Getränke."},{"t":"Agg.: unterdrückte Ausschläge oder Absonderungen; Nacht; heißes Wetter; kalter Wind; Erbrechen; Berührung."},{"t":"Amel.: Schweißausbrüche; kalte Getränke."}],"rem":1,"orig":"Cuprum metallicum"},{"label":"Curare","short":"Curare","group":"Arzneimittellehre","paras":[{"t":"Curare, Pfeilgift. Muskellähmung ohne Verminderung von Gefühl und Bewußtsein. Lähmung der Atemmuskulatur. Reflexe verringert. Schwäche bei alten Leuten und durch Verlust von Flüssigkeiten. Katalepsie. Nervöse Schwäche."},{"t":"Unentschlossenheit; will nicht mehr denken oder für sich selber handeln. Wahnvorstellung, daß alles schmutzig ist. Abneigung Gesellschaft; verschließt sich. Schlägt sich selbst."},{"t":"Gesichtslähmung. Gefühl als ob Kopf voller Flüssigkeit. Vermehrter Appetit bei Fieber."},{"t":"Drohende Atemlähmung, quälende Atemnot, Agg.: Stufensteigen, feuchtes Wetter. Brust schmerzhaft bei Druck. Kurzer, trockener Husten mit Erbrechen und Ohnmacht."},{"t":"Schwere und Schwäche der Arme; Paralyse der rechten Deltoideusregion. Streckerlähmung. Schwäche von Händen und Fingern bei Pianisten. amyotrophe Lateralsklerose; Guillain-Barré."},{"t":"Haut sieht schmutzig aus. Furunkel. Knötchen auf Nase. Leberflecken. Blutsickern. Jucken."},{"t":"Verlangen: Säuren; Saures."},{"t":"Abneigung: Brot."},{"t":"Agg.: Feuchtigkeit; kaltes Wetter; 2 Uhr; rechts."}],"rem":1,"orig":"Curare"},{"label":"Cyclamen europaeum","short":"Cyclamen europaeum","group":"Arzneimittellehre","paras":[{"t":"Cyclamen europaeum, Alpenveilchen. Anämisch, leicht ermüdet. Gewissensbisse. Kummer. Bekümmert über vernachlässigte Pflicht oder böse Tat. Traurigkeit und Verdrossenheit. Verlangen, alleine zu sein. Depression. Mürrisch, schlecht gelaunt, reizbar. Stilles Weinen. Abneigung frische Luft."},{"t":"Kopfschmerz morgens mit Flackern vor den Augen, wie bunte, feurige Funken; Flimmerskotom; Doppelbilder; Strabismus conv.; Sehstörung mit Magenstörung. Schwindel, Amel.: Zimmer, Agg.: im Freien."},{"t":"Sättigung nach wenigen Bissen. Essen verursacht Übelkeit in Kehle und Gaumen. Salziger Geschmack von Essen und Speichel; Schluckauf, Agg.: fette Nahrung. Diarrhoe nach Kaffee. Durstlos. Schwangerschaft: Schluckauf; Erbrechen."},{"t":"Menses reichlich, schwarz, membranös, klumpig, zu früh, mit wehenartigen Schmerzen vom Rücken zum Schambein, Amel.: während des Fließens."},{"t":"Prostatabeschwerden, Agg.: während Stuhlgang und Wasserlassen; Gehen, Sitzen; mit Schmerz um Anus und Perineum."},{"t":"Rheumatismus der Füße, Sprunggelenke. Fersenschmerz wund, brennend, Agg.: Sitzen, Stehen. Periostschmerz."},{"t":"Verlangen: Limonade; Unverdauliches; Sardinen."},{"t":"Abneigung: Brot; Bier; Butter; Fett; Fleisch; Schweinefleisch."},{"t":"Agg.: Schweinefleisch; Fett; Kälte; frische Luft; unterdrückte Menses."},{"t":"Amel.: Weinen; während Menses; Zimmer; Bewegung."}],"rem":1,"orig":"Cyclamen europaeum"},{"label":"Cypripedium pubescens","short":"Cypripedium pubescens","group":"Arzneimittellehre","paras":[{"t":"Cypripedium pubescens, Frauenschuh. Nervöse Kinder, durch Zahnen und Beschwerden des Magen-Darmkanals. Zerebrale Hyperästhesie kleiner Kinder, infolge von Überreizung des Gehirns. Kind weint nachts; erwacht und beginnt zu lachen und zu spielen. Schlaflosigkeit. Hautsymptome wie Rhusvergiftung; wichtiges Gegenmittel."}],"rem":1,"orig":"Cypripedium pubescens"},{"label":"Digitalis purpurea","short":"Digitalis purpurea","group":"Arzneimittellehre","paras":[{"t":"Digitalis purpurea, Fingerhut. Große Schwäche, wie sterbend. Zyanose. Erweiterte Venen der Lider, Ohren, Lippen, Zunge. Kälte der Haut."},{"t":"Gefühl, als ob das Herz aufhören würde zu schlagen, wenn er sich bewegt (Gels., wenn er sich nicht bewegt). Puls schwach, unregelmäßig, abnorm langsam; setzt jeden 3. /5. /7. Schlag aus. Myokardschwäche und Dilatation. Vorhofflimmern. Perikarditis mit Erguß. Herzstiche. Geringste Bewegung verursacht Herzklopfen. Herzneurosen und Augenbeschwerden durch Tabak. Gelber oder grüner Hof um Objekte."},{"t":"Niedergeschlagenheit. Angst mit Leeregefühl im Magen; vor der Zukunft; vor Herzkrankheit. Weinen von Musik. Migräne. Kopfschmerz nach Eiskrem, kalten Getränken."},{"t":"Appetitlos mit Durst. Übelkeit, nicht erleichtert durch Erbrechen, Agg.: Geruch von Essen; Schwäche im Magen, Agg.: Bewegung. Brennen, zum Ösophagus ausstrahlend. Oberbauch empfindlich; neuralgischer Magenschmerz."},{"t":"Stühle weiß, kalkartig, aschenartig, Bleistiftstuhl, unfreiwillig. Durchfall bei Gelbsucht. Leberhypertrophie und -induration; Ikterus; Hepatitis."},{"t":"Prostata vergrößert, Retention, dauernder Drang; schneidender, pulsierender Schmerz im Blasenhals, als ob ein Strohhalm hin- und hergezogen würde, Agg.: nachts. Urethritis, Phimose, Strangurie."},{"t":"Atmung unregelmäßig, Verlangen, tief einzuatmen. Kann Sprechen nicht ertragen."},{"t":"Fährt aus dem Schlaf hoch mit Gefühl zu fallen."},{"t":"Kombination Herz-Prostata; Hepatitis-langsamer Puls."},{"t":"Verlangen: Bitteres."},{"t":"Agg.: Anstrengung; Aufsitzen; Aufstehen; Liegen auf der linken Seite; Kälte."}],"rem":1,"orig":"Digitalis purpurea"},{"label":"Dioscorea villosa","short":"Dioscorea villosa","group":"Arzneimittellehre","paras":[{"t":"Dioscorea villosa, Yamswurzel. Verdauungsschwäche. Kolikschmerz verlagert sich plötzlich in entfernte Körperteile, wie Finger und Zehen. Schmerz in regelmäßigen Anfällen, scharf im Oberbauch; als ob Därme von starker Hand gepackt und gezerrt würden. Viel Wind. Gallenkolik; Schmerz von der Leber zur rechten Brustwarze schießend. Schmerz von der Gallenblase in Rücken, Brust und Arme. Nierenkolik mit Schmerz in Extremitäten. Leeregefühl in Magengrube. Sodbrennen. Angina pectoris- Schmerz vom Magen in die linke Brust und in den linken Arm ziehend mit Beklemmung. Schmerz am Brustbein entlang und in Arme ausstrahlend. Aufstoßen saurer, bitterer Winde mit Schluckauf. Flatulenz bei Teetrinkern. Diarrhoe: akut, blutig."},{"t":"Erschlaffung und Kälte der Genitalien; stark riechender Schweiß auf Hodensack und Schamgegend. Samenergüsse nachts, mit schwachen Knien. Lebhafte, erotische Träume."},{"t":"Uteruskolik. Schwangere mit Abdominalbeschwerden."},{"t":"Panaritium im Frühstadium.: erstes Stechen, quälend, Nägel brüchig."},{"t":"Agg.: Krümmen; Bücken; Sitzen; Liegen."},{"t":"Amel.: Zurücklehen; Stehen; Bewegung im Freien; starker Druck."}],"rem":1,"orig":"Dioscorea villosa"},{"label":"Diphtherinum","short":"Diphtherinum","group":"Arzneimittellehre","paras":[{"t":"Neigung zu Katarrhen in Hals, Rachen, Atemwegen. Skrofulose. Diphtherie. Schwäche, Erschöpfung. Maligner Verlauf. Schmerzlose Diphtherie. Zu schwach, apathisch, erschöpft, um sich zu beklagen. Sopor, aber ansprechbar, wenn er geweckt wird; Augen stumpf, töricht (Bapt.; Sulph.). Tonsillen und Gaumenbögen dunkelrot geschwollen. Atem und Absonderungen aus Hals, Nase, Mund entsetzlich stinkend. Zunge rot, geschwollen. Drüsenschwellungen."},{"t":"Diphtherische Membranen dick, dunkel. Subfebrile Temperatur. Puls schnell und schwach. Kalte Extremitäten."},{"t":"Nasenbluten und starke Schwäche sofort nach Beginn der Erkrankung (Ail.; Apis; Carb-ac.)."},{"t":"Schlucken schmerzlos, aber Flüssigkeiten werden sofort erbrochen oder kommen aus der Nase zurück."},{"t":"Der Patient scheint von Anfang an verloren, die sorgfältigst gewählten Mittel schaffen keine Erleichterung oder dauerhafte Besserung."},{"t":"Bei Larynxdiphtherie, nachdem Chlor., Kali-bi., Lac-c. versagt haben. Postdiphtherische Lähmung, nachdem Caust., Gels. versagt haben."}],"rem":1,"orig":"Diphtherinum"},{"label":"Dolichos pruriens","short":"Dolichos pruriens","group":"Arzneimittellehre","paras":[{"t":"Dolichos pruriens, Juckbohne. Rechtsseitig. Leber; Haut; sehr intensives Jucken ohne Ausschlag. Extreme nervöse Empfindlichkeit. Seniler Pruritus. Verstopfung mit intensivem Juckreiz. Kolik von nassen Füßen. Aufgetriebener Bauch; weiße Stühle. Leberschwellung. Hämorrhoiden mit Brenngefühl. In Schwangerschaft."},{"t":"Schlaflos, ruhelos, verzweifelt bis zum Suizid durch Juckreiz. Schreit laut, will sich umbringen vor Juckreiz und Empfindlichkeit, Agg.: nachts bis 3/4 Uhr. Splitterschmerz im Rachen. Entzündetes Zahnfleisch mit Schmerz; Jucken am Zahnfleisch, Agg.: Bettwärme, Amel.: Kälteanwendungen; kann nicht essen oder trinken. Will Haut aufreißen, bis Blut fließt."},{"t":"Bauch aufgetrieben, viel Blähungen, Windabgang. Nach Ägyptenreise."},{"t":"Nach Kratzen verlagert sich der Juckreiz. Herpes zoster."},{"t":"Agg.: nachts; Kratzen; Wärme; rechts."},{"t":"Amel.: Kälte; nasse Umschläge."}],"rem":1,"orig":"Dolichos pruriens"},{"label":"Drosera rotundifolia","short":"Drosera rotundifolia","group":"Arzneimittellehre","paras":[{"t":"Drosera rotundifolia, Sonnentau. Hustenanfälle mit starkem Nasenbluten. Anfälle rasch hintereinander. Asthma, Agg.: Sprechen. Tiefer, heiserer, bellender Husten. Ständiger, nächtlicher, bellender Husten bei Kindern, Agg.: Liegen, sobald der Kopf das Kissen berührt (Bell.; Hyos.; Rumex); muß beim Husten die Seiten halten; gefolgt von Würgen, Erbrechen, kaltem Schweiß, Zyanose, Agg.: nach Mitternacht. Schleim eitrig oder blutig. Keuchhusten. Kitzeln wie Feder oder Krümel im Kehlkopf. Frösteln mit heißem Gesicht, sogar im Bett. Linke Gesichtshälfte kalt, rechts heiß und schmerzhaft. Tonisch-klonische Krämpfe. Zucken."},{"t":"Chronische Halsentzündung: rauh, kratzend, trocken, tief im Schlund. Stimme heiser, tonlos, kann nur mit Mühe sprechen. Heiserkeit. Phthisis."},{"t":"Beschwerden nach Masern."},{"t":"Abneigung: Schweinefleisch; Saures."},{"t":"Agg.: nach Mitternacht; Hinlegen; Saures; Wärme; Trinken; Singen; Lachen; Weinen; nach Masern."}],"rem":1,"orig":"Drosera rotundifolia"},{"label":"Dulcamara","short":"Dulcamara","group":"Arzneimittellehre","paras":[{"t":"Solanum dulcamara, Bittersüß. Egozentrik. Kontrolliert, dominiert; besitzergreifend. Eigensinnig, andere sind undankbar, an allem schuld. Rechthaberisch. Außerhalb des Einflußbereiches: gehässig. Extreme Angst um andere wegen erstickendem Besitzanspruch. Innere Anspannung führt zu Hypertonie. Folge von Wetterwechsel von heiß nach feucht-kalt: Diarrhoe, Gelenkschmerz, Schnupfen. Asthma oder Durchfall von unterdrückten Ausschlägen. Kopfschmerz nach unterdrücktem Katarrh. Gesichtsneuralgie nach unterdrücktem Hautausschlag im Gesicht. Husten nach körperlicher Anstrengung."},{"t":"Heuschnupfen. Allergien mit Schleimhautaffektionen. Gesichtslähmung mit schwieriger Sprache; von unterdrückter Akne."},{"t":"Gesichtskälte mit Heißhunger, gefolgt von Schmerz. Harndrang bei Frost."},{"t":"Ausschlag während Menses, flüchtiges Exanthem vor Menses. Grindkopf, Ausschlag Gesicht und Genitalien. Juckreiz bei feuchtkaltem Wetter. Fleischige, flache Warzen (Gesicht, Hände)."},{"t":"Verlangen: kalte Getränke; Süßigkeiten."},{"t":"Agg.: Erkältung; Kaltwerden nach Überhitzung; Wetterwechsel; Kälte, Nässe; feuchte Keller; Unterdrückung; kalte Getränke."},{"t":"Differentialdiagnose: Calc.: beide Adipositas, kälteempfindlich, Agg.: Warm nach Kalt, Süßverlangen, Angst um Zukunft, aber Dulc. extreme Angst um andere."},{"t":"Differentialdiagnose: Kali-c.: auch innerlich angespannt, verträgt keine Kälte, Verlangen nach Süßem."}],"rem":1,"orig":"Dulcamara"},{"label":"Elaps corallinus","short":"Elaps corallinus","group":"Arzneimittellehre","paras":[{"t":"Elaps corallinus, Korallenotter. Schwarze Absonderungen, Menses, Zerumen, Auswurf, Nasenbluten. Kälte Brust, Magen, nach Trinken; Agg.: Obst, nasses Wetter. Tuberkulose in der Familienanamnese."},{"t":"Furcht vor Regen; vor Schlaganfall. Mißtrauisch, intensiv, hochmütig."},{"t":"Chronischer Nasenkatarrh mit stinkendem Geruch und grünlichen Krusten. Ozaena. Nasenausgänge verstopft mit grünem Schleim. Links wunder Rachen."},{"t":"Appetit mit Unfähigkeit zu essen; Essen und Getränke fallen schwer in den Magen. Kaltes bekommt nicht. Obst und Eiswasser liegen sehr kalt im Magen. Magenschmerz, Amel.: Liegen auf dem Bauch; ausstrahlend zum Rücken. Als ob etwas im Uterus platzt, dann dunkles Blut; Endometriose; Dysmenorrhoe. Rheumatische Diathese. Rechtsseitige Lähmung."},{"t":"Verlangen: Milch; Saures; Salat; Eis; Orangen; kaltes Essen."},{"t":"Abneigung: Bananen."},{"t":"Agg.: herannahender Sturm; feuchtes Wetter; kalte Getränke; Obst."},{"t":"Amel.: Liegen auf dem Bauch."}],"rem":1,"orig":"Elaps corallinus"},{"label":"Equisetum hyemale","short":"Equisetum hyemale","group":"Arzneimittellehre","paras":[{"t":"Equisetum, Ackerschachtelhalm. Dysurie. Enuresis. Starker, dumpfer Schmerz und Völlegefühl in der Blase, nicht erleichtert durch Wasserlassen. Drang und Schmerz am Schluß der Miktion (Sars.). Je voller die Blase, desto angenehmer. Ständiger Drang. Große Mengen klaren Urins. Brennender, schneidender Schmerz in Urethra beim Wasserlassen. Tiefer Schmerz in rechten Niere, in Unterbauch ausstrahlend. Rechte Lumbalgegend schmerzhaft. Blasenlähmung alter Frauen. Enuresis nocturna mit Alpträumen beim Einnässen."},{"t":"Enuresis diurna et nocturna."},{"t":"Agg.: Ende der Miktion; Druck."}],"rem":1,"orig":"Equisetum hyemale"},{"label":"Erigeron canadense","short":"Erigeron canadense","group":"Arzneimittellehre","paras":[{"t":"Erigeron canadensis, Kanadisches Berufskraut. Blutungen. Leukorrhoe; Metrorrhagie mit heftiger Reizung von Rektum, Blase, Uterusprolaps; Menorrhagie,"},{"t":"Agg.: geringste Belastung oder Bewegung. Reichliche Blutung hellrot, in Güssen. Uterusblutung nach Abort; blutige Lochien. Nasenbluten statt Menses. Anhaltende Blutung aus der Blase. Blutende Hämorrhoiden. Dysenterie mit Wundheit und brennender Blase. Blähsucht."},{"t":"Agg.: Belastung; Bewegung."}],"rem":1,"orig":"Erigeron canadense"},{"label":"Eupatorium perfoliatum","short":"Eupatorium perfoliatum","group":"Arzneimittellehre","paras":[{"t":"Eupatorium perfoliatum, Wasserhanf. Schmerzen wie zerschlagen, zerbrochen am ganzen Körper, kommen und gehen plötzlich. Heiserkeit und Husten mit Empfindlichkeit der Brust. Muß Brust halten. Kopfschmerz wie Bleikappe auf ganzen Schädel; Gefühl, nach links zu fallen. Kopfschmerz mit gichtigen Schmerzen, Amel.: Galleerbrechen; Unterhaltung. Kopfschmerz mit Schmerz in den Augäpfeln; periodisch, alle 3/7 Tage. Hinterkopfschmerz, Agg.: Liegen, mit Schweregefühl. Zunge gelb, bitterer Geschmack, Leberschmerz. Durst."},{"t":"Husten nach Masern."},{"t":"Lumbalgie. Schmerz in kleinen Knochen. Handgelenk fühlt sich luxiert an. Schwellung linke Großzehe. Gicht; entzündete Knötchen an Gelenken. Influenza mit großer Empfindlichkeit in Muskeln und Knochen. Gliederschmerz am ganzen Körper; Schmerz macht ruhelos. Schüttelfrost von 7-9 Uhr, vorher unstillbarer Durst mit starker Reizbarkeit und Knochenschmerzen. Schüttelfrost kommt, weil er nicht genug trinken kann. Bitteres Erbrechen nach Schüttelfrost. Wiederkehrendes Fieber. Periodizität. Innerliche Hitze, aber äußerlich kalt."},{"t":"Verlangen: Eiskrem; kalte Getränke und Essen; bei Fieber warme Getränke."},{"t":"Agg.: kalte Luft; Bewegung; 7-9 Uhr."},{"t":"Amel.: Gallebrechen. Schwitzen erleichtert alle Symptome, außer Kopfschmerz."}],"rem":1,"orig":"Eupatorium perfoliatum"},{"label":"Eupatorium purpureum","short":"Eupatorium purpureum","group":"Arzneimittellehre","paras":[{"t":"Eupatorium purpureum, Roter Wasserhanf. Reizblase mit Dysurie. Nierenwassersucht; Albuminurie, Diabetes insipidus. Schmerz und Frösteln laufen nach oben. Heimweh. Linksseitiger Kopfschmerz mit Schwindel."},{"t":"Ständiger Harndrang; Blase scheint voll zu sein. Vergrößerte Prostata. Kolikschmerz nach Wasserlassen. Schmerz in linkem Ovar. Vulva fühlt sich feucht an. Frösteln beginnt im Rücken. Heftiges Zittern mit relativ wenig Kaltsein. Kein Durst beim Schüttelfrost, aber Stirnkopfschmerz; oder Verlangen nach kalten Getränken und Limonade."},{"t":"Verlangen: kalte Getränke; Limonade (während Frost)."},{"t":"Agg.: Bewegung; Lagewechsel."}],"rem":1,"orig":"Eupatorium purpureum"},{"label":"Euphorbium officinarum","short":"Euphorbium officinarum","group":"Arzneimittellehre","paras":[{"t":"Euphorbia lathyris, Kreuzblättrige Wolfsmilch. Schreckliche, brennende Schmerzen. Krebsschmerzen. Gliederschmerzen und paralytische Gelenkschwäche. Wirkt auf Haut und Schleimhäute bei reichlich Absonderung und Trockenheitsgefühl."},{"t":"Akute Manie: Wahnvorstellung, die selbe Person geht vor und hinter ihm."},{"t":"Alles erscheint größer. Reichlich salziger Speichelfluß. Durst auf kalte Getränke."},{"t":"Dyspnoe mit Zusammenschnürung der Brust. Spastischer, trockener Husten tag und nacht, mit Asthma. Heftiger Laufschnupfen mit Brennen und Husten. Dauernder Husten mit Stichen vom Epigastrium zu den Seiten des Brustkorbs. Krupp. Trockener, hohler Husten. Wärmegefühl in Brust wie von Schlucken heißer Nahrung."},{"t":"Erysipel mit Bläschen im Gesicht mit Beißen, Stechen, Rötung, Schwellung. Gangrän. Ulzerierendes Karzinom und Epitheliome der Haut."},{"t":"Agg.: Sitzen; beginnende Bewegung."},{"t":"Amel.: fortgesetzte Bewegung; kalte Anwendungen."}],"rem":1,"orig":"Euphorbium officinarum"},{"label":"Euphrasia officinalis","short":"Euphrasia officinalis","group":"Arzneimittellehre","paras":[{"t":"Euphrasia off., Augentrost. Konjunktivitis mit reichlichem, beißendem Tränenfluß bei mildem Schnupfen, Agg.: abends, Amel.: im Freien. Katarrhalische Konjunktivitis mit scharfem Eiter. Häufige Neigung zu Blinzeln. Augen schwimmen dauernd. Klebriger Schleim auf Hornhaut. Kleine Blasen auf Hornhaut. Rheumatische Iritis. Photophobie mit Lidspasmen."},{"t":"Starker Fließschnupfen mit heftigem Husten und massenhaftem Auswurf. Keuchhusten nur am Tage, mit reichlichem Tränenfluß."},{"t":"Hochräuspern und Erbrechen von stinkendem Schleim, Agg.: morgens."},{"t":"Berstender Kopfschmerz mit Gefühl des Geblendetseins in den Augen."},{"t":"Katarrhalischer Kopfschmerz mit starker Absonderung aus Augen und Nase."},{"t":"Gähnen beim Gehen im Freien. Schläfrig am Tage."},{"t":"Masern im ersten Stadium mit Augensymptomen."},{"t":"Menses schmerzhaft, regelmäßig, nur eine Stunde lang."},{"t":"Agg.: Licht; warmer Südwind; Zimmer; Wärme."},{"t":"Amel.: im Freien."}],"rem":1,"orig":"Euphrasia officinalis"},{"label":"Eupionum","short":"Eupionum","group":"Arzneimittellehre","paras":[{"t":"Eupion, Holzteerdestillat. Frauenmittel: Lumbago; Leukorrhoe; Uterusverlagerungen. Uterusprolaps. Menses zu früh und reichlich. Nach Menses gelber Ausfluß mit starken Rückenschmerzen. Bei Aufhören des Rückenschmerzes gußartiger, milder Weißfluß. Brennen im rechten Ovar. Chronische Tubenerkrankung. Wundheitsschmerz zwischen Schamlippen beim Wasserlassen. Starker Schweiß durch leichteste Anstrengung. Unangenehme, ekelerregende Träume. Während Menses reizbar und wortkarg."},{"t":"Kreuzschmerz, wie gebrochen. Schwere Lumbago; muß sich zur Unterstützung gegen etwas lehnen. Schmerzen strahlen ins Becken aus."},{"t":"Zittern mit Gefühl, als sei der Körper aus Gallert gemacht."}],"rem":1,"orig":"Eupionum"},{"label":"Fagopyrum esculentum","short":"Fagopyrum esculentum","group":"Arzneimittellehre","paras":[{"t":"Fagopyrum esculentum, Buchweizen. Juckreiz alter Menschen, Agg.: Kratzen, Berührung; Amel.: Kaltbaden. Sichtbares Pulsieren der Arterien. Zerebrale Hyperämie. Unfähig zu studieren und erinnern. Reizbarkeit; Traurigkeit."},{"t":"Kopfschmerz tief im Kopf mit Druck nach oben. Berstender Hinterkopfschmerz."},{"t":"Augenjucken und Schmerz, mit Schwellung und Hitze. Schmerz im Tragus des Ohres. Fließschnupfen mit Niesen, danach Trockenheit und Krustenbildung. Katarrh des Nasenrachenraumes. Übelriechende Absonderungen. Juckendes Erythem."},{"t":"Aufstoßen von brühendheißer, saurer, wässeriger Substanz."},{"t":"Jucken der Vulva mit gelbem Ausfluß."},{"t":"Schmerz um das Herz, zum linken Arm / zur linken Schulter ausstrahlend, Amel.: Liegen auf dem Rücken. In Streifen verlaufende Schmerzen in Armen und Beinen. Juckreiz in Armen und Beinen. Jucken tief in den Händen."},{"t":"Agg.: nachmittags; Sonnenlicht; Kratzen."},{"t":"Amel.: Kaltbaden/Umschläge; Kaffee."}],"rem":1,"orig":"Fagopyrum esculentum"},{"label":"Ferrum iodatum","short":"Ferrum iodatum","group":"Arzneimittellehre","paras":[{"t":"Schwäche, sehr starkes Schwitzen durch leichte Belastung und Wärme, Agg.: nachts. Adipositas. Hypothyreose."},{"t":"Sozial aktiv, aber oberflächliche Kontakte."},{"t":"Exophthalmischer Kropf nach unterdrückten Menses. Völlegefühl nach wenig Nahrung. Auftreibung des Kolons mit viel Gas. Durchfall, Kolitis."},{"t":"Gefühl des Krabbelns in Urethra und Rektum."},{"t":"Gefühl, als ob etwas in der Vagina nach oben presse. Retroversion und Uterusprolaps. Pruritus vulvae."},{"t":"Hypertonie."},{"t":"Verlangen: Salz; Fisch."},{"t":"Abneigung: Tabak; Wärme."}],"rem":1,"orig":"Ferrum iodatum"},{"label":"Ferrum phosphoricum","short":"Ferrum phosphoricum","group":"Arzneimittellehre","paras":[{"t":"Schwäche, Anämie. Nervös, empfindlich, leichtes Erröten. Unzufrieden. Abneigung Gesellschaft."},{"t":"Nasenbluten. Pulsieren des Körpers und Kopfes. Wut verursacht Schwäche, Kopfschmerz, Zittern, Schwitzen. Akutes Fieber ohne Modalitäten."},{"t":"Kopfschmerz mit Ohrenschmerz, Amel.: Nasenbluten und kalte Anwendungen. Kongestion."},{"t":"Wunder Hals, Agg.: Schlucken. Pharyngitis."},{"t":"Kurzer, schmerzhafter, kitzelnder Husten. Harter, trockener Husten mit wunder Brust. Rechtsseitige Pneumonie mit Haemoptysis. Bronchitis kleiner Kinder. Durst auf große Mengen."},{"t":"Schulterschmerz, ausstrahlend zum Brustkorb, Handgelenk. Rheumatismus wandert von Gelenk zu Gelenk."},{"t":"Verlangen: Saures; Stimulanzien; Erfrischendes."},{"t":"Abneigung: Fleisch; Milch."},{"t":"Agg.: nachts; Unterdrückte Schweiße."},{"t":"Amel.: kalte Anwendungen (Kopfschmerz)."}],"rem":1,"orig":"Ferrum phosphoricum"},{"label":"Ferrum metallicum","short":"Ferrum metallicum","group":"Arzneimittellehre","paras":[{"t":"Ferrum met., Eisen. Geringstes Geräusch unerträglich (Asar.; Ther.). Streitsüchtig, zänkisch, leicht erregt. Reizbarkeit. Ärgerlich von geringstem Widerspruch. Stimmungsschwankungen."},{"t":"Furcht vor Schlaganfall. Schwäche, trotz kräftigen Aussehens. Blässe, aber leichtes Erröten durch Schmerz, Erregung, Wein, Anstrengung. Rote Stellen werden weiß. Herzklopfen durch Anämie. Ruhelosigkeit nachts, treibt aus dem Bett. Schwindel mit schwankendem Gefühl wie auf Wasser; beim Anblick von fließendem Wasser, beim Überqueren einer Brücke; Abwärtsgehen. Kopfschmerz hämmernd, für 2-3 Tage, periodisch, alle zwei Wochen. Nasenbluten von Kindern; abwechselnd mit blutiger Expektoration. Zahnschmerz, Amel.: eiskaltes Wasser. Leichtes Erbrechen, kann danach sofort weiteressen. Erbrechen während des Essens. Heißhunger abwechselnd mit Widerwillen gegen alle Speisen. Unverträglichkeit von Eiern. Diarrhoe, Agg.: nachts; beim Essen oder Trinken; schmerzlos bei gutem Appetit. Unverdaute Stühle. Jucken von Würmern. Urin tröpfelt den ganzen Tag. Dyspnoe von unterdrückten Hautausschlägen; nach Mitternacht."},{"t":"Kalte Hände und Füße. Schulterschmerz. Schwellung von Händen und Füßen, Ödeme. Varizen. Schwitzen mit Hitzewallungen. Adipositas. Anämie."},{"t":"Verlangen: Brot und Butter; Tomaten; warmes, flüssiges Essen; Süßes."},{"t":"Abneigung: Eier; Saures; saures Obst; Bier."},{"t":"Agg.: Mitternacht; Säfteverlust; Erregung; Anstrengung; Eier."},{"t":"Amel.: langsame Bewegung, Schwäche zwingt jedoch zum Niederlegen; Wärme."},{"t":"Rauhere Persönlichkeit als Calc. Harte Arbeiter, möchte viel Geld verdienen, handelt aus Entschlossenheit. Bei Erschöpfung reizbarer als Calc."}],"rem":1,"orig":"Ferrum metallicum"},{"label":"Fluoricum acidum","short":"Fluoricum acidum","group":"Arzneimittellehre","paras":[{"t":"Flußsäure. Gleichgültig gegenüber geliebtesten Personen; unfähig, Verantwortung wahrzunehmen; materialistisch; erfolgreiche Geschäftsleute; unsensibel; primitive Energie; starkes sexuelles Verlangen; aggressiv; braucht Macht über andere; Eile. Unkontrollierbare Furcht: Krebs, schlimmes Leiden."},{"t":"Tiefgehende, zerstörende Prozesse. Wundliegen, Ulzerationen. Varizen. Naevi. Juckende Körperöffnungen. Juckende Narben, umgeben von Pickeln. Gefühl, als ob heißer Dampf aus Poren abgelassen wird. Warmblütig."},{"t":"Karies der Knochen, Gehörknöchelchen, Zähne, Haut. Periostaler Abszeß."},{"t":"Fisteln von Rektum, Tränengang, Zahnfleisch (blutige, salzige Absonderung). Vorzeitige Alterung. Leberzirrhose. Wenig Durst. Splittergefühl unter Nägeln; deformiert, brechen ab. Haarausfall; Epitheliom. Varizen. Schläft sofort ein (links und rechts), erwacht nach 3-4 Std., Amel.: Kaltduschen (ergänzend: Puls.; Sil.)"},{"t":"Kopfschmerz entlang den Nähten, Amel.: Wasserlassen. Haarausfall. Glabellagebiet geschwollen. Gefühl, als ob kalter Wind durch die Augen bliese. Wunder Rachen beim Einatmen kalter Luft. Verstopfung; Prolaps; Hämorrhoiden. Schmerzhafte nächtliche Erektionen, Priapismus."},{"t":"Ulzera von Uterus und Zervix. Nymphomanie. Schlaflosigkeit, erwacht nach 3-4 Stunden mit sexuellen Gedanken."},{"t":"Verlangen: Gewürztes; Stimulanzien; kalte Getränke."},{"t":"Abneigung: Kaffee; warme Getränke."},{"t":"Agg.: Wärme; Nacht; Hitze oder Kälte."},{"t":"Amel.: Kaltbaden; energische Bewegung."}],"rem":1,"orig":"Fluoricum acidum"},{"label":"Formica rufa","short":"Formica rufa","group":"Arzneimittellehre","paras":[{"t":"Formica rufa, rote Waldameise. Arthritis. Chronische Gicht mit Gelenksteifigkeit. Gichtanfall. Plötzlich auftretender Rheumatismus mit Ruhelosigkeit. Rasch sich verlagernde rheumatische Schmerzen und Schwellungen. Schweiße erleichtern nicht. Schwäche der unteren Extremitäten. Paraplegie. Hüftschmerz. Muskeln überanstrengt und wie aus ihren Ansätzen gerissen. Beschwerden durch Überheben."},{"t":"Schnupfen mit verstopfter Nase. Polypen in Nase und Ohr. Rheumatische Iritis. Ziehender Schmerz um den Nabel vor Stuhlgang. Schmerzhafter Stuhlgang mit Zittern und Frösteln. Durchfallartiger Drang. Zusammenschnürung des Anus. Haut gerötet, juckend, brennend, Urtikaria."},{"t":"Agg.: Kälte, Nässe; Bewegung; vor Schneesturm."},{"t":"Amel.: Reiben; Druck; Wärme; nach Mitternacht."}],"rem":1,"orig":"Formica rufa"},{"label":"Gambogia","short":"Gambogia","group":"Arzneimittellehre","paras":[{"t":"Gambogia, Orangebraunes Gummiharz. Reichlicher Durchfall im Alter, wässerig, plötzlich, gewaltsam herausstoßend, Agg.: heißes Wetter; Sommerdiarrhoe (Crot-t.). Tenesmus mit Brennen nach dem Stuhlgang. Kollaps mit Brechdurchfall und kaltem Schweiß. Schmerz in Ileözäkalregion und Nabel; druckempfindlich. Dauernder Drang, nicht erleichtert durch Stuhlgang. Morbus Crohn; Kolitis. Rumpeln und Kollern."},{"t":"Traurigkeit wechselt mit Durchfall; oder Traurigkeit von unterdrücktem Durchfall. Dysenterie. Reizbarer Magen; Zunge und Rachen schmerzhaft brennend, trocken."},{"t":"Suizidgedanken. Sehr starkes sexuelles Verlangen; Perversionen."},{"t":"Brennender Schmerz in Leber, Auge, Anus. Kältegefühl an den Zahnrändern."},{"t":"Dermatitis mit Rötung der Hinterbacken bei Kindern mit Durchfall. Schmerz im Steißbein. Fröstelig."},{"t":"Kombination: Durchfall und Hypersexualität, Nymphomanie."},{"t":"Agg.: Kälte; kaltes Essen; Eis; abends und nachts; heißes Wetter; im Alter."}],"rem":1,"orig":"Gambogia"},{"label":"Gelsemium sempervirens","short":"Gelsemium sempervirens","group":"Arzneimittellehre","paras":[{"t":"Gelsemium sempervirens, Falscher Jasmin. Zerbrechlichkeit. Erschöpfung und Schwäche. Betäubung und Zittern am ganzen Körper; motorische Paralyse verschiedener Muskelgruppen. Benommenheit. Muskelkoordinationsstörungen, Muskeln gehorchen nicht dem Willen."},{"t":"Schwermut, Traurigkeit: \"Ich bin so schwach, ich kann nicht arbeiten\". Unzufriedenheit. Apathie, die eigene Krankheit betreffend. Abscheu, Gleichgültigkeit dem Leben gegenüber. Scheu, schüchtern, Abneigung gegen und Angst vor Gesellschaft."},{"t":"Erwartungsangst (Hauptmittel): Beine schwach, Zittern, Diarrhoe vor öffentlichem Auftritt; Feigheit. Schlimme Folgen von schlechter Nachricht, Kummer, Erregung, Schreck, plötzlichen Gefühlserregungen; nach Grippe nicht richtig erholt. Nach Masturbation unzufrieden, nervös, reizbar."},{"t":"Zittern mit Herzklopfen, muß sich bewegen, damit Herz nicht stehenbleibt."},{"t":"Leicht erregbar, Nervensystem aufs Höchste angespannt; Angst, Kontrolle zu verlieren. Angst vor Abwärtsbewegung im Fahrstuhl (Bor.). Schwindel vom Hinterkopf sich ausbreitend (Sil.), mit Doppelbildern, Sehstörungen. Schwankt wie betrunken."},{"t":"Kopfschmerz vom Nacken zum Hinterkopf, über ganzen Kopf. Bersten der Stirn und in Augäpfeln, Agg.: Anstrengung; Tabakrauch; Sonnenhitze; Kopftieflage. Gefühl wie Band um den Kopf. Kopfhaut berührungsempfindlich. Sehstörung vor Kopfschmerz (Iris Hauptmittel; Sep.). Eiskalte Füße während Kopfschmerz (Bell.), Amel.: nach Wasserlassen. Gesicht dunkelrot, heiß, schwer, berauscht aussehend (Bapt.; Op.). Gesichtsneuralgie. Zunge taub, dick, zitternd, gelähmt."},{"t":"Viele Augensymptome: Herunterhängen der Lider, Lähmung. Schwere der Augenlider. Trübsichtigkeit. Orbitalneuralgie. Netzhautablösung. Glaukom."},{"t":"Samenergüsse ohne Erektion, während Stuhlgang. Rigidität des Zervix."},{"t":"Fieberfrost ohne Durst, in Wellen den Rücken hinauf- und hinunterlaufend."},{"t":"Masern im katarrhalischen Stadium. Influenza."},{"t":"Agg.: schlechte Nachrichten; Aufregung; Rauchen; Darandenken; feuchtkaltes Wetter; vor Gewitter; fallendes Barometer."},{"t":"Amel.: Harnausscheidung; Schweiß; Kopfschütteln; Alkohol; Trinken."}],"rem":1,"orig":"Gelsemium sempervirens"},{"label":"Glonoinum","short":"Glonoinum","group":"Arzneimittellehre","paras":[{"t":"Glonoinum, Nitroglyzerin. Nervosität. Verwirrung. Verträgt keinen Widerspruch. Mattigkeit."},{"t":"Kopfschmerz, Agg.: Haareschneiden, Hitze, offenes Feuer, Sonne. Kann keinerlei Hitze am Kopf ertragen (Lach.; Nat-c.). Beschwerden durch Erregung, Schreck, Furcht, körperliche Verletzung und deren Folgen (Acon.; Bell.)."},{"t":"Furcht, vergiftet zu werden; vor Apoplexie beim Erwachen. Verirrt sich in wohlbekannten Straßen. Kopfschmerz anstatt Menses. Vergrößerungsgefühl des Kopfes. Pulsierender Kopfschmerz, Hitzewallungen, Agg.: Hitze, Bewegung, Bücken, Amel.: Druck; kommt und geht mit der Sonne. Gehirn wie zu groß. Hypertonie. Heftige hämmernde Pulsationen; Blut schießt nach oben. Krämpfe. Sonnenstich. Herzklopfen mit klopfenden Karotiden, spürbar im ganzen Körper bis in Fingerspitzen. Mühsame Herztätigkeit, Agg.: jede Anstrengung. Ohnmachtsanfälle."},{"t":"Konvulsionen bei Kindern durch zerebrale Kongestion. Kindern wird übel beim Sitzen vor dem Feuer. Meningitis, während Zahnung. Klimakterium; unterdrückte Menses."},{"t":"Agg.: Hitze; Sonne; künstliches Licht; Erschütterung."},{"t":"Amel.: frische Luft; Liegen mit erhöhtem Kopf; Weinbrand."}],"rem":1,"orig":"Glonoinum"},{"label":"Gnaphalium polycephalum","short":"Gnaphalium polycephalum","group":"Arzneimittellehre","paras":[{"t":"Gnaphalium polycephalum, Vielköpfiges Ruhrkraut. Ischiasschmerz mit Taubheit; oder Schmerz abwechselnd mit Taubheitsgefühl. Amel.: Anziehen der Beine und Beugen der Oberschenkel gegen den Leib. Waden- und Fußkrämpfe. Schienbeinneuralgie (Staph.)."},{"t":"Neuralgische Schmerzen im Abdomen, Genitalien. Dysmenorrhoe."},{"t":"Lumbago, Amel.: Liegen auf dem Rücken. Rheumatismus von Sprunggelenk und Füßen. Schmerz in Gelenken, als ob es ihnen an Öl fehlte."}],"rem":1,"orig":"Gnaphalium polycephalum"},{"label":"Graphites","short":"Graphites","group":"Arzneimittellehre","paras":[{"t":"Graphites, Abart des Kohlenstoffes, Reißblei. Stumpf, dickhäutig, fett, schlaff. Verstopfung. Verzögerte Menses. Klimakterium. Fernfahrer; Arbeiter. Geist träge, lethargisch; schwierig, Kontakt aufzunehmen. Schwaches Gedächtnis, geistige Leere. Zögern; Unentschlossenheit. Neigung, hochzufahren. Furchtsam: daß etwas Schlimmes passiert. Weinen bei Musik, Traurigkeit, Verzagtheit, denkt an den Tod."},{"t":"Ungezogene Kinder, hänselnd, quengelnd, lachen bei Tadel."},{"t":"Schlimme Ekzeme. Fibrome, Keloide. Herpesartig, schuppend, in Ellenbeuge, Kniekehle, an Haargrenze und Ohren; Handrückenekzem; Hautrisse an Brustwarzen, Mund, zwischen Zehen, Anus, Fingerspitzen. Ausschlag mit dicker, klebriger, honigartiger Absonderung. Lidekzem, feucht und rissig; Lidränder verkrustet. Hauttrockenheit. Hautausschläge hinter den Ohren. Trockenheit des inneren Ohres."},{"t":"Hören, Amel.: bei Geräusch, im rollenden Fahrzeug."},{"t":"Jede Verletzung eitert (Hep.).; alte Narben brechen auf; Entartung von alten Narben rezidivierender Abszesse. Brüchige, deformierte Nägel."},{"t":"Nach unterdrücktem Ausschlag: Asthma, Ulzera, Kopfschmerz. Magenkrämpfe, Brennschmerz, Amel.: Essen und nach heißer Milch."},{"t":"Abwechselnd: Ulkus - Haut. Chronische Obstipation. Wundschmerz im Anus nach Stuhl. Diarrhoe stinkend, durch unterdrückte Hautausschläge. Sommersprossen, Agg.: Verstopfung."},{"t":"Erröten, kurz, bevor körperliches Symptom auftritt. Lichtempfindlich. Taubheit der Extremitäten, vor allem Unterarm;"},{"t":"Kälteempfindlich. Juckende Varizen. Ulcus cruris."},{"t":"Abneigung gegen Verkehr. Dysmenorrhoe; Menses spärlich, blaß, spät, unregelmäßig, verzögert nach Durchnässung der Füße (Puls.). Wundmachende Leukorrhoe mit Rückenschwäche. Kombination Heiserkeit und Ausschlag. Beschwerden gehen von links nach rechts."},{"t":"Abneigung: Salz; Süßes; Fisch (einziges Mittel mit dieser Kombination, Gegenteil: Arg-n.); Fleisch; Fett."},{"t":"Verlangen: Hähnchen."},{"t":"Agg.: morgens; unterdrückte Ausschläge; Kälte."},{"t":"Amel.: abends; warme Getränke; Essen."}],"rem":1,"orig":"Graphites"},{"label":"Gratiola officinalis","short":"Gratiola officinalis","group":"Arzneimittellehre","paras":[{"t":"Gratiola off., Gottesgnadenkraut. Blähungen wie Lyc.; Gastritis; Zwölffingerdarmgeschwüre. Nervlich schwach, unzufrieden, sehr gereizt (Cham.; Nux-v.), egoistisch. Frauenmittel, sexuell nicht zu befriedigen, Nymphomanie. Linksseitig. Neuralgien. Adnexitis. Nierenkolik. Hochmut aus Unzulänglichkeit. Impulsiv. Kolitis mit Auftreibung. Rumpeln. Durchfall, schmerzlos und zwingend; grünes, schaumiges Wasser, danach Brennen am Anus."},{"t":"Krämpfe und Kolik nach dem Abendessen und in der Nacht mit Schwellung des Leibes und Verstopfung. Kältegefühl im Magen und Abdomen."},{"t":"Klopfen und Schmerz im Steißbein nach Stuhlgang."},{"t":"Gefühl, als ob Kopf zu klein, Gehirn zusammengezogen. Blutandrang zum Kopf."},{"t":"Folge von Kaffeeabusus. Viele Nux-v.-Symptome bei Frauen."},{"t":"Kombination: Verdauungsprobleme und Hypersexualität, Nymphomanie, Mut."},{"t":"Verlangen: nur Brot."},{"t":"Agg.: zuviel Wasser; Kaffee; links."}],"rem":1,"orig":"Gratiola officinalis"},{"label":"Grindelia robusta","short":"Grindelia robusta","group":"Arzneimittellehre","paras":[{"t":"Grindelia robusta aut squarrosa. Erstickungsanfälle beim Einschlafen oder Erwachen. Dyspnoe, Rasseln, Emphysem, chronische Bronchitis mit schwieriger Expektoration."},{"t":"Schmerz in den Augäpfeln, nach hinten ausstrahlend, Agg.: Bewegung der Augen. Milzvergrößerung. Schneidender Schmerz von der Milz zur Hüfte."},{"t":"Dyspnoe, Agg.: Liegen; muß sich aufsetzen. Herzdilatation bei Dyspnoe. Cheyne-Stokes Atmung. Keuchhusten. Rhusvergiftung."}],"rem":1,"orig":"Grindelia robusta"},{"label":"Guajacum officinale","short":"Guajacum officinale","group":"Arzneimittellehre","paras":[{"t":"Guajacum off., Harz des Guajakbaumes, Pockenholz. Alt aussehend. Starrer Blick. Flexibilitätsverlust. Verkürzungsgefühl der Sehnen. Arthritis mit Entzündungsgefühl nach Tonsillarabszeß, Amel.: kaltes Wasser (nicht zu kalt), Agg.: Hitze, Bewegung, Druck. Gelenkabszeß."},{"t":"Antwortet langsam. Vergeßlich; langsames Verstehen."},{"t":"Gichtiger, rheumatische Kopfschmerz, zum Nacken ausstrahlend. Kopfschmerz endet in Stechen. Anwachsende Schmerzen. Nackensteifigkeit und Schulterschmerz. Rheumatismus der oberen Gliedmaßen, besonders des (links) Handgelenks und der Brustwirbelsäule. Karpaltunnelsyndrom."},{"t":"Unsauberer Körpergeruch. Faulige Absonderungen."},{"t":"Verlangen: Äpfel; Obst."},{"t":"Abneigung: Milch."},{"t":"Agg.: Hitze; Berührung; Bewegung."},{"t":"Amel.: kalte Anwendungen."}],"rem":1,"orig":"Guajacum officinale"},{"label":"Hamamelis virginiana","short":"Hamamelis virginiana","group":"Arzneimittellehre","paras":[{"t":"Hamamelis virginiana, Viginische Zaubernuß. Passive Blutung aller Körperteile, aus allen Körperöffnungen. Venöse Kongestion. Wundheitsgefühl Schmerzhaftigkeit mit Zerschlagenheitsgefühl der betroffenen Körperteile. Schnitt-, Riß- Quetschwunden."},{"t":"Kopf wie zu klein. Gefühl wie Bolzen von Schläfe zu Schläfe. Blutunterlaufene Augen, Konjunktivitis. Blutungen im Auge, nach starkem Husten. Unstillbares Nasenbluten. Varizen im Rachen."},{"t":"Magenblutung; Bluterbrechen."},{"t":"Schmerzhafte Hämorrhoidenblutung mit Wundheitsgefühl am Anus, wie roh; Schweregefühl, als ob der Rücken durchbrechen wollte. Dysenterie. Pulsationen am Anus. Große Schwäche nach wenig Blutverlust."},{"t":"Menses dunkel, reichlich, mit Bauchschmerz. Metrorrhagie zwischen den Perioden."},{"t":"Neuralgische Schmerzen im Samenleiter, in Hoden ausstrahlend. Varikozele. Orchitis, Hoden vergrößert, heiß, schmerzhaft. Epididymitis."},{"t":"Varizen, punktförmig stechende Ulzera. Akute Thrombophlebitis; Thrombose. Bluthusten. Hämaturie."},{"t":"Agg.: feuchtwarme Luft; während Menses."}],"rem":1,"orig":"Hamamelis virginiana"},{"label":"Hecla lava","short":"Hecla lava","group":"Arzneimittellehre","paras":[{"t":"Hecla lava, Lava vom Heklavulkan, Island. Knochen: Exostosen, Karies, Knötchenbildung, Osteosarkom. Gesichtsneuralgie durch Zahnkaries und nach Extraktion. Zahnfleischabszeß. Schwierige Zahnung. Kieferschwellung. Geschwollene, verhärtete Drüsen."}],"rem":1,"orig":"Hecla lava"},{"label":"Helleborus niger","short":"Helleborus niger","group":"Arzneimittellehre","paras":[{"t":"Helleborus niger, Christwurzel, schwarze Nießwurz. \"Sie schauen, aber sie sehen nicht; sie hören, aber sie verstehen nicht\". Verbindung nach außen unterbrochen, Sinneseindrücke werden nicht bewußt. Antwortet sehr langsam, überlegt lange. Unfähigkeit zu reflektieren; unentschlossen. Stierender Blick, erschreckter Ausdruck. Geist leer, akuter Schwachsinn. Seufzen. Emotional abgestumpft, apathisch, empfindet nichts. Mag nicht gestört werden. Im Inneren spielt sich etwas Qualvolles ab. Wildes Gefühl im Kopf. Hyperventilation. Eigene Welt."},{"t":"Folge von Enzephalitis, Meningitis, Chemotherapie, emotionaler Schock, Schädel-Hirn-Trauma."},{"t":"Hydrozephalus. Konvulsionen mit extremer Kälte des Körpers. Ruhelosigkeit bei meningealer Reizung. Cri encéphalique. Bohrt den Kopf in die Kissen. Rollt den Kopf hin und her. Schlägt mit den Händen gegen den Kopf. Kauende Mundbewegungen. Automatismen. Schrecklicher Mundgeruch."},{"t":"Hirndrucksteigerung: Hinterkopfschmerz, Erbrechen, Bewußtlosigkeit, erweiterte Pupillen. Zupfen an Kleidern und Lippen. Automat. Bewegung eines Armes und eines Beines. Vorderlappentumoren mit Persönlichkeitsveränderungen."},{"t":"Urin rot, schwarz, spärlich, kaffeesatzartiges Sediment."},{"t":"Ödeme, Ergüsse: Hirnödem, Hydrothorax, Aszites, akutes Nierenversagen."},{"t":"Abneigung: Gemüse; Fleisch; Sauerkraut; Äpfel."},{"t":"Agg.: 16-20 Uhr; Unterdrückung; kalte Luft."}],"rem":1,"orig":"Helleborus niger"},{"label":"Heloderma-h. + -s. (old abbr.)","short":"Heloderma-h. + -s. (old abbr.)","group":"Arzneimittellehre","paras":[{"t":"Heloderma suspectum, Gift der Krustenechse."},{"t":"\"Arktische\" Kälte einzelner Körperteile, oder Körperstellen; wie gefroren. Gefühl, sich zu Tode zu frieren. Kältewellen. Untertemperatur."},{"t":"Parkinson, lokomotorische Ataxie; Stolpern."},{"t":"Kältewellen vom Hinterkopf zu den Füßen und umgekehrt. Kaltes Band um den Kopf. Schmerz vom rechten Ohr um den Hinterkopf zum linken Ohr ausstrahlend. Kältegefühl um das Herz; Bradyarrhythmie."},{"t":"Hebt Füße beim Gehen zu stark an, tritt zu hart mit der Ferse auf. Gehen wie auf einem Schwamm; als ob Füße geschwollen sind. Zyanose der Hände."},{"t":"Allergien. Wie Band um den Körper. Linksseitig."},{"t":"Agg.: nachts; nach Schlaf; Kälte."},{"t":"Amel.: Ausstrecken; Wärme."}],"rem":1,"orig":"Heloderma-h. + -s. (old abbr.)"},{"label":"Helonias dioica","short":"Helonias dioica","group":"Arzneimittellehre","paras":[{"t":"Helonias dioica. Schwächegefühl mit Ziehen, wie von einem Gewicht im Kreuz und Becken mit großer Mattigkeit. Fühlt Uterus, Agg.: Bewegung; Darandenken. Erschöpfung nach Geburt, Abort, Schwangerschaft."},{"t":"Uterusverlagerung, Prolapsneigung infolge Erschlaffung, erschöpft durch Trägheit und Luxus; ausgelaugt durch harte körperliche Arbeit. Menses reichlich, zu häufig, oder unterdrückt. Pruritus vulvae in der Schwangerschaft."},{"t":"Empfindlich auf geringsten Widerspruch, nörgelig, reizbar, will alleine gelassen werden. Melancholie, träger Geist."},{"t":"Blutandrang in den Nieren statt Menses. Nierenschmerz., Albuminurie. Nierenumrisse spürbar mit ständigem brennendem Schmerz."},{"t":"Diabetes mellitus und insipidus."},{"t":"Gefühl, als ob kalter Wind auf Waden und Beine bliese."},{"t":"Amel.: Beschäftigung; Ablenkung."}],"rem":1,"orig":"Helonias dioica"},{"label":"Hepar sulphur","short":"Hepar sulphur","group":"Arzneimittellehre","paras":[{"t":"Hepar sulfuris calcareum, Kalkschwefelleber. Schwäche; Überempfindlichkeit; nervöse Erregung: Intoleranz; empfindlich (als lägen wunde Nervenenden frei); extrem schmerzempfindlich (Cham.; Coff.), leisester Druck unerträglich; beschimpft andere; ärgerlich, bösartig; ängstlich wegen Kleinigkeiten. Angst vor Umwelt, kann sich nicht abgrenzen, wie allergisch gegen die Welt. Haßt TV-Nachrichten. Gefühl, sich nicht schützen zu können. Verzweiflung, suizidal gefährdet (Ars.; Nux-v.)."},{"t":"Spricht, ißt, trinkt eilig. Folge von unterdrücktem Zorn. Tötungsimpulse, Kind zu töten (Nux-v.; Sep.). Verlangen, Feuer zu legen. Leiden unerträglich, viel Leiden wegen geringer Ursachen, Jammern, Flehen, Weinen. Gefühl, als ob kalter Wind auf Körperteil bliese."},{"t":"Depression, Suizidgedanken (Nit-ac.). Weinen vor dem Husten; Husten kruppartig, würgend, erstickend, Agg.: kalter Wind."},{"t":"Entzündung von Ohr, Auge, Rachen, Splitterschmerz im Hals, Agg.: Kälte, Amel.: Wärme. Sehr kälteempfindlich. Bronchitis, Sinusitis, Drüsenschwellungen, Hautausschläge, Eiterungen. Asthma durch unterdrückte Hautausschlägen. Kleine Verletzungen eitern. Riß in der Mitte der Unterlippe."},{"t":"Verstopfung bei weichem Stuhl. Übelriechender Atem, Schweiß, Absonderungen: Geruch nach altem Käse, säuerlich."},{"t":"Verlangen: Fett; Saures; Gewürztes; Pickles; Senf; Wein."},{"t":"Abneigung: Fett."},{"t":"Agg.: geringster kalter Luftzug; Berührung kalter Oberflächen; Aufdecken; Berührung; Nacht; trockenes Wetter."},{"t":"Amel.: warme Anwendungen; feuchtheißes Wetter."},{"t":"Hura brasiliensis"},{"t":"brasiliensis, Sandbüchsenbaum, Knallfrucht. Fühlt sich verlassen. Denkt ohne Furcht an den Tod. Reizbar von Kleinigkeiten. Zerstörerisch: zerbricht Dinge, beißt Hände. Schuldgefühle; Angst um die ewige Seligkeit."},{"t":"Appetit verstärkt nach dem Essen. Bauchschmerz, gefolgt von Diarrhoe. Lumbago, Amel.: Zurücklehnen; Agg.: Vorbeugen."},{"t":"Juckende, brennende Ausschläge, vor allem Pickel. Schlaf gestört durch heftigen Juckreiz."},{"t":"Träume: Mord, erotisch, ängstlich."}],"rem":1,"orig":"Hepar sulphur"},{"label":"Hydrastis canadensis","short":"Hydrastis canadensis","group":"Arzneimittellehre","paras":[{"t":"Hydrastis canadensis, Kanadische Gelbwurz. Alt, schwach, leicht ermüdet, kachektisch, schwach. Krebs. Katarrh. Dicke, zähe, gelbe, fädige Absonderung (Kali-bi.)."},{"t":"Deprimiert, überzeugt, daß er sterben muß; wünscht sich den Tod herbei."},{"t":"Sinusitis; Schleim dick, retronasal. Tubenkatarrh. Zungenschwellung; Zähneindrücke."},{"t":"Kropf bei Pubertät und Schwangerschaft. Leukorrhoe dick, fädig."},{"t":"Schwächegefühl im Magen; Geschwür oder Magenkrebs mit viel Erbrechen und Schmerz, Amel.: Milch. Erbricht alles Essen, behält nur Milch und Wasser. Bitterer Geschmack."},{"t":"Chronische Verstopfung, verbunden mit Kopfschmerz. Leberschwäche."},{"t":"Empfindliche Zervikalregion."},{"t":"Husten, Amel.: Liegen. Bronchitis alter Menschen mit dickem Auswurf. Lumbago: muß sich mit Hilfe der Arme von Stuhl erheben."},{"t":"Kälte der Hinterbacken."},{"t":"Krebsige Hautgeschwüre. Haut fleckig, runzlig; Schmerz wie Messerstiche, scharf; eingezogene Brustwarze."},{"t":"Agg.: Einatmen kalter Luft; leichte Blutungen; Waschen; Alter."},{"t":"Verlangen: Schokolade."}],"rem":1,"orig":"Hydrastis canadensis"},{"label":"Hyoscyamus niger","short":"Hyoscyamus niger","group":"Arzneimittellehre","paras":[{"t":"Hyoscyamus niger, Bilsenkraut. Milde Fassade, innerlich hart wie Stahl. Verlangen zu töten; Extreme Eifersucht. Emotionen tiefgefroren; kommuniziert nur über den Kopf. Reizbar, nervös, hysterisch, gewalttätig; Mißtrauen. Paranoia; Schizophrenie; Vergiftungswahn; Zwangsvorstellungen; Geist schwelgt in fremd anmutenden, lächerlichen Dingen. Senilität; murmelt lauter Unsinn, spricht mit Toten. Zupft an Kleidern; Delirium tremens. Delirium mit Ruhelosigkeit, springt aus dem Bett, versucht zu entkommen."},{"t":"Böse Folgen von enttäuschter Liebe; mit Eifersucht, Tobsucht, zusammenhanglosem Reden."},{"t":"Erotische Manie; obszön; Exhibitionist; redet nur noch von Sex, schamlos, geschwätzig; faßt sich im Delirium an Genitalien. Bettnässer, näßt / kotet ein, Tag und Nacht; spielt mit Kot. Muskelzuckungen (Verat.; Agar.). Unwillkürliche Gesten, Wasserphobie, Nägelbeißen."},{"t":"Verlängertes Zäpfchen; Zusammenschnürung des Rachens, kann keine Flüssigkeiten schlucken."},{"t":"Trockener, spastischer Husten, Agg.: nachts; Hinlegen; Essen; Trinken."},{"t":"Epilepsie. Konvulsionen beim Hören fließenden Wassers. Typhöses Fieber mit murmelndem Delirium."},{"t":"Agg.: nachts; Erregung; Hinlegen; Eifersucht; unglückliche Liebe."}],"rem":1,"orig":"Hyoscyamus niger"},{"label":"Hypericum perforatum","short":"Hypericum perforatum","group":"Arzneimittellehre","paras":[{"t":"Hypericum perforatum, Johanniskraut. Verletzungen an Körperteilen mit reichlich sensiblen Nervenendigungen (Finger, Hand, Fußsohle, Fußballen, Nagelbett). Neuralgie durch Nervenverletzung von Stich-, Schnitt-, Riß-, Bißwunden, eingetretenen Nägeln, Reißzwecken etc."},{"t":"Punktionswunden. Wirbelsäulenverletzung. Druckgefühl über Kreuzbein. Steißbeinschmerz nach Sturz, strahlt in Rückgrat und Beine aus."},{"t":"Kribbeln in Händen und Füßen. Phantomschmerz. Schmerz in alten Narben. Nervenverletzung nach Tierbissen. Tetanus. Liegt auf dem Rücken, den Kopf nach hinten gezogen; Hände und Füße nach innen gedreht."},{"t":"Schädelbruch, Knochensplitter. Schmerz in Augen und Ohren."},{"t":"Kopfschmerz nach Sturz auf Hinterkopf. Gefühl, als würde er hoch in die Luft gehoben, mit Angst, herunterzufallen."},{"t":"Asthma, Agg.: Nebel; Wetterwechsel; vor Stürmen, Amel.: starkes Schwitzen."},{"t":"Verlangen: Pickles; warme Getränke; Wein."},{"t":"Agg.: Verletzung; Erschütterung; Schock; Bewegung."},{"t":"Amel.: Reiben; Kopf zurücklehnen; Liegen auf dem Gesicht."}],"rem":1,"orig":"Hypericum perforatum"},{"label":"Ictodes foetida","short":"Ictodes foetida","group":"Arzneimittellehre","paras":[{"t":"Ictodes foetida, Pothos foetida. Asthmatische Beschwerden,"},{"t":"Agg.: Einatmen von Staub, Amel.: nach Stuhlgang. Hysterie. Wandernde, spastische Schmerzen. Geistesabwesend. Gefühl des Ziehens nach außen an der Glabella,"},{"t":"Amel.: im Freien (Puls.)."},{"t":"Kopfschmerz an einzelnen Stellen mit heftigem Pulsieren der Schläfenarterien. Rote Schwellung quer über der Nase. Niesen mit Schmerz im Rachen. Blähung und Spannung im Bauch. Atemnot mit plötzlichem Angstgefühl und Schweißausbruch. Schmerz in der Brust mit Atembeschwerden."}],"rem":1,"orig":"Ictodes foetida"},{"label":"Ignatia amara","short":"Ignatia amara","group":"Arzneimittellehre","paras":[{"t":"Ignatia, Ignatiusbohne. Empfindliches, mildes Wesen. Fähig, klug, künstlerisch, romantisch, empfindsam. Folge von kürzlich erlebter Enttäuschung, (stillem) Kummer, Verlust eines geliebten Menschen, Liebeskummer, Heimweh, Zorn, Schreck, verletzter Ehre, schlechten Nachrichten, Erwartungsspannung, Überlastung: reizbar, launisch, schnell, schroff, beleidigend."},{"t":"Zusammenbruch: Krämpfe, Hysterie mit Ohnmacht, Seufzen, tief atmen, behält Kummer für sich (Nat-m.); kann zunächst nicht weinen; geht in ihr Zimmer, dann tiefes, fast krampfartiges Schluchzen, Agg.: Trost."},{"t":"In Beziehung sehr verletzlich, wechselhaft, bis Partner es nicht mehr ertragen kann, dann beschimpft sie ihn."},{"t":"Körperlich: Krämpfe und Spasmen aller Art. Globus hystericus; Torticollis; Leere in Magen, nicht besser durch Essen; Seufzen; Magenkrämpfe. Verträgt Leichtverdauliches schwerer als Schwerverdauliches. Nagelkopfschmerz."},{"t":"Kinder: Chorea durch Tadel des Lehrers; Krämpfe; Schmerzen."},{"t":"Taubheit ab bestimmtem Zeitpunkt. Husten schlimmer durch Husten; Lähmung von Körperteilen. Entzündung mit Rötung / Schwellung, unempfindlich gegen Druck. Schlucken von festen Speisen besser als Trinken und Leerschlucken,"},{"t":"Verträgt keinen Widerspruch; in Beziehung unterdrückt sie alles, was sie stört, dann: hysterische Entladung, Mann beachte sie nicht genug; zieht sich zurück, verhärmt. Kritik- und tadelsüchtig. Große Empfindsamkeit; veränderliche und widersprüchliche Symptome."},{"t":"Schwitzt nur im Gesicht. Gesichtszuckungen. Anorexie / Bulimie."},{"t":"Rektumprolaps; Hämorrhoiden: scharfe Stiche schießen aufwärts durch das Rektum. Krämpfe des Rektums nach Stuhlgang. Menses unterdrückt durch Kummer. Heiserkeit und Stimmverlust durch emotionale Erregung."},{"t":"Herzinfarktsymptome nach Kummer. Herzklopfen, Amel.: Liegen auf der linken Seite. Träume von Wasser, Flutwellen, Ertrinken."},{"t":"Verlangen: Rohkost; Unverdauliches; Saures; Obst; Roggenbrot; Käse."},{"t":"Abneigung: Obst (Phos.; Bar-c.); warmes Essen; Fleisch; Alkohol; Tabakrauch."},{"t":"Agg.: Rauch; Gefühlserregung; Kummer; Berührung; Tabak; Kaffee; Süßes."},{"t":"Amel.: tiefes Atmen; Schlucken; Essen; Liegen auf betroffener Seite."}],"rem":1,"orig":"Ignatia amara"},{"label":"Iodium","short":"Iodium","group":"Arzneimittellehre","paras":[{"t":"Jodum. Energieverbrennung. Gewichtsabnahme trotz Heißhunger. Ruhelosigkeit und Heftigkeit. Grundlose Übererregung; ungeheure Angst; geistig überstimuliert, muß aufkommende Gedanken aussprechen, zwanghaft, nicht zu bremsen; bei Anamnese ein Zettel nach dem anderen; befürchtet, etwas vergessen zu haben. Chaos, fixe Ideen. Bewegungsdrang; Kinder völlig ruhelos, bei Kontrollversuch Gewalttätigkeit. Impuls zu töten, \"Schüler tötet Klassenkameraden\". Drüsen geschwollen, hart."},{"t":"Eines der heißesten Mittel, wie Motor in Maschine."},{"t":"Endzustand: Anorexia nervosa; völlig zurückgezogen; gealtert; Drüsen/Leber/Milz vergrößert; Ikterus. Verstopfung mit erfolglosem Drang, Amel.: Trinken von kalter Milch; abwechselnd mit Durchfall."},{"t":"Fließschnupfen im Freien. Heißer Laufschnupfen. Hyperämie der Nase mit Hypertonie. Kropf mit Einschnürungsgefühl."},{"t":"Große Schwäche während der Menses; unregelmäßig. Blutungen. Ovariitis. Schmerz wie von Keil vom rechten Ovar zum Uterus. Heiserer, trockener Kitzelhusten. Atrophie der Mammae. Schmerz im Kehlkopf. Laryngitis. Greift sich beim Husten an den Kehlkopf. Rechtsseitige Pneumonie mit hohem Fieber. Herzklopfen von geringster Anstrengung, hörbar und sichtbar, mit Schweißausbrüchen."},{"t":"Agg.: Wärme; Sitzen; unterdrückter Bewegungsdrang; rechts."},{"t":"Amel.: Essen; frische Luft; Bewegung."}],"rem":1,"orig":"Iodium"},{"label":"Ipecacuanha","short":"Ipecacuanha","group":"Arzneimittellehre","paras":[{"t":"Ipecacuanha, Brechwurzel. Starke Übelkeit mit sauberer Zunge. Asthma mit Hautkrankheit. Andauernde Übelkeit bei allen Beschwerden Speichelbildung. Erbrechen großer Mengen hellen Schleims, bessert nicht."},{"t":"Unbeholfen, stößt alles um. Schwer zu befriedigen; kapriziös; reizbar."},{"t":"Gefühl des Absinkens im Magen. Schneidende Nabelkolik mit Blähungen. Quetschen, als ob sich alle Finger einer Hand kräftig in Därme einpreßten, Agg.: Bewegung. Stuhl: grün, pechartig, wie schaumige Melasse, schleimig. Herbstdysenterie (Colch.; Merc.). Schmerz vom Nabel zum Uterus."},{"t":"Husten mit Würgen und Erbrechen. Husten unaufhörlich und heftig mit jedem Atemzug; trocken; spastisch; asthmatisch; eingeengt. Husten mit Schleimrasseln beim Einatmen; drohende Erstickung durch Schleim, der nicht abgehustet werden kann. Keuchhusten. Bluthusten. Kind wird steif und blau im Gesicht. Heiserkeit am Ende der Erkältung. Knochenschmerzen, wie in Stücke geschlagen. Hellrote Blutungen aus allen Öffnungen."},{"t":"Hellrote, reichliche, klumpige Menses."},{"t":"Verlangen: Süßes; Leckereien."},{"t":"Agg.: reichhaltiges Essen; warmes, feuchtes Wetter; geringste Bewegung."},{"t":"Amel.: frische Luft; Augenschließen."}],"rem":1,"orig":"Ipecacuanha"},{"label":"Iris versicolor","short":"Iris versicolor","group":"Arzneimittellehre","paras":[{"t":"Iris versicolor, Bunte Schwertlilie. Müdigkeit und Sehstörungen vor Kopfschmerz, nach Entspannung von Streß, periodisch, alle 7 Tage."},{"t":"Künstlerisch, dünn, verfeinert, charmant."},{"t":"Kopfschmerz (Stirn, rechte Schläfe) mit Übelkeit; reichlicher Speichelfluß; Verstopfung; reichliches Harnlassen; Amel.: leichte Bewegung; Erbrechen."},{"t":"Agg.: Husten; kalte Luft; Zucker."},{"t":"Dröhnen, Summen, Klingeln in den Ohren mit Taubheit; Schwindel von den Ohren her. Speichel tropft aus dem Mund beim Sprechen. Leber- und Pankreaserkrankungen. Brennen des ganzen Verdauungstrakts."},{"t":"Diarrhoe: schmerzlos, scharf, wässerig, brennend, fettig."},{"t":"Ischias, als ob die linke Hüfte ausgerenkt wäre. Psoriasis und Sehstörungen. Herpes zoster mit Magenverstimmung."},{"t":"Reichliche, saure, wundmachende Absonderungen."},{"t":"Verlangen: Zucker."},{"t":"Agg.: heißes Wetter; geistige Erschöpfung; Herbst; Frühjahr."},{"t":"Amel.: leichte, dauernde Bewegung; Erbrechen."}],"rem":1,"orig":"Iris versicolor"},{"label":"Jaborandi","short":"Jaborandi","group":"Arzneimittellehre","paras":[{"t":"Jaborandi. Erschöpfender, reichlicher Schweiß. Infektlabilität. Speichelfluß mit zähem, klebrigem Speichel. Mumps mit rotem Gesicht; Metastasierung in die Hoden."},{"t":"Erschöpfte Sehkraft; Kurzsichtigkeit; enge Pupillen. Weiße Flecken vor den Augen. Exophthalmischer Kropf. Übelkeit beim Benutzen der Augen oder beim Blicken auf bewegliche Objekte."},{"t":"Nachtschweiß bei Tuberkulose."}],"rem":1,"orig":"Jaborandi"},{"label":"Jalapa","short":"Jalapa","group":"Arzneimittellehre","paras":[{"t":"Jalapa, Exogonium purga, Jalapenknolle. Leibkrämpfe und Durchfall. Kind tagsüber gut zu haben, aber Schreien und Ruhelosigkeit die ganze Nacht. Schlaflos. Kolik mit Auftreibung und Flatulenz. Durchfall bei Kindern mit wässerigen Stühlen, Agg.: nachts; mit allgemeiner Kälte und blauem Gesicht."},{"t":"Zunge glatt, wie glasiert, schmerzhaft. Schmerz am rechten Rippenbogen."},{"t":"Schmerz an den Nagelwurzeln. Brennende Fußsohlen. Schmerz im Großzehengrundgelenk."},{"t":"Agg.: nachts."}],"rem":1,"orig":"Jalapa"},{"label":"Jatropha curcas","short":"Jatropha curcas","group":"Arzneimittellehre","paras":[{"t":"Jatropha curcas, Purgiernußbaum. Cholera und Durchfall. Durchfall plötzlich, reichlich, wässerig, wie Reiswasser, wie aus einem Spundloch; gewaltsame Entleerung; lautes Gurgeln im Bauch, dabei Kälte des ganzen Körpers, (Waden-)krämpfe, Übelkeit und Erbrechen."},{"t":"Sehr leichtes Erbrechen. Schluckauf mit nachfolgendem Erbrechen. Hitze und Brennen im Magen mit krampfartigen Einschnürungsschmerzen."},{"t":"Amel.: Hände in kaltes Wasser tauchen."}],"rem":1,"orig":"Jatropha curcas"},{"label":"Juglans cinerea","short":"Juglans cinerea","group":"Arzneimittellehre","paras":[{"t":"Juglans cinerea, Butternuß, amerikanische Walnuß. Auffällig viele Leberflecke am Bauch und auf den Händen. Leber-Ikterus-Haut. Ausschläge mit Leber- und Gallenbeschwerden. Hinterkopfschmerz."},{"t":"Ikterus mit Schmerz über der Leber und dem rechten Schulterblatt. Ausschlag auf Handrücken, Kreuzbein und den Beinen. Juckreiz, Agg.: Warmwerden. Pusteln."},{"t":"Schnupfen, dem Schmerz unter dem Brustbein vorausgeht."},{"t":"Bei Versagen aller Mittel für Ekzeme oder wenn der Patient Walnußöl benutzt."}],"rem":1,"orig":"Juglans cinerea"},{"label":"Juglans regia","short":"Juglans regia","group":"Arzneimittellehre","paras":[{"t":"Juglans regia, Walnuß. Verwirrt, Gefühl, als ob Kopf in der Luft schwämme. Starker Hinterkopfschmerz. Gerstenkörner."},{"t":"Menses früh, schwarz, pechartig gerinnend. Bauch aufgetrieben."},{"t":"Mitesser und Gesichtsakne. Kleine, rote, juckende Pusteln. Heftiger Juckreiz der Kopfhaut, Agg.: nachts. Schankerartige Ulzera. Beulen unter den Achseln. Schweißdrüsenbeulen und Hinterkopfschmerz. Beulen, weniger juckend, eher infektiös."}],"rem":1,"orig":"Juglans regia"},{"label":"Kalium arsenicosum","short":"Kalium arsenicosum","group":"Arzneimittellehre","paras":[{"t":"Unruhig, nervös, anämisch. Extreme Furcht vor Herzkrankheit; plötzliche Panik bei Menschen, die sonst wie Kali-c. erscheinen."},{"t":"Konservativ, zurückhaltend, humorlos, verschlossen. Materiell orientiert. Kann nicht genießen. Alles genau geplant."},{"t":"Schlaflosigkeit 1-4 Uhr."},{"t":"Asthma 2-3 Uhr mit Abneigung gegen frische Luft."},{"t":"Empfindliche Solarplexus-Region. Schläft mit den Händen auf dem Herzen. Anfallsartige Tachykardie mit Angstzuständen mit Abneigung gegen Gesellschaft."},{"t":"Sehr frostig."},{"t":"Trockene, schuppende Ausschläge; Juckreiz; Psoriasis. Rasch fortschreitender Hautkrebs. Risse in Ellenbeugen und Kniekehlen. Zahlreiche kleine Knötchen unter der Haut."},{"t":"Agg.: 2-3 Uhr; während und nach Menses; Ausziehen; Wärme; Gehen."},{"t":"Amel.: Regenwetter."}],"rem":1,"orig":"Kalium arsenicosum"},{"label":"Kalium bichromicum","short":"Kalium bichromicum","group":"Arzneimittellehre","paras":[{"t":"Schmerz an kleinen Stellen, plötzlich wandernd. Schmerzhafte rezidivierende Sinusitis mit viel fadenziehendem Schleim (\"wie geschmolzener Käse auf Toast\"). Druckschmerz an Nasenwurzel. Liderschwellung. Ulzera tief, wie ausgestanzt und Krusten in der Nase. Tubenkatarrh; Bronchitis; Asthma; arteriosklerotische Ulzera mit fadenziehenden Krusten. Magenulkus, Gastritis, Agg.: Bier."},{"t":"Ganze Person wie verkalkt (Erfahrungen, Gefühle, Verhalten)."},{"t":"Zunge glänzend, glatt, trocken, Haargefühl."},{"t":"Flimmerskotom oder Blindheit vor Kopfschmerzattacken."},{"t":"Schmerz kommt und geht plötzlich (Bell.; Ign.); Neuralgie täglich zur selben Stunde. Frostig, Amel.: Wärme; anämisch. Furcht/Angst in der Brust lokalisiert, Kältegefühl in Brust, in Herz."},{"t":"Abwechselnd Schleimhäute-Gelenke; Rheumatismus-Dysenterie/Magen."},{"t":"Ischias, Agg.: Bier, Amel.: Bewegung; Beugen des Beines."},{"t":"Verlangen: Bier; saure Getränke."},{"t":"Abneigung: Fleisch; Fett; Bitteres; Wasser."},{"t":"Agg.: 2/3 Uhr; Bier; Kaffee; Kälte; Frühling; heißes Wetter; Morgen."},{"t":"Amel.: Wärme; Bewegung; Druck."},{"t":"Wie alle Kali-Verbindungen: verschlossen, zurückhaltend, tüchtig, korrekt."},{"t":"Dazu: Engstirnigkeit; eigene kleine Welt; alles in geordneten Bahnen, immer das gleiche, Materialismus, antispirituell; Sex nach Stundenplan. Braucht keine Gesellschaft. Konzentriert sich zu Hause auf sein Gebiet, läßt keinen an sich heran; hat keine Probleme."},{"t":"Allgemeine Schwäche. Leicht entmutigt, düster, schwermütig. Emotional abgekapselt. Übellaunig, zornig, leicht beleidigt, verdrießliche Gleichgültigkeit. Alles bis ins Detail, will in extremer Weise zeigen, wie gut er seine Arbeit macht."}],"rem":1,"orig":"Kalium bichromicum"},{"label":"Kalium bromatum","short":"Kalium bromatum","group":"Arzneimittellehre","paras":[{"t":"Psychose. Paranoia. Zusammenbruch der geistigen Kräfte mit Verlust des Erinnerungsvermögens. Tiefe Melancholie. Fühlt sich moralisch schwach, hört Stimmen; Wahnideen von Verschwörung, vergiftet oder bestraft zu werden, verdammt zu sein, daß er bestimmt ist, Gottes Rache auszuführen, suizidale Manie. Nächtliche Ängste, Angst vor Zerstörung seiner Umgebung. Unfähig, sich sprachlich auszudrücken."},{"t":"Folge von Verlust seines Geschäftes, Beschäftigung; sexuelle Exzesse."},{"t":"Geschwächtes Herz. Eisige Kälte (alle Kali-Verbindungen)."},{"t":"Anästhesie der Schleimhäute, besonders im Rachen, Auge."},{"t":"Psoriasis (Hauptmittel). Bromismus. Akne, Agg.: während der Regel. Unklarheit und Taubheitsgefühl im Kopf. Kälte, die sich in den Hals erstreckt. Gesteigerter Geschlechtstrieb bei beiden Geschlechtern."},{"t":"Unruhige, nervöse Hände, geschäftige Finger, zuckende Muskeln. Ständig in Bewegung. Unruhiger Schlaf. Probleme mit Magensäure."},{"t":"Apoplexie mit Schläfrigkeit, Stupor, Konvulsionen und Aphasie,"},{"t":"Epilepsie 1-2 Tage vor Menses."},{"t":"Agg.: geistige Anstrengung; Kummer; Gefühlserregung; Nacht; 2 Uhr."},{"t":"Amel.: bei geistiger und körperlicher Beschäftigung."}],"rem":1,"orig":"Kalium bromatum"},{"label":"Kalium carbonicum","short":"Kalium carbonicum","group":"Arzneimittellehre","paras":[{"t":"Schmerz heftig, stechend, schneidend, Amel.: Bewegung. Schwäche. Kaltes Wetter unerträglich. Wassersucht. Schweiß, Rückenschmerz, Schwäche. Folge von Wehen und Fehlgeburt mit Schwächezuständen."},{"t":"Husten: trocken, stechend, anfallsweise, mit zähem Schleim, mit Würgen und Erbrechen, Kälte in der Brust; Hydrothorax; Asthma, kardiale Dyspnoe, Agg.: 2/4/5 Uhr, Amel.: Vorbeugen. Gefühl, als ob Herz an einem Faden hinge (Lach.). Dyspnoe und Herzmuskelschwäche nach Grippe."},{"t":"Furcht im Epigastrium. Gefühl, beim Hinlegen in Magen gestoßen zu werden, Amel.: Umhergehen; Würgen, Erbrechen. Ulcus ventriculi/duodeni, Nüchternschmerz. Gefühl, Magen ist voller Wasser. Aszites. Hämorrhoiden bluten. Vertopfung / Durchfall abwechselnd. Sehr starke Flatulenz. Zucken beim Zubettgehen. Ödeme zwischen Oberlider und Augenbrauen."},{"t":"Stiche im Nierengebiet und Schulterblatt. Lumbago, stechend, scharf, plötzlich, strahlt nach oben und unten aus, Agg.: vor und während Menses,"},{"t":"Amel.: Umhergehen. Schmerz von Hüfte bis Knie. Knieschmerz. Arthrosis deformans."},{"t":"Ausschläge an Fingerspitzen, Finger-/Zehennägel. Ekzeme juckend, schmerzend, Amel.: kaltes Wasser. Nasenbluten morgens beim Gesichtwaschen."},{"t":"Berührung unerträglich (vor allem Beine)."},{"t":"Verlangen: Süßes; Gesellschaft."},{"t":"Agg.: Liegen auf schmerzhafter Seite; 2-4 Uhr; Zugluft; Koitus; Milch; warmes Essen; eine Woche vor Menses; links oben nach rechts unten."},{"t":"Schwer zu erfassen. Routine, Ordnung, Pflichtbewußtsein. Korrekt, aufrecht, konservativ. Schwarz/Weiß-Denken, richtig/falsch."},{"t":"Stoisch, klaglos. Integrität, Würde, wird von anderen bewundert. Polizeibeamter, Staatsanwalt, Übersetzer, Buchhalter. Dogmatisch bis Starrheit, Verstand hat eiserne Kontrolle über das Erleben, das Verhalten und die Gefühle. Erscheint gefühllos; sehr empfindlich, weint leicht; verschlossen; ärgerlich, möchte alleine sein, hat keine Probleme und keine Symptome. Reizbarkeit, übellaunig, kann Krankheit nicht akzeptieren. Verlangen nach Gesellschaft, die er schlecht behandelt. Reizbarkeit vor Menses."},{"t":"Furcht: Dunkelheit, drohende Krankheit, Zukunft (Phos.), Geister, Zugluft."}],"rem":1,"orig":"Kalium carbonicum"},{"label":"Kalium ferrocyanatum","short":"Kalium ferrocyanatum","group":"Arzneimittellehre","paras":[{"t":"Wut mit darunterliegender Traurigkeit. Blutungen mit Anämie. Menorrhagie / Metrorrhagie. Wurde als Kind sexuell mißbraucht."},{"t":"Starke moralische Einstellung. Stark kontrolliertes Verhalten; schluckt Gefühle. Will Familie kontrollieren. Verschlossen. Abneigung gegen Berührung, gegen Veränderungen. Fühlt Angst im Solarplexus. Furcht vor dem Tod."},{"t":"Wut und Reizbarkeit vor der Menses. Dysmenorrhoe, Amel.: bei Einsetzen der Blutung. Hämorrhagien."},{"t":"Starkes sexuelles Verlangen."},{"t":"Ovarialzysten; Fibroide Tumoren. Nachuntendrängen. Schwangerschaftserbrechen."},{"t":"Herzklopfen. Asthma, Brustempfindlichkeit."},{"t":"Erwachen 2-4 Uhr."},{"t":"Schwäche. Anämie mit relativ guter Energie. Frostgefühl, zugluftempfindlich."},{"t":"Wandernde Schmerzen."},{"t":"Agg.: Zugluft."},{"t":"Amel.: Menses."},{"t":"Ferrumanteil: rauh, reizbar, konzentriert auf Geschäft."}],"rem":1,"orig":"Kalium ferrocyanatum"},{"label":"Kalium iodatum","short":"Kalium iodatum","group":"Arzneimittellehre","paras":[{"t":"Photodermatose und Asthma (Lach.; Rhus-t.; Ars.; Dulc.; Puls.). Haut, Agg.: Sonne, Wärme, Amel.: kalte Anwendungen, kaltes Bad und kalte Luft. Neigt zum Weinen. Erwacht 1-4 Uhr wegen Juckreiz, muß aufstehen."},{"t":"Reichlicher, scharfer, heißer, wässeriger Schnupfen mit Stirnhöhlenschmerz;"},{"t":"Schmerz in Nasenwurzel. Verstopfung und Trockenheit der Nase ohne Absonderung. Absonderung reichlich, kühl, grünlich, nicht reizend."},{"t":"Kopfschmerz, Agg.: 5 Uhr. Drüsenschwellungen. Stinknase mit Septumperforation."},{"t":"Kropf. Absteigende Kälte. Kehlkopf rauh, Kehlkopfödem, Erstickungsgefühl. Auswurf grünlich, wie Seifenschaum. Pneumonie bei beginnender Hepatisation. Pneumokokkenmeningitis. Kälte nach unten in die Brust ziehend. Pleuraerguß. Viel Durst."},{"t":"Hodenatrophie."},{"t":"Schlimmer Ischias, Agg.: nachts, Wärme, Liegen auf schmerzhafter Seite, Amel.: Gehen. Rheumatismus des Knies mit Schwellung und Erguß. Schmerz breitet sich über großes Gebiet aus."},{"t":"Abneigung: Fett."},{"t":"Agg.: nachts; Wärme; Berührung; kalte Speisen und Getränke, besonders Milch."},{"t":"Amel.: Bewegung in kühler, frischer Luft."}],"rem":1,"orig":"Kalium iodatum"},{"label":"Kalium nitricum","short":"Kalium nitricum","group":"Arzneimittellehre","paras":[{"t":"Asthma, Herzasthma, extreme Dyspnoe, Agg.: 3 Uhr, kann Atem nicht lange genug anhalten, um zu trinken; mit Übelkeit, dumpfen Stichen und Brennen in der Brust. Bronchitis mit trockenem, scharfem, kurzem, hackendem Husten. Spastischer Krupp, Kehlkopfdiphtherie. Stiche, Reißen zwischen / in Schulterblättern und Gelenken."},{"t":"Gastrointestinale Entzündungen mit viel Schwäche. Ähnlich Kali-c., aber warmblütig und Fettverlangen."},{"t":"Sehkraft umwölkt, Farbringe, Tränenfluß, Glaskörpertrübungen. Nasenpolypen (rechts), Nasenspitze rot und juckend."},{"t":"Plötzliche ödematöse Schwellungen am ganzen Körper."},{"t":"Durchfall nach Kalbfleisch."},{"t":"Reichlich klarer Urin. Eitrige Nephritis."},{"t":"Menses: zu früh, reichlich, schwarz; mit schwerer Lumbago."},{"t":"Verlangen: Fett."},{"t":"Agg.: Gehen; Kalbfleisch; 3 Uhr; gegen Morgen."},{"t":"Amel.: Schlürfen von Wasser."}],"rem":1,"orig":"Kalium nitricum"},{"label":"Kalium phosphoricum","short":"Kalium phosphoricum","group":"Arzneimittellehre","paras":[{"t":"Nervenmittel. Extrem nervös, schwach und und erschöpft durch geringste Anstrengung, vor allem junge Menschen (rothaarig). Pavor nocturnus. Nervöse Furcht. Mattigkeit, Lethargie, Depression. Abneigung gegen eigene Familie, Gesellschaft, Unterhaltung. Beschwerden durch Sorgen. Nervös, fährt leicht hoch, reizbar. Hirnmüdigkeit, Gedächtnisverlust. Hysterie, Alpdruck. Schlafwandeln; Schlaflosigkeit wegen Sorge/Ärger im Geschäft. Angst um Gesundung."},{"t":"Kopfschmerz vom Studieren mit Absinken, Leere im Magen, Amel.: leichte Bewegung."},{"t":"Ohrgeräusche, Summen und und Brummen. Mundtrockenheit mit stinkendem Atem."},{"t":"Fauler, eitriger, gelber Durchfall, Rektumprolaps. Blutstühle. Durchfall beim Essen. Blähungskolik. Morbus Crohn. Sehr gelber Urin."},{"t":"Nächtliche Samenergüsse; extreme Schwäche nach Koitus. Nach Krebsoperationen, wenn die Haut zu fest über die Wunde gezogen wird. Subfebrile Temperatur."},{"t":"Verlangen: Eiswasser; Essig; Süßigkeiten."},{"t":"Abneigung: Brot; Fleisch."},{"t":"Agg.: Sorgen; Erregung; Koitus; Essen; Kälte; Morgens früh."},{"t":"Amel.: sanfte Bewegung; Essen; Anlehnen; Wärme."}],"rem":1,"orig":"Kalium phosphoricum"},{"label":"Kalium sulphuricum","short":"Kalium sulphuricum","group":"Arzneimittellehre","paras":[{"t":"Rasseln bei Kindern im Schlaf. Durst. Erkältungen mit gelber, schleimiger Absonderung. Nase verstopft, Geruchsverlust. Blutandrang in Nasen- und und Rachenschleimhaut."},{"t":"Nach Operation von Adenoiden fortbestehende Schleimhautschwellung und Taubheit bei Tubenkatarrh."},{"t":"Rasseln in der Brust (Ant-t.). Husten, Agg.: abends, bei heißem Wetter,"},{"t":"Amel.: kalte, frische Luft. Husten nach Grippe. Asthma mit gelblicher Absonderung. Kruppartige Heiserkeit (Spong.)."},{"t":"Ausschläge mit starker Abschilferung. Kopfgrind, Bartgrind, Schuppen."},{"t":"Psoriasis. Ekzeme; brennender, juckender, papulöser Ausschlag. Nesselfieber. Polypen. Epitheliom. Seborrhoe. Ringwurm."},{"t":"Schreckliche Träume von Geistern und Mord. Qualvolle Angst bei Fieberhitze. Reichliche Schweiße."},{"t":"Wandernde Schmerzen. Rheumatismus, Agg.: Hitze."},{"t":"Verlangen: Süßes; Saures; kaltes Essen."},{"t":"Abneigung: heiße Getränke; Eier."},{"t":"Agg.: Hitze; Wärme; Abends."},{"t":"Amel.: Bewegung; Kälte; langsames Gehen."}],"rem":1,"orig":"Kalium sulphuricum"},{"label":"Kalmia latifolia","short":"Kalmia latifolia","group":"Arzneimittellehre","paras":[{"t":"Kalmia latifolia, Berglorbeer. Neuralgische Schmerzen mit Schwäche, Taubheitsgefühl; schießen abwärts, entlang den Nerven. Kopfschmerz kommt und geht mit der Sonne (Nat-m.). Starres, ziehendes Gefühl und heftige stechende Schmerzen in Augen und Augenhöhle, Agg.: Bewegung."},{"t":"Kopfschmerz, Amel.: reichliches Urinieren. Schwindel, Amel.: Bücken; Nachuntensehen. Trigeminusneuralgie rechts."},{"t":"Schmerz in Magengrube, Agg.: Vorbeugen, Amel.: Aufrechtsitzen."},{"t":"Albuminurie mit Gliederschmerz. Nephritis nach Scharlach."},{"t":"Langsamer Puls. Schwere Angina pectoris, stellt die Luft ab; Schmerz durch Brustkorb oberhalb des Herzens in Schulterblätter. Herzklopfen, Agg.: Vorbeugen; Liegen auf der linken Seite, Amel.: Liegen auf dem Rücken. Karditis nach Gelenkrheumatismus oder Gicht."},{"t":"Schmerz von Halswirbelsäule-Region in den Arm. Rheumatismus der rechten Schulter."},{"t":"Kribbeln und Taubheitsgefühl im linken Arm; Schmerz entlang N. ulnaris. Gelenke rot, heiß, geschwollen, Agg.: leichteste Bewegung."},{"t":"Schlaflosigkeit; erwacht sehr früh am Morgen."},{"t":"Agg.: Bewegung; Vorbeugen; Nachuntensehen; Sonne."}],"rem":1,"orig":"Kalmia latifolia"},{"label":"Kreosotum","short":"Kreosotum","group":"Arzneimittellehre","paras":[{"t":"Kreosotum, Destillationsprodukt des Buchholzteers. Ätzende, brennende, jauchige Schleimhautabsonderungen; Blutungen; Geschwüre; Krebs."},{"t":"Musik verursacht Herzklopfen und Weinen. Stupide, vergeßlich, launisch, reizbar; unzufrieden, Kind verlangt nach Dingen, wirft sie dann weg. Sehr schmerzhafte Zahnung. Rascher Zahnverfall mit schwammigem, blutendem Zahnfleisch. Zähne schwarz, krümelnd. Fauliger Mundgeruch. Erbricht unverdautes Essen einige Stunden nach dem Essen. Kältegefühl wie Eiswasser im Magen. Magenschmerz, Amel.: Essen. Schmerzhafte, harte Stelle, Bluterbrechen. Wasser schmeckt bitter."},{"t":"Kopfschmerz wie gegen Stirn drückendes Brett, Agg.: Menses. Hinterkopfschmerz."},{"t":"Stinkender Urin. Harninkontinenz, kann nur im Liegen urinieren."},{"t":"Muß sich beeilen bei Harndrang. Enuresis im ersten Schlaf. Leukorrhoe gelb, scharf, stinkend, Agg.: zwischen Menses. Vor und während Menses Klingeln, Brausen und Sausen in den Ohren und Taubheit. Menses aussetzend. Blutfluß beim Hinlegen, Stillstand beim Umhergehen. Jucken und Brennen in Vagina mit Furcht vor Koitus."},{"t":"Blutung braun, dunkel, von kleinen Wunden. Sehr starker Juckreiz abends."},{"t":"Heiserkeit mit Kehlkopfschmerz. Husten, Agg.: abends, mit Würgen, Brustschmerz. Winterhusten alter Menschen mit Druck auf Brustbein. Lungengangrän. Eitriger, reichlicher Auswurf nach jedem Husten. Bluthusten; periodische Anfälle."},{"t":"Verlangen: geräuchertes Fleisch."},{"t":"Agg.: kaltes Wetter, Kaltwerden; Ruhe; Liegen; Zahnung; 18-6 Uhr; Menses."},{"t":"Amel.: Wärme; Bewegung; heiße Speisen; morgens, auch nach schlafloser Nacht."}],"rem":1,"orig":"Kreosotum"},{"label":"Lacticum acidum","short":"Lacticum acidum","group":"Arzneimittellehre","paras":[{"t":"Milchsäure. Blasse, anämische Frauen. Diabetes und rheumatische Schmerzen. Knieschmerz mit Schwäche, wandernd, Amel.: Bewegung; Wärme."},{"t":"Übelkeit morgens, andauernd, Amel.: Essen. Klumpengefühl im Hals, als ob Nahrung hinter Sternum liegen bleibt. Aufstoßen, Speichelfluß."},{"t":"Schwangerschaft: Übelkeit, Erbrechen. Extremer Durst; Heißhunger."},{"t":"Schmerz in Brüsten mit Schwellung der Achseldrüsen; Schmerz in Hände ausstrahlend. Blasenschmerz, wenn Harndrang nicht sofort nachgegeben wird. Urin: hell."},{"t":"Häufiges Wasserlassen."}],"rem":1,"orig":"Lacticum acidum"},{"label":"Lac caninum","short":"Lac caninum","group":"Arzneimittellehre","paras":[{"t":"Lac caninum, Hundemilch. Hochsensibel. Schwäche, starke Vorstellungskraft, Nervosität, Ruhelosigkeit, Schlaflosigkeit. Phobien."},{"t":"Keine Selbstachtung, kein Selbstvertrauen. Verwirrung, sehr vergeßlich, Wortfindungsstörungen; verschreibt sich. Verzweifelt, hoffnungslos, hält sich für unheilbar. Chronisch schwermütig (Lyc; Puls.). Furcht vor Tod, Gewitter, Erdbeben, im Dunkeln alleine, vor (Spinnen) Schlangen."},{"t":"Zorn, Fluchen, Haß, mißtraut sich selbst. Liegt im Bett und meint zu schweben; auch beim Gehen Gefühl, nicht geerdet zu sein; Gefühl zu schweben. Furcht, verrückt zu werden. Träumt von Hunden."},{"t":"Erhöhtes Cholesterin, Hypertonie. Schmerzen wandern (Kali-bi.; Puls.). Seitenwechsel. Kopfschmerz Seitenwechsel, pulsierend, nach Mitternacht, Hinterkopf beim Erwachen. Als ob sich Schmerz ganze Nacht über aufbaut bis zum Moment des Erwachens. Photophobie. Ohrgeräusche."},{"t":"Nase wie Kali-bi. grün, dick, Seitenw.@ der Nasenlöcher. Alles schmeckt schlecht, außer Salz. Kieferknacken beim Essen (Nit-ac.; Rhus-t.)."},{"t":"Schlafpos.: ein Bein angewinkelt, das andere gestreckt oder Knie fast im Gesicht; eingerollt, streckt Füße aus dem Bett."},{"t":"Lumbago mit brennendem Schmerz lateral auf Haut mit äußerster Berührungs- und Druckempfindlichkeit, schiebt Bettdecke weg."},{"t":"Hitze in Extremitäten, Brennen der Fußsohlen und Handflächen, hält Finger gespreizt, um Berührung zu vermeiden. Fersenschmerz."},{"t":"Flatus vaginalis. Leicht erregbar. Menses zu früh, reichlich, gußartiger Fluß. Uterusschmerz, nach oben ausstrahlend. Brüste schmerzhaft geschwollen vor Menses, Agg.: geringste Erschütterung; muß Brüste beim Treppengehen ganz fest halten. Galaktorrhoe. Wichtiges Mittel zum Abstillen. Versiegen der Milchsekretion ohne Grund."},{"t":"Kinder: Einbildungen von Schlangen; bösartig; Kreischen im Schlaf; aufgebracht; aggressiv; schimpfen."},{"t":"Verlangen: Fisch; Milch; Salz; Pfeffer; Senf; Scharfes; Whisky; Kaffee. Abneigung: Flüssigkeiten."},{"t":"Agg.: Berührung; Wärme; während Menses; Morgen des einen, Abend des nächsten Tages."},{"t":"Amel.: Kälte; kalte Getränke."}],"rem":1,"orig":"Lac caninum"},{"label":"Lac vaccinum defloratum","short":"Lac vaccinum defloratum","group":"Arzneimittellehre","paras":[{"t":"Lac defloratum, Entrahmte Milch. Migräne mit Blindheit und Obstipation. Schmerz von Stirn zu Hinterkopf. Reichliches, farbloses Urinieren, erleichtert nicht."},{"t":"Kopfschmerz pulsierend; Übelkeit, Erbrechen, Agg.: Milch, Lärm, Licht, Bewegung, bei Menses. Kopfschmerz periodisch, alle 7 Tage, Amel.: Druck, Bandagieren, Erbrechen."},{"t":"Vor Kopfschmerz Abneigung gegen Gedanken an Essen. Schnupfen durch Milch."},{"t":"Übelkeit und unstillbares Erbrechen während der Schwangerschaft. Gefühl eines großen Balles (Globus), der vom Magen zum Hals aufsteigt mit Erstickungsgefühl. Übelkeit beim Autofahren."},{"t":"Verstopfung mit vergeblichem Drang. Stuhl voluminös, hart, schreit beim Pressen vor Schmerz, Anus reißt ein."},{"t":"Menses zu spät, unterdrückt durch Milchtrinken oder Halten der Hände in kaltes Wasser."},{"t":"Große Erschöpfung. Ruhelosigkeit. Schlafmangel. Kind lehnt Muttermilch ab;"},{"t":"Abneigung: Milch."},{"t":"Agg.: Milch; Kälte; Luftzug."},{"t":"Amel.: Ruhe; Druck; Bandagieren; Erbrechen."}],"rem":1,"orig":"Lac vaccinum defloratum"},{"label":"Lachesis mutus","short":"Lachesis mutus","group":"Arzneimittellehre","paras":[{"t":"Lachesis muta, Buschmeister. Überstimulation, die Ventil sucht. Gefühlswelt auf Hochtouren: durchschaut schnell; Leidenschaft. Starkes Pulsieren im ganzen Körper. Herzrasen; Hypertonie; Druck in Herzgegend; Ohnmachtsanfälle; Kreislauflabilität. Nachts geistige Höchstleistung."},{"t":"Eifersucht; Neid; Haß; Rache; Besitzgier; Mißtrauen; böse Zunge (Zittern). Zahlt sofort heim. Ablecken der Oberlippe beim Sprechen."},{"t":"Selbstzerstörerisch; Drogenabhängigkeit; Quartalssäufer; Freßsucht. Tiefgreifende Ängste und Depressionen nach dem Aufstehen, nach heißem Bad. Angst: Zukunft, Herzkrankheit, verrückt zu werden."},{"t":"Folge von Überreizung. Fühlt sich sehr schnell unterdrückt."},{"t":"Blutungen dunkel; Varizen; Hämorrhoiden. Bläulich zyanotische Hautfarbe. Ulzera und Ausschläge rot, pink, zyanotisch. Berührungsempfindlich: Hals, Magen, Bauch auf Kleiderdruck. Kloß im Hals, Amel.: Schlucken."},{"t":"Erwacht angstvoll, glaubt zu ersticken; kann nicht auf der linken Seite liegen. Linksseitig oder von links nach rechts. Ausnahme: Ischialgie rechts."},{"t":"Nierensteine/-kolik/-versagen,"},{"t":"Kopfschmerz hämmernd, brodelnder Blutandrang, als ob Augen von innen nach außen gedrückt werden."},{"t":"Tonsillitis links, Agg.: Schlucken von Flüssigkeiten schmerzhafter als Festes (Bell.; Bry.; Ign.); Schmerz strahlt nach rechts aus. Rachen dunkelpurpurrot."},{"t":"Agg.: heiße Getränke; nach Schlaf."},{"t":"Gefühl, als rolle ein Ball in der Blase."},{"t":"Verstopfung ohne Drang, Gefühl von Sphinkterkrampf."},{"t":"Dysmenorrhoe: je besser der Fluß, desto weniger Schmerz."},{"t":"Klimakterium: Hitzewallungen, heiße Schweiße; brennender Scheitelkopfschmerz. Schneidende Schmerzen in Brüsten und Ovarien (Sep.; Phos.),"},{"t":"Wegen Unterdrückung Ventil wichtig: Manie, unglaublicher Redefluß, Tränen, Ausfluß, Menses, Stuhlgang, Masturbation, Ausschweifung, Zornesausbruch,"},{"t":"Verlangen: Stärkehaltiges, Nudeln; Austern; Alkohol; Pickles."},{"t":"Agg.: Wein; Klimakterium; Unterdrückte Sexualität; Schwangerschaft; Morgen; Wärme; Herbst; Frühjahr; Kleiderdruck; nach Schlaf; geringste Berührung; Druck; Sonnenhitze."},{"t":"Amel.: Sich-Luft-verschaffen; kühle frische Luft; kaltes Wasser; Essen; Kaffee; während Menses; Absonderungen."}],"rem":1,"orig":"Lachesis mutus"},{"label":"Latrodectus mactans","short":"Latrodectus mactans","group":"Arzneimittellehre","paras":[{"t":"Latrodectus mactans, Schwarze Witwe. Angina pectoris mit Todesangst und heftigem Präkordialschmerz, zur (links) Axilla oder Arm ausstrahlend mit Ruhelosigkeit, Lahmheit, Taubheit und Erschöpfung."},{"t":"Schwäche der Beine, Krämpfe der Bauchmuskeln. Schmerz von der Brust zum Bauch mit drohender Ohnmacht."},{"t":"Extreme Atemnot mit Furcht zu ersticken und vor dem Tod. Haut eiskalt."},{"t":"Agg.: Bewegung, sogar der Hände; Erschöpfung; Sprechen."}],"rem":1,"orig":"Latrodectus mactans"},{"label":"Lathyrus sativus","short":"Lathyrus sativus","group":"Arzneimittellehre","paras":[{"t":"Lathyrus sativus aut cicera, Platterbse. Lähmung der unteren Extremitäten. Befällt Vorder- und Seitenstränge des Rückenmarks. Poliomyelitis anterior. Athetosis, torkelnder Gang. Amyotrophe Lateralsklerose."},{"t":"Schwindel im Stehen mit geschlossenen Augen. Brennen der Zungenspitze, wie verbrüht."},{"t":"Kann im Sitzen Glieder nicht strecken oder kreuzen. Beim Gehen schlagen Knie aneinander. Fersen berühren beim Gehen nicht den Boden und die Füße werden schwer aufgesetzt. Kalte Beine tagsüber, brennende Hitze in der Nacht, deckt sie auf."},{"t":"Fortwährendes Gähnen mit Schläfrigkeit."},{"t":"Verstärkte Reflexe und Lähmung. Myelitis mit spastischen Symptomen."},{"t":"Schwäche nach Grippe und anderen Krankheiten. Abmagerung der Glutealmuskeln und der unteren Glieder. Sitzt nach vorne gebeugt mit Schwierigkeiten beim Aufrichten."}],"rem":1,"orig":"Lathyrus sativus"},{"label":"Laurocerasus","short":"Laurocerasus","group":"Arzneimittellehre","paras":[{"t":"Laurocerasus, Kirschlorbeer. Spastischer, kitzelnder Husten bei Herzpatienten. Keucht nach Atem, greift nach dem Herzen. Zyanose."},{"t":"Mangelnde Reaktion bei Herz- und Brustbeschwerden. Neugeborenenasphyxie. Plötzlicher Gedächtnisverlust. Furcht vor eingebildetem Bösen."},{"t":"Ösophagusspasmen, Getränke rollen hörbar durch die Speiseröhre und Eingeweide. Gurgelnde Flatulenz."},{"t":"Umklammerungsgefühl am Herzen. Legt Hände auf Herz. Husten trocken, kitzelnd, bei Herzklappenfehler, Mitralinsuffizienz. Auswurf reichlich, gallertartig, blutig."},{"t":"Erstickungsanfälle mit Zyanose, Agg.: Sitzen, Amel.: Liegen. Zusammenschnürungsgefühl der Brust. Endstadium von Thoraxerkrankungen; erholt sich nicht von Bronchitis etc. (Carb-v.), Ohnmacht und Bewußtlosigkeit."},{"t":"Knoten in Fingern und Zehen. Klumpenbildung bei den Fingern."},{"t":"Heftiger Magenschmerz mit Verlust der Sprache."},{"t":"Kälte, nicht besser durch Wärme. Frostigkeit."},{"t":"Agg.: Aufsitzen; Kälte."},{"t":"Amel.: Liegen mit flachem Kopf."}],"rem":1,"orig":"Laurocerasus"},{"label":"Ledum palustre","short":"Ledum palustre","group":"Arzneimittellehre","paras":[{"t":"Ledum palustre, Sumpfporst. Wunden und Verletzungen, purpurfarben, entzündet und geschwollen, kalt bei Berührung, aber Agg.: (Bett-) Wärme. Langanhaltende Verfärbung nach Verletzungen. Abmagerung betroffener Körperteile."},{"t":"Rheumatismus oder Gicht, nach oben steigend, Amel.: Baden. Gelenke knotig, schmerzhaft, gichtig. Knöchel geschwollen bis zu den Knien. Großzehenballen schmerzhaft geschwollen. Fersenschmerz wie gequetscht. Gichtknoten. Lumbago nach Erheben vom Sitzen. Verstauchter Knöchel. Periarthritis linke Schulter."},{"t":"Linke Schulter und rechte Hüfte. Rechtsseitiger Ischias."},{"t":"Kontusion des Augapfels mit Blutextravasaten; Ekchymose an Lidern und Bindehaut."},{"t":"Stichwunden mit spärlicher Blutung, (Ratten-) Bisse und Insektenstiche, auch Wunden durch Seeanemonen, Quallen."},{"t":"Rote Stippen auf Stirn und Wangen, stechend bei Berührung."},{"t":"Bluthusten abwechselnd mit Rheumatismus. Keuchhusten mit doppelter Einatmung und Schluchzen."},{"t":"Allgemein frostig, friert ständig, aber Agg.: Wärme. Rhusvergiftung."},{"t":"Agg.: Wärme; Bewegung; nachts; Wein; Alkohol."},{"t":"Amel.: Kaltbaden."}],"rem":1,"orig":"Ledum palustre"},{"label":"Lemna minor","short":"Lemna minor","group":"Arzneimittellehre","paras":[{"t":"Lemna minor, Entengrütze, Wasserlinse. Nasenkatarrh mit Nasenpolypen, geschwollene Nasenmuscheln. Atrophische Rhinitis. Asthma durch verstopfte Nase, Agg.: feuchtes Wetter, besonders schwere Regenfälle."},{"t":"Eitriger Geruch und Geschmack. Trockenheit von Nase und Nasenrachenhöhle. Retronasales Tröpfeln. Schmerz wie von einem Band von Nasenflügeln zum Ohr. Reichlich schleimig-eitriger Absonderung."},{"t":"Agg.: feuchtes Wetter, starker Regen."}],"rem":1,"orig":"Lemna minor"},{"label":"Leptandra virginica","short":"Leptandra virginica","group":"Arzneimittellehre","paras":[{"t":"Leptandra virginica, Veronica virginica, Virginischer Ehrenpreis. Schmerz Leber/Gallengegend, strahlt zur Wirbelsäule, zum Nabel oder zum linken Schulterblatt aus."},{"t":"Ikterus. Schwäche, kann kaum stehen oder gehen."},{"t":"Bitterer Geschmack. Gelbe Zunge oder schwarzer Streifen entlang Zungenmitte. Galleerbrechen. Gallensteine. Blutende Magengeschwüre."},{"t":"Stuhl stinkend, schwarz, teerig mit Schmerz um den Nabel. Typhusartige Stühle, die schwarz werden und wie Teer aussehen. Rektumprolaps; blutende Hämorrhoiden. Nägel sehr dünn, weich, spalten sich."},{"t":"Verlangen: eiskalte Getränke."},{"t":"Abneigung: Fleisch; Gemüse."},{"t":"Agg.: kalte Getränke; Bewegung; periodisch."}],"rem":1,"orig":"Leptandra virginica"},{"label":"Lilium tigrinum","short":"Lilium tigrinum","group":"Arzneimittellehre","paras":[{"t":"Lilium tigrinum, Tigerlilie. Lilie: Reinheit, Moral; Tiger: wild, aggressiv. Sexueller Konflikt: arbeitet hart, um inneren Konflikt bewußt zu unterdrücken. Triebunterdrückung. Religiöse Verzweiflung wechselnd mit sexueller Erregung. Nervöse, hysterische, alte Jungfer ohne Liebesbeziehung."},{"t":"Aggressiv, reizbar, unzufrieden. Fluchen, Schlagen. Türen knallen, Schreien, Hysterie, (religiöse) Verzweiflung. Ziellose Eile, hastig, unter Druck (Tarent.). Fühlt sich moralisch entgleist. Furcht vor dem Bösen, daß etwas Schreckliches passiert; vor Krankheit, HK, Geisteskrankheit; nicht ins Paradies zu kommen. Schuldkomplex."},{"t":"Als ob sie in einem wilden Traum lebt, nicht in der Gegenwart."},{"t":"Kummer, Depressionen, Agg.: Trost. Gleichgültigkeit."},{"t":"Kopfschmerz nach Aufregung, Amel.: frische Luft, umhergehen. Wildes Gefühl im Kopf."},{"t":"Will Leute, die vor ihr sind an den Haaren ziehen (Bell.; Lach.; Tarent.)."},{"t":"Nach-unten-Drängen im Abdomen und Becken, Klumpengefühl im Rektum, Agg.: Stehen (Differentialdiagnose: Sep.: Sex), \"meine Gedärme wollen herausfallen\", Agg.: während Menses (Sep.; Plat.); Stehen. Exzessiver Sex. Reizbarkeit nach Orgasmus am stärksten. Im Abdomen viele Symptome links (Lach.)."},{"t":"Menstruationsfluß in Bewegung, hört auf im Liegen im Bett (Nat-s.)."},{"t":"Tumor linkes Ovar (auch rechts), geschwollen. Schmerz Ovar, zur Oberschenkelinnenseite oder linken Brust ausstrahlend; abwechselnd Schmerz Genitalien und Herzschmerz."},{"t":"Klimakterium: Herzklopfen, Agg.: Liegen auf rechten Seite."},{"t":"Verstopfung (Nux-v.), Diarrhoe mit Stuhldrang, der aus dem Bett treibt (Sulph.). Zystitis mit starkem Brennschmerz (Canth.; Cann-i.)."},{"t":"Bei Männern auch Versuch, sexuelles Verlangen zu unterdrücken, führt zu Zwölffingerdarmgeschwüre, Nebenhodenentzündung."},{"t":"Nachts Engegefühl Herz, wie Schraubstock. muß gebeugt laufen, \"Herzflattern\", braucht Bewegung als Ventil. Angina pectoris mit Schmerz im rechten Arm. Herzklopfen in der Schwangerschaft. Ruhelose Glieder. Unerquicklicher Schlaf. Schmerzen strahlen nach hinten und unten aus. Ohnmacht im warmen Zimmer. Kann nicht auf unebenem Boden gehen. Hitze der Fußsohlen und Handinnenflächen."},{"t":"Verlangen: Fleisch; Saures; Süßes."},{"t":"Agg.: 17-8 Uhr; Stehen; nach Menses; warmes Zimmer; Trost."},{"t":"Amel.: Bewegung; frische Luft; Beschäftigung; Anstrengung."}],"rem":1,"orig":"Lilium tigrinum"},{"label":"Lithium carbonicum","short":"Lithium carbonicum","group":"Arzneimittellehre","paras":[{"t":"Rheumatismus mit Herzschädigungen und Schwachsichtigkeit. Wundheit und Schwere am ganzen Körper. Gichtknoten. Harnsaure Diathese."},{"t":"Kopfschmerz, Amel.: Essen. Doppelbilder; Hemianopsie; rechte Hälfte nicht sichtbar, Agg.: bei Menses. Lichtscheu. Trockene Lider. Augenschmerz nach Lesen."},{"t":"Säure, Übelkeit, nagender Schmerz, Amel.: Essen."},{"t":"Urin spärlich, dunkel, trüb, scharf. Nierensteine. Schmerz in rechter Niere, Harnleiter und Blase."},{"t":"Schmerz im Herzen, strahlt zum Kopf aus mit Augensymptomen, Agg.: vor Menses; Vorbeugen, Amel.: Wasserlassen. Schmerzen in den Brustdrüsen, strahlen in Arme und Finger aus. Akuter Rheumatismus der kleinen Gelenke. Schmerz Amel.: heißes Wasser. Hüftarthritis."},{"t":"Schuppiger, flechtenartiger Ausschlag an Händen, Kopf, Wangen; vorher rote, rauhe Haut. Bartflechte."},{"t":"Agg.: nachts; Morgen; rechts; nach unterdrückten Menses."},{"t":"Amel.: Essen; Wasserlassen; Bewegung."}],"rem":1,"orig":"Lithium carbonicum"},{"label":"Lobelia inflata","short":"Lobelia inflata","group":"Arzneimittellehre","paras":[{"t":"Lobelia inflata, \"Aufgeblasene\" Lobelie. Heller Teint, dicklich. Atemnot durch Luftzug, Anstrengung, Erregung, unterdrückte Menses. Spasmodisches Asthma. Keuchhusten. Frostigkeit mit Ohnmacht. Gesicht kaltschweißig."},{"t":"Taubheit von unterdrücktem Ausfluß oder Ekzem."},{"t":"Speichelfluß bei gutem Appetit; metallischer Geschmack. Globusgefühl."},{"t":"Extreme Übelkeit mit Erbrechen. Morgenübelkeit. Schwangerschaftsübelkeit. Mattigkeit und Schwäche im Oberbauch. Folge von Tee- und Tabakabusus. Speichelfluß bei gutem Appetit. Schweißausbruch. Schwäche. Rotes Sediment."},{"t":"Lungenkrankheit in Familie oder Anamnese. Einschnürung der Brust,"},{"t":"Agg.: Anstrengung. Druckgefühl, Brustschmerz, Amel.: schnelles Gehen."},{"t":"Schmerz im Kreuzbein, Agg.: geringste Berührung, weiches Kissen; sitzt nach vorne gebeugt. Prickelnde Haut vor Asthmaanfall mit Übelkeit. Beschwerden von unterdrückten Absonderungen, Menses."},{"t":"Verlangen: Süßes; Fett."},{"t":"Agg.: Geruch oder Geschmack von Tabak; Bewegung; Berührung; Kälte; Zugluft; Wetterwechsel oder Temperaturwechsel; Kaltwaschen."},{"t":"Amel.: frische Luft; schnelles Gehen."},{"t":"Differentialdiagnose: Ars.: Lob. hysterischer als Ars., hysterische Magenkrämpfe und Übelkeit mit Erbrechen, Unruhe ähnlich Ars."}],"rem":1,"orig":"Lobelia inflata"},{"label":"Lycopodium clavatum","short":"Lycopodium clavatum","group":"Arzneimittellehre","paras":[{"t":"Lycopodium, Bärlappsporen. Abmagerung von oben nach unten; ergraut früh; fahl mit tiefen Falten auf der Stirn. Leber/Lunge/Niere. Schmerz rechts, oder von rechts nach links wandernd: Hals, Brust, Abdomen, Leber, Ovar."},{"t":"Gedächtnis geschwächt; verschreibt und verspricht sich."},{"t":"Furcht: Dunkelheit; Alleinsein; Gesundheit; Verletzung; was andere von ihm denken; öffentliche Auftritte; in Menschenansammlung; Klaustrophobie."},{"t":"Nase nachts verstopft, chronischer Schnupfen, Sinusitis frontalis; Krusten und elastische Pfröpfe (Kali-bi.)."},{"t":"Alles schmeckt sauer; bitter. Sodbrennen im Rachen, stundenlang. Abneigung gegen Speisen, bis er gekostet hat, dann Heißhunger. Essen macht hungrig. Kopfschmerz, wenn er nicht ißt. Magen/Darm \"gebläht wie das Ego\", Agg.: nach dem Essen. Nach wenigen Bissen steht Essen bis zum Hals. Wacht nachts auf und hat Hunger. Gärung mit Blähungsrumpeln im Unterbauch (Carb-v. Oberbauch; Chin. gesamter Bauch). Kolitis. Magengeschwüre. Verstopfung seit Pubertät; unterwegs; bei Kindern; erfolgloser Drang; Hämorrhoiden. Leistenhernie rechts. Ein Fuß heiß, der andere kalt (Chin.; Dig.; Ip.)."},{"t":"Kitzelhusten; tief, hohl; Atemnot; Pneumonie rechts unten; Brust scheint voll von rasselndem Schleim. Auswurf salzig (Ars.; Phos.; Puls.)."},{"t":"Nephritis, Nierensteine, roter Sand im Urin. Kind schreit vor Urinieren. Schlaf unerquicklich, morgens reizbar und mürrisch."},{"t":"Sehr trockenes Handrückenekzem. Gliederschmerz, Agg.: Liegen auf schmerzhafter Seite, beim Sitzen, Amel.: Gehen, Wärme, Bettwärme. Gliederschmerz und Schwäche in Füßen. Ejaculatio praecox. Schwache Erektion. Impotenz (immer mit derselben...), gerne in Bordell. Schläft ein beim Verkehr. Trockenheit der Vagina. Brennen bei und nach Koitus, deshalb Abneigung gegen Sex. Mangel an Lebenswärme."},{"t":"Kinder: brav in der Schule, zu Hause tyrannisch. Schwächlich aber helle; Baby schreit den ganzen Tag, schläft die ganze Nacht. Atmet durch den Mund, lymphatisch, Erkältungsneigung, Neurodermitis, Asthma. Scharlach."},{"t":"Verlangen: Süßes; Austern; heißes Essen/Getränke."},{"t":"Agg.: Kleiderdruck; warmes Zimmer; 16-20 Uhr; nach Schlaf;"},{"t":"kalte Getränke (Tonsillitis); Austern, Kohl, Hülsenfrüchte, Zwiebeln."},{"t":"Amel.: Entblößen des Kopfes; Lockern der Kleidung."},{"t":"Will beeindrucken; Fassade. Wirkt sehr tüchtig, freundlich. Minderwertigkeitskomplex; mangelndes Selbstvertrauen. Einzelgänger aus Furcht vor Verantwortung."},{"t":"(Zartere Natur: schüchtern, philosophisch, zurückgezogener Bücherwurm.) Angeber, feige. Haustyrann. Diktatorisch. Chauvinist. Arroganz."},{"t":"Mißtrauisch; geizig; habgierig; neidisch; bösartig."},{"t":"Folge von Zorn, Ärger, Kränkung, Verdruß mit unterdrücktem Ärger (Staph.). Konservativ, loyal, Recht und Ordnung, Tradition; liebt Institutionen. Gewissenhaft in Kleinigkeiten, traut keinen Ärzten. Narzißtische Egozentrik mit Angst, unter Belastung zusammenzubrechen. Depression. Überempfindlichkeit. Leicht beleidigt, intolerant, streitsüchtig, verträgt keinen Widerspruch. Übt auf andere Druck aus, setzt sich nicht wirklich auseinander; läßt sich nicht fassen."},{"t":"Beeindruckt von berühmten Persönlichkeiten und Pomp. Hochmut."},{"t":"Keine echte emotionale Beteiligung."},{"t":"Priester, Rechtsanwälte, Politiker, Lehrer (viele öffentliche Auftritte)."}],"rem":1,"orig":"Lycopodium clavatum"},{"label":"Lysinum","short":"Lysinum","group":"Arzneimittellehre","paras":[{"t":"Lyssinum, Tollwutnosode. Übererregbarkeit der Sinne. Konvulsionen, Spasmen von blendendem, reflektiertem Licht oder dem Geräusch fließenden Wassers. Folge von Hundebiß oder Tollwutimpfung."},{"t":"Heftige Wut mit sonderbaren Impulsen. Furcht vor Wasser, Erstickung, verrückt zu werden, Klaustrophobie. Hellsichtigkeit."},{"t":"Verlangen nach Mitgefühl und Zärtlichkeit."},{"t":"Wirft den Kopf beim Niesen zurück. Zähneknirschen."},{"t":"Ösophagusspasmen, verlangt trotzdem nach häufigen, kleinen Schlucken."},{"t":"Kann keine großen Pillen schlucken. Spuckt ständig Speichel aus. Sofortiger Harndrang beim Geräusch fließenden/tropfenden Wassers."},{"t":"Abnormes sexuelles Verlangen. Vaginismus. Seltsame Gelüste in der Schwangerschaft. Uterusprolaps."},{"t":"Schmerz in Halswirbelsäule-Region, Amel.: Kopf rückwärts beugen. Schmerz in rechter Hüfte."},{"t":"Verlangen: Schokolade; Tabak."},{"t":"Abneigung: Fett."},{"t":"Agg.: Anblick/Geräusch fließenden Wassers; helles, blendendes Licht; Sonnenhitze; Geruch von Tabak; Gemütserregung; kränkende Neuigkeiten."}],"rem":1,"orig":"Lysinum"},{"label":"Magnesium carbonicum","short":"Magnesium carbonicum","group":"Arzneimittellehre","paras":[{"t":"Trockene Haut, erdig-gelb, altaussehend. Reizbar (Cham.) mit angegriffenen, erschöpften Nerven. Müde, schwach, zusammengebrochen. Trigeminusneuralgie links (Hauptmittel), Agg.: Kälte, Luftzug, Ruhe, Amel.: Aufstehen und umhergehen. Gastrointestinale Beschwerden."},{"t":"Angst und Unruhe, daß etwas Schlimmes passiert."},{"t":"Ganzer Körper schmerzhaft, Unruhe der Beine und Füße. Zappelphilipp."},{"t":"Alles riecht sauer (Hep.; Rheum). Magen-Darm-Katarrh mit Hyperazidität. Spasmen an allen Hohlorganen: Magen, Darm, Luftröhre (Husten), Uterus, mit krampfartigen, kolikartigen Beschwerden; Gefäßspasmen, Ischämie; Gefäßerschlaffung (Kollaps)."},{"t":"Kolik mit Diarrhoe, Agg.: 3-5 Uhr, alle 3 Wochen, Amel.: Krümmen. Grüner, schaumiger, froschlaichartiger Stuhl; entfärbter Stuhl."},{"t":"Schlaf nicht erfrischend, müder beim Aufstehen als beim Zubettgehen. Zahnschmerz nachts; in Schwangerschaft. Deckt nachts Füße auf."},{"t":"Kinder, mit Gedeihstörung: dünn, schwach, Leberschwäche (Hauptmittel)."},{"t":"Abneigung oder Durchfall auf Milch. Milch passiert unverdaut bei gestillten Babies. Baby verweigert die Brust."},{"t":"1. Kopfschmerz kongestiv mit Schwindel, Amel.: frische Luft, Agg.: Wärme, Auftreten, Bücken."},{"t":"2. Kopfschmerz stechend, halbseitig, neuralgisch oder migräneartig, Amel.: Wärme."},{"t":"Menses fließen nur nachts oder im Liegen und versiegen beim Gehen. Lumbago in Schwangerschaft, Agg.: Sitzen, Liegen, Amel.: Umhergehen, Rücken warmhalten. Erkältungskrankheiten während Menses. Häufiger Symptomwechsel."},{"t":"Verlangen: Obst; Gemüse; Fleisch; trockenes Brot."},{"t":"Abneigung: grünes Obst; Gemüse; Milch."},{"t":"Agg.: Milch; Fleisch (Haut); vor und während Menses; alle 3 Wochen; 3-5 Uhr; Nachts, die Ruhe treibt aus dem Bett; Wärme trotz Frostigkeit (Husten, Kopfschmerz, Zahnschmerz, Gliederschmerz); Temperaturextreme; nach Schlaf, auch nach Mittagsschlaf; Aufregung, Ärger, Schreck."},{"t":"Amel.: Bewegung an der frischen Luft; warme Luft, aber Agg.: Bettwärme."}],"rem":1,"orig":"Magnesium carbonicum"},{"label":"Magnesium muriaticum","short":"Magnesium muriaticum","group":"Arzneimittellehre","paras":[{"t":"Lethargische, verbitterte, säuerliche Menschen. Jahrelange Leber/Galleerkrankung. Gefühl wie nach Drogeneinnahme. Keine Energie mehr. Hat viel gelitten. Möchte alleine sein. Frostig (streckt trotzdem heiße Füße aus dem Bett). Ängstlich, ruhelos (Rhus-t.; Ars.). Brennen der Nasenflügel, Schnupfen. Im Liegen mit geschlossenen Augen muß er husten und ringt nach Luft, ruhelos, Aufstehen bessert. Mundwinkelrhagaden."},{"t":"Gastritis, Agg.: Salz, Milch. Verstopfung wie Nux-v. (auch bei Säuglingen, bei Zahnungsschmerz Verstopfung). Säugling verdaut keine Muttermilch. Stuhl hart, knotig, krümelnd. Leberzirrhose, Hepatitis. Schmerz in Leberregion, Agg.: rechts liegen. Kolik 1 Uhr."},{"t":"Bei hysterischer Krise Taubheit in unteren Extremitäten. Furcht während Abendessen, abends beim Lesen, allgemein kaum Angst."},{"t":"Kopfschmerz Schläfen, Amel.: harter Druck, warm einwickeln; Sieden im Kopf beim Niederlegen. Amel.: Zitrone (Ptel.); Kopfschmerz tritt nach Schlaf auf, dauert 2-3 Tage oder periodisch alle 4-6 Wochen (Ferr.). Kopfschmerz um Periode (vor, während und nach), Amel.: Weinen, Umhergehen, frische Luft, (wie Lyc.: friert und will raus), starker Druck. Schläft links."},{"t":"Kinder können Milch nicht verdauen. Empfindungslos beim Wasserlassen."},{"t":"Verlangen: Gemüse; Obst; Süß."},{"t":"Agg.: 3 Uhr; Hinlegen; morgens (geistig träge, Unwohlsein wie vergiftet, weil Leber nicht entgiftet hat); Salz; Schwimmen im Meer; rechts Liegen; leichte Berührung (alle Mag.)."},{"t":"Pazifist, empfindlich, verletzlich; möchte, daß andere glücklich und zufrieden sind; Gerechtigkeitssinn; selbst unzufrieden, gequält, Gesichtsausdruck: verdrießlich, bitter, empfindlich gegen jede Auseinandersetzung, nicht nur persönliche. Unterdrückt eigene Gefühle, Kind leidet entsetzlich unter Streit der Eltern und versucht, Frieden zu stiften. Starkes Pflichtbewußtsein, sich selbst zuviel aufgehalst. Angst, nicht zurechtzukommen, Nervensystem sehr angespannt, Schlaf erquickt nicht (Hauptmittel). Erwacht 3 Uhr, kann nicht mehr schlafen; mag morgens nicht sprechen. Hysterisch, reizbar, depressiv, am Rande der nervlichen Belastbarkeit, kann sich absolut nicht entspannen. Zucken wie elektrische Schläge."}],"rem":1,"orig":"Magnesium muriaticum"},{"label":"Magnesium phosphoricum","short":"Magnesium phosphoricum","group":"Arzneimittellehre","paras":[{"t":"Nervosität. Sehr starke neuralgische Schmerzen, mehr rechts, Amel.: Wärme. Schmerz schneidend, durchbohrend; schießend, stechend; kommt und geht blitzartig. Zum Wahnsinn treibende Schmerzanfälle; Schmerz wandert rasch."},{"t":"Magenkrämpfe, als ob ein Band um Körper geschlungen wäre."},{"t":"Bauchkoliken, krampfartige Schmerzen, Amel.: Reiben, Sichkrümmen, Druck, sehr heiße Anwendungen, so heiß wie möglich (Nux-v. nicht ganz so heiße Anwendungen). Blähungskoliken. Saubere Zunge. Furcht vor dem Aufdecken, kalter Luft, Berührung."},{"t":"Kopfschmerz, Trigeminusneuralgie, Zahnschmerzen, Agg.: Kälte, Amel.: Hitze, heiße Flüssigkeiten (Amel.: Kälte: Bry.; Coff.; Ferr-p). Krämpfe bei zahnenden Kindern, ohne Fieber. Krämpfe vom Klavier- oder Geigespielen."},{"t":"Folge von Stehen im kalten Wasser."},{"t":"Matt, müde, nervös, reizbar; morgens fit (Phos.-Element);"},{"t":"Dysmenorrhoe, Agg.: vor Menses, Amel.: Hitze, warme Getränke, Sichkrümmen. Frauen müssen Genitalreg. sehr warm halten (auch Nux-v.)."},{"t":"Agg.: kalte Getränke; Berührung; nachts; rechtsseitig."},{"t":"Amel.: fester Druck; Sichkrümmen; Wärme; heiße Anwendungen."}],"rem":1,"orig":"Magnesium phosphoricum"},{"label":"Mancinella","short":"Mancinella","group":"Arzneimittellehre","paras":[{"t":"Hippomane mancinella, Manchinellbaum. Furcht vor Wahnsinn, von Teufel besessen zu sein. Fixe Ideen, weiß, es ist Unsinn, wird sie aber nicht los. Sieht Unfälle voraus (Arg-n.). Furcht, Agg.: nachts; hohe Plätze. Fürchtet, ihr Kind zu töten, die Kontrolle zu verlieren. Schuldgefühle über sexuelles Verlangen / Verhalten. Plötzlich verschwindende Gedanken, wandernde Gedanken. Suizidgedanken. Starkes religiöses Gefühl mit Beten. Furcht vor Toten; kann nicht auf Beerdigung gehen; Furcht vor Geistern."},{"t":"Typus: schwacher Wille und Intellekt, weniger impulsiv als Arg-n. Heimweh. Folge von entsetzlichen Ereignissen, von Horrorfilmen."},{"t":"Gefühl Kopf wie in Drahtkäfig. Schwindel wie schwebend."},{"t":"Optische Halluzinationen, sieht Farben. Plötzliche Erblindung. Eingebildete Gerüche. Schwellungen des Gesichts, Lippenherpes."},{"t":"Durst vor Menses. Schmerzhafter Punkt unterhalb des Rippenbogens."},{"t":"Elektrische Schläge in Halswirbelsäule-Region."},{"t":"Eiskalte Hände und Füße. Handflächenekzem. Große Blasen, Pemphigus."},{"t":"Psoriasis bei Kindern."},{"t":"Beschwerden seit der Pubertät."},{"t":"Agg.: nachts; Wärme; Klimax."}],"rem":1,"orig":"Mancinella"},{"label":"Manganum-act. + -c. (old abbr.)","short":"Manganum-act. + -c. (old abbr.)","group":"Arzneimittellehre","paras":[{"t":"Manganum aceticum. Parkinson. Unwillkürliches Lachen und Weinen. Rückwärtsgehen. Alle Symptome Amel.: Niederlegen. Maskengesicht."},{"t":"Syphilitischer Patient mit Anämie und paralytischen Symptomen. Redner und Sänger. Asthma, Agg.: Federbett."},{"t":"Gemütssymptome, Amel.: traurige Musik, Hinlegen. Furcht, daß etwas passiert. Taubheit bei feuchtem Wetter. Tubenkatarrh. Schmerz von anderen Körperteilen strahlt ins Ohr aus. Ohrenschmerz, Agg.: Kälte. Monotone Stimme. Chronische Heiserkeit; jede Erkältung führt zu Bronchitis, Agg.: feuchtes Wetter."},{"t":"Husten, Amel.: Hinlegen; mit Aphonie. Juckreiz, Agg.: Schwitzen; Federbett."},{"t":"Schwäche mit Verlangen, sich hinzulegen. Gicht. Chronische Arthritis, Rheumatismus; Knochenschmerz; wandernde Schmerzen, Agg.: nachts, Wundheitsgefühl bei Berührung. Geht nach vorne gebeugt; Neigung, nach vorne zu fallen. Diagonalschmerz."},{"t":"Agg.: Wetterwechsel; Berührung; Kälte; Nacht; Federbett."},{"t":"Amel.: Hinlegen."}],"rem":1,"orig":"Manganum-act. + -c. (old abbr.)"},{"label":"Medorrhinum","short":"Medorrhinum","group":"Arzneimittellehre","paras":[{"t":"Medorrhinum, Trippernosode. Extrem und sprunghaft, hochempfindlich; erleichtert, wenn er sich verschwendet, alles im Exzeß: Hitze, körperliche Absonderungen, Zorn, Impulsivität; denkt immer an Sex, am liebsten \"verbotene Beziehung\", schläft auf dem Bauch. Unentschlossen, schiebt Entscheidungen vor sich her."},{"t":"Absonderungen aller Scheimhäute.: Konjunktiva, Nase (chronische Sinusitis mit grüner Absonderung), Pharynx, Urethra, Vagina. Zystitis, Nephritis seit der Heirat; bei Kindern chronische Katarrhe, Asthma. Windeldermatitis, Genitalsoor. Folge unterdrückter Absonderungen (GO): Gewichtsverlust, Tonusverlust, Energieschwund. Warzen, Kondylome."},{"t":"Chronischer Rheumatismus, Herzkrankheit. Reiter-Syndrom. Pruritus ani. Enuresis."},{"t":"Ruhelose, zappelige Beine und Füße (Zinc.). Brennen der Hände und Füße."},{"t":"Gerne barfuß auf kaltem Boden. Knöchelschwellungen."},{"t":"Verlangen: Salz; Süßes; Fett; Eiswürfel; Likör; Alkohol; Käse; Orangen; grünes, unreifes Obst."},{"t":"Amel.: am Meer; abends (Nachtmensch); Absonderung; Schlaf in Knie-Ellbogenlage; Luftzufächeln (Asthma)."},{"t":"Agg.: 2 Uhr Magen, Asthma (Kali-c.; Ars.); morgens lange Anlaufzeit; Darandenken; von Sonnenaufgang bis -untergang (umgekehrt: Syph.)."},{"t":"Kinder: Spur von Alter, nicht wohlgenährt, frech, schwierig (noch schwieriger: Cham.; Calc-p.; Cina), aggressiv; produzieren Zornausbrüche. Nägelbeißen."},{"t":"Von einem Extrem ins andere, es gibt keinen Normalzustand:"},{"t":"sehr hart, grausam gegen Mensch und Tier/möchte liebkost werden;"},{"t":"extreme Tierliebe / Grausamkeit; Unempfindlichkeit und Härte / Überempfindlichkeit; Machotyp (meistens) / sehr femininer Mann. Egoistisch, gebieterisch, hat immer recht (Sulph.); grollt lange. Geist plötzlich leer. Beim Erzählen plötzlich \"andere Schiene\"; Vergeßlichkeit und Verwirrung (Alum.); gestern erscheint ihm wie vor zwei Wochen. Kann nicht sprechen, ohne zu weinen. Hellsichtigkeit. Unentschlossenheit."},{"t":"Verschlossenheit/offen in entsprechender Gesellschaft, dann emotional sehr ausdrucksstark, triebmäßig emotional. Geisteskrankheit, innerliche Wildheit, Sturm. Verliert Kontakt zur Realität, alles wie im Traum, in sich gekehrt wie Ph-ac.; Ängste, Schuldgefühle wegen Vergangenheit führen zu religiösem Fanatismus. Angst vor Krebs als Strafe Gottes."},{"t":"Eile, nie genug Zeit, Dinge zu Ende zu führen; Zeit vergeht zu langsam. Furcht vor Dunkelheit, Geisteskrankheit, daß jemand hinter ihm geht und ihn zur Eile drängt. Kann nicht alleine auf die Straße gehen. Paranoide Ängste. Drogenabhängige ohne Orientierung."}],"rem":1,"orig":"Medorrhinum"},{"label":"Melilotus officinalis","short":"Melilotus officinalis","group":"Arzneimittellehre","paras":[{"t":"Melilotus officinalis, Steinklee. Blutstauungen, Amel.: Blutungen. Blutandrang, vor allem zum Kopf. Prämenstruelles Syndrom. Depression post partum."},{"t":"Bei prämenstruellem Syndrom völlig andere Person: Wahnidee, daß jeder sie anschaut, möchte weglaufen und sich verstecken; Furcht, laut zu sprechen, beobachtet zu werden, vergiftet zu werden, bis zum Verfolgungswahn. Furcht vor Polizei, ins Gefängnis zu kommen (Merc.). Plötzlicher Wahnsinn mit Blutsturz aus der Nase. Große Erregung mit Schlaflosigkeit. Ruhelosigkeit und Eile, geballte Fäuste. Grimassenschneiden. Delirium."},{"t":"Dysmenorrhoe mit Übelkeit. Konzentrations- und Gedächtnisschwäche."},{"t":"Rotglühendes Gesicht mit pochenden Karotiden (Bell.). Kopfschmerz pulsierend in der Stirn, Wellengefühl im Gehirn. Kopfschmerz mit Übelkeit, Amel.: Nasenbluten, Menses, reichliches Wasserlassen. Völle im ganzen Kopf. Augen schwer, möchte sie schließen. Neuralgie rechte Kopfseite und im Nacken."},{"t":"Verstopfte Nase, trockene, harte Borken in der Nase, reichliches Nasenbluten."},{"t":"Zusammenschnürungsgefühl im Rektum, Klopfen, Völle, kein Drang (Alum.). Menses spärlich, intermittierend mit Übelkeit und Nachuntenziehen. Starke Dysmenorrhoe, Amel.: Menses bei reichlichem Fluß. Ovarialgie."},{"t":"Konvulsionen nervöser Kinder bei Zahnung (Bell.). Kindliche Spasmen, Eklampsie, Epilepsie. Kombination: Epistaxis und Dysmenorrhoe."},{"t":"Agg.: Regen; vor Sturm; bei Bewegung; Wetterwechsel; Klimakterium."},{"t":"Amel.: Blutungen; reichliches Wasserlassen."}],"rem":1,"orig":"Melilotus officinalis"},{"label":"Menyanthes trifoliata","short":"Menyanthes trifoliata","group":"Arzneimittellehre","paras":[{"t":"Menyanthes trifoliata, Bitterklee, Fieberklee. Fieber, bei dem das Kältestadium überwiegt; intermittierend, Malaria. Kältegefühl in Bauch, Beinen, Nasenspitze."},{"t":"Kopfschmerz drückend am Scheitel, Amel.: starker Druck mit der Hand. Als ob schweres Gewicht bei jedem Schritt auf den Kopf drückte (Cact.; Glon.; Lach.),"},{"t":"Agg.: Treppensteigen, oft mit eisiger Kälte von Händen und Füßen. Schmerz vom Nacken aus über das ganze Gehirn, Amel.: Bücken, Sitzen."},{"t":"Völlig durstlos. Heißhunger vergeht nach kleinen Nahrungsmengen. Kältegefühl zur Speiseröhre aufsteigend. Abdomen gedehnt und voll,"},{"t":"Agg.: Tabakrauchen. Kälte des Bauches."},{"t":"Spannungsgefühl in Nasenwurzel, Armen, Händen, Fingern, Haut, wie einige Nummern zu klein."},{"t":"Weinerliche Stimmung."},{"t":"Kieferknacken. Gesichtszuckungen. Zucken der Beine nach dem Niederlegen."},{"t":"Verlangen: Fisch; Fleisch."},{"t":"Abneigung: Brot und Butter."},{"t":"Agg.: Ruhe; Gehen; Erschütterung; Treppensteigen."},{"t":"Amel.: harter Druck; Dämmerung; Bücken."}],"rem":1,"orig":"Menyanthes trifoliata"},{"label":"Mephitis putorius","short":"Mephitis putorius","group":"Arzneimittellehre","paras":[{"t":"Mephitis putorius, Stinktier. Erregt, voller Phantasien. Kann weder schlafen, noch arbeiten. Geschwätzigkeit. Verkrampfte Persönlichkeit."},{"t":"Spastischer Husten und Keuchhusten; Asthmaanfälle, meist nachts,"},{"t":"Agg.: Sprechen und Trinken. Zusammenziehung der Stimmritze beim Sprechen oder Trinken. Pseudokrupp."},{"t":"Hustenanfälle so heftig, daß scheinbar jeder Anfall das Leben beenden könnte."},{"t":"Kind muß hochgehoben werden, wird blau im Gesicht, kann nicht Ausatmen, Bei Husten/Asthmaanfall Gefühl, Schwefel einzuatmen."},{"t":"Verlangt, in eiskaltem Wasser zu baden."},{"t":"Erwacht nachts mit Blutandrang in Unterschenkeln mit Hitzegefühl. Kurzer Schlaf erfrischt."},{"t":"Neigung zum Knacken seiner Fingergelenke."},{"t":"Verlangen: Salz."},{"t":"Agg.: nachts; Sprechen; Trinken."},{"t":"Amel.: kaltes Bad oder Wetter."}],"rem":1,"orig":"Mephitis putorius"},{"label":"Mercurius corrosivus","short":"Mercurius corrosivus","group":"Arzneimittellehre","paras":[{"t":"Tenesmus des Rektums und der Blase. Ängstlich, Ruhelos. Versteht nicht, was andere sprechen; starrt sie an. Sprachstörungen."},{"t":"Scharfer Tränenfluß; Iritis, Iris lichtempfindlich. Hornhautgeschwür mit Ulzeration. Rachen hochrot, geschwollen, schmerzhaft, Agg.: Druck; strahlt zu Ohren aus. Brennen mit starker Schwellung, Agg.: leichter Druck."},{"t":"Dysenterie und sommerliche Darmgrippe, von Mai bis November auftretend. Kolik unterhalb des Nabels. Drang und Schmerz bleiben nach Stuhlgang. Diarrhoe: blutig, schleimig, heiß, wundmachend, stinkend. Schleimhautfetzen und furchtbare schneidende, kolikartige Schmerzen. Colitis ulcerosa. Brennen des Anus. Schweißausbruch während und nach Stuhlgang."},{"t":"Brennen in Harnröhre; Urin heiß, brennend, spärlich, tropfenweise mit großem Schmerz; blutig, braun, Ziegelmehlsediment, Albuminurie. GO, zweites Stadium, grünliche Absonderung, Agg.: nachts; starkes Brennen und Tenesmus."},{"t":"Enorme Schwellung von Hoden und Penis. Eichel schmerzhaft, heiß."},{"t":"Geschwüre mit ätzendem, scharfem Eiter. Nephritis."},{"t":"Verlangen: kalte Getränke; kaltes Essen."},{"t":"Agg.: Kälte; Nacht; Schlucken; saure Speisen; nach Stuhlgang und Wasserlassen."}],"rem":1,"orig":"Mercurius corrosivus"},{"label":"Mercurius iodatus flavus","short":"Mercurius iodatus flavus","group":"Arzneimittellehre","paras":[{"t":"Rachenbeschwerden, Amel.: kalte Getränke, mit stark geschwollenen Drüsen und dickem Zungenbelag, gelb an der Basis. Ständiger Schluckzwang. Angina lacunaris mit spärlicher Exsudation, leicht zu entfernen. Geschwüre an Rachen oder Mandeln. Mittelohreiterung."},{"t":"Grünliche, zähe Klumpen aus Schlund oder hinteren Nasengängen."},{"t":"Rechtsseitig oder von rechts nach links."},{"t":"Nächtliche Knochenschmerzen."},{"t":"Schwindel oder Ohnmacht beim Aufstehen. Stirnkopfschmerz mit Schmerz an Nasenwurzel. Schanker; Verhärtung hält lange an. Geschwollene Leistendrüsen, groß und hart. Brusttumoren mit Neigung zu starkem, warmem Schweiß und Magenstörungen. Gelber Fluor kleiner Mädchen."},{"t":"Herzschmerz mit Schmerz im Abdomen oder vorausgegangenem Kopfschmerz. Herzklopfen mit Dyspnoe, Agg.: Liegen auf dem Rücken."},{"t":"Verlangen: saure Getränke."},{"t":"Agg.: Gerüche; Aufrichten; warme Getränke; Liegen auf der linken Seite."},{"t":"Amel.: kalte Getränke; im Freien."}],"rem":1,"orig":"Mercurius iodatus flavus"},{"label":"Mercurius iodatus ruber","short":"Mercurius iodatus ruber","group":"Arzneimittellehre","paras":[{"t":"Diphtherie und ulzerierte Halsentzündungen, besonders rechts, mit starker Halslymphknotenschwellung/verhärtung und Parotisschwellung,"},{"t":"Agg.: Leerschlucken. Neigung zum Räuspern. Kloßgefühl im Rachen. Muskelsteifheit von Rachen und Nacken."},{"t":"Schnupfen und Schwerhörigkeit; Nase rechts heiß. Räuspert Schleim aus Choanen. Nasenmuschel geschwollen, öffnet sich mit einem Knall."},{"t":"Dicker gelber Belag am Zungengrund. Spitze und Ränder rot; rechte Seite von Hals und Nacken. Husten durch verlängerte Uvula."},{"t":"Starke Schwellung der Leistendrüsen, keine Neigung zur Eiterung. Harter Schanker."},{"t":"Verlangen: salziges Essen."},{"t":"Agg.: Leerschlucken; nachts."},{"t":"Amel.: nach Schlaf."}],"rem":1,"orig":"Mercurius iodatus ruber"},{"label":"Mercurius solubilis","short":"Mercurius solubilis","group":"Arzneimittellehre","paras":[{"t":"Mercurius solubilis, Quecksilber. Mangelnde Reaktionskraft mit Instabilität. Empfindlichkeit; Haut / Schleimhaut, peripheres Nervensystem, Rückenmark, Gehirn, Augen, Ektoderm."},{"t":"Drüsenschwellungen mit/ohne Eiterungen. Neigung zu Schweißen, die nicht erleichtern. Chronische Eiterungen, jahrelang. Schmerzen nachts."},{"t":"Schwäche und Zittern durch geringste Anstrengung (Parkinsontremor). Fauliger Geruch von Atem, Körper und Exkrementen (Psor.). Zahnschmerz pulsierend, reißend, schießend, Krone verfällt, Wurzel intakt (umgekehrt: Mez.). Zahnfleisch schwammig, zurückweichend, leicht blutend."},{"t":"Schnupfen mit viel Niesen; flüssig, scharf, ätzend, gelbgrün, eitrig, stinkend, Geschwüre, Agg.: nachts, feuchtes Wetter."},{"t":"Mundfäule, Aphthen, widerlicher Mundgeruch; übermäßiger Speichelfluß;"},{"t":"zäh, stinkend, metallisch, kupferig."},{"t":"Zunge groß, schlaff, Zahneindrücke (Chel.; Podo.; Rhus-t.); Furche in Längsrichtung; Schmerzen; Geschwüre. Starker Durst auf kalte Getränke bei feuchtem Mund."},{"t":"Mumps, Diphtherie, Tonsillitis. Ständiger Schluckzwang. Peritonsillarabszeß. Brennende Kehle, Stimmverlust. Nach Eiterbildung."},{"t":"Schwache Verdauung mit dauerndem Hunger. Stuhl schleimig, blutig mit Kolik und Ohnmacht; Tenesmus; Gefühl, nie fertig zu sein."},{"t":"Pollutionen, blutig durchsetzt."},{"t":"Dysmenorrhoe, Leukorrhoe wundmachend, brennend, juckend, Agg.: nachts; Agg.: Wasserlassen, Amel.: Kaltwaschen. Windeldermatitis."},{"t":"Milch in den Brüsten bei Menses, schmerzhaft."},{"t":"Husten trocken, quälend, kann nicht rechts liegen, Agg.: nachts, Bettwärme. Rechter Unterlappen, Stiche zum Rücken hin (Chel.; Kali-c.). Lungeneiterung."},{"t":"Geschwüre mit speckigem Grund und dunklem Hof, zusammenlaufend."},{"t":"Verlangen: Butter; kalte Getränke; Bier; Milch; Süßes."},{"t":"Abneigung: Fleisch; Kaffee."},{"t":"Agg.: nachts; Hitze, Kälte (lebendes Thermometer); frische Luft; nasses Wetter; Wetterwechsel; Bettwärme; Speisen; Schweiße; Anstrengung; unterdrückte Absonderungen."},{"t":"Amel.: Bettruhe."},{"t":"Antwortet langsam. Geistig zuerst verlangsamt, schwer von Begriff; später ineffektive Eile, Ruhelosigkeit. Geschwächtes Gedächtnis. Lebensmüde. Mißtrauisch, beobachtet genau; mißtrauische Zurückhaltung."},{"t":"Schwierigkeiten, über oder Gefühle zu sprechen. Stottern."},{"t":"Weinen/Lachen; impulsiv; Schlagen; Impuls, geliebten Menschen zu töten (Nux-v.; Plat.), beim Anblick eines Messers. Eifersucht."},{"t":"Braucht zur Unterdrückung der inneren Impulse viel Energie."},{"t":"Furcht vor Geisteskrankheit; Paranoia, jeder ist Feind. Abhängigkeit."}],"rem":1,"orig":"Mercurius solubilis"},{"label":"Mezereum","short":"Mezereum","group":"Arzneimittellehre","paras":[{"t":"Daphne mezereum, Seidelbast. Unentschlossen, phlegmatisch, hypochondrisch; Gleichgültigkeit. Mürrisch, gedankenversunken, benommen, traurig. Wut über Kleinigkeiten mit schneller Reue. Verlangen nach Gesellschaft. Angst steigt vom Magen auf."},{"t":"Neuralgien von Gesicht und Zähnen, zum Ohr ausstrahlend, rechtsseitig,"},{"t":"Speichelfluß, Amel.: Ofenwärme, Agg.: nachts, Essen, Kälte und Zugluft. Frösteln."},{"t":"Kopfschmerz heftig, nach geringem Ärger, rechts, Agg.: Berührung."},{"t":"Ausschlag auf der Kopfhaut mit dicken Krusten und Eiter darunter. Milchschorf. Langwierige, extrem schlimme Hautprobleme, nie Hände."},{"t":"Herpes zoster und Neuralgien nach Herpes."},{"t":"Ausschläge mit heftigem Juckreiz, Agg.: Warmbaden; wandern beim Kratzen."},{"t":"Altersjuckreiz. Juckreiz ohne Ausschlag. Ekzeme und juckende Ausschläge nach Impfung. Feuchte Ausschläge. Kind kratzt sich ständig das blutverschmierte Gesicht. Perioral. Kinn."},{"t":"Extrem fröstelig; Kälte erkrankter Körperteile. Einseitige Beschwerden."},{"t":"Schmerz in langen Röhrenknochen, entzündet, geschwollen, Periostschmerz, Agg.: nachts im Bett, Berührung, feuchtes Wetter."},{"t":"Taubheit nach unterdrückten Hautausschlägen. Als ob kalte Luft durch das Mittelohr bläst. Verlangen, in Ohren zu bohren."},{"t":"Karies an Zahnwurzeln. Zähne wie verlängert."},{"t":"Zungenbrennen, zum Magen ausstrahlend. Mund wird wässerig. Gefühl von Übelkeit im Rachen. Übelkeit und schokoladenfarbenes Erbrechen. Magengeschwür/-krebs mit brennenden Schmerzen, Amel.: Milch. Chronische Gastritis."},{"t":"Hodenschwellung. Heftige Libido. GO. mit Hämaturie."},{"t":"Atemnot, abwechselnd mit oder durch unterdrückte Ausschläge."},{"t":"Verlangen: Schinken; Fett; Kaffee; Wein."},{"t":"Agg.: Nacht; Unterdrückung; warmes Bett; Kälte; Berührung; Bewegung; Impfung."},{"t":"Amel.: abstrahlende Hitze; frische Luft."}],"rem":1,"orig":"Mezereum"},{"label":"Millefolium","short":"Millefolium","group":"Arzneimittellehre","paras":[{"t":"Millefolium, Schafgarbe. Starke Blutungen, hellrot, schmerzlos (Nase, Lunge, Uterus, Darm, Hämorrhoiden)."},{"t":"Beschwerden durch Sturz, Überheben, Überanstrengung. Blutung post partum, nach Abort. Nach Steinoperationen."},{"t":"Schmerzhafte Schwangerschaftsvarizen."},{"t":"Bluthusten bei beginnender Schwindsucht."},{"t":"Schwindel bei langsamer Bewegung. Gefühl, etwas vergessen zu haben. Kopf scheint voll Blut zu sein. Konvulsionen und Epilepsie durch unterdrückte Menses. Stichartige, durchbohrende Kopfschmerzen."}],"rem":1,"orig":"Millefolium"},{"label":"Moschus","short":"Moschus","group":"Arzneimittellehre","paras":[{"t":"Moschus, Bisam. Hysterie, nervöses Zittern und häufige Ohnmachtsanfälle. Kältegefühl. Krankheiten verlaufen nicht normal. Spannung in Muskeln, Haut und Geisteszuständen."},{"t":"Vorzeitige Senilität. In Eile, unbeholfen. Heftige Wut, Schimpfen, bis die Lippen blau, die Augen starr werden und sie in Ohnmacht fällt. Unkontrollierbares Gelächter. Geschwätzigkeit. Verwöhnte, verzogene Kinder."},{"t":"Eine Backe rot und kalt, die andere blaß und heiß. Krampfhafter, nervöser Schluckauf. Starke Libido. Übelkeit und Erbrechen nach Koitus."},{"t":"Brustbeklemmung mit Atemnot. Hysterische Spasmen der Brust. Asthma. Stimmritzenkrampf. Globus."},{"t":"Husten hört auf, Schleim kann nicht abgehustet werden."},{"t":"Herzklopfen mit Todesangst. Kälte einzelner Körperteile oder allgemein. Diabetes."},{"t":"Verlangen: schwarzer Kaffee; Stimulanzien; Weinbrand; Bier."},{"t":"Agg.: Erregung; Kälte."}],"rem":1,"orig":"Moschus"},{"label":"Muriaticum acidum","short":"Muriaticum acidum","group":"Arzneimittellehre","paras":[{"t":"Salzsäure. Sehr ernster Zustand. Große körperliche Schwäche. Folge extremer andauernder Überanstrengung, von Fieber. Totales Aufgeben: \"Laßt mich sterben\", kein Lebenswille mehr. Kann im Bett nicht sitzen: Augen schließen sich, Unterkiefer hängt nach unten, rutscht im Bett herunter; dabei sehr ruhelos. Sieht sehr alt aus, will nicht sprechen; Lautes Stöhnen. Reizbar, mürrisch, ärgerlich, traurig, leidet schweigend."},{"t":"Sepsis mit brennender Hitze und Abneigung gegen Unterhaltung."},{"t":"Zersetzung der Flüssigkeiten."},{"t":"Blutungen aus Mund und Anus, Nasenbluten. Aphthen. Lippen trocken, mit Rissen; stinkender Atem."},{"t":"Zunge trocken, lederartig, gelähmt, tiefe Geschwüre, Kanten bläulich-rötlich (Carb-ac.), Zahnfleischschwellung."},{"t":"Hämorrhoiden treten plötzlich bei Kindern auf. Hämorrhoiden schmerzhaft bei Berührung; bläulich, heiß, mit heftigen Stichen, Agg.: geringste Berührung (Bettuch); Schwangerschaft. Jucken am Anus, Prolaps beim Wasserlassen. Unwillkürliche Stühle bei Urin-/Windabgang."},{"t":"Schwindel, Agg.: Rechtsliegen."},{"t":"Puls beschleunigt, klein und schwach, setzt jeden dritten Schlag aus."},{"t":"Ataxie durch Schwäche der Schenkel und Knie. Juckende Ausschläge; Handrückenekzem. Ausschlag durch Sonne, Schwimmbad."},{"t":"Schläfrigkeit; kann nicht wach bleiben."},{"t":"Abneigung: Fleisch."},{"t":"Verlangen: Schokolade; Chips; Popcorn."},{"t":"Agg.: geringste Berührung; nasses Wetter; Meer."},{"t":"Amel.: Bewegung; Wärme; Linksliegen."}],"rem":1,"orig":"Muriaticum acidum"},{"label":"Murex purpurea","short":"Murex purpurea","group":"Arzneimittellehre","paras":[{"t":"Murex, Purpurschnecke. Nervös, lebhaft, liebevoll, niedergeschlagen, traurig mit Schwäche und Erschöpfung. Klimakterische Beschwerden. Gefühl des Absinkens und Schwäche im Magen (Sep.)."},{"t":"Leiseste Berührung verursacht heftige sexuelle Erregung. Nymphomanie."},{"t":"Kann Uterus spüren, Wundheitsschmerz im Uterus (Helon.; Lyss.)."},{"t":"Diagonalschmerz vom rechten Becken zur (rechten oder) linken Brust."},{"t":"Menses unregelmäßig, reichlich, häufig, verlängert, große Klumpen. Prolapsgefühl. Uterusvergrößerung mit Tenesmen im Becken und starken Schmerzen, in die Brüste ausstrahlend, Agg.: Niederlegen."},{"t":"Dysmenorrhoe und chronischer Endometritis mit Verlagerung. Muß Beine eng gekreuzt halten."},{"t":"Ausfluß grün oder blutig. Bei Schwermut glücklicher, wenn Leukorrhoe stärker ist. Schmerzen im Kreuzbein. Gutartige Tumoren in Brüsten mit Schmerz bei Menses."},{"t":"Harn häufig nachts; riecht wie Baldrian; dauernder Drang (Kreos.)."},{"t":"Lumbago, zwingt zum Umhergehen."},{"t":"Agg.: Berührung; Sonne; Klimakterium; Menses; nach Schlaf."},{"t":"Amel.: Druck; vor Menses; Essen."}],"rem":1,"orig":"Murex purpurea"},{"label":"Myrica cerifera","short":"Myrica cerifera","group":"Arzneimittellehre","paras":[{"t":"Myrica cerifera, Wachsbaum. Schleimhäute und Leber. Gelbsucht. Niedergeschlagen, reizbar, benommen. Dumpfer, schwerer Schmerz in Schläfen und Stirn, morgens beim Erwachen. Schmerz und Steifheit im Nacken. Gelbe Skleren. Gesicht/Haut gelb, juckend, krabbelndes Gefühl wie von Insekten."},{"t":"Zunge gefurcht, schlechter Geschmack und Übelkeit."},{"t":"Zäher, dicker, widerlicher Schleim, fädig, schwer zu lösen. Schluckdrang, Trockene, schuppige Krusten im Mund und auf Gaumen mit Durst."},{"t":"Zusammenschnürungsgefühl im Hals. Zahnfleisch dick, schwammig, blutend (Merc.)."},{"t":"Appetitlosigkeit mit Völlegefühl im Magen wie nach kräftigem Mahl. Senkungs- und Schwächegefühl im Oberbauch, Übelkeit, Agg.: nach Essen, Amel.: rasches Gehen."},{"t":"Dumpfer Schmerz in der Leber. Rumpeln oberhalb des Nabels. Viel Windabgang beim Gehen und bei Stuhlgang."},{"t":"Urin dunkel, schaumig, spärlich, gallig."},{"t":"Verlangen: Saures."},{"t":"Naja tripudians"},{"t":"tripudians, Gift der Kobra, Brillenschlange. Wahnsinn mit Neigung zu Selbstmord (Aur.). Brütet dauernd über eingebildeten Sorgen. Deprimiert. Furcht vor Regen, Tod, alleingelassen zu werden. Als wenn er zwei Willen hätte."},{"t":"Linksseitige Beschwerden. Als ob Organe zusammengezogen würden."},{"t":"Kopfschmerz linke Schläfe und linke Orbita, in Hinterkopf ausstrahlend, mit Übelkeit und Erbrechen. Heufieber mit trockener Kehle. Augen starren. Ptosis. Schwarze Absonderung aus den Ohren."},{"t":"Zusammenschnüren des Kehlkopfes im Schlaf. Erstickungsanfälle nach dem Schlafen (Lach.), greift zum Hals; unfähig zu sprechen. Reizender, trockener Husten bei Herzschäden (Spong.; Laur.); geschädigtes Herz nach Infektionskrankheiten. Akute und chronische Endokarditis; Hypertrophie; Klappenschäden. Angina pectoris mit Schmerz in Nacken, linker Schulter und linkem Arm. Stechender Herzschmerz. Dabei Schmerz in Stirn und Schläfen. Gefühl wie heißes Eisen in Brust."},{"t":"Asthmatische Einschnürung abends. Asthma beginnt mit Schnupfen. Klebriger Schleim und Speichel. Neuralgie des linken Ovars, zum Herzen ziehend."},{"t":"Verlangen: Stimulanzien, die verschlechtern."},{"t":"Agg.: Linksliegen; Kleidung; kalte Luft; nach Schlaf; Menses; Nacht."},{"t":"Amel.: Fahren oder Gehen im Freien."}],"rem":1,"orig":"Myrica cerifera"},{"label":"Natrium arsenicosum","short":"Natrium arsenicosum","group":"Arzneimittellehre","paras":[{"t":"Extremer Perfektionismus. Intellektueller Überflieger. Überaus erfolgreich mit Kummer, über den nicht gesprochen wird. Mißbrauch in Kindheit (Staph.; Caust; Nat-m.; Ars.; Sep.)."},{"t":"Nasenkatarrh mit Kopfschmerz, Schmerz in Nasenwurzel, trockenen und schmerzhaften Augen. Ruhelosigkeit wie Ars. Schwimmendes Gefühl beim schnellen Kopfdrehen. Stirnkopfschmerz, Agg.: Druck; Tabakrauch (Hauptmittel). Konjunktivitis, Blepharitis. Trockene, brennende, schmerzhafte Augen; Starrheit der Augäpfel und Neigung, die Lider zu schließen. Schweregefühl, hängende Lider. Tränenfluß im Wind. Verklebung morgens. Augen ermüden leicht. Ödem der Orbitalregion. Supraorbitalschmerz."},{"t":"Sinusitis mit Krusten in der Nase."},{"t":"Hals purpurfarben, ödematös geschwollen, glasiert."},{"t":"Bergmannasthma. Beklemmung in Brust- und Herzgebiet, auch in der Kehle. Gefühl in den Lungen wie von eingeatmetem Rauch."},{"t":"Quälender Husten mit reichlichem, grünlichem Auswurf."},{"t":"Schmerz zwischen Schulterblättern, Amel.: Vorbeugen."},{"t":"Verlangen: Olivenöl."},{"t":"Agg.: Milch."}],"rem":1,"orig":"Natrium arsenicosum"},{"label":"Natrium carbonicum","short":"Natrium carbonicum","group":"Arzneimittellehre","paras":[{"t":"Große Schwäche durch Sommerhitze, Agg.: geringste Anstrengung. Chronische Folgen von Sonnenstich (Hauptmittel, auch an Gran. denken) und Hitzschlag. Abgemagert, blaß, blaue Ringe um die Augen, erweiterte Pupillen. Dunkler Urin; anämisch; milchig-blasse Haut und große Schwäche."},{"t":"Unfähig zu denken, schweres, langsames Begriffsvermögen. Sorgen, Depression. Angst und Ruhelosigkeit bei Gewitter (Phos.), Agg.: Musik (Ambr.). Auffallende Vergnügtheit. Empfindlich gegen Anwesenheit bestimmter Personen."},{"t":"Kopfschmerz, Agg.: leichteste geistige Anstrengung; Sonne; Arbeiten bei künstlichem Licht (Glon.; Lach.). Spannung im Genick oder Hinterkopf vor den Menses. Gefühl, Kopf zu groß, als ob er bersten wolle. Kopfschmerz bei Wiederkehr heißen Wetters. Abwechselnd Kopfschmerz - Magenschmerz."},{"t":"Schlechte Assimilation: Verdauungsstörung durch kleinsten Diätfehler; Böse Folgen von Kalttrinken bei Überhitzung. Magenschmerz, Agg.: Berührung, warme Getränke, Amel.: Brot. Alte Menschen mit Dyspepsie, immer aufstoßend, mit saurem Magen und Rheumatismus. Dyspepsie, Amel.: Salzgebäck. Heißhunger 5/23 Uhr; Widerwille/Durchfall von Milch. Plötzlicher Stuhldrang; Entleerung mit Hast und Geräusch; orangenartiger Stuhl."},{"t":"Sehr schwache Sprunggelenke, leicht verrenkt. Skoliose, schwaches Knochengerüst, Gang nach vorn gebeugt."},{"t":"Stinkender Nasenkatarrh. Dauerschnupfen. Tropfen in Hals aus Nasenrachenraum. Hochräuspern von Schleim aus dem Rachen. Reichliche Absonderung tagsüber, verstopfte Nase nachts (Nux-v.), Agg.: geringste Zugluft. Gelbe Flecken, Pickel im Gesicht."},{"t":"Abneigung gegen Sex."},{"t":"Haut trocken, rauh, rissig, oder leichtes Schwitzen. Ausschlag an Fingerspitzen, Knöcheln und Zehen Ausschläge durch Sonnenlicht."},{"t":"Hypertonie durch Sonnenbestrahlung."},{"t":"Abneigung: Milch (Hauptmittel); Honig; Fleisch; Fett; frische Luft; Anstrengungen aller Art."},{"t":"Verlangen: Alkohol; Fett; Brot; Süßes."},{"t":"Agg.: Sonne; Sommerhitze; kalte Getränke bei Überhitzung; Alkohol; trockene Speisen; Nudeln; Wetterwechsel; vor und während Sturm (danach völlig erschöpft); bei Gewitter; nach Essen, Diätfehler."},{"t":"Empfindsamkeit. Verfeinert. Anpassungsschwierigkeiten; kann neue Situation nicht \"verdauen\", kann bestimmte Nahrungsmittel, Geräusche, Personen, Dinge nicht \"aufnehmen\". Empfindlich auf Atmosphäre; aufmerksam; beeindruckbar. Spirituell, dient dem Guru. Rücksicht und Hingabe gegenüber geliebten Menschen; höflich, verletzlich, verletzt nie jemanden, drängt sich nicht auf, will andere mit Sorgen/Kummer nicht belasten. Würde. Fassade der Heiterkeit. Einsiedler, Abneigung Gesellschaft, besser durch Alleinsein (Folge von Kummer). Kann sich nicht mehr freuen, leicht gekränkt. Suizidgedanken von Musik (Graph. weint bei Blasmusik). Masochist. Züge; alles düster, ganz schwere Depressionen. Hat Ärger und Abscheu für sich behalten, dadurch innerer Druck."},{"t":"Verlangen, magnetisiert zu werden. Furcht mit Zittern beim Klavierspielen. Eile beim Gehen."}],"rem":1,"orig":"Natrium carbonicum"},{"label":"Natrium muriaticum","short":"Natrium muriaticum","group":"Arzneimittellehre","paras":[{"t":"Emotionale Verletzlichkeit; introvertiert; ärgerlich wegen Kleinigkeiten, wenn angesprochen. Sehr ernst. Mangel an Leichtigkeit. Verschlossen. Sehnt sich nach Trost, weist ihn aber zurück; Trost verschlechtert alle Beschwerden. Romantisch. Unangepaßt, kritisch."},{"t":"Folge von Kummer, Furcht, (unterdrücktem) Ärger, Beleidigung."},{"t":"Kopfschmerz pulsierend, blindmachend, Zickzacklinien, Blitze. Kopfschmerz wie von tausend kleinen Hämmern, die auf Gehirn schlagen, Agg.: morgens beim Aufwachen; nach Menses; Sonnenauf- bis Sonnenuntergang; 10-15 Uhr; Augenüberanstrengung. Strabismus divergens. Gefühl, Kopf zu groß; kalt. Anämischer Kopfschmerz bei Schulmädchen. Chronischer Kopfschmerz, halbseitig, kongestiv. Übelkeit, Erbrechen, Migräne. Geräusch-, Lärm-, Lichtempfindlichkeit. Periodizität. Sinusitis. Tränenfluß bei jedem Husten. Schleim und Eiter bei Druck auf Tränensack. Schmerz in Augen beim Hinuntersehen; beginnender Katarakt. Ohrgeräusche. Heftiger Fließschnupfen, wässerig, 1-3 Tage, dann Verstopfung mit erschwerter Atmung. Geruchs- und Geschmacksverlust. Nase innen wund. Heuschnupfen mit Juckreiz in der Nase."},{"t":"Stirn ölig glänzend, Herpes labialis. Mundwinkelrhagaden. Tiefer Riß in Unterlippe. Landkartenzunge. Aphthen am Zahnfleisch."},{"t":"Starke Abmagerung trotz guten Essens; rapide Abmagerung an Hals und Nacken abwärts, bei Kindern mit Sommerdurchfällen. Durst auf große Mengen. Gastritis; Pulsieren in Magengrube; Stiche in Kardia. Schneidender Bauchschmerz. Verstopfung, Stuhl trocken, krümelnd (Mag-m.). Anus eingerissen, blutend. Schmerzloser, reichlicher Durchfall."},{"t":"Urin unfreiwillig. Pinkelhemmung. Schneiden in Harnröhre nach Wasserlassen (Sars.). Samenergüsse nach Koitus. Impotenz mit verzögertem Erguß. Menses unregelmäßig; reichlich. Vagina trocken. Koitus schmerzhaft. Weißfluß scharf, wässerig. Nach-unten-ziehende Schmerzen, Agg.: morgens (Sep.). Uterusprolaps mit Schneiden in Urethra. Unterdrückte Menses, Amenorrhoe. Hitze bei Menses."},{"t":"Husten durch Kitzeln in der Magengrube, Stiche in Leber, Herausspritzen von Urin."},{"t":"Stiche im ganzen Brustkorb. Husten mit berstendem Schmerz im Kopf. Asthma 17-19 Uhr. Keuchhusten mit Tränenfluß beim Husten."},{"t":"Tachykardie. Einschnürungsgefühl von Herz und Brust. Herz setzt aus beim Niederlegen. Rückenschmerz, Amel.: Liegen auf hartem Brett. Ischias, Amel.: fester Druck. Handflächen heiß und schwitzend. Nietnägel. Dornwarzen. Knöchel schwach, knicken leicht um. Kälte der Beine."},{"t":"Schläft auf der linken Seite. Nervöses Zucken im Schlaf. Träumt von Räubern. Schlaflos wegen Kummer."},{"t":"Haut fettig an behaarten Teilen. Trockene Ausschläge an Haaransatz, Gelenkbeugen, hinter Ohren. Urtikaria; Jucken und Brennen. Haarausfall. Jucken nach Anstrengung. Periodizität."},{"t":"Fieber mit Frösteln 9-11 Uhr. Hitze, heftiger Durst mit Fieber. Malaria. Verlangen: Salz; Saures; Bitteres; Nudeln; Fisch; frische Luft."},{"t":"Abneigung: Fett; schleimige Speisen; Hühnerfleisch; Brot."},{"t":"Agg.: 9-11 Uhr; Sommersonne (Haut, Kopfschmerz); Frühjahr; Morgen; Hitze; Kälte; Meer; Geräusch; Musik; Zimmerwärme; Hinlegen; Trost; Kummer."}],"rem":1,"orig":"Natrium muriaticum"},{"label":"Natrium phosphoricum","short":"Natrium phosphoricum","group":"Arzneimittellehre","paras":[{"t":"Offener als Natrium, verschlossener als Phos. Angespannt, Reizbarkeit, wirkt bei Erregung wie Med. Leidenschaftlich."},{"t":"Absonderungen sind sauer und gelb. Kinder, die zuviel Milch und Zucker bekommen haben. Hyperazidität. Ängste wie Phos: nachts, Dunkelheit, Gewitter. Angst um Gesundheit; hochgelegene Orte."},{"t":"Gleichgültigkeit gegenüber geliebten Personen, gegen alles."},{"t":"Ein Ohr rot, heiß, juckend mit Magenbeschwerden. Nasenjucken. Nasenrachenkatarrh mit dickem, gelbem, stinkendem Schleim. Aphthen von Lippe und Wangen. Blasen an der Zungenspitze, stechend, Agg.: abends. Rachen entzündet, Kloßgefühl. Dünner, feuchter Belag auf der Zunge. Gelber, cremiger Belag hinten am Gaumen. Dysphagie. Kolik bei Wurmbefall. Unruhiger Schlaf wegen Würmern."},{"t":"Blähsucht mit saurem Aufstoßen; saures Erbrechen, grünlicher Durchfall. Unfreiwilliger Stuhl mit Flatus."},{"t":"Jede Nacht Ergüsse ohne Träume mit Schwäche im Rücken und Zittern in den Gliedern. Wirbelsäulenbeschwerden, Agg.: nachts. Leukorrhoe sauer, wässerig. Kälte der Extremitäten. Füße eiskalt tags, Brennen nachts. Schmerzen in Hand- und Fingergelenken; Kniesehnen schmerzhaft. Synoviale Krepitation. Rheumatische Arthritis."},{"t":"Urtikaria. Jucken verschiedener Körperteile, vor allem Knöchel. Gelbsucht."},{"t":"Haut glatt, rot, glänzend, Erysipel. Erwacht durch leisestes Geräusch."},{"t":"Verlangen: Spiegeleier (selten); gebratener Fisch; kräftiges Essen; Salz; Bier; Fett; Eiscreme."},{"t":"Abneigung: Süßes; Brot; Butter; Fett; Saures; kalte Getränke."},{"t":"Agg.: Zucker; Milch; Koitus; Gewitter."}],"rem":1,"orig":"Natrium phosphoricum"},{"label":"Natrium sulphuricum","short":"Natrium sulphuricum","group":"Arzneimittellehre","paras":[{"t":"Sykose. Warmblütig mit Hitze von Scheitel und Füßen. Konvulsionen, Kopfschmerz, nach Verletzung des Kopfes / der Wirbelsäule. Beschwerden von feucht-nasser Umgebung; Wetterwechsel von trocken zu feucht."},{"t":"Gallenkopfschmerz mit bitterem Geschmack; nach Kopfverletzungen. Meningitis."},{"t":"Lider granuliert, kleine Bläschen, grüner Eiter, Photophobie."},{"t":"Nasenkatarrh dick, gelb, salzig, läuft hinten herunter."},{"t":"Zunge braun belegt. Speichel dick, zäh, weißlich. Bitterer Geschmack."},{"t":"Schlechte Verdauung, Agg.: Stärkehaltiges. Leberkrankheiten. Verstopfung; Flatulenz. Blähungskoliken. Lockere Morgenstühle; Durchfall nach dem Aufstehen, nach Frühstück; unwillkürlicher Stuhl mit Blähungsabgang. Krebs des Colon sigmoideum und des Rektums."},{"t":"Pneumonie links Unterlappen mit starkem Wundheitsgefühl der Brust während des Hustens, muß aufsitzen im Bett und die Brust mit beiden Händen halten. Asthma, Dyspnoe, Agg.: Feuchtigkeit; 4/5 Uhr; Rasseln in der Brust. Sputum reichlich, grünlich. Schwäche der Brust. Dauerndes Verlangen, tief und lange einzuatmen. Asthma bei Kindern."},{"t":"Warzen, Kondylome, weich und rot um Genitalien. Weißfluß folgt nach GO."},{"t":"Rheumatismus. Gelbsucht."},{"t":"Verlangen: Joghurt; Eis; gekochte Milch; eiskaltes Wasser."},{"t":"Abneigung: Fleisch; Brot."},{"t":"Agg.: feuchtes, nasses Wetter; Linksliegen; Ruhe; Liegen; Stärke; Milch; Obst; Gemüse; Kopfverletzung; Musik."},{"t":"Amel.: Durchfall; trockenes Wetter; Lagewechsel; \"fröhlich nach Stuhlgang\"."},{"t":"Empfindsam (am wenigsten empfindlich von der Natriumgruppe)."},{"t":"Systematisch. Möchte alles ordentlich machen und immer der Erste sein. Fühlt sich benachteiligt durch körperliche Schwäche (Asthma); dies führt zu grollender, rachsüchtiger Einstellung auf die, die besser sein könnten und zu zunehmender Verschlossenheit."},{"t":"Sexualtrieb in Bezug auf eine bestimmte Frau sehr stark, zerbricht, wenn er sie verliert; innerlich sehr gereizt, hart. Im Leben häufig verletzte Gefühle. Pflichtbewußt, reizbar und erfolgreich (findet Erfolg normal). Will aufsteigen. Starrheit, Plan zu erfüllen (Nat-m.), Leber (in China: Organ der Planung). Zeigt keine Gefühle, nicht spontan und impulsiv. Geschäftsmann, bodenständig, würde sich gerne umbringen (erhängen, selten erschießen), hält sich zurück wegen Verantwortung Familie gegenüber. Bei Nachtclubmusik: weich, sentimental, Neigung zum Weinen (Nat-c.; Graph.). Erwartet, verstanden zu werden. Verzagtheit. Unzufriedenheit."}],"rem":1,"orig":"Natrium sulphuricum"},{"label":"Niccolum-met. + -c. (old abbr.)","short":"Niccolum-met. + -c. (old abbr.)","group":"Arzneimittellehre","paras":[{"t":"Schwäche, häufige Kopfschmerzen, Dyspepsie und Verstopfung. Katarrhe und Husten."},{"t":"Periodischer Kopfschmerz, Agg.: 10-11 Uhr, Amel.: abends; von links nach rechts."},{"t":"Heftiges Niesen und Nasenkatarrh mit roter Nasenspitze. Wunder Hals rechts, Agg.: äußere Berührung. Sinkendes, leeres Gefühl im Magen ohne Appetit. Schluckauf. Schmerz vom Magen zur Schulter. Verstopfung; Dyspepsie."},{"t":"Leukorrhoe, Agg.: nach Wasserlassen; nach den Menses."},{"t":"Husten: muß aufsitzen und Kopf halten; muß Schenkel halten bei Husten; Kind muß hochgenommen werden."},{"t":"Knacken in Halswirbelsäule-Region bei Kopfbewegung."},{"t":"Agg.: vormittags; Gehen; Milch; alle 2 Wochen; jedes Jahr."},{"t":"Amel.: abends; nach dem Essen."}],"rem":1,"orig":"Niccolum-met. + -c. (old abbr.)"},{"label":"Nitricum acidum","short":"Nitricum acidum","group":"Arzneimittellehre","paras":[{"t":"Salpetersäure. Dünn, sehnig, frostig, schwach, anämisch blaß. Unglücklich, unzufrieden. Kann nicht verzeihen, auch sich selbst nicht, unversöhnlich. Sehr Reizbar. Fluchen. Schwören. Krebsangst. Von Arzt zu Arzt. Hoffnungslosigkeit. Suizidgedanken, aber Furcht zu sterben. Geräuschempfindlich, Knacken in den Ohren beim Kauen. Chronisch krank. Erkältungsneigung. Durchfallneigung. Milchunverträglichkeit."},{"t":"Leicht blutende Fissuren/Risse/Blasen/Geschwüre an Körperöffnungen, Haut/Schleimhautgrenzen (Mundwinkel, Zunge, weicher Gaumen, Anus, Penis, Urethra, Vagina). Kondylome und Warzen bluten dunkel, sehr empfindlich. Speichelfluß, blutiger Speichel."},{"t":"Widerliche Absonderungen, stinkend, ätzend, blutend; ekelhafter Fußschweiß, scharf, wundmachend. Urin riecht wie Pferdeurin, kalt beim Wasserlassen. Durchfall schleimig, stinkend. Empfindliche Hämorrhoiden. Bandgefühl um Kopf. Kopfschmerz durch Hutdruck. Dyspnoe, Agg.: Steigen."},{"t":"Schlaf unerquicklich, morgens übelgelaunt."},{"t":"Splitterschmerz, stechend. Schmerz in langen Röhrenknochen, Agg.: nachts."},{"t":"Rektumkarzinom (Hauptmittel), (Colon descendens.: Nat-s.). Anhaltender Schmerz nach Stuhlgang."},{"t":"Verlangen: Fett und Salz; Hering; Süßigkeiten."},{"t":"Abneigung: Käse; Brot; Milch; Eier; Fleisch; Süßigkeiten."},{"t":"Amel.: Fahren in der Kutsche."},{"t":"Agg.: Denken an Beschwerden; abends und nachts; leiseste Berührung; Erschütterung; Lärm; Wetterwechsel; Schweiß; Gehen; Milch."},{"t":"Unglück und Belastungen haben zum Zusammenbruch geführt. Hypochondrie, nicht zu beruhigen; Winseln, Jammern, fühlt sich elend."},{"t":"Allergien aller Art. \"Wofür soll man leben?\" (früher vielleicht Jet-Set). Abscheu vor dem Leben, Nihilist, antriebslos. Ängstlich, kein Mut mehr, weiterzukämpfen. Pflegt seinen unausgewogenen Zustand, weil er soviel Angst um seine Gesundheit hat, vor Krebs (Hauptmittel). Sehr vorsichtig mit Leben und Nahrung. Nicht ernstlich krank, wird alt. Arzt ist persönlicher Dienstbote; ruft zu jeder Tageszeit an, bricht dann in überwältigendes Weinen aus: \"Ich werde sterben\"."},{"t":"Die anstrengendsten Patienten."},{"t":"Sexualität zur körperlichen Befriedigung, kein tiefer Kontakt (Sex-Club, Puff)."}],"rem":1,"orig":"Nitricum acidum"},{"label":"Nux moschata","short":"Nux moschata","group":"Arzneimittellehre","paras":[{"t":"Nux moschata, Muskatnuß. Hysterie mit Ohnmachtsneigung. Abwechselndes Lachen und Weinen. Geistesabwesend. Gleichgültig. Wahnvorstellung, doppelt zu sein, zwei Köpfe zu haben. Erkennt bekannte Straßen nicht wieder (Cann-i.; Lach.). Gedächtnisverlust; schwindende Gedanken. Verwirrt, wie betrunken."},{"t":"Trägheit und Schläfrigkeit bei allen Beschwerden."},{"t":"Ohnmacht beim Anblick von Blut; mit dem Schmerz. Kopfschmerz, Amel.: starker Druck. Überempfindlich gegen Licht; Geräusch; Gerüche; Berührung."},{"t":"Rachen-/Mundtrockenheit, durstlos, Agg.: bei Menses. Speichel wie Watte."},{"t":"Magenschmerz beim Essen oder sofort danach (Kali-bi.). Magen/Darm enorm gebläht nach jeder Mahlzeit. Schluckauf mit Verlangen nach stark gewürzten Speisen. Diarrhoe, Agg.: nach kalten Getränken; im Herbst epidemisch, weiß, stinkend. Verstopfung bei weichem Stuhl. Ohnmacht bei/nach Stuhlgang."},{"t":"Fieber ohne Schweiß, mit trockener Haut."},{"t":"Menses dunkel, unregelmäßig, unterschiedlich stark."},{"t":"Hysterische Heiserkeit. Heiser beim Gehen gegen den Wind. Husten beim Warmwerden im Bett; durch feuchte Kälte (Nat-s.). Frostig."},{"t":"Rheumatische Schmerzen durch nasse Füße, feuchte Kälte; linke Schulter."},{"t":"Verlangen: Pikantes."},{"t":"Agg.: Kälte, Nässe, Wind; Liegen auf schmerzhafter Seite; Menses; Gefühlserregung."},{"t":"Amel.: warmes Wetter, Wärme."}],"rem":1,"orig":"Nux moschata"},{"label":"Nux vomica","short":"Nux vomica","group":"Arzneimittellehre","paras":[{"t":"Nux vomica, Brechnußbaum. Robust, stämmig, kräftig. Ehrgeizig, kompetent, pflichtbewußt. Pragmatisch, nicht philosophisch. Sehr ordnungsliebend. Überstimuliert. Spricht schnell und effizient."},{"t":"Kann nicht abschalten, denkt an Geschäft. Erwacht 4 Uhr, schläft erst morgens ein. ZNS und Magen überempfindlich. Alle möglichen Folgen von Zorn/Wut."},{"t":"Liebt Reizmittel aller Art. Sex (\"amoralisch\"), zu viel; Impotenz."},{"t":"Übelkeit, Erbrechen, Agg.: morgens; nach Essen. Übelkeit, ohne Erbrechen zu können. Magendrücken wie von einem Stein, Stunden nach Essen. Sodbrennen, Blähungen. Leistenhernie, Nabelhernie. Obstipation. Schwierige Entleerung von Blase und Darm. Häufiger, erfolgloser Drang, kleine Mengen."},{"t":"Pfortaderstau, Ösophagusvarizen, Hämorrhoiden, Ikterus, Leberzirrhose; Gallen-/Nierenkolik. Durchfall nach Zorn. Ohnmachtsneigung."},{"t":"Nervensystem, nervöse Zuckungen. Lumbago nach Zorn; nach Masturbation."},{"t":"Asthma mit Völle im Magen. Husten verursacht berstenden Kopfschmerz."},{"t":"Kopfschmerz Hinterkopf oder über Augen mit Schwindel; Scheitelkopfschmerz wie von Nagel; nach Apoplexie mit Stechen in gelähmten Gliedern; Krämpfe, Opisthotonus, Epilepsie. Delirium tremens."},{"t":"Strabismus convergens bei Kindern."},{"t":"Sehr empfindlicher Magen auf fast alles. Appetit gering."},{"t":"Schnupfen, Agg.: warmes Zimmer, Amel.: in kalter Luft. Scharfe Absonderung mit Verstopfungsgefühl. Nase verstopft im Freien und nachts. Fließschnupfen tagsüber. Frostig."},{"t":"Verlangen: Fett; Pikantes; Stimulanzien; Alkohol."},{"t":"Abneigung: Fleisch."},{"t":"Agg.: äußere Reize; Ärger; nach Essen; feuchte Kälte; 4 Uhr; Zugluft."},{"t":"Amel.: naßfeuchtes Wetter; warme Anwendungen; kurzer Schlaf."},{"t":"Ruiniert Gesundheit fürs Geschäft. Rücksichtslos, freut sich über immer mehr Verantwortung, anspruchsvoll. Kann eigene Grenzen nicht akzeptieren. Zorn, wenn gezwungen, zu antworten. Schimpft und tadelt aus geringem Anlaß. Verträgt keinen Widerspruch, weil er sowieso recht hat. Impulsiv, direkt, zerschlägt Telefon; undiplomatisch. Boshaft, heimtückisch, gewalttätig; tritt plötzlich nach einem Tier (Med.), Männer schlagen Frauen, Eltern mißhandeln Kinder. Suizidneigung aber Furcht vor dem Tod. Paranoia. Tötungsimpuls. Furcht vor Verletzung und Beleidigung. Abneigung gegen Heiraten, Gesellschaft."}],"rem":1,"orig":"Nux vomica"},{"label":"Ocimum canum","short":"Ocimum canum","group":"Arzneimittellehre","paras":[{"t":"Ocimum canum, Kampherbasilikum. Nierenkolik, vor allem rechts. Nierensteinsymptome. Harnleiterschmerz, Nierenkrämpfe."},{"t":"Urin: hoher Säuregehalt, Urate; trüb, dick, eitrig, blutig. Backsteinrotes oder gelbes Sediment; Moschusgeruch."},{"t":"Hitze und Schwellung linker Hoden."},{"t":"Vulva geschwollen; stechender Schmerz in Labien. Drüsenschwellung inguinal. Brüste voll und gespannt. Juckend. Brustwarzen empfindlich beim leichtesten Kontakt."}],"rem":1,"orig":"Ocimum canum"},{"label":"Oenanthe crocata","short":"Oenanthe crocata","group":"Arzneimittellehre","paras":[{"t":"Oenanthe crocata, Rebendolde. Epileptische Krampfanfälle,"},{"t":"Agg.: Menses, Schwangerschaft, im Kindbett, urämisch; im Schlaf; mit Priapismus. Status epilepticus. Schreit laut und fällt nach hinten."},{"t":"Halluzinationen."},{"t":"Krampfhaftes Zucken der Gesichtsmuskeln; Schaum vor dem Mund, Kieferstarre. Opisthotonus. Viel Gähnen. Weinen wegen Kleinigkeiten."},{"t":"Brennen in Rachen und Magen, Übelkeit und Erbrechen, tagelang, durch nichts zu beeinflussen."},{"t":"Rote Flecken im Gesicht, auf Brust und Abdomen. Ichthyosis; Lepra."},{"t":"Kitzelhusten mit Rasseln im Unterlappen; dicker, schaumiger Auswurf. Schweres, spastisches Atmen. Stertoröses Atmen."},{"t":"Kalte und Taubheit von Händen und Füßen."},{"t":"Agg.: sexuelle und menstruelle Störungen; Verletzungen; Winter."}],"rem":1,"orig":"Oenanthe crocata"},{"label":"Oleum animale aethereum","short":"Oleum animale aethereum","group":"Arzneimittellehre","paras":[{"t":"Oleum animale, Brenzöl, Destillat aus Tierkadavern. Nervensystem, vor allem im Lungen-Magengebiet. Schmerz \"zieht nach oben\" und \"von hinten nach vorne\". Brennen. Stechen."},{"t":"Kälte und Schmerz einzelner Körperteile."},{"t":"Migräne mit Polyurie. Reißender Kopfschmerz mit Trauer und Reizbarkeit, Agg.: nach dem Essen, Amel.: Reiben. Gefühl, Backenknochen werden gewaltsam hochgezogen. Zahnschmerz, Amel.: Zusammenpressen der Zähne. Kälte der Zähne."},{"t":"Zucken der Lippen. Gefühl wie von Wasser im Magen; von Kälte, Einschnürung und Brennen, Amel.: Aufstoßen. Nach Harn riechendes Aufstoßen."},{"t":"Polyurie mit viel farblosem Urin; Geruch wie Fischlake. Häufiger Drang. Tenesmus. Jucken in Urethra."},{"t":"Hodenschmerz wie ergriffen und gewaltsam nach oben gezogen. Samenstrangneuralgie. Druck im Damm, Prostatahypertrophie."},{"t":"Frühe und spärliche Menstruation; schwarzer Fluß."},{"t":"Asthma durch unterdrückten Fußschweiß. Zusammenschnürungsgefühl. Stiche in der Brust von hinten nach vorne. Fußschweiß riecht wie Fischlake."},{"t":"Agg.: nach dem Essen; 14-21 Uhr; unterdrückter Fußschweiß."},{"t":"Amel.: Reiben; Aufstoßen; im Freien."}],"rem":1,"orig":"Oleum animale aethereum"},{"label":"Oleum jecoris aselli","short":"Oleum jecoris aselli","group":"Arzneimittellehre","paras":[{"t":"Oleum jecoris aselli, Dorschlebertran. Atrophie bei Kindern mit Milchunverträglichkeit. Abmagerung mit heißen Händen und heißem Kopf. Mangelernährung. Mattigkeit."},{"t":"Unruhig und fiebrig nachts. Erkältungsneigung. Schwäche."},{"t":"Schmerz und Schwere in der Leber, Agg.: Anstrengung. Pankreaserkrankungen."},{"t":"Trockner, hackender, kitzelnder Husten, Agg.: nachts; mit Herzklopfen. Keuchhusten. Mukoviszidose. Beginnende Tuberkulose. Schmerzhaftigkeit in der Brust oder Stiche. Kreuzschmerz; Frostschauer vom Kreuzbein nach oben. Brennen in Handflächen. Ikterus; Milchschorf; Herpes circinatus."},{"t":"Täglich remittierendes Fieber. Nachtschweiß."},{"t":"Agg.: Kälte, Feuchtigkeit; Milch; Bewegung."}],"rem":1,"orig":"Oleum jecoris aselli"},{"label":"Oleander","short":"Oleander","group":"Arzneimittellehre","paras":[{"t":"Nerium oleander. Taubheit, Schwäche und paralytische Zustände mit krampfartigen Kontraktionen der oberen Gliedmaßen; Hemiplegie. Deutliche Aussprache erschwert. Blässe, blaue Augenringe (Ph-ac.)"},{"t":"Schwindel und Doppeltsehen, Agg.: Nachuntensehen, beim Fixieren; beim Aufstehen vom Bett. Sieht Gegenstände nur beim Seitwärtsblicken."},{"t":"Gefühl, als würden die Augen nach hinten in den Kopf gezogen."},{"t":"Feuchte, scharfe, juckende Ausschläge auf dem Kopf, hinter den Ohren (Graph.; Petrol.), am Hinterkopf. Jucken an Stirn und Haarrand, Agg.: Hitze. Rote, rauhe, herpesartige Stellen an der Stirn."},{"t":"Heißhunger mit hastigem Essen. Kollern mit viel stinkendem Flatus. Stinkende, unverdaute Stühle; geht ab bei Flatus. Brennen im Anus."},{"t":"Brustbeklemmung wie von einem Gewicht; asthmatisch beim Niederlegen. Herzklopfen mit Schwäche und Leeregefühl in der Brust. Atemnot. Stiche."},{"t":"Schwäche der unteren Gliedmaßen. Schmerzlose Lähmung."},{"t":"Haut sehr empfindlich, leichtestes Reiben verursacht Wundheit und Abschilfern. Heftig juckender Ausschlag, blutend, nässend, schorfig, ringförmig, Agg.: Orangen, Tomaten, Saures. Juckreiz nach Entkleiden. Herpes, empfindlich und taub; nächtliches Brennen."},{"t":"Verlangen: kaltes Wasser; Orangen."},{"t":"Abneigung: Käse."},{"t":"Agg.: Reiben; Auskleiden; Orangen."},{"t":"Amel.: Weinbrand; Seitwärtssehen."}],"rem":1,"orig":"Oleander"},{"label":"Onosmodium virginianum","short":"Onosmodium virginianum","group":"Arzneimittellehre","paras":[{"t":"Onosmodium virginianum, Falscher Steinsamen. Mangelhafte Konzentration und Koordination. Unentschlossenheit in seinen Handlungen."},{"t":"Migräne. Kopfschmerz durch Überanstrengung der Augen; Hinterkopf, Agg.: links. Sex. Erregung bei Kopfschmerz. Angestrengtes Gefühl im Auge, Agg.: Lesen von kleiner Schrift. Augen schwer und trübe, muskuläre Asthenopie. Schmerz in Augäpfeln, zur linken Schläfe ausstrahlend. Entfernte Objekte sehen vergrößert aus, hebt deshalb Fuß unnötig hoch beim Übersteigen kleiner Objekte."},{"t":"Gefühl von Auftreibung im Bauch, Verlangen nach Eiswasser."},{"t":"Ejaculatio praecox; psychisch bedingte Impotenz. Völliger Libidoverlust bei beiden Geschlechtern. Nachuntendrängen im Uterus. Weißfluß gelb, scharf, weißlich. Wunde Eierstöcke und Rektum. Müdes und taubes Gefühl in unteren Gliedmaßen. Wankender Gang. Schmerz linkes Schulterblatt. Starke Muskelschwäche und -müdigkeit."},{"t":"Verlangen: Eiswasser; kalte Getränke."},{"t":"Agg.: Anstrengung der Augen; sexuelle Exzesse; enge Kleidung."},{"t":"Amel.: Entkleiden; kalte Getränke; Liegen auf dem Rücken."}],"rem":1,"orig":"Onosmodium virginianum"},{"label":"Opium","short":"Opium","group":"Arzneimittellehre","paras":[{"t":"Opium, Schlafmohnmilchsaft. Reaktionsmangel. Großes Leiden ohne Schmerz. Furcht besteht weiter nach Schreckerlebnis. Empfindungslosigkeit mit Paralyse. Lähmung nach Schreck. Von CO-Gas, Gasinhalation, bei Säufern. Apoplexie."},{"t":"Große Schlafsucht, Schmerzlosigkeit und Apathie; verlangt nichts, beklagt sich nicht. Sprechen im Delirium mit weit geöffneten Augen. Denkt, er ist nicht zu Hause; Zupfen am Bettzeug. Akuter Schizophrenieschub. Leichtigkeit des Kopfes bei alten Leuten."},{"t":"Spasmen bei Kindern durch Annäherung Fremder; vom Stillen nach Schreck der Mutter (Hyos.); vom Schreien."},{"t":"Augen halboffen und nach oben gedreht. Pupillenkontraktion. Aufschreien vor/bei Krampf."},{"t":"Gesicht rot, geschwollen, dunkel, blutunterlaufen, heiß. Sieht töricht aus, Unterkiefer hängt herunter, spastisches Gesichtszucken. Mund trocken, Zunge gelähmt, schwarz."},{"t":"Tiefe, röchelnde, intermittierende, ungleiche Atmung; Bewußtlosigkeit. Schläfrig, kann aber nicht schlafen, dabei geschärftes Gehör auf entfernte Geräusche, die ihn am Einschlafen hindern."},{"t":"Bett erscheint so heiß, daß sie nicht darauf liegen kann."},{"t":"Hitze in der Brust, Brennen in Herzgegend. Husten mit Dyspnoe und blauem Gesicht."},{"t":"Voller, langsamer Puls, heißer Schweiß am ganzen Körper, nicht an Beinen. Hohes Fieber. Durst."},{"t":"Verdauung gelähmt, umgekehrte Peristaltik, Koterbrechen. Gefühl, Anus verschlossen. Hartnäckige Obstipation, kein Drang; von Bleivergiftung; postoperativ. Stuhl hart, runde schwarze Knollen (Chel.; Plb.; Thuj.); schlüpft zurück. Stuhl unfreiwillig, besonders nach Schreck (Gels.), durch Sphinkterlähmung."},{"t":"Harnverhalt bei voller Blase, wird nicht bemerkt. Blasenlähmung."},{"t":"Abgemagertes Kind mit runzeliger Haut, sieht alt aus."},{"t":"Agg.: Schreck; unterdrückte Ausschläge und Absonderungen; im/nach Schlaf (Apis; Lach.); beim Schwitzen; Wärme. Stimulanzien."},{"t":"Amel.: Kälte; Umhergehen."}],"rem":1,"orig":"Opium"},{"label":"Origanum majorana","short":"Origanum majorana","group":"Arzneimittellehre","paras":[{"t":"Origanum majorana, süßer Majoran. Stark erregte Libido mit Masturbation bei jungen Mädchen; Jucken der Genitalien. Laszive Träume und Ideen. Erotomanie. Weißfluß. Hysterie. Schwellung und Jucken der Brustwarzen und Schmerz in den Brüsten. Verlangen nach körperlicher Bewegung treibt Patienten zum Laufen an."}],"rem":1,"orig":"Origanum majorana"},{"label":"Osmium metallicum","short":"Osmium metallicum","group":"Arzneimittellehre","paras":[{"t":"Osmium met. Reizung und Katarrh der Atemwege, Schmerz in Trachea und Larynx; Ekzem; Albuminurie; stinkende Schweiße. Glaukom; Grüne Farben um das Kerzenlicht. Konjunktivitis, verwischtes Sehen, Lichtscheu."},{"t":"Schnupfen mit Völlegefühl in Nase. Nase und Kehlkopf empfindlich auf kalte Luft. Kleine Schleimklumpen aus hinteren Nasenöffnungen."},{"t":"Akute Laryngitis mit Schmerz im Kehlkopf, Agg.: Sprechen, Husten."},{"t":"Husten und Auswurf von zähem, fädigem Schleim. Konvulsiver Husten. Husten, als ob eine Membran aus der Kehle gerissen würde."},{"t":"Lauter, trockener, harter Husten in heftigen, kurzen Stößen, aus der Tiefe kommend, den ganzen Körper erschütternd. Schmerz des Brustbeins. Zucken der Finger bei spastischem Husten."},{"t":"Steingefühl im Magen. Ängstlich nach wenig Essen. Magenkontraktionen nach dem Essen."},{"t":"Ekzem mit Juckreiz. Gereizte Haut. Juckende Stippen. Bromhidrosis. Achselschweiß riecht nach Knoblauch, Agg.: abends und nachts."},{"t":"Nagelhaut haftet am wachsenden Nagel."},{"t":"Albuminurie, Urin spärlich, schwarz mit Veilchengeruch."},{"t":"Abneigung: Schokolade; Kaffee."}],"rem":1,"orig":"Osmium metallicum"},{"label":"Oxalicum acidum","short":"Oxalicum acidum","group":"Arzneimittellehre","paras":[{"t":"Oxalsäure. Schmerz an bestimmten, kleinen Stellen (Kali-bi.), Agg.: Bewegung, Darandenken. Lanzinierende Schmerzen, zuckend, blitzartig schießend. Linksseitiger Rheumatismus. Periodische Remissionen. Neurasthenie."},{"t":"Überempfindlichkeit der Netzhaut. Augenschmerz. Vergrößerungsgefühl."},{"t":"Heftige Schmerzen im Epigastrium, Agg.: Berührung, Zucker; Amel.: Flatus. Kann keine Erdbeeren essen. Schmerz um den Nabel, zwei Stunden nach dem Essen. Erwacht um 3 Uhr mit Magen- und Bauchschmerz. Durchfall von Kaffee. Samenstrangneuralgie, Agg.: Berührung. Urin oxalatreich."},{"t":"Stimmverlust mit oder abwechselnd mit Herzbeschwerden. Scharfer Schmerz im Herzen oder in der linken Lunge, nimmt den Atem, strahlt zum Oberbauch aus."},{"t":"Dyspnoe, Agg.: nachts; kurze, zuckende Einatmung. Angina pectoris, ausstrahlend den Arm hinunter mit Taubheit der Finger. Aortenklappeninsuffizienz. Sitzt aufrecht mit den Armen über die Brust gefaltet. Schmerzhafte Haut, Agg.: Rasieren."},{"t":"Rückenschmerz, taub, schwach. Myelitis. Muskelschwäche. Schmerzen von der Wirbelsäule in Extremitäten ausstrahlend. Multiple Sklerose und Sklerose der hinteren Wurzelstränge. Handgelenk schmerzhaft, wie verstaucht (Ulm-c.)."},{"t":"Agg.: Kälte; Berührung; Bewegung; Darandenken; Kaffee; Wein; saures Obst; Rasieren."}],"rem":1,"orig":"Oxalicum acidum"},{"label":"Paeonia officinalis","short":"Paeonia officinalis","group":"Arzneimittellehre","paras":[{"t":"Paeonia off., Pfingstrose. Chronische Ulzera an unteren Körperteilen, Bein, Fuß, Zeh, Brust."},{"t":"Unerträgliche Schmerzen während und nach Stuhlgang; Brennen im Anus nach Stuhlgang mit innerem Frösteln."},{"t":"Beißen und Jucken im Anus. Analfistel. Hämorrhoiden, Fissuren und Geschwüren von Anus und Damm, purpurfarben, bedeckt mit Krusten. Stinkende, nässende Geschwüre. Hämorrhoiden sind groß, kongestiert, thrombotisch. Splitterartige, stechende Schmerzen, erzwingen Umhergehen und Kratzen. Schmerz bleibt nach Stuhlgang bestehen."},{"t":"Hautgeschwüre durch Druck allgemein, vom Wundliegen, drückenden Schuhen. Schreckliche Alpträume."},{"t":"Beschwerden von schlechten Nachrichten."},{"t":"Agg.: Berührung; Druck; Nacht; Bewegung; während und nach Stuhlgang."}],"rem":1,"orig":"Paeonia officinalis"},{"label":"Palladium metallicum","short":"Palladium metallicum","group":"Arzneimittellehre","paras":[{"t":"Liebt Bestätigung. Stolz; leicht beleidigt, weinerlich. Beschwerden von Kränkung, verletzter Ehre. Munter in Gesellschaft aber nachher erschöpft und traurig. Heftige Ausdrucksweise. Zeit vergeht zu langsam. Agg.: traurige Nachrichten. Hochmut (Plat.)."},{"t":"Schmerz im oberen Teil des Kopfes von Ohr zu Ohr. Schießen vom Nabel zum Becken; vom Nabel zur Brust."},{"t":"Neuralgie des rechten Ovars, Amel.: starker Druck. Prolaps oder Verlagerung des Uterus und hinabdrängende Schmerzen, Amel.: Reiben. Schneidender Uterusschmerz, Amel.: nach Stuhl. Entzündung der Beckenregion. Weißfluß eiweißartig."},{"t":"Menses in der Stillzeit. Schmerz strahlt zu Hüfte und Schenkeln aus. Enorme Schwäche."},{"t":"Beginn rechtes Ovar, sekundär Uterusverlagerung / Uterusprolaps / Pelviperitonitis."},{"t":"Agg.: Erschöpfung; schlechte Nachrichten; Gefühlserregung."},{"t":"Amel.: Druck; Reiben; nach Stuhlgang; Beschäftigung und Ablenkung."}],"rem":1,"orig":"Palladium metallicum"},{"label":"Paris Quadrifolia","short":"Paris Quadrifolia","group":"Arzneimittellehre","paras":[{"t":"Paris quadrifolia, Einbeere. Empfindet Körperteile als zu groß oder zusammengezogen. Eine Seite kalt, die andere Seite heiß."},{"t":"Gestörter Tastsinn."},{"t":"Taubheit; Schweregefühl."},{"t":"Manische Geschwätzigkeit, wechselt Themen. Unverschämt, verachtend."},{"t":"Schmerzen, als ob ein Faden von den Augen zum Hinterkopf gezogen würde."},{"t":"Augen wie zu groß."},{"t":"Hinterkopfschmerz mit Gewichtsgefühl."},{"t":"Eingebildete schlechte Gerüche; Brot, Fleisch, Fisch riechen verfault. Zunge trocken beim Erwachen; durstlos. Räuspert zähen, grünen Schleim. Klumpengefühl im Hals. Periodische, schmerzlose Heiserkeit."},{"t":"Gefühl eines Gewichts in Halswirbelsäule-Region; ausstrahlend in die Arme. Steißbeinneuralgie. Taubheit der Finger. Alles erscheint rauh."},{"t":"Agg.: Denken; Augenanstrengung; Berührung."},{"t":"Amel.: Druck."}],"rem":1,"orig":"Paris Quadrifolia"},{"label":"Pareira brava","short":"Pareira brava","group":"Arzneimittellehre","paras":[{"t":"Pareira brava, Grießwurz. Nierenkolik; Schmerz von der linken Niere durch die Ureter zur Leiste. Dauernder Drang, starkes Pressen, mit großem Schmerz zu den Schenkeln hinunter beim Pressen."},{"t":"Muß zum Urinieren knien, mit dem Kopf auf den Boden gepreßt."},{"t":"Heftiger Schmerz in Eichel und Penis beim Wasserlassen. Gedehntes, berstendes Gefühl in der Blase. Prostatahypertrophie. Nachtropfen. Jucken entlang der Urethra. Induration der Urethra."},{"t":"Urin schwarz, blutig, schleimig, roter Sand, dick."}],"rem":1,"orig":"Pareira brava"},{"label":"Petroleum","short":"Petroleum","group":"Arzneimittellehre","paras":[{"t":"Petroleum, Steinöl. Hautsymptome im Winter. Haut trocken oder feucht, gerissen, rot, rauh, empfindlich, dick. Ekzeme. Psoriasis der Hände. Risse mit wässeriger Absonderung. Risse bluten leicht. Eiterung nach Kratzen. Kratzt bis es blutet. Fingerspitzen rauh, geplatzt, rissig."},{"t":"Fühlt den Tod nahen, muß sich beeilen, seine Angelegenheiten zu ordnen. Langanhaltende Beschwerden nach Gefühlserregung, Schreck, Ärger. Verwirrung, verliert die Orientierung in bekannten Straßen; Wahnvorstellung, doppelt zu sein. Reizbarkeit, streitsüchtig; leicht beleidigt."},{"t":"Kopf empfindlich, Gefühl wie von kaltem Wind. Feuchter Ausschlag der Kopfhaut. Kopfschmerz, Amel.: Schläfendruck; mit Übelkeit und Hunger. Schwindel im Hinterkopf wie seekrank. Schwere im Hinterkopf wie Blei."},{"t":"Lidrandentzündung."},{"t":"Übelkeit mit blassem Gesicht und Verlangen nach frischer Luft. Magenschmerz, Amel.: Essen. Muß nachts aufstehen und essen (Psor.)."},{"t":"Durchfall: nur tagsüber, Agg.: Gemüse; von unterdrückten Hautausschlägen; Hunger nach Durchfall. Juckreiz von Rektum und Damm. Herpesausschläge der weiblichen Genitalien. Chronische Urethritis und Prostatitis. Brennende, juckende Handflächen und Fußsohlen; möchte sie aufdecken. Frostbeulen der Füße. Stinkender Fußschweiß."},{"t":"Knackende Gelenke bei chronischem Rheumatismus. Symptome erscheinen und verschwinden rasch. Jede Verletzung eitert. Reisekrankheit. Frostig."},{"t":"Verlangen: Bier; Süßigkeiten."},{"t":"Abneigung: Fleisch; Fett; heißes, gekochtes Essen."},{"t":"Agg.: Reiten; Winter; vor und bei Gewitter."},{"t":"Amel.: Frische Luft."},{"t":"vgl. Juglans cinerea"}],"rem":1,"orig":"Petroleum"},{"label":"Petroselinum sativum","short":"Petroselinum sativum","group":"Arzneimittellehre","paras":[{"t":"Petroselinum sativum, Petersilie. Plötzlicher, unwiderstehlicher Harndrang; Kind springt vor Schmerzen auf und ab, wenn es nicht sofort urinieren kann. Heftiges Beißen, Jucken, tief in der Urethra. Verlangen, Harnröhre mit rauhem Gegenstand zu reiben. Brennen, Stechen vom Damm aus durch die ganze Harnröhre."},{"t":"Akute oder chronische GO mit milchig-schleimigem Ausfluß. Traumatische oder chronische Urethritis. Striktur der Urethra. Harnprobleme bei Babies."},{"t":"Priapismus mit Penisverkrümmung. Schmerz an Peniswurzel oder Blasenhals. Nachtripper. Schleimige Verklebung der Harnröhrenöffnung. Prostatahypertrophie mit Dysurie."},{"t":"Juckende Hämorrhoiden."}],"rem":1,"orig":"Petroselinum sativum"},{"label":"Phosphoricum acidum","short":"Phosphoricum acidum","group":"Arzneimittellehre","paras":[{"t":"Phosphorsäure. Blaue Ringe um die Augen. Totale Schwäche, zuerst emotional. Gleichgültigkeit. Ursache sind kleine \"Schocks\", Kummer (Ign.); meist nach Zerbrechen einer Beziehung. Keine Reserven, dadurch \"wechselnde Stimmung\". Hauptmittel für Folge von ausgiebiger sexueller Betätigung (Schwindel, Kopfschmerz, Schwäche, Herzzittern...)."},{"t":"Reizbarkeit; enttäuscht, weiß nicht, wie es weitergehen soll."},{"t":"Schwäche nach innen gerichtet, kann deshalb Auseinandersetzungen nicht ertragen; braucht Unterstützung z. B. der Familie. Trost bessert. Stützsystem verloren; kein Gefühl mehr, Emotionen wie eingefroren, Teilnahmslosigkeit, \"ich kann nicht mehr, muß aufgeben, keiner kann mir helfen\"; aber nicht aggressiv."},{"t":"Schwäche dann auch geistig: total verlangsamt, kein Interesse, verspätete Reaktionen auf Reiz (Cocc.); schwaches Gedächtnis; fühlt sich Gesellschaft nicht gewachsen, meidet sie deshalb."},{"t":"Körperlich ständig bergab; Schläfenkopfschmerz, kochend; Kopfschmerz mit Druck von oben nach unten; Schulkopfschmerz; abwechselnd Frostschauer, Hitzewellen, subfebrile Temperatur. Schwindel abends, Agg.: Stehen, Gehen. Schwachsichtigkeit. Schmerz, als ob die Augäpfel gewaltsam zusammengepreßt würden. Bauchschmerz im Nabelgebiet."},{"t":"Diarrhoe schmerzlos, nicht schwächend, weiß, wässerig, unwillkürlich. mit Flatus (Nat-m.; Aloe). Reichliches Urinieren nachts von klarem, wässerigem Urin, der sofort weiße Wolke bildet (Phosphate)."},{"t":"Pollutionen häufig, reichlich, schwächend, unwiderstehlicher Drang zu onanieren, danach Schuldgefühle. Impotenz."},{"t":"Trockenheit Nase, Augen, Mund. Erschöpfung, Trägheit. Nebennierenrindenstörung. Diabetes. Dehydration, Folge von anhaltendem Flüssigkeitsverlust (Chin.). Keine sexuelle Energie mehr; Haarausfall, Ergrauen. Wachstumsschmerzen."},{"t":"Verlangen: Frisches; Säfte."},{"t":"Abneigung: Kaffee; saure Getränke."},{"t":"Agg.: Säfteverlust, besonders Sperma; Onanie, sexuelle Exzesse; Reden verursacht Schwäche in der Brust; angstvolle Schlaflosigkeit (Mur-ac. schläft)."},{"t":"Amel.: kurzer Schlaf."}],"rem":1,"orig":"Phosphoricum acidum"},{"label":"Phellandrium aquaticum","short":"Phellandrium aquaticum","group":"Arzneimittellehre","paras":[{"t":"Phellandrium aquaticum, Wasserfenchel. Katarrhe. Übelriechender Auswurf und Husten bei Lungenkrankheiten wie Bronchitis, Emphysem, Tuberkulose des Mittellappens; mit Atemnot und Dauerhusten früh morgens; zwingt zum Aufsitzen. Heiserkeit."},{"t":"Alles schmeckt süß. Hämoptyse."},{"t":"Gefühl eines Gewichtes auf dem Scheitel; Schmerzen und Brennen in den Schläfen und über den Augen. Zerquetschungsgefühl im Scheitel."},{"t":"Schwindel beim Hinlegen."},{"t":"Schmerz in den Milchgängen; unerträglich beim Stillen. Schmerz in Brustwarzen."},{"t":"Stechender Schmerz durch die rechte Brust strahlt nach hinten aus, zum Rücken, nach den Schultern."},{"t":"Verlangen: Saures; Milch; Bier."},{"t":"Abneigung: Wasser."},{"t":"Amel.: Stillen."}],"rem":1,"orig":"Phellandrium aquaticum"},{"label":"Phosphorus","short":"Phosphorus","group":"Arzneimittellehre","paras":[{"t":"Phosphorus, gelber Phosphor. Durchdringung. Hochgewachsen, schlank, hell, rot/blond."},{"t":"Zart, Überempfindlichkeit gegen geistige Beanspruchung, gegen alle Sinneseindrücke. Erregbarkeit, dadurch Hitzegefühl. Unruhig, zappelig."},{"t":"Lernschwierigkeiten durch Ablenkung. Gerne in Gesellschaft, wird gerne umarmt, geküßt, massiert. Nach wenig Schlaf erholt. Geistig beweglich, nimmt schnell auf, aber rasch erschöpft und dann von mangelnder Konzentration. Lebhafte Sexualität. Jähzornig, boshaft, nachtragend. Trostlosigkeit, lebensmüde, düstere Vorahnungen. Hellsehen."},{"t":"Ängste: um das Wohl nahestehender Menschen; Dunkelheit; Alleinsein; Gewitter."},{"t":"Große Schwäche und völlige Leere in Kopf, Brust, Magen, Abdomen."},{"t":"Blutungsneigung: Nase, Menorrhagie, Magen/Darm, Bluterbrechen, Teerstühle, Hämaturie. Diabetes."},{"t":"Verlangt Wärme am Körper, Kälte am Kopf. Blutandrang zum Kopf. Hitze von der Wirbelsäule. Schwindel mit Schwäche."},{"t":"Atrophie des Sehnervs; grüner Hof um Kerzenlicht, Buchstaben erscheinen rot. Taubheit für menschliche Stimme. Sehr schmerzhafte Kehle, trocken, rauh, wund, Agg.: Sprechen. Unterkiefernekrose."},{"t":"Husten durch Kitzeln im Rachen, Agg.: kalte Luft, Lesen, Lachen, Sprechen, Linksliegen. Enge, Beklemmung der Brust. Scharfe Stiche, Atmung beschleunigt, Hitze, Pneumonie. Sputum blutig. Halsschmerz beim Husten. Brennen zwischen Schulterblättern."},{"t":"Obstipation. Diarrhoe, herausschießend, als bliebe der Anus offen. In Schwangerschaft Übelkeit beim Anblick von Wasser."},{"t":"Erbrechen, sobald Wasser im Magen warm wird. Nächtlicher Hunger. Akute Hepatitis; Leberatrophie. Menses reichlich. Kribbeln und Taubheit der Fingerspitzen. Durst auf große Mengen kalten Wassers. Chorea vom schnellen Wachsen."},{"t":"Verlangen: kalte Getränke; Eiscreme; Salz; Fisch; Schokolade; Süß."},{"t":"Abneigung: Austern; Fisch; Ei; Fleisch; Obst; Kohlensäuregetränke."},{"t":"Agg.: Linksliegen; Kälte; warmes Essen; Wetterwechsel; Emotionen; Salz."},{"t":"Amel.: kurzer Schlaf; Magnetismus; Reiben; Essen; kaltes Essen, Getränke, Eiscreme bessert Magenschmerz; Baden."}],"rem":1,"orig":"Phosphorus"},{"label":"Physostigma venenosum","short":"Physostigma venenosum","group":"Arzneimittellehre","paras":[{"t":"Physostigma venenosum, Kalabarbohne (Alkaloid: Eserin). Akkommodationslähmung, Pupillen kontrahiert, Zucken der Augenmuskeln. Lagophthalmus. Mouches volantes. Lichtblitze. Glaukom. Zucken der Ziliarmuskeln mit Reizung nach Arbeit mit den Augen. Zunehmende Kurzsichtigkeit."},{"t":"Zucken der Nasenmuskeln. Wundheit der Zungenspitze. Herzflattern wird im Rachen gefühlt. Schmerz im rechten Kniekehlengebiet. Anfälle überwältigender Schläfrigkeit. Brennen und Vibrieren in der Wirbelsäule. Reizung des Rückenmarks, Verlust der Beweglichkeit. Rigidität mit Hirnhautreizung. Paralyse. Erschöpfung mit sehr empfindlichen Wirbeln. Taubheit in Händen und Füßen. Gliederzucken beim Einschlafen. Tetanie, Trismus,"},{"t":"Agg.: leichtester Luftzug. Motorische Ataxie. Taubheit in gelähmten Teilen, krampfartige Gliederschmerzen. Poliomyelitis. Chorea."},{"t":"Abneigung gegen Baden und Trinken von kaltem Wasser. Beschwerden durch Verletzungen."},{"t":"Agg.: Augenanstrengung; Erschütterung; Luftzug."},{"t":"Amel.: Augenschließen; erschöpfte Willenskraft; Schlaf."}],"rem":1,"orig":"Physostigma venenosum"},{"label":"Phytolacca decandra","short":"Phytolacca decandra","group":"Arzneimittellehre","paras":[{"t":"Phytolacca decandra, Kermesbeere. Bindegewebe, Drüsen, Tonsillen. Rheumatische Schmerzen, Agg.: morgens. Plötzliche Schmerzen, schießend, lanzinierend, wie elektrische Schockwellen, rasch den Ort wechselnd (Puls; Kali-bi.). Schmerz rechte Schulter, unfähig, den Arm zu bewegen. Syphilitischer Ischias; Ischias rechts, strahlt zur Unterseite der Oberschenkel aus; Fersenschmerz,"},{"t":"Amel.: Heben der Füße. Füße geschwollen, Schmerz in Knöcheln und Füßen. Neuralgie in Zehen."},{"t":"Allgemeine Wundheit, Kopfschmerz, Rückenschmerz, Agg.: Bewegung, muß sich aber bewegen. Schmerzen am Sehnenansatz. Neigung, sich hinzulegen."},{"t":"Zahnende Kinder haben unwiderstehliches Verlangen, Zahnfleisch zusammenzupressen (Podo). Kinn auf Sternum gezogen. Rote Zungenspitze."},{"t":"Schmerzen, Erschöpfung, Ruhelosigkeit. Gleichgültigkeit, ist sicher, daß er sterben muß; lehnt Nahrung ab; schamlos. Geschäften abgeneigt."},{"t":"Reichlicher, heißer Tränenfluß."},{"t":"Schmerz an Zungenwurzel, zum Ohr ausstrahlend. Parotitis, Mumps. Angina. Trockenheit. Enges, sehr heißes Gefühl wie glühende Kohle im Hals, geschwollene Mandeln (rechts) und Rachenring, Klumpengefühl mit Schluckzwang; dunkelrot/bläulichrot, Agg.: Schlucken, warme Getränke; Amel.: kalte Getränke (Lach.); in Ohren einschießend."},{"t":"Urin unterdrückt mit Nierenschmerz. Schmerz entlang Perineum zum Penis."},{"t":"Mammae hart, sehr empfindlich. Zysten in den Mammae. Galaktorrhoe. Schmerz beim Stillen, der sich über den Körper ausbreitet. Jede Erregung/Streß geht auf die Brüste. Abszeß der Brust, Fisteln. Fissuren, Ulzera der Brustwarzen. Schmerz vom Herzen in den rechten Arm. Taubheit rechter Arm. Vergrößerte Halslymphknoten; Nackensteifigkeit. Furunkel; venerische Bubonen. Psoriasis."},{"t":"Verlangen: warme Getränke (Mastitis)."},{"t":"Agg.: feuchtkaltes Wetter, Regen; Bewegung; nachts; heiße Getränke; Elektrizitätsänderung der Atmosphäre; rechts."},{"t":"Amel.: trockenwarmes Wetter; kalte Getränke; Ruhe."}],"rem":1,"orig":"Phytolacca decandra"},{"label":"Picricum acidum","short":"Picricum acidum","group":"Arzneimittellehre","paras":[{"t":"Pikrinsäure. Nervöse Erschöpfung (Kali-p.). Überanstrengung des Geistes, geistige Müdigkeit, will nicht denken, \"es ist, als ob mein Geist seit Urzeiten arbeitet\". Sitzt still und teilnahmslos. Geistig ermüdete, unter Druck stehende Studenten, schon nach 15 Min. studieren erschöpft; onaniert dann, fühlt sich danach nicht besser. Abneigung gegen Bücher."},{"t":"Geisteskrankheit; emotional qualvoller Zustand mit großer Angst, daß etwas passiert, Trost hilft nicht; Rette-mich-Blick, \"ich gebe auf\"."},{"t":"Brennen entlang der Wirbelsäule (Kali-p.) mit großer Schwäche; Rückenmarkserweichung (Phos.; Zinc.)."},{"t":"Kopfschmerz Hinterkopf- und Halsgegend (Nat-m.; Sil.), Agg.: Bewegung, geistige Anstrengung, Amel.: festes Bandagieren. Schwindel und Geräusche in den Ohren. Furunkel in Ohren und am Nacken. Müdes, schweres Gefühl über ganzen Körper, besonders Extremitäten."},{"t":"Priapismus mit Rückenmarkserkrankung, heftige Erektionen. Pollutionen."},{"t":"Urin spärlich, Anurie, Nierenentzündung."},{"t":"Füße kalt, können nicht warm werden. Akute, aufsteigende Paralyse."},{"t":"Beine weit auseinander beim Stehen. Schreibkrämpfe."},{"t":"Agg.: warmes Wetter; geistige Anstrengung."},{"t":"Amel.: kalte Luft; festes Bandagieren."}],"rem":1,"orig":"Picricum acidum"},{"label":"Piper methysticum","short":"Piper methysticum","group":"Arzneimittellehre","paras":[{"t":"Piper methysticum, Kava-Kava, Rauschpfeffer. Exaltiert, lebhaft, mit Verlangen nach Unterhaltung; kann arbeiten ohne zu ermüden. Alle Symptome werden besser durch Ablenkung. Ruhelosigkeit, möchte ständig die Lage wechseln. Gefühl wie vergiftet."},{"t":"Arthritis deformans. Haut: weiße Flecken; Lepra; Ichthyosis."},{"t":"Amel.: Beschäftigung."}],"rem":1,"orig":"Piper methysticum"},{"label":"Plantago major","short":"Plantago major","group":"Arzneimittellehre","paras":[{"t":"Plantago major, Breitblättriger oder Großer Wegerich. Neuralgische Schmerzen Ohr, Zähne, Gesicht. Schmerz von einem Ohr zum anderen durch den Kopf. Ohrschmerz mit Zahnschmerz. Schmerz wandert zwischen Zähnen und Ohren. Periodische Trigeminusneuralgie von 7-14 Uhr, dabei Tränenfluß und Lichtscheu."},{"t":"Zahnschmerz, Agg.: Kaltes, Warmes, Berührung, Amel.: Essen. Alveolar-Pyorrhoe."},{"t":"Schwellung der Wangen. Speichelfluß."},{"t":"Augenschmerz als Reflexschmerz von schlechten Zähnen oder Mittelohrentzündung. Reflexneuralgie der Augenlider. Augapfel sehr berührungsempfindlich."},{"t":"Große Mengen blassen Urins nachts mit Durst. Enuresis nocturna."},{"t":"Depression und Schlaflosigkeit bei Rauchern. Verursacht Widerwillen gegen Tabak."},{"t":"Hautjucken, Brennen, Papeln, Urtikaria, Frostblasen."}],"rem":1,"orig":"Plantago major"},{"label":"Platinum metallicum","short":"Platinum metallicum","group":"Arzneimittellehre","paras":[{"t":"Platina, Platin. Hochmut, Verachtung. Blond. Sonnenbrille. Gesteigertes sexuelles Verlangen. Verführerisch. Impuls (Ehemann/Kind) zu töten beim Anblick eines Messers. Hysterische Stimmungsschwankungen. Fürchterliche Ängste: Tiere, Tod, um Gesundheit, vor Herzkrankheit, Apoplexie. Depressionen mit Suizidneigung. Sinnestäuschungen am Körper. Gefühl, daß Teile ihres Körpers an Größe zugenommen hätten, Gegenstände geschrumpft sind. Erwacht nachts mit Gefühl fremder Umgebung. Gefühl der Taubheit um den (sinnlichen) Mund; Fazialisparese. Überempfindliche, schmerzhafte Genitalien, kann Tampon/Binde nicht ertragen. wollüstige Uteruskrämpfe, Abortgefahr. Vaginismus. Schmerz bei Koitus. Nymphomanie. Masturbation bei Kindern. Zysten, Tumoren der Ovarien und Hoden. Schläft und Sitzt mit gespreizten Beinen. Schmerzen nehmen allmählich zu und wieder ab. Schmerz mit Taubheit. Bandagiertes Gefühl. Kälte, Taubheit einzelner Teile. Klebrige Absonderungen. Körperliche Symptome wechseln mit Gemütssymptomen ab."},{"t":"Agg.: Gefühlserregung; Berührung; nervöse Erschöpfung."},{"t":"Zunächst romantische Vorstellung, sexuelle Phantasien. 7-9 j. Mädchen/Jungen onanieren (Orig. 3-6 J.); sexueller Kontakt mit 12-14 J. Aura von Sinnlichkeit, \"wird verführt\", nimmt dadurch aber keinen seelischen Schaden. Phantasiereich und idealistisch; achtet sehr auf Kleidung, Meinung anderer sehr wichtig, braucht Schmeicheleien. Gefühle und sexuelles Verlangen soll befriedigt werden. Läßt sich kaum verwirklichen, von Realität enttäuscht."},{"t":"Exzessiver Männerkonsum, Perversionen aller Art. Sehnt sich nach jemandem, der ihre Perversionen aushält, auf den sie sich verlassen kann. Kummer, Frust, Abscheu sich selbst gegenüber; innere Qual durch starken Trieb. Übersteigertes Ich, Größenwahn. Zwang, die erste sein zu müssen,"},{"t":"\"ich bin schön und zweifle nicht an meiner Schönheit\", Arroganz, Hochmut, Stolz völlig ungerechtfertigt. Verachtung für die Welt."},{"t":"Gefühl, sie hat mehr von sich (Liebe) als alle anderen gegeben, nicht geschaffen für diese Welt."},{"t":"Später, falls Trieb unterdrückt: bissig, verdrießlich, scharfzüngig. Grübelei und Depression, Suizidgedanken; schließlich echte Geisteskrankheit: Größenwahn oder aggressive erotische Manie; aktiv aggressiver Sex mit Fremden (Tarent.)."}],"rem":1,"orig":"Platinum metallicum"},{"label":"Plumbum metallicum","short":"Plumbum metallicum","group":"Arzneimittellehre","paras":[{"t":"Plumbum met., Blei. Allgemeine Sklerose. Bleiparalyse. Anämie. Ikterus. Äußerlich selbstzufrieden, hager, Furchen im Gesicht, fettig glänzend, leichenblaß, eingefallen. \"Gutes Leben\", Besitzgier, Egoismus. Furcht, vergiftet, ermordet zu werden."},{"t":"Allmähliche Krankheitsentwicklung Wahrnehmung und Ausdruck lassen nach, Gedächtnis, Wortschatz schlechter. Antwortet sehr langsam, sehr angestrengt (Phos. Leere im Kopf; Merc. Zerstreutheit). Apathie; zorniger Impuls, sich Messer in Leib zu stoßen, selbstzerstörerisch und pervers. Reiz des Verbotenen, Spieler, braucht Nervenkitzel, um Apathie zu bekämpfen. Kolik, krampfhafte Schmerzen, abwechselnd mit Delirium."},{"t":"Blaue Linie am Zahnfleischrand. Bleifarbener Saum der Zahnleisten. Nächtliche Empfindung im Bauch veranlaßt zu stundenlangem heft. Strecken. Muskelatrophie durch Sklerose des Spinalsystems. Parkinson; Schwäche; Spastik; Zittern; lokomotorische Ataxie; multiple Sklerose; Fallhand; amyotrophe Lateralsklerose; Lähmung von Blase (Harnverhalt) und Rektum (Obstipation mit Schafkotstuhl). Gicht."},{"t":"Brightsche Krankheit: chronische interstitielle Nephritis, Kolik, Kahnbauch, Abmagerung, Schwäche, Schrumpfniere."},{"t":"Schmerz in rechte Großzehe, Agg.: nachts, Berührung. Verdickte Sehnen. Dupuytren. Trockene Haut. Fehlender Schweiß."},{"t":"Herzklopfen in Linksseitenlage (Phos.; Lach.), Amel.: Reiben, Massage. Gefühl, als würde Bauchdecke (Nabel, Magen, Brust) an Schnur zum Rückgrat gezogen. Darm-/Nierenkoliken, zu allen Körperteilen ausstrahlend. Schmerzhafter Tenesmus ani. Vaginismus. Stinkender Fußschweiß (Sil.). Verhärtete Brustdrüse. Links unten, rechts oben."},{"t":"Übermäßige, schnelle Abmagerung. Marasmus kleiner Kinder."},{"t":"Agg.: Erschöpfung; Bewegung; Nacht; klares Wetter."},{"t":"Amel.: Reiben; fester Druck; Sichkrümmen."},{"t":"Differentialdiagnose: Alumina: Lähmung schlimmer, schlaff, untere Extremitäten, bei Plb. spastisch, obere Extremitäten."}],"rem":1,"orig":"Plumbum metallicum"},{"label":"Podophyllum peltatum","short":"Podophyllum peltatum","group":"Arzneimittellehre","paras":[{"t":"Podophyllum peltatum, Entenfuß. Schwäche und Sinken im Abdomen, nach Geburt, nach Durchfall. Rektumprolaps. Leber schmerzhaft, Amel.: Reiben. Geschwätzigkeit im Fieber. Einbildung, sehr krank zu sein und sterben zu müssen (Ars.)."},{"t":"Kopfschmerz abwechselnd mit Durchfall (Aloe). Kopfschmerz im Winter, Diarrhoe im Sommer."},{"t":"Rollen des Kopfes von Seite zu Seite. Gesicht rot und heiß bei Durchfall. Verlangen, Zahnfleisch aufeinanderzupressen (Phyt.)."},{"t":"Zunge breit, groß, brennend. Speichelfluß."},{"t":"Kann nur auf dem Bauch liegen. Schwangerschaftserbrechen. Abneigung gegen Essensgeruch."},{"t":"Bauchschmerz, Agg.: Krümmen, Druck. Gastroenteritis mit Kolikschmerz und galligem Erbrechen. Schmerzloser Brechdurchfall. Cholera infantum."},{"t":"Durchfall früh morgens (4-5 Uhr); beim Zahnen, mit heißen, glühenden Wangen, beim Baden oder Waschen; bei heißem Wetter, nach sauren Früchten. Schmerzlos, Grün, wässerig, stinkend, reichlich, spritzend über gesamte Kloschüssel und daneben. Kolitis mit Durchfall (Hauptmittel), Leberbeteiligung. Verstopfung wechselnd mit Durchfall (Ant-c.). Rektumkarzinom."},{"t":"Hämorrhoiden, Analprolaps, auch in Schwangerschaft."},{"t":"Uterusprolaps. Schmerz rechtes Ovar mit wandernden Geräuschen am aufsteigendem Kolon entlang. Zyste des rechten Ovars. Menorrhagie durch vergrößerten Uterus. Schwellung der Schamlippen bei Schwangerschaft."},{"t":"Stöhnen im Schlaf. Durst auf große Mengen kalten Wassers (Bry.)."},{"t":"Verlangen: Saures."},{"t":"Agg.: früher Morgen; saure Früchte; heißes Wetter; Zahnung; Essen; Rechts."},{"t":"Amel.: Reiben der Leber; Liegen auf dem Bauch."}],"rem":1,"orig":"Podophyllum peltatum"},{"label":"Prunus spinosa","short":"Prunus spinosa","group":"Arzneimittellehre","paras":[{"t":"Prunus spinosa, Schlehdorn. Neuralgien von Auge, Kopf und Harnorganen. Schmerzen berstend, nach außen drückend, schießend. Ziliarneuralgie. Berstender Schmerz im rechten Augapfel, blitzartig durch das Gehirn schießend zum Hinterkopf. Plötzlicher Schmerz im linken Auge, als ob es platze, Amel.: Tränenfluß. Iridochorioiditis. Glaskörpertrübung."},{"t":"Einschießender Kopfschmerz aus dem rechten Stirnknochen durch das Gehirn zum Hinterkopf."},{"t":"Plötzlicher Harndrang mit Krämpfen und Schmerzen. Urin scheint bis zur Eichel zu gehen, dann zurückzukehren und verursacht Schmerz in Urethra. Neuralgische Dysurie. Muß lange pressen, bis Urin kommt."},{"t":"Brustbeklemmung, pfeifende Atmung beim Gehen. Angina pectoris, wildes Herzklopfen, Agg.: leichteste Bewegung."}],"rem":1,"orig":"Prunus spinosa"},{"label":"Psorinum","short":"Psorinum","group":"Arzneimittellehre","paras":[{"t":"Psorinum, Krätzenosode. Juckreiz. Zerfall. Psora: ruhelos, nervös, schreckhaft. Körper riecht schmutzig. Alle Ausscheidungen stinken ekelhaft wie verwestes Fleisch (Arn. faule Eier). Juckreiz, muß kratzen, bis es blutet. Juckreiz unter der Haut, kann durch kratzen nicht erreicht werden. Ganzer Körper innerlich entzündet."},{"t":"Sehr frostig, Pelzmütze im Sommer."},{"t":"Ruhelosigkeit, findet keine bequeme Position."},{"t":"Angst als Folge unterdrückter Ausschläge. Angst vor schlimmen Ereignissen. Hoffnungslosigkeit; Verzweiflung wegen Juckreiz; an Genesung; Selbstmitleid; Seelenqual; fürchtet den Tod aber ständig Suizidgedanken; trotz Wohlstand Furcht vor Verarmung; Unsicherheit. Deprimiert durch kleinsten Fehlschlag. Erfolgreicher Geschäftsmann."},{"t":"Ausschläge feucht, eiternd, juckend, Agg.: Bettwärme, Wolle; um die Nägel, am Ohr, Gesicht, Gelenkbeugen. Haut schmutzig, ölig aussehend."},{"t":"Hautausschläge heilen nicht, breiten sich langsam, aber stetig aus. Absonderungen aus den Ohren, faulig stinkend und Juckreiz (immer). Schwäche, besonders Beine, möchte nach Hause, sich hinlegen."},{"t":"Akute Bronchitis mit Frost bei Fieber; dampft, stinkt, schmutzig (Sulph.). Dyspnoe, Amel.: Liegen auf dem Rücken, Arme weit gespreizt."},{"t":"Kopfschmerz vom geringsten Luftzug; mit Sehstörungen; möchte Kopf einwickeln, Hut im Sommer, Amel.: Essen. Heuschnupfen. Nächtlicher Hunger, bei Kopfschmerz."},{"t":"Stuhl schleimig, blutig, stinkend."},{"t":"Kinder tagsüber gut zu haben, schreien die ganze Nacht. Ruhelos vor Gewitter."},{"t":"Klimakterium: starke Blutung und Dysmenorrhoe, meist kurz vor Menopause, Gefühl, heißes Wasser falle auf den Körper;"},{"t":"Abmagerung bei gutem Appetit. Stinkende Schweiße, Agg.: nachts. Dampfender Schweiß. Verlangen nach Wärme, die Juckreiz verursacht."},{"t":"Beschwerdefrei vor Attacke (Asthma, Migräne, etc.)."},{"t":"Verlangen: Bier; Saures."},{"t":"Abneigung: Schweinefleisch."},{"t":"Agg.: Kälte; Luftzug; Waschen; Unterdrückung; Wolle; Sturm; Bettwärme; Nachts."},{"t":"Amel.: Liegen in Kopftieflage; Starkes Schwitzen nach akuter Krankheit; Essen; 1-2 Tage vor akuter Erkrankung."}],"rem":1,"orig":"Psorinum"},{"label":"Ptelea trifoliata","short":"Ptelea trifoliata","group":"Arzneimittellehre","paras":[{"t":"Ptelea trifoliata, Lederbaum. Leber- und Magenbeschwerden mit Schweregefühl; nach Hepatitis. Unfähig zu geistiger Arbeit."},{"t":"Kopfschmerz von der Stirn zur Nasenwurzel, nach außen drückend."},{"t":"Speichelfluß mit bitterem Geschmack. Aufstoßen mit Geschmack fauler Eier. Leber wund und geschwollen, Agg.: Druck, Linksliegen, Amel.: Liegen auf der rechten Seite. Geschwollene Füße und Bein durch Leberkrankheit."},{"t":"Leber- und Magensymptome bei Gliederschmerzen."},{"t":"Asthma, Erstickungsgefühl beim Liegen auf dem Rücken."},{"t":"Abneigung: Butter; Fett. Kann den Anblick von Essen nicht ertragen."},{"t":"Agg.: Linksliegen; Käse; Fleisch; Pudding."},{"t":"Amel.: Essen saurer Speisen, Zitronen."}],"rem":1,"orig":"Ptelea trifoliata"},{"label":"Pulsatilla pratensis","short":"Pulsatilla pratensis","group":"Arzneimittellehre","paras":[{"t":"Pulsatilla pratensis, Anemone pulsatilla, Küchenschelle. Wechselhaftigkeit in Stimmung und Symptomen; Unentschlossenheit; Nachgiebigkeit. Kein starkes Ichgefühl, formt sich nach Wünschen anderer. Weint leicht. Verlangen nach Trost und Aufmerksamkeit. Selbstmitleid, fühlt sich verlassen. Unaufgelegt, ohne Grund schlecht gelaunt; äußerst ärgerlich; besitzergreifend; eifersüchtig; Grübeln. Ablösung von Zuhause schwierig; Leiden seit Pubertät."},{"t":"Furcht in geschlossenen Räumen, Gefühl zu ersticken. Furcht vor der Dunkelheit, vor anderem Geschlecht."},{"t":"Kopfschmerz beginnt rechte Schläfe, Tränenfluß; Schulkopfschmerz. Nasenbluten. Dicke, gelbgrüne Absonderungen aus Auge, Nase, Ohr. Heuschnupfen. Chronisch verstopfte Nase."},{"t":"Als ob Trommelfell beim Niesen platzt."},{"t":"Schweiß riecht süßlich, Speichel süßlich. Mumps befällt Mamma oder Hoden."},{"t":"Asthma. Trockener Husten abends/nachts, morgens locker. Mundtrockenheit morgens ohne Durst. Zunge weiß belegt, Bläschen auf -spitze, als ob verbrüht. Als ob Wurm aus dem Hals kriecht."},{"t":"Kinder haben Angst, nach oben zu schauen. Kreislauf leicht erregbar, Erröten. Erschlafft in der Wärme, kann Sonne nur in Bewegung ertragen; kommt vor Hitze um, erträgt keine Sauna (Lach.; Apis). Heiße Füße, deckt sie auf. Mag Kaltes; als ob kaltes Wasser über Rücken gegossen wird. Durstlosigkeit; Fettunverträglichkeit. Keine zwei Stühle gleich."},{"t":"Muttertyp, wird gerne massiert; großes sexuelles Verlangen. Zystitis mit Brennen der Urethra, verminderter Drang, Agg.: Hinlegen. Verliert Urin beim Husten."},{"t":"Amenorrhoe; Dysmenorrhoe; Menses spärlich, unterbrochener Fluß, veränderlich, verzögert. Orchitis, Schmerz vom Bauch zum Hoden. Prostatitis."},{"t":"Durchfall nachts, stark wechselnd, von Obst, Kaltem, Eiscreme."},{"t":"Schwindel im Klimakterium (Hauptmittel), Gewichtszunahme, Lumbago."},{"t":"Schmerzen ziehend, reißend, unstet, schnell wechselnd von einem Körperteil zum anderen, begleitet von starkem Frösteln; Schmerz kommt plötzlich, vergeht allmählich oder umgekehrt. Ischias, Amel.: Umhergehen."},{"t":"Verlangen: Käse; Eiscreme; Saures; Pikant; Hering; Kartoffeln."},{"t":"Abneigung: Fett; Schweinefleisch; Butter; warmes Essen/Getränke; Buttercreme."},{"t":"Agg.: Fett; kalte Füße; warmes Zimmer; Abends; chronisch Hitze, akut Kälte; Alkohol; Wetterwechsel; Lagewechsel; Zwielicht."},{"t":"Amel.: in kühlem Wasser; an der Küste; Bewegung an der frischen Luft; Weinen."}],"rem":1,"orig":"Pulsatilla pratensis"},{"label":"Pyrogenium","short":"Pyrogenium","group":"Arzneimittellehre","paras":[{"t":"Pyrogenium, Extrakt aus faulem Rindfleisch. Sepsis, Abszesse, Ulzera mit stark übelriechenden Absonderungen. Bett zu hart. Aufliegende Körperteile fühlen sich wund und zerschlagen an (Bapt.); schneller Dekubitus (Carb-ac.) Ruhelosigkeit, um an schmerzhaften Stellen Erleichterung zu haben."},{"t":"Zunge sauber, glatt, wie lackiert, feuerrot, trocken, rissig, schwierige Artikulation. Eitriger, übler Geschmack. Kaffeesatzartiges Erbrechen, kotartig bei Ileus (Op.; Plb.)."},{"t":"Stinkender Durchfall (Psor.), schmerzlos, unfreiwillig bei Flatus. Obstipation hartnäckig bei Ileus, Fieber (Op.)."},{"t":"Stuhl massig, schwarz, aashaft, kleine schwarze Bällchen wie Oliven (Op.; Plb.). Fetus seit Tagen tot im Uterus. Puerperalfieber."},{"t":"Der Kranke spürt deutlich sein Herz, Pochen hindert am Schlaf. Herzschwäche nach sept. Zuständen. Rascher Puls, unangemessen im Verhältnis zur Temperatur. Frost beginnt im Rücken zwischen Schulterblättern, spürt Frost in den Knochen. Septisches Fieber, sehr hoch, Puls schnell, klein, drahtig. Auf Schwitzen kein Temperaturabfall. Durst auf kleine Mengen kaltes Wasser, das jedoch zurückgewiesen wird."},{"t":"Fokusprovokation bei latent fiebererzeugenden Prozessen."}],"rem":1,"orig":"Pyrogenium"},{"label":"Radium bromatum","short":"Radium bromatum","group":"Arzneimittellehre","paras":[{"t":"Bestrahlungsfolgen. Rheuma, Gicht, schwere, anhaltende Schmerzen,"},{"t":"Agg.: nachts, verlagernd, zwingen zur Bewegung; Ruhelosigkeit. Gelenkschmerzen, Arthritis. Gefühl von Härte und Brüchigkeit der Knochen. Schweregefühl."},{"t":"Trockene, brennende Hitze über den ganzen Körper; Verlangen nach frischer Luft. Furcht vor dem Alleinsein, Dunkelheit, Angst um andere; großes Verlangen nach Gesellschaft. Geschwätzig."},{"t":"Kopfschmerz über dem rechten Auge, zum Scheitel und Hinterkopf ausstrahlend,"},{"t":"Amel.: Wärme. Metallischer Geschmack; Brennen der Zungenspitze. Leeres, absinkendes Gefühl im Magen. Bauchbeschwerden abwechselnd mit Brust- und Ohrsymptomen. Blähungskolik, Amel.: Krümmen, nach Stuhlgang. Pruritus ani. Juckreiz der Genitalien. Andauernder Husten durch Kitzelreiz im Halsgrübchen. Lumbosakraler Knochenschmerz, Agg.: Stufensteigen, Winter; chronisch; zu den Hüften ausstrahlend, nicht gebessert durch Druck oder Hitze. Dermatitis. Brennende, juckende Haut. Entfernt kleine Naevi, Muttermale. Träume von Feuer."},{"t":"Verlangen: Schweinefleisch. Abneigung: Süßigkeiten; Eiscreme."},{"t":"Agg.: nachts; Tabak; Rasieren; Bewegung."},{"t":"Amel.: heißes Bad; frische Luft; fortgesetzte Bewegung."}],"rem":1,"orig":"Radium bromatum"},{"label":"Ranunculus bulbosus","short":"Ranunculus bulbosus","group":"Arzneimittellehre","paras":[{"t":"Ranunculus bulbosus, Knollenhahnenfuß. Interkostalneuralgie. Neuralgie nach Zoster. Folgen von Alkoholismus wie krampfhafter Schluckauf, Delirium tremens. Linksseitig."},{"t":"Schmerz im Rücken zwischen Schulterblatt und Wirbelsäule (Puls.), Brennen kleiner Stellen durch kleine Bewegungen wie Nähen, Klavierspielen."},{"t":"Unzufrieden; leicht beleidigt; reserviert. Schwäche führt zu Ängsten: Zukunft; Gesundheit; Herzkrankheit; Geister; Agg.: abends, alleine."},{"t":"Spürt Angst im Thorax. Mangel an Selbstvertrauen. Empfindsam, ordnungsliebend; Tagblindheit. Herpes corneae. Lichtscheu, Tränenfluß. Gicht. Plötzliches, brennendes Stechen in rechter Großzehe. Bohrende Schmerzen, Agg.: Herabhängenlassen der Füße. Bauch empfindlich auf Druck."},{"t":"Bronchitis, Pneumonie mit Druck auf der Brust; kalte Stellen Schmerz beim tiefen Einatmen (Bry.), Agg.: Gehen an frischer Luft, Kälte, Zugluft. Schmerz entlang Unterrand des Schulterblatts (links). Pleuritis (links). Schmerz linke Schulter, wenn Rhus-t. versagt hat. Brennende, juckende Haut, Agg.: Kontakt. Fingerspitzen und Handflächen rissig. Blasenartiger, pustulöser Ausschlag in Handflächen."},{"t":"Thorax wund, wie zerschlagen,"},{"t":"Agg.: Kälte; Berührung; Abend; Bewegung und Drehen (Bry); nasses, stürmisches Wetter; Liegen auf schmerzhafter Seite; Druck; Alkohol."},{"t":"Amel.: Ruhe; Wärme."},{"t":"Unterwürfiger Respekt von bescheidener und höflicher Person, die aber ebenso behandelt werden möchte. \"Fühle mich unwohl, kann Verantwortung nicht übernehmen\", lehnt Beförderung ab. Wirkt hypochondrisch. Verwirrung, Benommenheit, verhält sich immer korrekt: in Öffentlichkeit, zu Hause, im Bett. Trägt Korrektheit zur Schau."},{"t":"Im Kopf verwirrt wie vom Wein."},{"t":"Heftiges sexuelles Verlangen, drückt es aber nicht aus."},{"t":"Zwang zu beten, sucht Hilfe Gottes (Aur.), Tadelsucht, will im Zornausbruch sein Kind auf den Boden schleudern (Nux-v.; Ars.)."},{"t":"Differentialdiagnose: Ars.: kommt wie Ars. mit Zettel, aber Ars.-Ruhelosigkeit fehlt."},{"t":"Differentialdiagnose: Rhus-t.: ob. Schulterblattwinkel links, Übergang Halswirbelsäule / Brustwirbelsäule, Rhus-Ruhelosigkeit fehlt."}],"rem":1,"orig":"Ranunculus bulbosus"},{"label":"Ranunculus sceleratus","short":"Ranunculus sceleratus","group":"Arzneimittellehre","paras":[{"t":"Ranunculus scleratus, Gifthahnenfuß. Bohrende, nagende Schmerzen, Agg.: abends vor Mitternacht. Ohnmacht mit Magenschmerz. Vesikuläre Ausschläge mit"},{"t":"großen Blasen; scharfe Exsudation, macht die Umgebung wund. Pemphigus."},{"t":"Indolenz; Abneigung gegen geistige Beschäftigung."},{"t":"Nagende Schmerzen an einer Stelle links vom Scheitel."},{"t":"Landkartenzunge. Brennen und Rauheit der Zunge."},{"t":"Schmerz über der Lebergegend mit Gefühl, als ob Durchfall einsetzen würde. Stiche in Thoraxmuskeln. Wundes Brennen hinter den Schwertfortsatzknorpeln. Kloßartiger Druck hinter den rechten falschen Rippen, Agg.: tiefes Einatmen."},{"t":"Hühneraugen mit Brennen und Schmerzhaftigkeit, besonders bei herabhängenden Füßen. Gicht in Fingern und Zehen. Plötzliche Stiche in rechter Großzehe."},{"t":"Ängstliche Träume: Leichen, Schlangen, Schlachten."},{"t":"Agg.: abends."},{"t":"Amel.: nach Mitternacht."}],"rem":1,"orig":"Ranunculus sceleratus"},{"label":"Raphanus sativus","short":"Raphanus sativus","group":"Arzneimittellehre","paras":[{"t":"Raphanus sativus, schwarzer Rettich. Hysterie; Globusgefühl, als ob ein Ball vom Uterus zum Hals aufsteigt, dort anhaltend. Hitze und Brennen im Rachen. Nymphomanie. Traurigkeit, Abneigung gegen Kinder, besonders Mädchen. Ödem der Unterlider. Schleim retronasal."},{"t":"Taubheit an wechselnden Stellen."},{"t":"Brennen im Magen, danach heißes Aufstoßen, übelriechend. Würgen und Erbrechen, Appetitlosigkeit, Auftreibung, tympanitisch, hart."},{"t":"Stiche in Leber und Milz. Vermehrt Gallen- und Speichelsekretion."},{"t":"Starke Blähungsbildung und festgesetzte Blähung. Keine Blähung geht nach oben oder unten ab. Postoperative Blähungsschmerzen."},{"t":"Stühle flüssig, schaumig, reichlich, braun mit Kolik und polsterartiger Schwellung der Eingeweide. Koterbrechen."},{"t":"Urin dick wie Milch, reichlich, trübe mit hefeartigem Sediment."},{"t":"Kälte eines Fußes."},{"t":"Sexuell bedingte Schlaflosigkeit (Kali-br.)."},{"t":"Kombination: Blähungskolik und Hypersexualität, Nymphomanie."}],"rem":1,"orig":"Raphanus sativus"},{"label":"Ratanhia peruviana","short":"Ratanhia peruviana","group":"Arzneimittellehre","paras":[{"t":"Ratanhie. Unendlich starker Schmerz am Anus nach Stuhlgang, stundenlang anhaltend, vermeidet deshalb Stuhlgang solange wie möglich. Rektum schmerzt, als ob es voll wäre von Glasscherben. Proktitis. Trockene Hitze am Anus mit plötzlichen messerstichartigen Schnitten. Zusammenschnürungsgefühl. Stuhlentleerung mit großer Anstrengung, Hämorrhoiden. Analfissuren mit starker Einschnürung, wie Feuer brennend, zeitweilig Amel.: kaltes Wasser. Harter Stuhl. Stinkender, dünner Durchfall, brennend. Feuchtigkeit am Anus. Fadenwürmer (Santin.; Teucr.; Spig.). Jucken des Anus. Messerschnittartige Schmerzen im Magen."},{"t":"Kopfschmerz, Agg.: bei Stuhlgang, Bücken, vorgebeugt sitzend."},{"t":"Zahnschmerz, Agg.: nachts, in den ersten Schwangerschaftsmonaten. Gefühl, als ob kalte Luft aus den Zähnen strömt, Zähne wie verlängert, Agg.: Liegen."},{"t":"Heftiger Schluckauf. Risse in Brustwarzen. Fehlgeburten."},{"t":"Zwangsneurose. Zwanghafte Rituale, meist bezüglich der Pflege des Anus."},{"t":"Agg.: nachts; Angst; Hitze; Berührung; bei und nach hartem Stuhlgang."},{"t":"Amel.: heißes Bad; kaltes Bad; langsam gehen; still liegen."},{"t":"Rheum palmatum"},{"t":"palmatum, Medizinrhabarber. Kinder mit saurem, schleimigem, grünem, wundmachendem Durchfall; Agg.: abends; unreifes Obst."},{"t":"Schwierige Zahnung. Das ganze Kind riecht sauer, sogar nach dem Baden."},{"t":"Schreiende Kinder mit Stuhldrang und sauren Stühlen."},{"t":"Zahnung (Kreos.; Cham.). Ungeduldig und heftig; reizbar; kapriziös (Cina; Staph.); unaufgelegt zum Spielen. Appetit auf verschiedene Speisen, aber bald lustlos. Pulsieren in der Magengrube. Speichelfluß bei Kolik oder Durchfall."},{"t":"Kältegefühl in den Zähnen. Alles schmeckt bitter, sogar Süßigkeiten. Kolik mit Schreien, Amel.: Krümmen, Agg.: Aufdecken."},{"t":"Kalter Schweiß um Mund und Nase. Schweiß auf der behaarten Kopfhaut, dauernd und reichlich (Calc.; Sanic.). Purpura haemorrhagica. Bläschen."},{"t":"Ruheloser Schlaf mit Weinen. Eigenartige Schlafpositionen. Braucht nur sehr wenig Schlaf/Essen."},{"t":"Agg.: Zahnung; unreifes Obst; Sommer; Aufdecken."},{"t":"Amel.: Wärme."}],"rem":1,"orig":"Ratanhia peruviana"},{"label":"Rhododendron chrysanthum","short":"Rhododendron chrysanthum","group":"Arzneimittellehre","paras":[{"t":"Rhododendron ferrugineum, Rostblättrige Alpenrose. Sehr empfindlich auf atmosphärische Veränderungen, Agg.: vor Sturm und Gewitter. Gicht; rheumatische Beschwerden mit reißenden, wandernden, Schmerzen in allen Gliedern, Agg.: Ruhe, naßkaltes und windiges Wetter (Rhus-t.). Akute, entzündliche Schwellung der Gelenke, von einem Gelenk zum anderen wandernd, Agg.: nachts, in Ruhe, bei rauhem, stürmischem Wetter. Kann nicht schlafen, wenn er die Beine nicht übereinanderschlägt."},{"t":"Gicht mit fibröser Ablagerung im Großzehengelenk, erscheint wie Fußballenentzündung (Colch.; Led.)."},{"t":"Verwirrt; vergeßlich. Furcht vor Donner und Gewitter."},{"t":"Ziliarneuralgie, Augapfel, Augenhöhle und Kopf mitbetreffend, Amel.: Wärme, Essen."},{"t":"Zahnschmerz im Frühjahr und im Herbst, bei scharfem Westwind, Agg.: Wetterwechsel, Gewitter, windiges Wetter."},{"t":"Hydrozele. Verhärtete, geschwollene schmerzhafte Hoden, hochgezogen, links."},{"t":"Atemlos und sprachlos wegen heftiger Rippenfellschmerzen, die vorne in der Brust nach unten laufen."},{"t":"Agg.: vor Sturm; Wetterwechsel; Sommer; Nachts."},{"t":"Amel.: wenn Sturm nachläßt; Wärme; Sonne; Essen."}],"rem":1,"orig":"Rhododendron chrysanthum"},{"label":"Rhus toxicodendron","short":"Rhus toxicodendron","group":"Arzneimittellehre","paras":[{"t":"Rhus toxicodendron, Gifteiche. Steifigkeit: ganzer Körper, Gelenke, Kiefer; auch emotional, kann Gefühle nicht spontan äußern, aus Angst, verletzt zu werden. Fixe Ideen, jemanden umzubringen. Unfähig, sich zu entspannen. Abergläubisch. Grundloses Weinen. Geschäftig."},{"t":"Große Ruhelosigkeit, Angst (Unglück, vergiftet zu werden), Besorgnis (Acon.; Ars.); kann nicht im Bett bleiben, braucht häufigen Lagewechsel. Unruhe, auch im Schlaf. Halswirbelsäule empfindlich (steif und knackt). Reizbarkeit. Lähmung. Chorea nach Kälte und Nässe."},{"t":"Herpes-Hautausschläge mit Bläschen, Brennen, Stechen, Jucken, Amel.: heißes Wasser; mehr im Genitalbereich als Rhus-v.. Juckreiz nach Streß, Druck. Dermographismus (Hauptmittel). Erythrasma. Erysipel von links nach rechts."},{"t":"Schwindel mit Gefühl, nach hinten zu fallen, Agg.: Stehen, Gehen, Hinlegen, Aufstehen, Bücken."},{"t":"Kopfschmerz wie Schwappen des Gehirns, betäubend; wie zerrissen; von Bier."},{"t":"Folgen von Durchnässung (besonders nach Überhitzung); zu langem Baden."},{"t":"Schmerzen wie verrenkt, als ob ein Muskel abgerissen würde; als ob Knochen mit Messer geschabt würde, Agg.: nach Mitternacht; bei Regen."},{"t":"Lumbago nach Überheben (Hauptmittel), Amel.: Bewegung, Hartliegen."},{"t":"Kopfschweiß nachts. Rotes Dreieck auf Zungenspitze. Kieferknacken beim Kauen, leicht verrenkt. Bitterer Geschmack."},{"t":"Juckreiz und Schwellung des Skrotums. Äußere Genitalien ödematös."},{"t":"Asthma abwechselnd mit Ausschlägen. Trockener Husten, Agg.: Hand aus Bett strecken. Trockener, quälender Husten, vor und bei Schüttelfrost bei intermittierendem Fieber. Husten mit Geschmack von Blut."},{"t":"Angina pectoris, in den linken Arm ausstrahlend, linkes Schulterblatt (Hinterwandinfarkt). Herzklopfen, Agg.: Ruhe, Amel.: Bewegung; Folge von Überanstrengung."},{"t":"Träumt von großer Anstrengung."},{"t":"Großer Durst mit trockenem Mund, Zunge, Kehle."},{"t":"Diarrhoe mit großer Erschöpfung und Ischias bei Stuhlgang."},{"t":"Verlangen: Milch, Käse, Joghurt."},{"t":"Agg.: feuchtkaltes Wetter; Durchnässung; Wetterwechsel; Lärm; rechts; Erwachen (Steifheit und Schmerz); schwer Heben; Bewegungsbeginn."},{"t":"Amel.: Wärme; Trockenheit; sehr heißes Wasser; fortgesetzte Bewegung; Strecken; Lagewechsel; Reiben."}],"rem":1,"orig":"Rhus toxicodendron"},{"label":"Rhus venenata","short":"Rhus venenata","group":"Arzneimittellehre","paras":[{"t":"Rhus venenata, Giftesche. Große Melancholie, trübsinnig. Ohne Lebenslust."},{"t":"Schwerer Stirnkopfschmerz, Agg.: Gehen, Bücken. Augen stark verschwollen. Otitis mit Blasenbildung. Nase rot und glänzend, Gesicht geschwollen."},{"t":"Rote Zungenspitze, Riß in der Mitte, Blasen auf der Unterseite."},{"t":"Abdominalkoliken 4 Uhr mit reichlichen, wässerigen, weißlichen Stühlen, mühsam entleert. Schmerz im Unterbauch vor jedem Stuhlgang."},{"t":"Paralytisches Ziehen im rechten Arm, besonders im Handgelenk, bis in die Finger."},{"t":"Erysipel mit dunkelroter Haut. Blasen zwischen den Fingern; nach Kratzen brennende Absonderung. Erythema nodosum mit nächtlichen Schmerzen in den langen Knochen und Juckreiz."},{"t":"Bläschen dicht beieinander, kolonieartig, gefüllt mit wässeriger Flüssigkeit, Juckreiz, Stechen, Amel.: heißes Wasser v. auch Hände."},{"t":"Amel.: heißes Wasser, Baden."}],"rem":1,"orig":"Rhus venenata"},{"label":"Robinia pseudacacia","short":"Robinia pseudacacia","group":"Arzneimittellehre","paras":[{"t":"Robinia pseudacacia, Robinie. Hyperazidität. Stuhl und Schweiß sauer. Hyperchlorhydrie mit scharfem Aufstoßen. Saurer Geschmack. Scharfes, sehr saures, grünliches Erbrechen (Sulph-ac.)."},{"t":"Stirnkopfschmerz dumpf, pulsierend, Agg.: Bewegung, Lesen."},{"t":"Kopfschmerz mit Magenbeschwerden, saures Erbrechen."},{"t":"Starke Auftreibung von Magen und Darm. Blähungskolik (Cham.; Dios.). Festgesetzte Blähung."},{"t":"Brennen im Magen und zwischen den Schulterblättern, Agg.: nachts, im Liegen."},{"t":"Wundmachender Weißfluß. Zwischenblutungen. Herpes an Vulva und Vagina."},{"t":"Agg.: nachts; Essen; Fett; Kohl; Obst; Eiscreme."}],"rem":1,"orig":"Robinia pseudacacia"},{"label":"Rumex crispus","short":"Rumex crispus","group":"Arzneimittellehre","paras":[{"t":"Rumex crispus, Krauser Ampfer. Trockener, quälender, unaufhörlicher Husten, Agg.: geringstes Einatmen kalter Luft, abends nach dem Hinlegen, 23 Uhr, Sprechen, Aufdecken, Druck, Berührung der Halsgrube, von Kitzeln in Halsgrube, Linksliegen; verhindert Schlaf. Bedeckt den Kopf mit der Bettdecke, um die Luft anzuwärmen. Wenig oder kein Auswurf."},{"t":"Wundes Gefühl in Kehlkopf und Trachea beim Husten (Caust.)."},{"t":"Kitzeln in Halsgrube wie von einer Feder, Agg.: Druck. Klumpengefühl im Hals, nicht besser durch Schlucken. Absonderung von Nase und Trachea erst reichlich, dann zäh. Roher Schmerz unter Schlüsselbein, unter Brustbein."},{"t":"Unwillkürlicher Urinverlust beim Husten (Caust.; Puls.; Sil.)."},{"t":"Fleisch verursacht Aufstoßen und Juckreiz. Chronische Gastritis. Magenschmerz, in die Brust schießend, in Rachenhöhle ausstrahlend. Blähsucht. Husten und Durchfall treiben aus dem Bett, früh morgens."},{"t":"Juckreiz, Agg.: Aufdecken, Ausziehen; besonders untere Glieder. Ausschläge."},{"t":"Sehr empfindlich auf kalte Luft. Viele veränderliche Schmerzen, überall."},{"t":"Jede Erkältung betrifft die Gelenke."},{"t":"Agg.: Einatmen kalter Luft; Ausziehen; Temperaturwechsel; Sprechen."},{"t":"Amel.: Mund bedecken; warm einwickeln."},{"t":"Ruta graveolens"},{"t":"graveolens, Weinraute. Verletzung, Quetschung, Verstauchung, Fraktur, Dislokation von Knochen und Periost. Ablagerungen in Periost, Sehnen, Gelenken, besonders Handgelenken (Überbein; Schleimbeutel). Zerschlagenheit mit Lahmheit überall, wie nach einem Fall oder Stoß in Gliedern und Gelenken (Arn.). Aufliegende Körperteile schmerzhaft, wie zerschlagen (Bapt.; Pyrog.). Beugesehnen schmerzhaft; Dupuytren. Verkürzungsgefühl im M. gluteus maximus. Ischias, Agg.: Hinlegen. Beine geben nach beim Aufstehen vom Sessel. Schmerz in Achillessehne, Knöchel, Fußknochen. Rückenschmerz, Amel.: Liegen auf dem Rücken. Steißbeinverstauchung."},{"t":"Ruhelos, ständiger Lagewechsel."},{"t":"Augenanstrengung vom Studieren, Feinarbeit, verursacht Kopfschmerz. Augen rot, heiß wie Feuerbälle, schmerzhaft. Akkommodationsstörung."},{"t":"Karzinom im unteren Darm. Rektumprolaps sofort beim Entleerungversuch, beim geringsten Bücken."},{"t":"Agg.: Überanstrengung der Augen; Verletzung, Prellung, Verstauchung; Kälte; Liegen; Sitzen; nasses, kaltes Wetter; Druck an einer Kante."},{"t":"Amel.: Liegen auf dem Rücken; Wärme."},{"t":"Unzufrieden mit sich selbst und anderen; streitsüchtig. Meint, ständig hintergangen zu werden. Große Schwäche und Verzweiflung. Furcht vor dem Tod während Hitze. Angst, Agg.: 23 Uhr; Schuldgefühle. Lebensüberdruß. Gleichgültigkeit und Abneigung gegen geistige Arbeit."}],"rem":1,"orig":"Rumex crispus"},{"label":"Sabadilla","short":"Sabadilla","group":"Arzneimittellehre","paras":[{"t":"Sabadilla, Mexikanisches Läusekraut. Nervös, furchtsam. Seltsame Einbildungen über seinen Körper: sehr krank zu sein, daß Körperteile geschrumpft sind, schwanger zu sein bei Blähungen. Delirium bei intermittierendem Fieber (Podo.)."},{"t":"Niesanfälle, gefolgt von Tränenfluß; reichlicher, wässeriger Schnupfen; Gesicht heiß, brennende, rote Augenlider. Akuter Heuschnupfen (erstes Mittel) mit heftigem Niesen und Jucken. Nasenkatarrh mit Stirnkopfschmerz."},{"t":"Asthma mit Verlangen, das Gesicht kalt abzuwaschen."},{"t":"Wunder Hals nach Schnupfen; von links nach rechts, Agg.: Leerschlucken, Amel.: Heißtrinken. Gefühl einer locker hängenden Haut, die verschluckt werden muß; dauernder Schluckzwang. Chronischer Halsschmerz, Agg.: kalte Luft. Durstlos. Sodbrennen, vom Magen zur Halsgrube aufsteigend."},{"t":"Würmer bei Kindern (Cina; Sil.; Spig.). Zucken, krampfhaftes Zittern, Katalepsie; Nymphomanie, durch Würmer. Juckreiz am Anus."},{"t":"Menses zu spät, unterbrochen. Dicke, verformte, verhornte Nägel."},{"t":"Verlangen: heiße Dinge; Milch; Süßigkeiten; Mehlspeisen; Pudding."},{"t":"Abneigung: Fleisch; Saures; Kaffee; Knoblauch."},{"t":"Agg.: kalte Luft und Getränke; Gerüche; periodisch."},{"t":"Amel.: warmes Essen und Getränke; Gesicht kalt abwaschen."},{"t":"Sabal serrulata"},{"t":"serrulata, Sägepalme. Sexuelle und allgemeine Schwäche. Nervöse Frauen und alte Männer. Sexualneurotiker; unterdrückte und pervertierte Neigungen. Prostataerkrankungen. Mitleid macht wütend. Mattigkeit, Apathie, Gleichgültigkeit."},{"t":"Furcht vorm Einschlafen. Verwirrung."},{"t":"Iritis mit Prostatabeschwerden. Vergrößerte Prostata. Dauernder Harndrang nachts, Enuresis. Blasenschließmuskellähmung. Schwieriges Wasserlassen. Brennen in Harnröhre; Schmerz zu Beginn des Wasserlassens. Spermatorrhoe; verkümmerte Hoden. Epididymitis. Verlust der Sexualkraft. Koitus schmerzhaft beim Erguß. Kältegefühl in Genitalien."},{"t":"Ovarien vergrößert und schmerzhaft."},{"t":"Mammae schmerzhaft, unterentwickelt, eine kleiner als die andere."},{"t":"Lumbago, Agg.: Koitus. Kreuzschmerz vor der Periode."},{"t":"Aufstoßen und Hyperazidität."},{"t":"Verlangen: Milch."},{"t":"Agg.: feuchtes, kaltes, wolkiges Wetter; Mitleid."},{"t":"Amel.: nach Schlaf."}],"rem":1,"orig":"Sabadilla"},{"label":"Sabina","short":"Sabina","group":"Arzneimittellehre","paras":[{"t":"Juniperus sabina, Sadebaum. Chronische Frauenleiden; Arthritis; Fehlgeburten im 3. Monat. Kombination Epistaxis und Dysmenorrhoe."},{"t":"Musik unerträglich, verursacht Nervosität, geht durch Mark und Bein."},{"t":"Ziehende Kreuzschmerzen, vom Kreuzbein zur Schamgegend oder umgekehrt, beinahe bei jeder Krankheit. Uterusblutung nach Abort, Agg.: geringste Bewegung (Sec.), aber Amel.: Gehen. Plazentaretention. Starke Nachwehen."},{"t":"Entzündung von Ovarien oder Uterus nach Fehlgeburt oder vorzeit. Wehen."},{"t":"Menses: zu früh, zu reichlich, lange hinziehend, teils flüssig und hell, teils Klumpen wie kleine Leberstückchen."},{"t":"Dysmenorrhoe: Blutung stoßweise mit Kolik und wehenartigen Schmerzen, in Oberschenkel ausstrahlend. Zwischenblutungen mit sexueller Erregung (Ambr.). Menorrhagie im Klimakterium bei Frauen, die Fehlgeburten hatten. Hämorrhoiden."},{"t":"Sexuelles Verlangen bei beiden Geschlechtern verstärkt. Gefühl von etwas Lebendigem, wie Fötus, in Abdomen."},{"t":"Feigwarzen, juckend, brennend. Warzen, schwarze Poren in der Haut."},{"t":"Eitrige GO. Brennender, wunder Schmerz in Eichel und Vorhaut."},{"t":"Heftiges Pulsieren überall. Schmerz steigt schnell an, fällt langsam ab."},{"t":"Verlangen: Limonade."},{"t":"Agg.: nachts; Wärme; Musik; Schwangerschaft; Abort."},{"t":"Amel.: Kälte; frische Luft."}],"rem":1,"orig":"Sabina"},{"label":"Salicylicum acidum","short":"Salicylicum acidum","group":"Arzneimittellehre","paras":[{"t":"Salizylsäure. Rheumatismus, Magenstörungen und Morbus Menière.."},{"t":"Influenzafolgen: Erschöpfung, Retinitis, Albuminurie, Hämaturie."},{"t":"Schwindel mit Taubheit und Tendenz, nach links zu fallen. Dröhnen und Klingeln in den Ohren. Netzhautblutungen."},{"t":"Pharyngitis; Rachen wund, rot, geschwollen, Schlucken schwierig."},{"t":"Lippengeschwür, brennend; stinkender Atem. Blähsucht; heißes, saures Aufstoßen und Flatulenz. Dyspepsie mit Gärung. Zunge purpur, bleifarben."},{"t":"Eitriger, grünlicher Durchfall bei Kindern; wie grüner Froschlaich (Mag-c.). Pruritus ani."},{"t":"Akuter Rheumatismus, Agg.: Berührung, Bewegung. Reichlicher Schweiß. Schmerzen wandern. Ischias, brennender Schmerz, Agg.: nachts."},{"t":"Urtikaria, Amel.: Kratzen. Schweiß ohne Schlaf. Heiße, brennende Haut, Purpura. Zoster. Nekrose und Weichwerden der Knochen."},{"t":"Beschwerden durch unterdrückten Fußschweiß."}],"rem":1,"orig":"Salicylicum acidum"},{"label":"Sambucus nigra","short":"Sambucus nigra","group":"Arzneimittellehre","paras":[{"t":"Sambucus nigra, Schwarzer Holunder. Profuse Schweiße oder Atemnot bei vielen Symptomen. Nase trocken und verstopft, Säuglingsschnupfen, der am Stillen hindert."},{"t":"Ärgerlich; Erstickungsanfälle nach Schrecken. Stimmritzenkrampf. Krupp."},{"t":"Heißes Gesicht mit eiskalten Füßen."},{"t":"Husten erstickend, Weinen, Agg.: um Mitternacht; hohl, tief keuchend, mit Brustkrampf; mit normalem Einatmen, aber seufzendem Ausatmen."},{"t":"Kind erwacht plötzlich, fast erstickt, setzt sich auf, blau, schnappt nach Luft; wiederholte Anfälle. Kind atmet ein, kann aber nicht ausatmen (Chlor.; Meph.); schläft in Anfall hinein. Trockener, tiefer Husten geht Fieberanfall voraus."},{"t":"Trockenes Fieber im Schlaf, durstlos, fürchtet sich vor dem Aufdecken. Reichlicher Schweiß während der wachen Stunden, beim Einschlafen kehrt trockene Hitze zurück. Schwitzen beim Erwachen."},{"t":"Durchfall bei Kindern; Kolik mit Übelkeit und Flatulenz."},{"t":"Akute Nephritis mit geschwollenen Beinen und Füßen."},{"t":"Agg.: Ruhe; nach Obstessen; Trockene, kalte Luft; kalte Getränke, wenn überhitzt; Mitternacht."},{"t":"Amel.: warm einpacken; Aufsitzen im Bett; Bewegung."}],"rem":1,"orig":"Sambucus nigra"},{"label":"Sanguinarinum nitricum","short":"Sanguinarinum nitricum","group":"Arzneimittellehre","paras":[{"t":"Sanguinarinum nitricum, nitriertes Alkaloidgemisch aus Sang. Influenza. Nasenpolypen; verstopftes Gefühl. Reichlicher, wässeriger, brennender Schleim. Postnasales Tröpfeln, haftend im Nasopharynx, schwer zu lösen."},{"t":"Vergrößerte Nasenmuscheln zu Beginn des hypertrophischen Prozesses."},{"t":"Rauheit und Wundheit der hinteren Nasenmuscheln. Niesen. Trockenheit und Brennen in den Nasenflügeln. Nasenöffnungen verstopft mit dickem, gelbem, blutigem Schleim."},{"t":"Geschwüre seitlich an der Zunge."},{"t":"Zusammengeschnürter, brennender Hals. Akute Pharyngitis. Akuter und chronischer Katarrh."},{"t":"Kurzer, hackender Husten mit dickem, gelbem, süßlichem Schleim. Kitzelhusten. Schmerz und Druck hinter Brustbeinmitte."},{"t":"Chronischer Nasen-, Kehlkopf- und Bronchialkatarrh. Stimme tief, heiser, verändert."}],"rem":1,"orig":"Sanguinarinum nitricum"},{"label":"Sanguinaria canadensis","short":"Sanguinaria canadensis","group":"Arzneimittellehre","paras":[{"t":"Sanguinaria canadensis, Kanadische Blutwurzel. Migränekopfschmerz über rechtes Auge oder vom Hinterkopf zum Auge, an- und absteigend mit der Sonne; periodisch; klimakterisch; Amel.: Schlaf, Erbrechen und reichliches Wasserlassen. Überarbeitungsmigräne, Amel.: Ruhe, dunkler Raum."},{"t":"Kopfschmerz besser durch Erbrechen, aber Erbrechen hört nicht auf. Kopfschmerz von rechter Schulter und Genick aufsteigend. Periarthritis humeroscapularis rechts."},{"t":"Heuschnupfen und Heuasthma. Trockenheit der Nase; Nasenpolypen. Umschriebene Röte der Wangen, brennend. Ikterus mit biliösem Stuhl und dunklem Urin. Durchfall bei Besserung des Schnupfens."},{"t":"Husten und Atemnot von Magenstörungen, Amel.: Aufstoßen und Flatulenz. Husten nach Influenza und Keuchhusten; kehrt nach jeder Erkältung zurück. Schmerz vom Thorax oder Magen zur rechten Schulter. Juckreiz der Achsel vor den Menses. Schmerz in rechter Schulter, Agg.: nachts, Daraufliegen, Umdrehen im Bett. Geruchsempfindlich. Klimakterische Hitzewallungen, brennende Handflächen und Fußsohlen; deckt Füße auf. Sehr durstig."},{"t":"Schwindel hohe Plätze, viel übelriechender Schweiß und Stuhl."},{"t":"Verlangen: Pikantes; Süßigkeiten."},{"t":"Abneigung: Butter."},{"t":"Agg.: Erschütterung; Klimakterium; Gerüche; Sonne; periodisch jeden 7. Tag."},{"t":"Amel.: Schlaf; Saures; Dunkelheit; Erbrechen."}],"rem":1,"orig":"Sanguinaria canadensis"},{"label":"Sanicula aqua","short":"Sanicula aqua","group":"Arzneimittellehre","paras":[{"t":"Sanicula aqua, Mineralwasser aus Ottawa, Illinois, USA."},{"t":"Marasmus an Körper, Geist und Seele. Kind sieht alt, schmutzig, schmierig und bräunlich aus; Haut um Nacken ist verschrumpelt, hängt in Falten. Schwaches Genick, kann Kopf nicht aufrecht halten (Abrot.; Iod.; Nat-m.; Sars.)."},{"t":"Abneigung gegen geistige Anstrengung, nichts wird zu Ende gebracht; sprunghaft im Gespräch. Dickköpfige Kinder; leicht beleidigt; werfen Gegenstände; Furcht vor Dunkelheit und Räubern. Reichlich Schweiß an Hinterkopf und Nacken (Calc.; Sil.). Schuppiger Grindkopf."},{"t":"Angst, daß etwas passiert, vor Abwärtsbewegung, daß jemand hinter ihm ist. Ständig wechselnde Beschäftigung; Verlangen zu reisen. Abwechselnd Reizbarkeit und Lachen."},{"t":"Lichtscheu, Tränenfluß bei Wind. Kinnakne, ungesunde Haut."},{"t":"Wundheit hinter den Ohren mit Absonderung weißlich-klebriger Flüssigkeit (Graph.; Psor.). Risse auf Handrücken."},{"t":"Ohrsekret scharf, mit Geruch von altem Käse. Zungenbrennen, streckt sie heraus zur Abkühlung. Heftiges, schwallartiges Erbrechen nach Milch, sobald sie sich im Magen befindet (Ars.; Phos.). Übelkeit im Auto. Vergrößertes Abdomen. Stuhl anstrengend, zurückgleitend (Sil.; Thuj.), trockene, graue Kugeln, müssen mechanisch entfernt werden, krümelnd am After (Mag-m.), Geruch von Limburger Käse. Diarrhoe wie Rührei, wie Schaum auf Froschteich."},{"t":"Unwillkürlicher Stuhlgang und Urinverlust. Schmerz im Perineum. Ausschlag um Anus (Sulph.) und Genitalien."},{"t":"Leukorrhoe mit Fischlakengeruch, Agg.: nach Stuhl. Nachuntendrängen, Amel.: Ruhe; Drang zu stützen (Lil-t.; Murx). Wundheitsgefühl des Uterus."},{"t":"Lumbago, Agg.: Bewegen der Arme nach hinten, Amel.: Liegen auf harter Unterlage."},{"t":"Deckt Füße ab in der Nacht. Stinkender Schweiß, Fußschweiß. Körper riecht wie alter Käse, nach Fischlake. Durst auf häufige, kleine Mengen."},{"t":"Verlangen: Süßigkeiten; Salz; Fett; Speck; kalte Milch; Eier; Fleisch."},{"t":"Agg.: kalte Luft im Genick; Bewegung; treppab; Reiten; Arme nach hinten bewegen; 21 Uhr."}],"rem":1,"orig":"Sanicula aqua"},{"label":"Sarsaparilla officinalis","short":"Sarsaparilla officinalis","group":"Arzneimittellehre","paras":[{"t":"Sarsaparillawurzel. Unsauber. Risse in Handflächen und Fußsohlen, die bluten; Rhagaden in Zehen und Fingern. Fingerrisse in Längsrichtung. Haut lederartig. Starke Abmagerung und Periostschmerzen durch venerische Krankheiten. Schmerz verursacht Depression. Schrumpelige, in Falten liegende Haut (Abrot.; Iod.; Nat-m.; Sanic.). Kinder haben Gesicht wie alte Leute. Vergrößertes Abdomen."},{"t":"Ulzeration um die Fingerenden; Schneiden unter den Nägeln. Ausschläge im Frühjahr, Agg.: frische Luft."},{"t":"Kopfschmerz vom Hinterkopf zu den Augen. Ausschlag auf Gesicht und Oberlippe; feuchter Ausschlag auf der Stirn, Agg.: Menses. (Sang.; Psor.)."},{"t":"Aphthen. Speichelfluß. Metallischer Geschmack. Bauchkolik mit Rückenschmerz."},{"t":"Akute Zystitis (1. Mittel). Schmerz am Ende des Wasserlassens in Urethra."},{"t":"Frostgefühl von der Blase zum Rücken. Nierensteine, Grieß, blutiger Urin. Urin tröpfelt im Sitzen. Schmerz von rechter Niere nach unten ausstrahlend."},{"t":"Urin hell, klar, aber brennend; spärlich, schleimig, flockig, reichlich, ohne Empfindung abgehend (Caust.); lagert weißen Sand ab. Kind schreit vor dem Wasserlassen."},{"t":"Gestank der Genitalien, häufige, blutige Pollutionen (Led.; Merc.). Brustwarzen eingezogen, rissig."},{"t":"Sehr wunde, gichtige Knoten. Schmerz, als ob Teile zusammengeschraubt würden."},{"t":"Agg.: Ende des Wasserlassens; Frühling; vor Menses; kalt, naß; nachts; unterdrückte GO; Erkältung im Wasser."},{"t":"vgl. Juglans cinerea"}],"rem":1,"orig":"Sarsaparilla officinalis"},{"label":"Scutellaria laterifolia","short":"Scutellaria laterifolia","group":"Arzneimittellehre","paras":[{"t":"Scutellaria lateriflora, Sumpfhelmkraut. Nervöse Schwäche nach Influenza. Schwierige Konzentration. Verwirrung. Furcht vor Unglück, Katastrophe. Ruhelos nachts, muß sich bewegen."},{"t":"Kopfschmerz in der Stirn, als ob Augäpfel nach außen gepreßt würden. Schmerz in Augäpfeln. Migräne, Agg.: über dem rechten Auge. Explosionsartiger Kopfschmerz bei Lehrern mit häufigem Wasserlassen. Kopfschmerz in Stirn und an Hirnbasis. Nervöser Kopfschmerz mit Übelkeit, Agg.: Lärm, Licht, Gerüche, Amel.: nachts, Ruhe."},{"t":"Alpträume. Plötzliches Erwachen."},{"t":"Völle, Gas, Auftreibung im Abdomen; Kolikschmerz."},{"t":"Chorea, Muskelzucken; scharfe, stechende Schmerzen in oberen Extremitäten. Nächtliche Unruhe. Schwäche und Schmerzen."},{"t":"Spasmen bei zahnenden Kindern."}],"rem":1,"orig":"Scutellaria laterifolia"},{"label":"Secale cornutum","short":"Secale cornutum","group":"Arzneimittellehre","paras":[{"t":"Secale cornutum, Mutterkorn. Inneres Brennen, als ob Funken auf die Haut fielen (Ars.); äußerlich Eiseskälte mit Abneigung gegen Zudecken. Trockene Gangrän, Agg.: äußere Wärme; Raynaud; kalte, taube Finger und Füße bei Rauchern. Manische Furcht. Wochenbettpsychose."},{"t":"Hämorrhagische Diathese, kleine Wunden bluten wochenlang (Lach.; Phos.)."},{"t":"Dünn, mager, ausgezehrt; alt, kraftlos, schlaff. Augen eingesunken mit blauen Rändern. Gesicht blaß, eingesunken; spastisch verzerrt. Zunge mit Rissen, steif, vibrierend auf der Spitze und tintenschwarze, blutige Absonderung."},{"t":"Diarrhoe, unwillkürlich; dünn, eitrig, braun, herausspritzend, Anus weit offen (Apis; Phos.). Enuresis bei alten Menschen."},{"t":"Metrorrhagie; konstantes Sickern zwischen den Menses; im Klimakterium mit heißen Füßen. Kindbettfieber. Drohender Abort im 3. Monat (Sabin.). Wehenschwäche; alles scheint schlaff und offen, aber keine Austreibungswehen. Nachwehen zu lange, zu schmerzhaft; sanduhrartige Kontraktionen. Unterdrückte Milchbildung bei dünnen, mageren Frauen, Brüste füllen sich nicht richtig. Weißfluß grün, braun, stinkend."},{"t":"Ataxie. Fingerkrämpfe, muß Finger spreizen."},{"t":"Ameisenlaufen unter der Haut. Variköse Geschwüre."},{"t":"Brennende Haut, Amel.: Kälte, Aufdecken."},{"t":"Schlaflosigkeit bei Süchtigen (Alkohol, Drogen, Medikamente)."},{"t":"Arteriosklerose. Unstillbarer Durst und Heißhunger mit Abmagerung. Warmblütig. Blutungen schwarz, sickernd, stinkend."},{"t":"Verlangen: Saures; Zitronenlimonade."},{"t":"Abneigung: Fleisch; Fett."},{"t":"Agg.: Wärme; warm zudecken; sexuelle Exzesse."},{"t":"Amel.: Kälte; kalt baden; kalt zufächeln; gewaltsames Strecken."}],"rem":1,"orig":"Secale cornutum"},{"label":"Selenium metallicum","short":"Selenium metallicum","group":"Arzneimittellehre","paras":[{"t":"Selenium. Vorzeitige Alterung; Große Schwäche nach erschöpfenden Krankheiten. Geil aber impotent. Priapismus, Hoden hochgezogen. Auszehrung. Depression und Verzweiflung. Vergessene Dinge fallen ihm im Schlaf ein."},{"t":"Haarausfall überall. Kopfschmerz bei Säufern, Agg.: Sonne, Tee, Wein, Limonade, jeden Nachmittag; über dem linken Auge."},{"t":"Schnupfen endet mit Durchfall. Bohren in der Nase."},{"t":"Heiserkeit; hustet jeden Morgen klaren Schleim ab. Knoten auf den Stimmbändern bei Sängern."},{"t":"Leber vergrößert mit flachem Ausschlag über der Leber."},{"t":"Verstopfung nach Fieber (meist Enteritis); Stuhl sehr hart, voluminös, hilft mechanisch nach (Aloe; Calc.; Sanic.; Sep.; Sil.)."},{"t":"Spermatorrhoe bei Stuhlgang, im Schlaf."},{"t":"Paralytischer Rückenschmerz, Amel.: Liegen auf dem Bauch, nach einer Krankheit. Komedonen mit öliger Haut. Juckreiz über den Knöcheln und Hautfalten; Bläschen zwischen den Fingern."},{"t":"Schlaf verhindert durch Pulsationen des ganzen Körpers; erwacht früh, immer zur selben Stunde. Unwiderstehliches Verlangen, sich hinzulegen und bei heißem Wetter zu schlafen. Hunger nachts (Cina; Psor.)."},{"t":"Verlangen: Spirituosen, Wein; Tee, der aber verschlechtert."},{"t":"Abneigung: Salz; Luftzug."},{"t":"Agg.: Sonnenhitze oder heiße Tage; nach Schlaf; Koitus; Luftzug; Singen; Tee; Wein; Salz; Limonade."}],"rem":1,"orig":"Selenium metallicum"},{"label":"Senecio aureus","short":"Senecio aureus","group":"Arzneimittellehre","paras":[{"t":"Senecio aureus, goldenes Kreuzkraut. Nervöse, blasse, schwache, schlaflose Frauen. Amenorrhoe mit Lumbago; Beschwerden durch unterdrückte Menses. Sexuelle Erregung mit Reizbarkeit der Genitalien."},{"t":"Reizbarkeit, Egoismus. Abwechselnd traurig und fröhlich."},{"t":"Schmerz über dem linken Auge, Schläfe und Gesicht. Wellenartiger Schwindel. Trockenheit von Mund und Rachen. Schmerz um den Nabel, Amel.: Stuhlgang."},{"t":"Tenesmus mit dünnem, dunklem Stuhl, gemischt mit harten Klumpen (Ant-c.). Anstrengung beim Stuhl."},{"t":"Prostatavergrößerung. Reizblase bei Kindern, Nephritis mit Kopfschmerz. Nierenkolik. Blutiger Urin; große Hitze und ständiger Drang."},{"t":"Blutungen anderer Organe mit verzögerten Menses. Frühzeitige, zu reichliche Menses (Calc.; Erig.). Vor Menses entzündliche Zustände von Rachen, Brust und Blase, Amel.: nach Beginn der Menses. Leukorrhoe, die Schenkel hinunterlaufend. Lockerer Husten, mit mühsamer Einatmung. Trockener Reizhusten, stechende Brustschmerzen. Frühe Leberzirrhose."},{"t":"Abneigung: Süßes und Kaffee, was sie vorher sehr mochte."},{"t":"Agg.: Pubertät; sexuelle Erregung; ausbleibende oder verzögerte Menses; vor Menses."},{"t":"Amel.: einsetzende Menses."}],"rem":1,"orig":"Senecio aureus"},{"label":"Senega","short":"Senega","group":"Arzneimittellehre","paras":[{"t":"Senega, Virginisches Milchkraut. Atemwegserkrankungen alter Menschen oder dicker Kinder. Leicht beleidigt, streitsüchtig."},{"t":"Berstender Stirnkopfschmerz; Blepharitis. Lider trocken und verkrustet (Graph.). Trockenheit mit Gefühl, als ob Augäpfel zu groß für -höhlen. Augenmuskellähmung. Tränenfluß; muß oft die Augen wischen. Doppelbilder, Amel.: Kopf zurücklehnen. Glaskörpertrübung."},{"t":"Schnupfen mit viel wässerigem Schleim und Niesen. Pfefferartiges Gefühl in Nasenlöchern. Mundtrockenheit. Katarrhalische Entzündung von Rachen und Schlund mit kratziger Heiserkeit. Stimme unstet mit Stimmbandlähmung. Aphonie. Brennen und Rauheit. Gefühl, als ob die Schleimhaut abgeschabt wäre. Erstickender Husten, der mit Niesen endet. Rasseln in der Brust. Dyspnoe beim Steigen. Katarrh mit schmerzhaften Brustwänden; Schwieriges Abhusten von zähem, reichlichem Schleim. Asthenische Bronchitis alter Menschen mit Nephritis oder Emphysem. Pleuraerguß. Druck auf der Brust, als ob Thorax zu eng wäre. Bei Pleuropneumonie nach Bry. Schmerz linker Thorax wie wund, brennende Stellen."},{"t":"Schmerz im Nierenlager; stark verminderter Harn. Hitze vor Wasserlassen."},{"t":"Agg.: frische Luft; Berührung; Ruhe. Amel.: Kopf nach hinten lehnen."}],"rem":1,"orig":"Senega"},{"label":"Sepia officinalis","short":"Sepia officinalis","group":"Arzneimittellehre","paras":[{"t":"Sepia off., Tintenfisch. Schwere/Völle in Beckenorganen, Hinabdrängendes Gefühl, muß Beine kreuzen. Verlangen nach heftiger Bewegung, Tanz. Venöse Stase."},{"t":"Abneigung gegen geliebte Menschen, gegen Sex. Keine Gefühle und traurig darüber, Agg.: Trost. Weint leicht. Kritisch, verletzt Gefühl anderer. Mag fest gehalten werden, aber Abneigung gegen Sex; Kind klammert an Mutter. Fröhlich bei Gewitter. Furcht Alleinsein; Männer; Freunde treffen; Armut. Habgierig. Sexuell mißbraucht."},{"t":"Kopfschmerz bei Menses mit spärlicher Blutung, Amel.: Druck, heftige Bewegung. Haarausfall. Hautpilz. Ringflechte. Hautverdickung nach Kratzen. Chronischer grüner Nasenkatarrh; postnasales Tröpfeln. Gelber Sattel über der Nase. Gelbe/braune Flecken im Gesicht. Lippenherpes. Riß in der Mitte der Unterlippe. Ptosis, Ziliarreizung. Schmerzhafte Leere im Magen. Übelkeit beim Gedanken an oder Geruch von Essen. Schwangerschaftsübelkeit. Leber schmerzhaft, Amel.: Rechtsliegen. Dickbäuchige Mütter. Gefühl eines Balles im Rektum, nicht besser nach Stuhlgang. Rektumkarzinom. Stiche in Vagina, aufwärts; bohrender, lanzinierender Schmerz vom Uterus zum Nabel. Fehlgeburt; Uterusprolaps. Menstruationsstörungen aller Art. Schmerzen erstrecken sich zum Rücken; Lumbago, Amel.: Liegen auf harter Unterlage. Hallux valgus. Kalte Hände und Füße; Raynaud."},{"t":"Unerfrischender Schlaf; unmöglich auf der linken Seite (wegen Träumen)."},{"t":"Ohnmachtsneigung, Agg.: Knien, extreme Temperaturen, Naßwerden, Reiten, harte Arbeit. Gefühl von Schwäche und Leere. Mangel an Lebenswärme."},{"t":"Klimakterium: Hitzewallungen mit Erröten, Agg.: geringste Bewegung."},{"t":"Folge von Interruptio, Kind stirbt, anfälliges Hormonsystem."},{"t":"Verlangen: Schokolade; gewürzt; Saures; Essig; Kaffee."},{"t":"Abneigung: Fett; Fleisch."},{"t":"Agg.: am Meer (Nat-m.; Tub.; Mag-m.); vor und während Menses; nach Essen; geistige Arbeit; im Gehen (plethorischer Typ); heißes Wetter; Kälte; vor Gewitter; Schneeluft; sexuellen Exzesse; Schwangerschaft; Milch."},{"t":"Amel.: Rennen; Tanzen; Sonne; Wärme; nach Schlaf."},{"t":"Stase. Keine Polarität; kein Interesse am Sex. Keine weibliche Kurven; dünn, flachbrüstig. Überlastete Hausfrau, benommen, dumpf, vergeßlich. Widerspenstig, unzufrieden, sieht schwarz, will ausbrechen."},{"t":"Depression, Opposition, Resignation."},{"t":"Emotionale Stase: kein Gefühl; Freude, Herzlichkeit, wie abgestellt; schlägt ihre Kinder. Bissig, schroff; Karrierefrau (weibliche Nux-v.). Übererregbarkeit, Nervosität. Ehrgeizig, hart arbeitend, kann Beengung am Hals nicht ertragen (Lach.). Heult Tag und Nacht, weiß nicht, warum. Ängstlich gegen Abend. Depressionen, Amel.: nachts, Agg.: tagsüber. Spirituell engagiert. Stille und Unbeweglichkeit; Schwerfälligkeit. Alles zuviel."},{"t":"Geistige Stase: Verstand steht still, bleibt intuitiv empfindsam und weiß jeden zu verletzen."},{"t":"Kinder: erregbar, nervös, dünn, blaß, geräuschempfindlich, kleine Mädchen sehen wie Phosphor aus; sehr aktiv, tanzen oft sehr gerne; sondern sich ab, Einzelgänger, wollen in Gesellschaft nicht persönlich angesprochen werden. Provozieren Mutter. Enuresis im ersten Schlaf. Neurodermitis. Legasthenie."},{"t":"Jugendliche: erregbare Phase, starke Zuneigung, will Sex; sucht tiefe, ideale Beziehung. Fühlt sich gegängelt und benachteiligt. Aufbegehren."}],"rem":1,"orig":"Sepia officinalis"},{"label":"Silicea terra","short":"Silicea terra","group":"Arzneimittellehre","paras":[{"t":"Silicea, Kieselsäure. Würde. Aristokratisch. Schüchtern; mild; überempfindlich; dünn; blaß; geduldig; reserviert; kritisch; eigensinnig; reizbar; ruhelos; zappelig; schreckhaft; Nachgiebigkeit aus Energiemangel; nervöse Schwäche; Neuralgie, hysterischer Anfall, Lähmung durch Überanstrengung. Möchte sich hinlegen. Geistige Arbeit strengt sehr an. Unternimmt nichts, was Energie raubt. Medium, Magnetismus. Fixe Ideen."},{"t":"Gewissensangst. Prüfungsangst, Selbstbehauptung durch Perfektion. Listenschreiben. Befürchtet, nicht gut genug zu sein. Angst, sich lächerlich zu machen. Sehr verantwortungsbewußt. Angst bei Menses, vor Nadeln und spitzen Gegenständen. Prinzessin auf der Erbse."},{"t":"Feine, trockene, blasse Haut. Warzen. Drüsenschwellung (Entzündung, Verhärtung, Eiterung): Parotis, Mamma, axillar, zervikal, Talgdrüsen, bösartig, gangränös. Skoliose. Folge geplatzter Silikonimplantate."},{"t":"Kopfschmerz vom Nacken zum Scheitel oder über rechtem Auge, trägt Hut, Amel.: Druck, warm einhüllen, Wasserlassen, dunkler Raum. Schwindel mit Gefühl, nach vorne zu fallen, Agg.: Aufwärtssehen; Linksliegen, Amel.: warm einpacken. Tubenkatarrh; Dröhnen in den Ohren. Splitterschmerz im Hals. Sinusitis. Husten, Agg.: Hinlegen, mit dicker, klumpiger Expektoration. Taubheit in aufliegenden Körperteilen. Schmerz wie Nadeln."},{"t":"Nachts durstig, viel Schweiß, widerlich scharf, stinkend trotz Waschen. Folgen von unterdrücktem Schweiß: Tuberkulose, Krebs, Steine."},{"t":"Nierenkrankheit; Katarakt; Fibrome; Tumoren (Calc-f.; Bar-m.); Zysten in den Mammae; eingezogene Brustwarze (Sars.); Keloide (Graph.); Impffolgen (Abszesse; Konvulsionen)."},{"t":"Fissuren; Nägel brüchig, weiß gefleckt, Pilz, eingewachsen;"},{"t":"Fisteln mit Schmerz und Schwellung an Rektum, Augen, Mund, (Calc-s. mit gelbem Ausfluß und weniger Schmerz); Pickel tief in der Haut; Akne mit kleinen Löchern."},{"t":"Eiterungen. Panaritium. Abszeßeröffnung."},{"t":"Obstipation, muß mechanisch nachhelfen, Jojostuhl, Agg.: vor/bei Menses. Schlechte Assimilation (Bar-c.; Calc.)."},{"t":"Frostig, aber Verlangen nach kalten Getränken/Essen."},{"t":"Agg.: Kälte, haßt Winter, Furcht vor Kälte. Friert auch bei Körperübungen."},{"t":"Rheumaschmerz, Agg.: Kaltanfassen (Rhus-t.; Thuja; Hep.). Frost, Agg.: bei Menses."},{"t":"Gefühl, wie Haar auf der Zunge (Kali-bi.)."},{"t":"Verlangen: Eier; Unverdauliches; Brot; Kalte Speisen."},{"t":"Abneigung: Salz; Fleisch; (Mutter-)milch; warme Speisen."},{"t":"Agg.: Kälte; Kaltes; geringster Luftzug; Neumond; während Menses; Entblößen des Kopfes; Hinlegen; Unterdrückung; Impfung."},{"t":"Amel.: warm einhüllen des Kopfes; Magnetismus; Wärme, außer Magen. Sommer."},{"t":"Kinder widerspenstig, eigensinnig. Weinen beim Ansprechen oder Anfassen. Großer Kopf, dünner Hals, Haare wie dünne Nadeln, -ausfall. Offene Fontanellen und Nähte. Starker Kopfschweiß. Aufgetriebener Bauch. Lernt langsam laufen."},{"t":"Die besten Schüler. Ängstlich, ruhelos, Prüfungsangst wegen Schwäche, läuft dann aber gut. Übermäßige geistige Unterdrückung, zu ernst, zu korrekt, bis zum Zusammenbruch, Blackout. Möchte nicht angesprochen werden (Thuj.), spricht über 3. Person. Kinder mit chronischen Sekreten aus Augen und Ohren. Baby erbricht Muttermilch (Hauptmittel)."}],"rem":1,"orig":"Silicea terra"},{"label":"Sinapis nigra","short":"Sinapis nigra","group":"Arzneimittellehre","paras":[{"t":"Sinapis nigra, Schwarzer Senf. Heuschnupfen. Trockenheit, Verstopfung der Nase, links oder Seiten wechselnd, Agg.: Tag, Nachmittag, Abend. Schleim der hinteren Nasenmuscheln fühlt sich kalt an. Scharfe Absonderung. Schweiß auf Oberlippe und Stirn."},{"t":"Stinkender Atem, nach Zwiebeln. Bauchkolik, Agg.: Bücken,"},{"t":"Amel.: Aufrechtsitzen."},{"t":"Agg.: Bücken."},{"t":"Amel.: Aufrechtsitzen."}],"rem":1,"orig":"Sinapis nigra"},{"label":"Solidago virgaurea","short":"Solidago virgaurea","group":"Arzneimittellehre","paras":[{"t":"Solidago virga aurea, Goldrute. Nierenlager druckempfindlich. Schmerz von den Nieren zu Abdomen oder Blase. Urin schwierig, spärlich, dunkel, stinkend. Dysurie. Chronische Nephritis. Zystitis. Erkrankungen anderer Organe kombiniert mit Harnsymptomen. Lumbago durch Nierenerkrankung."},{"t":"Vergrößerung des Uterus; Fibrome. Prostatavergrößerung."},{"t":"Petechien auf unteren Extremitäten mit Ödemen und Nierenkrankheit. Juckreiz, Ekzeme durch unterdrückten Urin. Schwäche."},{"t":"Heuschnupfen bei Allergie gegen Solidago. Augen injiziert, brennend, stechend. Niesanfälle."},{"t":"Wiederholte Erkältungen bei Tuberkulose. Frösteln wechselnd mit Hitze."},{"t":"Amel.: reichliches Wasserlassen."}],"rem":1,"orig":"Solidago virgaurea"},{"label":"Spigelia anthelmia","short":"Spigelia anthelmia","group":"Arzneimittellehre","paras":[{"t":"Spigelia anthelmia, Wurmfarn. Kombiniert Herz- und Augensymptome. Sichtbarer und hörbarer Herzschlag. Starke Schmerzen in/um Auge. Neuralgien. Empfindlich gegen Berührung; im berührten Körperteil wird Frösteln empfunden."},{"t":"Furcht vor Nadeln. Suizidale Stimmung; Starren. Fröhlich bei Schmerz."},{"t":"Nervöser Kopfschmerz; periodisch, beginnt an Hirnbasis, setzt sich am linken Auge und der linken Schläfe fest; pulsierend, heftig, klopfend. Scharfer Schmerz an kleiner Stelle. Gefühl, Augen zu groß für Orbita, berührungsempfindlich, wie Band um Kopf."},{"t":"Zahnschmerz vom Tabakrauchen, Amel.: Hinlegen, Essen, Agg.: Darandenken, Kälte."},{"t":"Schwindel; Gefühl, nach links zu fallen, Agg.: Nachuntensehen; als ob die Füße höher als der Kopf sind. Trigeminusneuralgie, links; von morgens bis Sonnenuntergang, ziehend, brennend, bei kaltem, regnerischem Wetter."},{"t":"Chronischer Nasenkatarrh; postnasales Tröpfeln von stinkendem Eiter, verursacht nächtliche Erstickungsanfälle. Fauliger Mundgeruch."},{"t":"Bauchschmerz um den Nabel bei Kindern. Würmer (Askariden)."},{"t":"Dyspnoe, muß auf der rechten Seite liegen, mit erhöhtem Kopf. Herzklopfen; Perikarditis. Angina pectoris, Amel.: heiße Getränke."},{"t":"Verlangen: Alkohol. Abneigung: Tabakrauch."},{"t":"Agg.: Berührung; Bewegung; Erschütterung."},{"t":"Amel.: Liegen auf rechter Seite mit erhöhtem Kopf; ständiger Druck."}],"rem":1,"orig":"Spigelia anthelmia"},{"label":"Spongia tosta","short":"Spongia tosta","group":"Arzneimittellehre","paras":[{"t":"Spongia marina tosta, Gerösteter Meerschwamm. Erwacht mit Erstickungsgefühl, als ob er durch einen Schwamm atmen müßte; Herzklopfen. Husten völlig trocken ohne Schleimrasseln; bellend, kruppös, krächzend, klingend, keuchend, pfeifend, wie eine Säge. Furcht vor dem Tod, Erstickung, Zukunft. Weinen. Ängstlicher Ausdruck mit Atemnot."},{"t":"Heiserkeit; Extreme Trockenheit von Kehle, Larynx, Trachea, Bronchien. Dyspnoe durch Amenorrhoe. Völle der Brust, als ob das Herz nach oben gedrängt würde. Taubheit der Finger und unteren Extremitäten bei Angina pectoris."},{"t":"Schwäche nach leichter Anstrengung mit Blutandrang von der Brust zum Gesicht. Brustschwäche, kann kaum sprechen. Vermehrter Durst und Appetit. Unerträglichkeit der Kleidung. Schwellung und Verhärtung der Drüsen. Kropf mit nächtlichen Erstickungsanfällen."},{"t":"Schmerzhafte Schwellung des Samenstranges und der Hoden."},{"t":"Hunger, Herzklopfen, Kreuzschmerz vor den Menses."},{"t":"Verlangen: Süßigkeiten."},{"t":"Agg.: Aufregung; Erschöpfung; vor Mitternacht; lautes Lesen, Singen, Reden; Schlucken; Kopf zurückbeugen; Einatmen bei Krupp (Acon. Ausatmen); trockene, kalte Luft oder Wind; nach dem Schlafen oder beim Erwachen; vor Mitternacht; Kopftieflage; Heben der Arme; Süßigkeiten."},{"t":"Amel.: warme Getränke, Essen einer Kleinigkeit, Kopf vorbeugen."}],"rem":1,"orig":"Spongia tosta"},{"label":"Squilla maritima","short":"Squilla maritima","group":"Arzneimittellehre","paras":[{"t":"Squilla maritima, Meerzwiebel. Beschwerden, die mehrere Tage brauchen bis zu ihrer vollen Entwicklung."},{"t":"Heftiger, wilder, erschöpfender Husten mit viel Schleim. Reichlicher, salziger, schleimiger Auswurf mit unwillkürlichem Urinabgang und Niesen; mit Augenreiben, Tränenfluß. Agg.: kalte Getränke, tiefes Einatmen, Anstrengung, Wechsel von warmer in kalte Luft."},{"t":"Kind reibt Gesicht mit der Faust während des Hustens. Atemnot und Stiche in der Brust. Bronchopneumonie. Laufschnupfen, wunde Nasenlöcher. Magendruck wie von einem Stein."},{"t":"Milzvergrößerung mit Stechen unter dem linken Rippenbogen. Durst auf kalte Getränke; trinkt in kleinen Schlucken bei Atemnot. Starker Harndrang; viel wässeriger Urin. Splitternde, sich spaltende Nägel. Kalte Extremitäten bei heißem Körper. Wunde Füße vom Stehen."},{"t":"Agg.: früher Morgen; Bewegung; Husten; Einatmen."},{"t":"Amel.: Ruhe; Ausatmen."}],"rem":1,"orig":"Squilla maritima"},{"label":"Stannum metallicum","short":"Stannum metallicum","group":"Arzneimittellehre","paras":[{"t":"Stannum, Zinn. Größte Erschöpfung und Schwäche in Kehle und Brust. Alte Tuberkulose-Patienten. Erschöpfender Nachtschweiß. Heiser. Anstrengung beim Abhusten. Heftiger, trockener Husten von Abend bis Mitternacht. Husten erregt durch Lachen, Singen, Sprechen, Agg.: Rechtsliegen. Atmung kurz, beklemmend, Stiche in der linken Brust. Reichlich grünlicher, süßlicher Schleim; Haut gelblich, kupferfarben, dick wie Leder. Mager, blaß, (niemals rosig). Hitze unter der Haut. Augenbrennen."},{"t":"Müdigkeit, Erschöpfung, kann kaum Sprechen, Telefonieren, zur Liege gehen, zum Waschbecken gehen. Liebenswürdig. Verzagt, entmutigt, menschenscheu. Angst vor der Zukunft; vor Menses, Amel.: wenn Menses fließen."},{"t":"Neuralgien, Agg.: mit Sonne, 10-16 Uhr, am schlimmsten 14 Uhr, auch 5 Uhr. Fängt vieles an, führt nichts zu Ende. Ineffizientes Arbeiten."},{"t":"Leere im Magen. Erbrechen beim Geruch von kochenden Speisen. Kolik, Amel.: harter Druck. Verstärktes sexuelles Verlangen vor den Menses; leichter Orgasmus. Menses früh, reichlich. Nachuntendrängen und Uterusprolaps mit Schwäche im Magen. Leukorrhoe nach unterdrückter Neuralgie."},{"t":"Glieder geben plötzlich nach, bei dem Versuch, sich hinzusetzen."},{"t":"Schläft mit einem Bein ausgestreckt, das andere gebeugt."},{"t":"Agg.: Sprechen; Bewegung; Erschöpfung; 5, 10 Uhr; Rechtsliegen."},{"t":"Amel.: harter Druck über einer Kante; rasche Bewegung; Abhusten."}],"rem":1,"orig":"Stannum metallicum"},{"label":"Staphisagria","short":"Staphisagria","group":"Arzneimittellehre","paras":[{"t":"Delphinium staphisagria, Stephanskraut. Folge von: unterdrückten (erotischen) Gefühlen, Kummer, verletzter Ehre; Demütigung, unverdiente Kränkung; Entrüstung mit Zorn oder unterdrücktem Ärger (Aur.). Nervöse Schwäche, wie nach schwerer Arbeit."},{"t":"Folge von Schnittverletzungen, Kolik nach Bauchschnitt."},{"t":"Hordeolum, Chalazion (Con.; Thuj.). Zahnschmerz bei Menses; Karies, Zahnverfall, dunkle Streifen, Verfall an den Kanten, Agg.: Berührung von Speisen oder Getränken, kalte Luft. Extremer Hunger, selbst bei vollem Magen. Gefühl, als hinge Magen schlaff herab."},{"t":"Kopfschmerz wie Holz, Stirn oder Hinterkopf. Sklerose; schwaches Gedächtnis nach sexuellen Exzessen. Vergeßlichkeit; unflexibel; Senilität. Hypertonie. Kleinfleckige Psoriasis (Hauptmittel) nach Entrüstung oder Zurechtweisung."},{"t":"Ekzem mit Blasen, gelbem, scharfem Sekret, Krusten, Juckreiz, wandernd."},{"t":"Wunden heilen schwer, verhärten. Verhärtete Drüsen: Liddrüsen, Ovarien, Uterus, Testes, Prostata; Warzen, Tumoren."},{"t":"Diarrhoe. Sehr empfindliche Kondylome am Anus. Zystitis in den Flitterwochen."},{"t":"Harndrang, Brennen in Urethra nach Wasserlassen. Blasenprolaps. Chronische Prostatitis, Urethritis, Epididymitis. Nach Zystoskopie. Gefühl eines Urintropfens in Urethra. Ovarial-, oder Bartholin Zyste. Leicht erregbar, masturbiert viel; Promiskuität, Wollüstigkeit, Lasterhaftigkeit. Lumbalgie, Schwäche nach Masturbation, Agg.: nachts im Bett, morgens vor Aufstehen."},{"t":"Husten, Agg.: nur tags, Essen, Fleischessen, Ärger, Entrüstung, Zähneputzen, Tabakrauch (Spong.)."},{"t":"Kinder: geistige Retardation durch Unterdrückung, lästiges Benehmen, in Schule 3 J. zurück; schlägt nach Mutter. Wutanfälle, gewalttätig, Stram. nützt nichts, umgedrehter Linkshänder."},{"t":"Verlangen: Süßigkeiten; Brot; Branntwein; Stimulanzien; Milch; Tabak."},{"t":"Agg.: Gefühlserregung; Kummer; Masturbation; Berührung; kalte Getränke; Mittagsschlaf."},{"t":"Amel.: Frühstück; Koitus; Ruhe; Wärme; Masturbation."},{"t":"Süßer als Phos. und kontrolliert sich stark. Romantisches Schwärmen. Gefühle leicht zu entfachen, lebhaft. Kummermittel."},{"t":"Mann mit harter Schale, innerlich empfindsam; schreibt Gedichte, schließt leicht Freundschaften, scheut Liebesbeziehung."},{"t":"Frau: liebenswürdige Passivität; Resignation; schüchtern; feinfühlig, um andere besorgt, will niemanden mit ihren Problemen belasten, zurückhaltend. \"Aggressiv\" als unpassende Überreaktion nur, wenn innerer Druck zu groß wird. Wirft mit Gegenständen. Zittern während Auseinandersetzung. Hypersexuell oder impotent."},{"t":"Schlaflosigkeit mit sexuellen Gedanken; hochsensibel, künstlerisch tätig (alleine): Malerei, Musik, Dichtung (paßt nicht zu extrovertiertem Schauspieler, Sänger)."},{"t":"Hypochondrie und Übergenauigkeit mit Angst um Gesundheit und um Eigentum."}],"rem":1,"orig":"Staphisagria"},{"label":"Stellaria media","short":"Stellaria media","group":"Arzneimittellehre","paras":[{"t":"Stellaria media, Vogelmiere. Reizbarkeit, Mattigkeit, Abneigung gegen Arbeit. Dumpfer Stirnkopfschmerz. Stauung und Erschlaffung aller Funktionen."},{"t":"Starke, wandernde, rheumatische Schmerzen in allen Körperteilen. Rheumatismus; schießende Schmerzen fast überall; Steifheit der Gelenke; Teile berührungsempfindlich; Agg.: Bewegung, morgens, Wärme."},{"t":"Chronischer Rheumatismus, wandernde Schmerzen. Psoriasis. Verdickte und entzündete, gichtige Fingergelenke."},{"t":"Völle der Leber, geschwollen mit stechendem Schmerz und Druckempfindlichkeit."},{"t":"Abwechselnd Durchfall und Verstopfung. Lehmstühle."},{"t":"Agg.: morgens; Wärme; Tabak."},{"t":"Amel.: abends; kalte Luft; Bewegung."}],"rem":1,"orig":"Stellaria media"},{"label":"Sticta pulmonaria","short":"Sticta pulmonaria","group":"Arzneimittellehre","paras":[{"t":"Sticta pulmonaria, Lungenmoos. Nervös; geschwätzig; verwirrt. Gefühl, in der Luft zu schweben. Schnupfen mit schmerzhafter Verstopfung und Trockenheit. Druck in Stirn und Nasenwurzel. Katarrhalischer Kopfschmerz, bevor Absonderung in Gang kommt. Dauerndes Verlangen, Nase zu schneuzen, aber keine Absonderung. Trockene Borken, besonders abends und nachts. Heufieber; unaufhörliches Niesen (Sabad.). Retronasales Tröpfeln."},{"t":"Asthma. Trockener, hackender Husten, Agg.: nachts, gegen Abend, Einatmen, bei Müdigkeit. Hält vom Schlafen ab. Tracheitis. Lockerer Husten morgens. Schmerz durch den Brustkorb vom Sternum zur Wirbelsäule, Agg.: Bewegung. Husten nach Masern (Sang). Pulsieren von der rechten Seite des Brustbeins hinunter in den Bauch."},{"t":"Rheumatismus mit Nackensteifigkeit. Schmerz rechte Schulter. Bursae, vor allem um Knie. Hausmädchenknie. Gefühl, als ob Beine in der Luft schwebten. Rote, heiße, entzündete Flecken auf betroffenen Gelenken. Rheumatische Schmerzen vor Katarrh."},{"t":"Schlaflosigkeit durch den Husten; durch Nervosität; nach Operationen."},{"t":"Agg.: nachts; Temperaturwechsel."},{"t":"Amel.: freie Absonderungen; frische Luft."}],"rem":1,"orig":"Sticta pulmonaria"},{"label":"Stramonium","short":"Stramonium","group":"Arzneimittellehre","paras":[{"t":"Datura stramonium, Stechapfel. Elemente von Angst und Gewalt. Verlangen nach Licht und Gesellschaft. Ängste haben Bezug zum Unterbewußtsein: Dunkelheit, Alleinsein, Friedhöfe, Tunnels, geschlossene Räume, große Wasserfläche, Hunde. Angst vor der animalischen Energie in sich selbst. Anblick glitzernder Gegenstände führt zu Krämpfen. Gewalttätiger Wahnsinn, akute Psychose. Hält sich für groß, doppelt; glaubt, ein Teil fehlt. Religiöse Manie. Tollwut. Fieber mit wilden Delirien, mit reichlich Schweiß, der nicht erleichtert. Schläft mit offenen Augen. Singen im Fieber. Will fliehen."},{"t":"Zerreist Kleider, zerschmettert Gegenstände, beißt, schreit, flucht, betet, spricht mit Geistern, hört Stimmen. Nach Schädelbasisfraktur mit Hypothalamusschädigung, Alkoholvergiftung. Spastik nach Geburtstrauma, Ikterus neonatorum, Chorea. Metrorrhagie mit Geschwätzigkeit, Singen. Kindbettmanie. Gesicht heiß, rot, Extremitäten kalt. Röte der Wangen."},{"t":"Mundtrockenheit, klebriger Speichel, Hydrophobie, Stottern, Grimassen. Schlundkrampf. Heftiger Durst. Alles schmeckt wie Stroh. Erbrechen, sobald er den Kopf vom Kissen hebt, durch helles Licht."},{"t":"Stirnkopfschmerz, Agg.: 9-12 Uhr, Sonne, Hitze, Liegen, Bewegung. Meningitis durch Otitis, Überanstrengung der Augen durch zu langes Studieren; Strabismus. Kleine Gegenstände sehen groß aus. Septische Zustände, begleitet v. Krämpfen. Hebt den Kopf häufig vom Kissen."},{"t":"Schmerz linke Hüfte. Husten, Agg.: helles Licht, Feuer."},{"t":"Ersticken, wenn Wasser über den Kopf gegossen wird."},{"t":"Plötzliche, leuchtende Hautrötung. Folgen von unterdrücktem Ausschlag bei Scharlach. Harn und Stuhl völlig unterdrückt. Schmerzlosigkeit."},{"t":"Verlangen: Saures; Zitronensaft."},{"t":"Abneigung: Wasser."},{"t":"Agg.: glänzende Objekte; Schreck; Dunkelheit; Alleinsein; nach Schlaf."},{"t":"Amel.: helles Licht; Gesellschaft; Wärme."},{"t":"Da ist ein Vulkan drin; Energie geblockt, geht nach innen; ganz tiefe Unsicherheit. Mögliche Krebsentstehung. Sehr tiefe Angst, verwundbar zu sein, verletzt zu werden; kann nicht an Unfall/Verletzungen denken, sich im TV keine Gewaltszenen anschauen. Chronische rezidivierende Zerstörungssucht, unkontrolliertes Hervorbrechen des Unbewußten. Gewalt, Aggression. Wenn Zwangsjacke und Gummizelle letzter Ausweg ist. Ursache: seelischer Schock, extreme Furcht, Infekt mit ZNS-Beteiligung."}],"rem":1,"orig":"Stramonium"},{"label":"Strontium carbonicum","short":"Strontium carbonicum","group":"Arzneimittellehre","paras":[{"t":"Sehr emotional; freudvoll/weint schnell, mitfühlend, hilfsbereit. Aktiv, voller Leben. Furcht vor Gewitter; Abscheu vor haarigen Tieren. Schwindel an hohen Plätzen, Adipositas."},{"t":"Arthritis; Hypertonie und Arteriosklerose. Rotes Gesicht, drohende Apoplexie. Ruhelosigkeit nachts."},{"t":"Schock nach (Bauch-)operation. Folge von Blutungen."},{"t":"Schwindel mit Übelkeit und Kopfschmerz. Supraorbitalneuralgie. Hitzewallungen im Gesicht, klimakterisch mit Nachtschweiß, dennoch Abneigung, sich aufzudecken."},{"t":"Durchfall periodisch, Agg.: nachts, Amel.: gegen Morgen; dauernder Drang; Brennen in Anus bleibt nach Stuhl lange bestehen. Kolikschmerz Leiste und Nabel. Schmerz von Halswirbelsäule-Region nach oben, Amel.: warm einhüllen."},{"t":"Sprunggelenksverstauchung mit Ödem. Ischias. Rheumatische Gelenkschmerzen."},{"t":"Rheumatismus mit Durchfall, Neuralgie, wandernd, nagender Schmerz im Knochenmark. Schmerzen nehmen langsam zu und ab. Paralytische Schwäche."},{"t":"Verlangen: Brot; Bier; weiche Eier. Abneigung: Fleisch."},{"t":"Agg.: Kälte; Aufdecken; nachts; Bewegungsbeginn."},{"t":"Amel.: warm einhüllen; Eintauchen in heißes Wasser."}],"rem":1,"orig":"Strontium carbonicum"},{"label":"Strophanthus hispidus","short":"Strophanthus hispidus","group":"Arzneimittellehre","paras":[{"t":"Strophanthus hispidus. Kardiale Dyspnoe. Puls schwach, abwechselnd rasch und langsam. Nervöses Herzklopfen. Herzbeschwerden durch Alkohol, Tabak, Tee. Ödeme. Arteriosklerose. Furcht vor Unheil. Wellengefühl im Kopf. Chronische Urtikaria."},{"t":"Herztonikum bei Insuffizienz mit Ödemen. Diuretische Wirkung. Verbessert die Kontraktilität der quergestreiften Herzmuskulatur. Pneumonie mit starker Erschöpfung. Anämie mit Herzklopfen. Basedow."},{"t":"Verlangen: Kaffee."},{"t":"Agg.: Treppensteigen; Tabak; Erschöpfung; Alkohol."}],"rem":1,"orig":"Strophanthus hispidus"},{"label":"Strychninum purum","short":"Strychninum purum","group":"Arzneimittellehre","paras":[{"t":"Strychninum. Reflexübererregbarkeit des Rückenmarks. Muskelspasmen, Krämpfe, Blasenkrämpfe, Trismus, Zittern, Tetanus, Muskelsteifigkeit;"},{"t":"Agg.: geringste Berührung oder Bewegung, Geräusch, Geruch."},{"t":"Verwandt mit Nux-v.: explosive Nervosität."},{"t":"Wollüstiges Verlangen bei geringster Berührung."},{"t":"Eisiges Gefühl entlang der Wirbelsäule."},{"t":"Kehlkopfspasmen. Dyspnoe durch Muskelspasmen. Steifigkeit des Nackens und Rückens. Schmerz und Steifigkeit erscheinen plötzlich und kehren nach bestimmten Intervallen wieder."},{"t":"Ruhelos, überreizt."},{"t":"Berstender Kopfschmerz. Augen heiß, schmerzhaft, Funkensehen, Zucken der Lider. Kieferklemme. Schlucken unmöglich. Würgen, Erbrechen, Schwangerschaftsübelkeit. Verstopfung. Unwillkürlicher Abgang bei Spasmen."},{"t":"Agg.: Berührung; Bewegung; Lärm."},{"t":"Amel.: Liegen auf dem Rücken."}],"rem":1,"orig":"Strychninum purum"},{"label":"Sulphuricum acidum","short":"Sulphuricum acidum","group":"Arzneimittellehre","paras":[{"t":"Schwefelsäure. Reizbar, ungeduldig, eilig, ruhelos, schwach, zitternd. Im Klimakterium Wallungen, sehr rotes Gesicht, Kopfschmerz und Schweiß (Lach. wirkt nicht), große Eile, ängstlich, fordernd. Schmerz nimmt allmählich zu und hört plötzlich auf (Puls.). Sauer; Kind riecht sauer, trotz Waschens (Hep.; Mag-c.; Rheum). Blutungen von schwarzem Blut aus allen Körperöffnungen."},{"t":"Oberflächliche Gefühlswelt. Ärger über Kleinigkeiten, weil alles zu langsam geht. Mürrisch, unwillig, Fragen zu beantworten. Setzt Arzt unter Druck. Herzschmerz bei Gemütsbewegung."},{"t":"Zusammenschnürung in der Stirn, erst steigend, dann plötzlich verschwindend. Stiche in rechter Schläfe, wie Pfropfen. Drückender Schmerz an Hinterhauptseiten, Amel.: Hände an Kopf halten. Schweregefühl."},{"t":"Blässe, Gefühl von Spinnweben."},{"t":"Saures Aufstoßen macht die Zähne stumpf. Aphthen, stinkender Atem, Zahnfleischbluten, Parodontose. Schluckauf. Kälte im Magen durch Wassertrinken. Erschlaffung im Magen mit Verlangen nach Stimulanzien. Als wolle ein Bruch heraustreten, Agg.: links."},{"t":"Durchfall schwarz, stinkend, sauer."},{"t":"Kehlkopf bewegt sich heftig auf und ab. Bronchitis bei Kindern mit kurzem, quälendem Husten."},{"t":"Purpura haemorrhagica. Gangrän nach mechanischen Verletzungen. Ekchymosen bleiben nach Verletzungen."},{"t":"Alpträume vor und nach Menses."},{"t":"Verlangen: Alkohol; Obst; frisches Essen."},{"t":"Abneigung: Kaffeegeruch."},{"t":"Agg.: kalte, frische Luft; Alkohol; Verletzung; Kaffeegeruch; Klimax."},{"t":"Amel.: Wärme; heiße Getränke; Hand am Kopf."}],"rem":1,"orig":"Sulphuricum acidum"},{"label":"Sulphur","short":"Sulphur","group":"Arzneimittellehre","paras":[{"t":"Sulfur, sublimierter Schwefel. Polarität. Unordentlich, schmutzig, aber Ekel. Stinkende Absonderungen, Mund, Stuhl, Schweiß. Brennende Hitze. Brennschmerz überall möglich. Theoretisieren. Angst um andere oder Gleichgültigkeit. Furcht und Schwindel an hohen Plätzen. Egoistisch, faul. Gewissenhaft in Kleinigkeiten. Furcht vor ansteckenden Krankheiten, in engen Räumen. Empfindsam, hochmütig. Hält Lumpen für schöne Kleider. Nägelkauen."},{"t":"Kopfschmerz, periodisch am Wochenende. Wintersonnenkopfschmerz. Brennen auf Scheitel, Stirn. Brennende Augen, wie von Sand; morgens verklebte Lider. Hunger, Leere 11 Uhr. Allesesser, Sodbrennen, übersäuerter Magen. Geschwüre. Durchfall 5 Uhr, treibt aus dem Bett. Röte, Juckreiz um Anus. Kolitis. Stühle voluminös, schmerzhaft, trocken, wie verbrannt. Wechsel mit Diarrhoe. Enuresis; plötzlicher Drang. Urin scharf, wundmachend. Durst auf kalte Getränke. Brennen Vagina. Atemnot, verlangt Fenster offen, Agg.: Mitternacht, Amel.: Aufsitzen. Zusammenschnürung wie Gewicht auf der Brust. Lumbago, muß gebeugt gehen. Ruhelosigkeit und Hitze der Füße, deckt sie auf. Ungesunde Haut. Ekzeme, Ausschläge, feucht, juckend, Agg.: nachts, Wetterwechsel, Naßwerden, Wärme. Alpträume, auf dem Rücken liegend."},{"t":"Unterdrückte Ausschläge. Erkältung vom Haarewaschen. Röte der Lippen und anderen Körperöffnungen."},{"t":"Reaktionsmittel; rezidivierende Beschwerden. Masern; Erysipel; Angina. Impffolgen. Arthritis."},{"t":"Verlangen: Süßigkeiten; Fett; Pikant; Whisky; Bier; Schokolade; Gurke."},{"t":"Abneigung: Oliven; Huhn; Saures; Eier."},{"t":"Agg.: Baden; Milch; Honig; Stehen; Wärme, Bettwärme; Wolle."},{"t":"Amel.: frische Luft; trocken-warmes Wetter; Rechtsliegen."},{"t":"Saustall; Sammler; hitzige und explosive Persönlichkeit; Angeben; Egoist; Selbstaufgabe für Anerkennung. Eigenbrötlerischer Erfinder; Wissenschaftler. Rationalität auf Kosten der Gefühle."},{"t":"Abneigung gegen Beruf, Geschäft. Unglaublich faul/fleißig."},{"t":"Kinder sehr aktiv, unruhig, laut, heftig und schwer zu beruhigen; nachts wach und am Tage schläfrig. Baden nicht gerne, sitzen nicht gerne am Eßtisch, werden nicht gerne angezogen und ins Bett gebracht. In der Klasse ein soziales Zentrum, hat Führungsqualitäten. Asoziales Verhalten; Aggressivität und Streitsucht. Endlose Diskussionen. Würmer."}],"rem":1,"orig":"Sulphur"},{"label":"Sumbulus moschatus","short":"Sumbulus moschatus","group":"Arzneimittellehre","paras":[{"t":"Sumbulus moschatus, Moschuswurzel. Hysterie, Nervöse Symptome. Neuralgien und funktionelle Herzbeschwerden. Taubheit beim Kaltwerden; links. Schlaflosigkeit bei Delirium tremens."},{"t":"Emotional; abwechselnd Lachen und Weinen. Furcht, verrückt zu werden. Ohnmacht beim Musikhören. Dumpf morgens, klar abends."},{"t":"Gefühl von Spinnweben auf dem Gesicht."},{"t":"Erstickende Zusammenschnürung im Hals mit ständigem Schlucken. Völlegefühl im Abdomen, Auftreibung, Schmerz."},{"t":"Fetthäutchen auf Urin."},{"t":"Ovarialgie. Klimakterische Hitzewallungen. Nervöses Herzklopfen; Herzasthma. Neuralgien um linke Brust und linke Unterrippengegend; erscheint wie Angina pectoris."},{"t":"Gefühl, als ob Wasser die Wirbelsäule hinunterliefe."},{"t":"Agg.: Bewegung; links; Klimakterium; Musik; Darandenken."}],"rem":1,"orig":"Sumbulus moschatus"},{"label":"Symphoricarpus racemosus","short":"Symphoricarpus racemosus","group":"Arzneimittellehre","paras":[{"t":"Symphoricarpus racemosus, Schneebeere. Hauptmittel für Übelkeit und anhaltendes Erbrechen in der Schwangerschaft. Übelkeit, Agg.: Bewegung,"},{"t":"Amel.: Liegen auf dem Rücken. Wasserkolik, bitterer Geschmack. Heftiges Erbrechen, sogar mit Blut oder großen Schleimmengen. Abneigung gegen jegliches Essen, gegen den Gedanken und Geruch von Essen."},{"t":"Empfindlich auf Benzingeruch. Verstopfung."},{"t":"Agg.: Bewegung."},{"t":"Amel.: Liegen auf dem Rücken."}],"rem":1,"orig":"Symphoricarpus racemosus"},{"label":"Symphytum officinale","short":"Symphytum officinale","group":"Arzneimittellehre","paras":[{"t":"Symphytum off., Beinwell. Verletzungen des Knorpels, Periosts. Nichtheilende Frakturen. Exzessive Schmerzen. Periostschmerz nach erfolgter Wundheilung. Stumpfschmerz nach Amputation. Psoasabszeß."},{"t":"Stoß, Prellung, Schlag auf den Augapfel; Schneeball."}],"rem":1,"orig":"Symphytum officinale"},{"label":"Syphilinum","short":"Syphilinum","group":"Arzneimittellehre","paras":[{"t":"Syphilisnosode. Viele Ängste. Daß das Schlimmste passiert; traut sich nicht mehr aus dem Haus; um Gesundheit, fleht ängstlich um Hilfe; unerträgliche Furcht vor der Nacht; fürchtet die schreckliche Erschöpfung beim Erwachen."},{"t":"Überzeugt, daß keiner helfen kann (Ars.), aber ein Hoffnungsschimmer (Ars. nicht). Abergläubisch. Unsicherheit, wenig Selbstvertrauen und -bewußtsein. Angst, etwas vergessen zu haben. Schwitzen bei geringster Gemütsbewegung, vom Annähen eines Knopfes."},{"t":"Ekel vor Schmutz (nach Besuch im Bordell). Schlimmster Bazillenfimmel, Waschzwang. Fragt immer das Gleiche: \"Glauben Sie, daß ich verrückt werde?\". Erwacht 2/3 Uhr, schläft nicht mehr ein."},{"t":"Matte, kupferrote Flecke, werden bei Kälte blau. Extreme Abmagerung des ganzen Körpers (Abrot.; Iod.). Gedächtnis- und Konzentrationsschwäche. Stechende Herzschmerzen von der Basis zur Spitze (umgekehrt: Med.)."},{"t":"Chronischer Kopfschmerz. Haarausfall. Chronische Hornhautentzündung. Doppelbilder."},{"t":"Zahnhälse verfallen. Gezackte Ränder, hohl, winzig, konvergent an der Spitze. Reichlicher Speichelfluß im Schlaf."},{"t":"Karies der Gehörknöchelchen."},{"t":"Verstopfung, Analfissur mit sehr schmerzhaftem Stuhl."},{"t":"Scharfer Weißfluß, stark, läuft die Beine hinunter."},{"t":"Rheuma im Schultergelenk; am Ansatz des Deltoideus, Agg.: seitliches Heben des Armes."},{"t":"Zwergwuchs; unterentwickelt; alt aussehend. Schmerzen allmählich an- und abschwellend (Stann.); langsame Entwicklung von Beschwerden, Hemiplegie."},{"t":"Stinkender Körpergeruch. Skoliose, Knochenverkrümmung. Tiefe, sägende Schmerzen, Agg.: nachts. Ulzerationen; Aufeinanderfolgende Abszesse. Chronische Ausschläge, Geschwüre, Ichthyosis."},{"t":"Verlangen: Alkohol."},{"t":"Abneigung: Fleisch."},{"t":"Agg.: nachts; von Sonnenuntergang bis Sonnenaufgang (Merc.; Phyt.); am Meer; Hitze und Kälte."},{"t":"Amel.: Berge; tagsüber; fortgesetzte langsame Bewegung."}],"rem":1,"orig":"Syphilinum"},{"label":"Tabacum","short":"Tabacum","group":"Arzneimittellehre","paras":[{"t":"Nicotiana tabacum, Tabak. Zerebraler Reizzustand mit ausgeprägter Vagusreizung. Abmagerung von Wangen und Rücken. Allgemeine Muskelentkräftung. Ohnmacht, Hypotonie. Schreckliche Schwäche und Flauheit des Magens mit Übelkeit."},{"t":"Migräne frühmorgens, steigert sich bis Mittag, mit tödlicher Übelkeit und heftigem Erbrechen, Agg.: geringste Bewegung, Lärm, Licht."},{"t":"Plötzlicher Kopfschmerz rechts, wie von Keule getroffen."},{"t":"Anfallsweises Auftreten der Symptome bei Asthma, Migräne, Schwindel."},{"t":"Verlangen, Abdomen aufzudecken bei allen Beschwerden. Verdrießlich; gleichgültig. Einbildung, er wird eingesperrt oder getötet."},{"t":"Schwindel, Agg.: Augenöffnen, mit kaltem Schweiß, Amel.: Frischluft, Erbrechen, Aufstehen, Nachhintenschauen."},{"t":"Erblindung; Zentralskotom, Atrophie des Sehnervs. Verschwommenes Sehen."},{"t":"Gesicht totenblaß, eingesunken, kaltschweißig. Eiseskälte der Haut und des Schweißes bei allen Akutbeschwerden. Eiskalte Beine knieabwärts."},{"t":"Schwangerschaftserbrechen mit viel Spucken. Reiseübelkeit auf See, im Auto. Herzklopfen, Agg.: Linksliegen. Angina pectoris. Akute Herzerweiterung."},{"t":"Zusammenschnürung der Muskeln der Hohlorgane. Sphinkterspasmen. Koliken."},{"t":"Diarrhoe plötzlich, gelbgrün, schleimig, wäßrig, mit Übelkeit/Erbrechen, Kaltschweiß."},{"t":"Agg.: Bewegung; Reiten; warmes Zimmer; Augenöffnen; Tabak."},{"t":"Amel.: frische Luft; kalte Umschläge; Bauch aufdecken."}],"rem":1,"orig":"Tabacum"},{"label":"Taraxacum officinale","short":"Taraxacum officinale","group":"Arzneimittellehre","paras":[{"t":"Taraxacum off., Löwenzahn. Leber vergrößert und verhärtet; Ikterus; Stiche. Gallensteinkoliken ohne spezifische Modalitäten. Landkartenzunge mit rauhem, weißlichem Film, der sich in Fetzen löst, rote, empfindliche Flecken zurücklassend. Appetitlosigkeit, bitterer Geschmack."},{"t":"Hitze auf dem Scheitel und Kopfschmerz durch gastrointestinale Störungen."},{"t":"Auftreibung des Abdomens; hysterische Tympanie; Gefühl von platzenden Blasen im Darm. Milzschmerz. Blasenkrebs. Darmentleerung schwierig."},{"t":"Linker Sternocleidomastoideus sehr schmerzhaft."},{"t":"Kälte der Fingerspitzen. Knieneuralgie, Amel.: Druck."},{"t":"Ruhelose und schmerzhafte Glieder bei Fieber. Starker Nachtschweiß, Schwitzen beim Einschlafen. Durstlose Hitze im Gesicht, in den Zehen. Frostig, besonders nach Trinken."},{"t":"Agg.: Fett; Ruhe; Hinlegen; Sitzen."}],"rem":1,"orig":"Taraxacum officinale"},{"label":"Tarentula cubensis","short":"Tarentula cubensis","group":"Arzneimittellehre","paras":[{"t":"Tarantula cubensis, Kubanische Vogelspinne. Septische Zustände. Diphtherie. Furunkel, Karbunkel; maligne, eiternde Geschwüre; bläuliche, purpurfarbene Abszesse mit brennenden, stechenden Schmerzen bei extremer Schwäche. Verhärtung betroffener Teile. Gangrän. Reichliches Schwitzen. Erleichtert die letzten Schmerzstadien, daher Euthanasiemittel. Wie Anthr., aber kleinere Furunkel."},{"t":"Juckreiz der Genitalien."},{"t":"Amel.: Tabakrauchen."}],"rem":1,"orig":"Tarentula cubensis"},{"label":"Tarentula hispanica","short":"Tarentula hispanica","group":"Arzneimittellehre","paras":[{"t":"Tarantula hispanica, Spanische Tarantel. Chorea Huntington. Zwanghaft getrieben, wie gespannte Feder, voller Energie; arbeitet ohne Unterlaß (Nux-v.); geschäftig (Nux-v.: Ehrgeiz), eilig, schnell. Ruhelosigkeit der Beine, des ganzen Körpers, die ganze Nacht, Agg.: Gehen. Zwang, Energie abzulassen. Musik beruhigt physisch. Tanzneigung. Angst, daß etwas schiefgeht (irrational). Mag nicht von anderen berührt werden."},{"t":"Körperlich ähnlich Ars.: Frostigkeit, große Abmagerung, Periodizität und plötzlich auftretende Leiden. Herzwirkung. Angst vor Herzklopfen. Veränderung der Mitralklappen; Atembeschwerden; Herzjagen. Furunkel und Karbunkel mit heft. Brennschmerz. Qualen bei Nagelbetteiterung zwingen zur Unruhe, nächtelang im Zimmer auf- und abzuwandern."},{"t":"Sexualorgane: Myome; Menorrhagie; Nymphomanie; Jucken der Vulva bis tief in Vagina; Hodentumor."},{"t":"Hysterie, wenn Druck von außen zu groß. Krämpfe, Ohnmacht, Spastik. Später Kontrollverlust; zerstörerisch, verbirgt Gewalttätigkeit mit Fuchsesschläue, Augen wie ein Fuchs. Selbstverstümmelung."},{"t":"Schließlich schwere Gewalttätigkeit (Stram.); Verlangen zu schlagen, zu töten. Erotische Manie."},{"t":"Verlangen: Rohkost; Sand; Unverdauliches; rote oder rotorangefarbene Getränke."},{"t":"Abneigung: Brot; Fleisch."},{"t":"Agg.: Berührung; Gehen; Kälte; Lärm; periodisch, jährlich."},{"t":"Amel.: Reiben; Schwitzen; Musik; Tanzen."}],"rem":1,"orig":"Tarentula hispanica"},{"label":"Taxus baccata","short":"Taxus baccata","group":"Arzneimittellehre","paras":[{"t":"Taxus boccata, Eibe. Schwere Trigeminusneuralgie ohne spezifische Modalitäten. Speichel heiß und scharf. Leere im Magen, muß häufig essen."},{"t":"Schmerz in Magengrube und um Nabel."},{"t":"Supraorbital- und Schläfenschmerz rechts mit Tränenfluß. Erweiterte Pupillen, Gesicht gedunsen, blaß."},{"t":"Große, flache, juckende Pusteln. Übelriechende Nachtschweiße. Podagra, Erysipel."}],"rem":1,"orig":"Taxus baccata"},{"label":"Tellurium metallicum","short":"Tellurium metallicum","group":"Arzneimittellehre","paras":[{"t":"Tellurium, Tellur. Chronische, scharfe Sekretion aus den Ohren, Fischlakengeruch. Juckreiz im (linken) Gehörgang. Augenlider entzündet, verdickt."},{"t":"Gesichtszuckung; linker Mundwinkel ist nach oben und seitwärts gezogen beim Sprechen."},{"t":"Empfindliche Wirbelsäule, Agg.: Berührung. Schmerz vom 7. Halswirbel zum 5. Brustwirbel. Schmerz des Sakroiliakalgelenks."},{"t":"Ischias rechts, Agg.: Husten, Niesen, Lachen, Pressen zum Stuhlgang, nachts, und Liegen auf schmerzhafter Seite. Sehnenkontraktion in der Kniekehle."},{"t":"Herpes circinatus (Ringflechte). Bartflechte. Jucken der Kopfhaut. Stinkender Fußschweiß. Schweiß mit Knoblauchgeruch."},{"t":"Brennen alter Narben. Taubheit. Langsame Entwicklung der Symptome."},{"t":"Verlangen: Äpfel."},{"t":"Agg.: Berührung; Kälte; Liegen auf betroffenen Körperteilen."}],"rem":1,"orig":"Tellurium metallicum"},{"label":"Terebinthinae oleum","short":"Terebinthinae oleum","group":"Arzneimittellehre","paras":[{"t":"Terebinthina, Terpentin aus Kiefernharz. Zystitis und Pyelonephritis mit Brennen entlang den Harnleitern und rauchfarbenem, schwarzem, blutigem Urin. Schmerz in Nierengegend; Aszites, Ödeme. Strangurie; Hämaturie. Urethritis mit schmerzhaften Erektionen (Canth.). Sediment kaffeesatzartig, wolkig, rauchig, eiweißhaltig, reichlich, dunkel, schmerzlos, Veilchengeruch. Blutungen passiv, schwarz, übelriechend."},{"t":"Stomatitis mit trockener, roter, glänzender Zunge, wie glasiert, brennende Zungenspitze. Belag löst sich bei Exanthemen."},{"t":"Abdomen extrem gebläht, Meteorismus, Agg.: Berührung."},{"t":"Durchfall wässerig, grünlich, schleimig, häufig, reichlich, stinkend, blutig. Brennen in After und Rektum; Ohnmacht und Erschöpfung danach. Würmer, Kitzeln im After, fauliger Atem, Würgen (Cina; Spig.)."},{"t":"Schmerz auf Darmbeinkamm lokalisiert. Intensives Brennen im Uterusgebiet. Metritis. Peritonitis. Beschwerden durch Pessar."},{"t":"Bronchitis mit blutiger Expektoration und unterdrücktem Urin."},{"t":"Purpura. Akne. Erythem; juckender, pustulärer Bläschenausschlag; Urtikaria. Ödeme nach Scharlach. Frostbeulen mit extremem Jucken und pulsierenden Schmerzen. Große Schwäche. Hungrig und durstig, wenn krank. Schmerzhaftigkeit der Muskeln."},{"t":"Agg.: Kälte; Nässe; nachts."}],"rem":1,"orig":"Terebinthinae oleum"},{"label":"Teucrium marum verum","short":"Teucrium marum verum","group":"Arzneimittellehre","paras":[{"t":"Teucrium marum, Katzengamander. Reaktionsmittel. Polypen in Nase, Vagina, Ohren. Fibrome. Erregbar, überempfindlich. Verlangen zu singen. Indolent. Verlangen, sich zu strecken. Nach zuviel Medizin."},{"t":"Chronischer Nasenkatarrh mit klumpiger Absonderung von den vorderen und hinteren Nasenmuscheln. Schnupfen mit Verstopfung der Nasenlöcher. Große, übelriechende Borken und Krusten. Atrophie und Ozaena mit Geruchsverlust. Krabbeln in der Nase mit Tränenfluß und Niesen. Gaumenjucken."},{"t":"Trockener Husten, Kitzeln in Luftröhre, modriger Geschmack im Rachen beim Hochräuspern von Schleim. Reichlicher Auswurf."},{"t":"Unnatürlicher Appetit, Erbrechen großer Mengen dunkelgrüner Massen. Dauernder Schluckauf, begleitet von Rückenschmerzen."},{"t":"Würmer (Askariden); nächtliche Unruhe, Herumwerfen im Bett. Krabbeln im Rektum nach Stuhl. Jucken des Anus und dauernde Reizung abends im Bett."},{"t":"Einwachsende Zehennägel. Brennen in Fingerspitzen."},{"t":"Agg.: Wetterwechsel nach kalt, naß; nachts; die Seite, auf der sie liegt."}],"rem":1,"orig":"Teucrium marum verum"},{"label":"Thallium met. + -act. (old abbr.)","short":"Thallium met. + -act. (old abbr.)","group":"Arzneimittellehre","paras":[{"t":"Thallium metallicum aut aceticum. Endokrine Drüsen, besonders Schilddrüse und Nebennieren betroffen."},{"t":"Entsetzliche, neuralgische, spastische, einschießende Schmerzen bei lokomotorischer Ataxie. Polyneuritis."},{"t":"Haarausfall nach erschöpfenden akuten Krankheiten."},{"t":"Schmerz in Magen und Eingeweiden, wie Elektroschocks."},{"t":"Zittern der Extremitäten. Lähmungsgefühl. Schmerzen wie Elektroschocks."},{"t":"Taubheit von Fingern und Zehen, nach oben ausstrahlend."},{"t":"Lähmung der Beine. Paraplegie. Myelitis. Zyanose der Extremitäten. Ameisenlaufen beginnt in den Fingern, wandert über das Becken, den Damm und die Innenseiten der Oberschenkel zu den Füßen."},{"t":"Trophische Läsionen der Haut."},{"t":"Sehr müde. Nachtschweiß."}],"rem":1,"orig":"Thallium met. + -act. (old abbr.)"},{"label":"Thea chinensis","short":"Thea chinensis","group":"Arzneimittellehre","paras":[{"t":"Teestrauch. Plötzlicher Impuls oder Furcht zu töten (ihr eigenes Kind). Gehörshalluzinationen. Suizidneigung: möchte aus dem Fenster springen. Romantisch. Dichtet. Streitsüchtig. Geschwätzig."},{"t":"Migräne mit Übelkeit, die von einem Punkt ausstrahlt. Beklommenheit, Leere, Schwäche im Epigastrium. Flatulenz und Rumpeln im Bauch."},{"t":"Herzklopfen, kann nicht auf der linken Seite liegen. Präkordialangst und Zusammenschnürungsgefühl."},{"t":"Müde tagsüber, schlaflos nachts. Müdigkeit nach Bier, Wein."},{"t":"Schreckliche Träume von Mord, die aber keine Angst machen. Nervöse Schlaflosigkeit, Herzbeschwerden, Herzklopfen und Dyspepsie alter Teetrinker."},{"t":"Verlangen: saure Speisen."},{"t":"Agg.: Gehen in frischer Luft; nachts; nach dem Essen."},{"t":"Amel.: Wärme; warmes Bett."}],"rem":1,"orig":"Thea chinensis"},{"label":"Theridion curassavicum","short":"Theridion curassavicum","group":"Arzneimittellehre","paras":[{"t":"Theridium curassavicum. Extreme Lärmempfindlichkeit. Schwindel, Agg.: Augenschließen, geringstes Geräusch, Bücken, Bewegung. Labyrinthschwindel, Menière. Übelkeit, Agg.: geringste Bewegung, Schließen der Augen, schnelles Autofahren. Kopfschmerz dumpf, drückend, hinter den Augen, über dem linken Auge, Agg.: Bewegungsbeginn, Hinlegen, geringste Kopfbewegung. Jeder Laut durchdringt und verursacht Schwindel und Übelkeit. Zahnschmerz, Agg.: Geräusche."},{"t":"Chronischer Nasenkatarrh mit dicker, gelber, stinkender Absonderung (Puls.; Thuj.). Seekrankheit."},{"t":"Romantisch; sehr kreativ. Hysterie, nervöse Empfindlichkeit in Pubertät, Schwangerschaft und Klimakterium. Zeit vergeht zu schnell. Fruchtlose Aktivität. Wenig Selbstvertrauen, wenig sexuelles Interesse."},{"t":"Rachitis, Knochenkaries, Nekrose. Schmerzen in allen Knochen, wie gebrochen. Stiche in der linken Brust, nach oben, unter Schulter, bis zum Hals. Empfindlich zwischen den Wirbeln, vermeidet Druck auf Wirbelsäule, sitzt seitlich auf Stuhl, Agg.: Erschütterung."},{"t":"Tuberkulöse Diathese, wenn wohl gewählte Mittel versagen."},{"t":"Verlangen: Orangen; Bananen; Tabak; Wein; saures Obst und Getränke."},{"t":"Agg.: Geräusche; Berührung; Augenschließen; Erschütterung; Fahren."}],"rem":1,"orig":"Theridion curassavicum"},{"label":"Thlaspi bursa pastoris","short":"Thlaspi bursa pastoris","group":"Arzneimittellehre","paras":[{"t":"Thlaspi bursa pastoris, Hirtentäschelkraut. Hämorrhagische und harnsaure Diathese. Beschwerden durch unterdrückte Blutungen oder durch unterdrückte Uteruserkrankung. Blutung aus jeder Körperöffnung, dunkel und klumpig. Kopfschmerz von über den Augen, über den Kopf, zum Nacken. Passives Nasenbluten bei Nasenoperationen."},{"t":"Blutiger Urin und Dysurie; Ziegelmehlsediment. Schmerz im Samenstrang, Agg.: Gehen, Fahren, Erschütterung. Metrorrhagie mit heftigen Krämpfen und uteriner Kolik; bei Chlorose, nach Abort, Wehen, Fehlgeburt; Klimakterium; Uteruskrebs. Menses zu früh; zu reichlich; zu lange, bis zu 15 Tage. Zweiter Tag Kolik, Erbrechen, Blutung mit großen Klumpen. Jede zweite Menstruation sehr reichlich. Wunder Schmerz im Uterus beim Aufstehen. Kaum erholt von Menstruation, beginnt schon die nächste."},{"t":"Leukorrhoe blutig, dunkel, stinkend; vor und nach Menses."},{"t":"Albuminurie in Schwangerschaft. Milchige, wässerige Absonderung aus rechter Brustwarze. Schmerz zwischen den Schulterblättern."},{"t":"Verlangen: Buttermilch."},{"t":"Agg.: Menses; Schwangerschaft; Wehen; Abort; Fahren; Gehen."},{"t":"Amel.: Wärme; Baden; rasche Bewegung."}],"rem":1,"orig":"Thlaspi bursa pastoris"},{"label":"Thuja occidentalis","short":"Thuja occidentalis","group":"Arzneimittellehre","paras":[{"t":"Thuja occidentalis, Abendländischer Lebensbaum. Sykose. Trockenheit: im Herzen; geistig (fixe Ideen, keine Ideale mehr); in der Nase; der Haare (fallen aus). Gelbliche Haut, wächsern, erdig, glänzend, fettiges Gesicht. Wechselhaftigkeit (weniger als Med.; Thuja Fassade, Med. nicht), geschwächte Kinder sykotischer Eltern, zerbrechlich, stärker krank als Med."},{"t":"Fixe Ideen: Gefühl, Beine wie aus Glas, hart und zerbrechlich; etwas lebendiges im Bauch zu haben; zu bestimmter Zeit zu sterben (Agn.; Arg-n.; Acon.); als ginge jemand neben ihm (Med. hinter ihm, Petr. als liege jemand neben ihm im Bett). Mag nicht angefaßt werden."},{"t":"Kopfschmerz linke Stirn / linker Hinterkopf, abwechselnd. Nagelkopfschmerz am Scheitel, Agg.: 3,4 Uhr, sexuelle Exzesse, Überhitzung, Tee. Trigeminusneuralgie, Agg.: 3,4 Uhr."},{"t":"Schwindel beim Schließen der Augen. Folge von Pockenimpfung."},{"t":"Braune Flecken auf Armen und Händen. Ausschlag auf bedeckten Teilen; Schweiß auf unbedeckten Körperteilen. Ausschläge unter Unterlid, symmetrisch. Ophthalmie bei Neugeborenen. Gerstenkörner, Verhärtung, Polypen, Warzen, Kondylome, Fissuren, Myome, Knoten, Ovarialtumor, Drüsenschwellung."},{"t":"Obstipation mit zurückschlüpfendem Stuhl. Hämorrhoiden, sehr schmerzhaft bei Berührung. Diarrhoe sprudelnd, wie Wasser aus einem Spundloch."},{"t":"Schleimhautabsonderungen aller Art: Nase, Urethra, Ausfluß, Amel.: Absonderung. Prostatavergrößerung; wässerige Prostataabsonderung, Nachtropfen nach Wasserlassen. Hernien. Genitalschweiß riecht nach Honig. Brüchige Nägel, Fußnägel wachsen ein."},{"t":"Rheumatismus, wandernde Schmerzen an kleinen Stellen. Sehnenschmerz beim Strecken. Rheuma infolge unterdrückter GO; nicht bei akuter GO anwenden."},{"t":"Asthma bei Kindern. Schlaflosigkeit beim Liegen auf der linken Seite. Träume vom Fallen."},{"t":"Verlangen: kalte Getränke; Salz."},{"t":"Abneigung: Zwiebeln; Rohkost; frisches Fleisch; Kartoffeln."},{"t":"Agg.: Zwiebeln; Tee; Nässe, Feuchtigkeit; 3-4, 15-16 Uhr; links; Strecken."},{"t":"Amel.: Absonderung; Niesen; Wärme."},{"t":"Als Kind schon das Gefühl, wertlos zu sein, nicht geliebt werden zu können; berechnende Verhaltensweise, um in Gesellschaft integriert zu sein. Zuerst ungeheures Selbstbewußtsein, unfehlbar, lügt, um Recht zu behalten, Fixiertheit. Später Zweifel an allem, Verwirrung; nicht zu überzeugen. Argwohn. Hat direkten Kontakt verloren, kann nicht mehr gradheraus mit Menschen umgehen. Berechnend. Verliert Zärtlichkeit. Bezweifelt seine eigenen Beobachtungen. Gefühle verhärtet; geistiger Verfall. Läßt beim Sprechen Worte aus, beendet Satz nicht. Träge und vergeßlich, niedergeschlagen, verzweifelt, unzufrieden. Kalt, berechnend; Geist fixiert auf bestimmte Ideen. Rückzug. Spürt Feindseligkeit, will nicht manipuliert werden, manipuliert aber andere. Später Schuldgefühl."},{"t":"Sexuell: erst viel Vergnügen; keine echte Zuneigung, Promiskuität. Leicht erregbar, dann gleichgültig. Später Schuldgefühle, Angst um Seelenheil."}],"rem":1,"orig":"Thuja occidentalis"},{"label":"Thyreoidinum","short":"Thyreoidinum","group":"Arzneimittellehre","paras":[{"t":"Thyreoidinum. Unterfunktion. Retardiertes Wachstum und Entwicklung. Müde, Verlangen, sich hinzulegen. Adipositas. Myxödem und Kretinismus. Akromegalie. Langsam heilende Frakturen. Tumoren."},{"t":"Zorn wegen Kleinigkeiten, Agg.: Widerspruch. Stupor, abwechselnd mit Traurigkeit. Verfolgungswahn."},{"t":"Dauerhafter Stirnkopfschmerz. Haarausfall. Exophthalmischer Kropf. Sehstörungen mit Zentralskotom. Schwangerschaftserbrechen. Enuresis nocturna. Reichlicher Urin mit Veilchengeruch; Albuminurie und Glykosurie. Kryptorchismus. Uterusfibrom. Fibrom der Brust."},{"t":"Zusammenschnürungsgefühl der Brust. Tachykardie. Herzklopfen, Agg.: geringste Anstrengung. Rheumatismus-Adipositas. Psoriasis-Adipositas. Drüsenverhärtung. Ichthyosis. Braune Schwellungen der Haut."},{"t":"Verlangen: Süßigkeiten; kaltes Wasser."},{"t":"Agg.: Anstrengung; Kälte; Bücken."}],"rem":1,"orig":"Thyreoidinum"},{"label":"Tilia europaea","short":"Tilia europaea","group":"Arzneimittellehre","paras":[{"t":"Tilia europaea, Linde. Neuralgischer Kopfschmerz, erst rechts, dann links, mit Schleier vor den Augen. Verwirrung mit Trübsehen. Binokulares Sehen gestört."},{"t":"Puerperale Metritis. Sehr wundes Gefühl um den Uterus, Nachuntendrängen mit heißem Schweiß, der nicht erleichtert. Viel schleimiger Weißfluß beim Gehen (Bov.; Carb-an.; Graph.). Wundheit und Röte der äußeren Genitalien (Thuj.; Sulph.). Beckenentzündung. Tympanie."},{"t":"Urtikaria. Heftiger Juckreiz und Brennen wie Feuer nach Kratzen. Kleiner, roter, juckender Pickelausschlag."},{"t":"Schweiß warm und reichlich, sogleich nach dem Einschlafen. Schweiß nimmt mit rheumatischen Schmerzen zu. Wundheits- und Schwächegefühl der Muskeln."},{"t":"Agg.: Bettwärme; Schwitzen; nach Schlaf; Luftzug."},{"t":"Amel.: kaltes Zimmer; Bewegung; frische Luft."}],"rem":1,"orig":"Tilia europaea"},{"label":"Trillium pendulum","short":"Trillium pendulum","group":"Arzneimittellehre","paras":[{"t":"Trillium pendulum, Amerikanische Waldlilie. Blutungen reichlich, aktiv, passiv, hellrot; aus Nase, Lungen, Nieren und Uterus (Ip.; Mill.). Blutung nach Zahnextraktion."},{"t":"Menorrhagie durch Überanstrengung, Überheben; mit Gefühl, als ob Hüften und Kreuz (Sakroiliakalgelenke) auseinanderfielen; Verlangen, sie fest zusammenzubinden; als wären die Beckenknochen gebrochen (Aesc.), mit Blutung."},{"t":"Menses reichlich, alle zwei Wochen, eine Woche oder länger dauernd"},{"t":"(Calc-p.), nach Überanstrengung, nach zu langer Fahrt."},{"t":"Drohender Abort mit Blutschwall bei jeder Bewegung."},{"t":"Uterusblutung mit Ohnmacht. Klimakterische Uterusblutung mit Erschöpfung, Schwindel, Trübsehen, Herzklopfen, Verstopfungsgefühl und Ohrgeräuschen (Form.) und schmerzhaftem Schwächegefühl im Magen."},{"t":"Klimakterium mit Schwachsichtigkeit, ängstlichem Aussehen; blaß, schwach, Blutung alle zwei Wochen."},{"t":"Chronische, schmerzlose, blutige Diarrhoe."},{"t":"Agg.: Bewegung; Klimakterium; Überanstrengung."},{"t":"Amel.: frische Luft; festes Einbinden."}],"rem":1,"orig":"Trillium pendulum"},{"label":"Tuberculinum bovinum kent","short":"Tuberculinum bovinum kent","group":"Arzneimittellehre","paras":[{"t":"Nosode aus tuberkulösem Abszeß. Familienanamnese, Impfung. Ständiger Symptomwechsel; beginnen plötzlich und hören plötzlich auf. Infektlabilität. Schwäche und Abmagerung bei gutem Essen."},{"t":"Nachtschweiß. Zähneknirschen. Nächtlicher Hunger. Periodizität."},{"t":"Kopfschmerz alle 7/14 Tage, als ob Kopf mit Stahlband gequetscht würde; oberhalb rechtes Auge zum Hinterkopf."},{"t":"Schulmädchenkopfschmerz, Agg.: Lernen, Naharbeit, wenn Brille nicht hilft."},{"t":"Meningitis akut mit drohendem Erguß, erwacht erschreckt und schreiend aus dem Schlaf."},{"t":"Furcht/Allergie vor Hunden und Katzen."},{"t":"Haare auf dem Rücken, kahle Stellen im Bart. Blaue Skleren. Perforiertes Trommelfell. Furunkel in der Nase, grüner, stinkender Eiter. Vergrößerte Adenoide. Häufig Bronchitis, Pneumonie, Asthma. Oberflächlicher chronischer Husten mit Abmagerung. Erstickungsgefühl."},{"t":"Diarrhoe frühmorgens, imperativ; braun, stinkend, große Schwäche."},{"t":"Dysmenorrhoe; Schmerz nimmt mit dem Fluß zu. Gutartige Mammatumoren. Chronische Ekzeme, knötchenförmig, ganzer Körper; Juckreiz, Agg.: Ausziehen, Baden; enorme Mengen weißer Schuppen; nässend hinter den Ohren, im Haar, in Hautfalten, schmerzhaft und wund; feuerrote Haut."},{"t":"Abmagerung mit gutem Appetit. Rheumatische Beschwerden wie Rhus-t."},{"t":"Verlangen: Fett; Schweinefleisch; Pikant; Salami; Geräuchertes; Süß; Salz; kalte Milch."},{"t":"Abneigung: Fleisch."},{"t":"Agg.: am Meer; naßkaltes Wetter; vor Gewitter; abends."},{"t":"Amel.: trockenes Klima; frische Gebirgsluft im Nadelwald; Wärme."},{"t":"Kerze, an beiden Enden gleichzeitig angezündet. Intensiv leben, denn das Leben ist kurz. Abmagerung, Infektneigung."},{"t":"Kinder: \"Mein Kind ist schrecklich\", schwierig, eigensinnig (Calc-p.; Cham.), schnippisch, bockig. Rituelles Verhalten: Dinge müssen in bestimmter Reihenfolge gemacht werden. Zerstörungswut, absichtlich bösartig, möchte Sachen zerbrechen; produziert Wutanfall, um Pläne der anderen zu durchkreuzen. Tut genau, was verboten wurde; Qual für die Eltern, können Familie zerstören."},{"t":"Erwachsene egoistisch; immer auf der Suche nach Befriedigung. Alles wird ausprobiert und konsumiert. Romantisch, würde für Emotionen alles geben; reizbar und unzufrieden, tiefes Unerfülltsein. Playboy; Benehmen unberechenbar, fein und sanft, dann bösartig und zerstörerisch;"},{"t":"Zusammenbruch mit ständiger Müdigkeit, Schwäche."},{"t":"Reist viel und gerne; zieht oft um, pathologisch dazu getrieben, haßt Routine. Aussehen schmal, schnell, muskulös (Sulph.; Phos.; Nux-v.)."},{"t":"Tief im Inneren \"Gefühl von Zerstörung und Tod\". Pessimist, glaubt alles sei vergebens. Sex kurz und stürmisch, starkes Verlangen."}],"rem":1,"orig":"Tuberculinum bovinum kent"},{"label":"Urtica urens","short":"Urtica urens","group":"Arzneimittellehre","paras":[{"t":"Urtica urens, Kleine Brennessel. Rheumatismus abwechselnd oder zusammen mit Urtikaria. Urtikaria,"},{"t":"Agg.: Baden, Wasser; Muschelvergiftung, Amel.: Reiben."},{"t":"Schwindel, Kopfschmerz mit Milzschmerz. Erbrechen von unterdrückter Nesselsucht. Brennende Hitze mit Ameisenlaufen. Urticaria nodosa (Bov.). Röte und Hitze betroffener Teile mit Juckreiz und Schwellung, auch tieferer Gewebe."},{"t":"Verbrennungen, Verbrühungen, Windpocken. Heftiger Juckreiz."},{"t":"Herpes lab. mit Hitze und Juckreiz. Jucken und Stechen im Skrotum."},{"t":"Juckreiz des Anus von Würmern. Pruritus vulvae."},{"t":"Milchversiegen bei stillenden Müttern."},{"t":"Ausschläge jährlich, verschwinden beim Liegen, kehren beim Aufstehen zurück."},{"t":"Gicht und harnsaure Diathese."},{"t":"Allergische Reaktionen auf Insektenstiche, Katzen- und Hundebisse."}],"rem":1,"orig":"Urtica urens"},{"label":"Ustilago maydis","short":"Ustilago maydis","group":"Arzneimittellehre","paras":[{"t":"Ustilago maydis, Sporen des Brandpilzes vom Beulenbrand, Maisbrand."},{"t":"Knotiges Gefühl innerlich. Blut klumpig, bildet lange, schwarze Fäden. Zervix schwammig, leicht blutend, mehr in Schwangerschaft als im Klimakterium, verursachen braune Blutstreifen in der Wäsche, Krebsverdacht. Verlust von Haar und Nägeln."},{"t":"Fibrome im Uterus. Menorrhagie im Klimakterium; reichliche Menses nach Abort; Postpartumblutung; reichliche Lochien."},{"t":"Andauernde Blutung zwischen den Menses. Nachuntendrängende Schmerzen beim Stillen. Ovarien brennen, schmerzhaft geschwollen."},{"t":"Zügellose Masturbation bei Männern. Ergüsse mit unwiderstehlichem Drang zur Masturbation. Amouröse Träume. Dumpfer Schmerz in Lendengegend mit großer Niedergeschlagenheit und Erregbarkeit."},{"t":"Furunkel, Haut trocken, Ekzem, Sonnenbrand, Psoriasis."},{"t":"Gefühl von kochendem Wasser den Rücken hinunter."},{"t":"Agg.: Klimakterium; Berührung; Bewegung."},{"t":"Uva ursi"},{"t":"ursi, Bärentraube. Chronische Blasenreizung. Entzündung bei Steinträgern."},{"t":"Brennen nach Absonderung von schleimigem Urin. Pyelonephritis."},{"t":"Heftiger Drang mit heftigen Blasenspasmen, brennender und reißender Schmerz. Urin enthält Blut, Eiter und viel zähen Schleim mit Klumpen in großen Massen. Unwillkürlich; grüner Urin. Dysurie."},{"t":"Urtikaria ohne Jucken."}],"rem":1,"orig":"Ustilago maydis"},{"label":"Valeriana officinalis","short":"Valeriana officinalis","group":"Arzneimittellehre","paras":[{"t":"Valeriana off., Großer Baldrian. Extreme der Gefühle, Stimmungsschwankungen. Hysterische Spasmen. Überempfindlichkeit aller Sinne (Cham.; Nux-v.). Fühlt sich leicht, wie in der Luft schwebend. Halluzinationen nachts. Reizbar. Zittrig."},{"t":"Furcht vor Dunkelheit, vor dem Alleinsein."},{"t":"Gefühl großer Kälte im Kopf; Gefühl, als ob ein Faden im Hals herunterhinge."},{"t":"Ohrenschmerz durch Kälte und Zugluft."},{"t":"Kind erbricht geronnene Milch in großen Klumpen; sobald es gestillt wurde, nachdem die Mutter zornig war. Durchfall mit Milchklumpen und Schreien. Fersenschmerz beim Sitzen. Ischias, Agg.: Strecken, Stehen, wenn Fuß Boden berührt (Bell.), beim Ausruhen von Anstrengung, Amel.: Bewegung. Rheumatische Beschwerden wie Rhus-t. Krämpfe. Dauerndes Zucken."},{"t":"Neuralgie mit unerträglichen Schmerzen."},{"t":"Agg.: Aufregung; Ruhe; Stehen."},{"t":"Amel.: Lagewechsel; Gehen; Reiben."}],"rem":1,"orig":"Valeriana officinalis"},{"label":"Variolinum","short":"Variolinum","group":"Arzneimittellehre","paras":[{"t":"Variolinum, Pockennosode. Ruhelosigkeit. Furcht vor Pocken."},{"t":"Qualvolle Rückenschmerzen ohne spez.@ Modalitäten. Beinschmerzen. Müdigkeit mit Ruhelosigkeit überall. Handgelenkschmerzen, Schmerzen ziehen vom Rücken in den Bauch. Herpesausschläge. Zoster."},{"t":"Agg.: Impfung; Bewegung; Nacht."}],"rem":1,"orig":"Variolinum"},{"label":"Veratrum viride","short":"Veratrum viride","group":"Arzneimittellehre","paras":[{"t":"Veratrum viride, grüne Nieswurz. Blutandrang zur Schädelbasis, zu Brust, Wirbelsäule und Magen. Spasmen, Chorea, Opisthotonus."},{"t":"Puls unregelmäßig, intermittierend (Dig.; Tab.), labile Hypertonie."},{"t":"Akuter Rheumatismus, hohes Fieber, voller, harter, schneller Puls; starke Schmerzen in Gelenken und Muskeln (Bry.; Sal-ac.), spärlicher, roter Urin. Septische Fieber. Heftiges Delirium."},{"t":"Furcht vor Vergiftung. Mißtrauisch. Streitsüchtig."},{"t":"Migräne oder nervöser Kopfschmerz; Blutandrang durch unterdrückte Menses; heftige Übelkeit, Erbrechen, Schwindel. Sonnenstich, Doppeltsehen, Halbsehen. Apoplexie: Blutandrang zum Gesicht, heißer Kopf, blutunterlaufene Augen, belegte Stimme, langsamer, voller Puls, hart wie Eisen."},{"t":"Weiße oder gelbe Zunge mit rotem Mittelstreifen. Oesophagitis. Schluckauf mit Ösophagusspasmen."},{"t":"Eklampsie und Kindbettfieber mit Konvulsionen und Manie. Schmerz in Nacken und Schultern. Basalmeningitis; zerebrospinale Erkrankungen; mit Spasmen, erweiterten Pupillen, Tetanie, Nackensteifigkeit. Feuchtkalter, klebriger Schweiß."},{"t":"Pulsieren im ganzen Körper, besonders rechter Oberschenkel. Sudeck Syndrom."}],"rem":1,"orig":"Veratrum viride"},{"label":"Veratrum album","short":"Veratrum album","group":"Arzneimittellehre","paras":[{"t":"Veratrum album, weiße Nießwurz. Religiös, selbstgerecht, kritisch und hochmütig. Eine Plage, ständig in Aktion, zwanghaft wiederholend (nicht destruktiv wie Stram.). Hält sich für Christus, auserwählt, die Welt zu retten; Straßenprediger, ist felsenfest von seiner Identität überzeugt."},{"t":"Manisch depressiv, verzweifelt über sein Seelenheil."},{"t":"Dysmenorrhoe junger Mädchen mit Kälte, Schwäche, Schweiß, Erbrechen, Diarrhoe; tiefe Hoffnungslosigkeit, Verzweiflung. Kälte im ganzen Bild."},{"t":"Überaktivität auch körperlich: explosiver Brechdurchfall wie Cholera,"},{"t":"Agg.: geringste Bewegung; extremer Durst auf große Mengen Eiswasser, das aber sofort erbrochen wird; Säfte fließen aus dem Körper. Erschöpft, Kollaps. Eiswasser in den Adern, Leichenkälte der Extremitäten, Gefühl eines Eisklumpens auf dem Scheitel, Kopfhaut kalt, Gesicht blaß, kalt;"},{"t":"Kalter Schweiß auf Stirn, friert; gleichzeitig schwitzt er stärker (Hauptmittel). Kopfschmerz; Erschöpfung; Kolik mit Übelkeit; Manie; Delirium; heftige Entzündungen; Muskelzucken (Hyos.; Agar.); schwere Neuralgien; schwere rheumatische Kopfschmerzen und Extremitätenschmerzen verursachen Manie, Kälte, Schweiß."},{"t":"Verlangen: Eis; saures Obst; Salz; kalte Säfte."},{"t":"Abneigung: warmes Essen und Getränke."},{"t":"Agg.: Erschöpfung; Trinken; kalte Getränke; Menses; Stuhlgang; bei Schmerz."},{"t":"Amel.: Reiben; Liegen in Kopftieflage; heißer, starker Kaffee."},{"t":"Differentialdiagnose: Ars. hat mehr Angst, Ruhelosigkeit, 1-2 Uhr, Schwäche schon nach wenig Durchfall, brennender Schmerz im Rektum nach Durchfall, amel.: warme Anwendungen."},{"t":"Differentialdiagnose: Camph. auch sehr kalt, will aber abgedeckt werden, auch Durchfall bei Eiseskälte."},{"t":"Differentialdiagnose: Cupr. Krämpfe auch während und nach Durchfall, nicht so fröstelig, kleinste Beweg. verursacht Krämpfe."}],"rem":1,"orig":"Veratrum album"},{"label":"Verbascum thapsus","short":"Verbascum thapsus","group":"Arzneimittellehre","paras":[{"t":"Verbascum thapsiforme, Königskerze. Trigeminusneuralgie, hauptsächlich des N. maxillaris. Neuralgische Gesichtsschmerzen, betreffen Jochbein, Kiefergelenk und Ohr (Meny.), links, Agg.: Sprechen, Niesen, geringste Bewegung, Zähnezusammenpressen, Temperaturwechsel; periodisch zur selben Stunde, morgens und nachmittags, jeden Tag. Gefühl von Quetschung mit Zangen."},{"t":"Enuresis, Agg.: nachts, Husten."},{"t":"Katarrhe und Erkältungen mit periodischer Trigeminusneuralgie;"},{"t":"heiserer, bellender Husten."},{"t":"Stimme heiser, wie Trompete, \"Basso profundo\"."},{"t":"Nervöser Husten im Schlaf, ohne aufzuwachen."},{"t":"Steifigkeit und neuralgischer Schmerz im linken Sprunggelenk."},{"t":"Agg.: 9-16 Uhr; zweimal täglich; Luftzug; Temperaturwechsel."}],"rem":1,"orig":"Verbascum thapsus"},{"label":"Viburnum opulus","short":"Viburnum opulus","group":"Arzneimittellehre","paras":[{"t":"Viburnum opulus, Gewöhnlicher Schneeball. Allgemeines Krampfmittel. Schwere, membranöse Dysmenorrhoe mit spastischen Schmerzen im Kreuzbein und bei Menses. Kolikartige Schmerzen in Beckenorganen. Uterusschmerz, strahlt um das Becken aus oder die Oberschenkel hinab. Schmerz in Kreuz- und Schambein mit Schmerz in den vorderen Oberschenkelmuskeln (Xanth.)."},{"t":"Plötzliche Bauchkrämpfe und kolikartige Schmerzen. Druckempfindlich um den Nabel."},{"t":"Schwindel vom zu schnellen Aufstehen. Einseitige Gesichtsröte."},{"t":"Menses spärlich, dauern nur wenige Stunden, zu spät. Häufiger und sehr früher Abort mit krampfartigen Schmerzen."},{"t":"Wundmachender Weißfluß. Schmerzen und Jucken der Genitalien."},{"t":"Kann nicht auf der linken Seite schlafen. Linksseitige Beschwerden."},{"t":"Agg.: Linksliegen; Menses; Kälte; Schneeluft."},{"t":"Amel.: Ruhe; Druck; frische Luft; Reiben."}],"rem":1,"orig":"Viburnum opulus"},{"label":"Vinca minor","short":"Vinca minor","group":"Arzneimittellehre","paras":[{"t":"Vinca minor, Immergrün. Alopecia areata; Haar fällt aus und graues oder weißes Haar kommt nach. Flecken auf der Kopfhaut mit sickernder Feuchtigkeit, die das Haar verfilzt. Fressendes Jucken der Kopfhaut. Kahle Stellen. Weichselzopf. Unwiderstehliches Verlangen zu kratzen."},{"t":"Nasenspitze wird leicht rot. Wunde Stellen in der Nase."},{"t":"Passive Uterusblutung. @Menometrorrhagie im Klimakterium."}],"rem":1,"orig":"Vinca minor"},{"label":"Viola odorata","short":"Viola odorata","group":"Arzneimittellehre","paras":[{"t":"Viola odorata, Märzveilchen. Kombination Ohr, Auge, Nieren. Rheumatische Beschwerden des Deltoideus und in den Karpal- und Metakarpalgelenken (Ulm-c.) der rechten Hand ohne spez.@ Modalitäten."},{"t":"Intellekt kontrolliert Gefühle, Impulse. Abneigung gegen Musik."},{"t":"Brennen der Stirn. Gespannte Kopfhaut; muß die Brauen zusammenziehen. Neigung zu Schmerz direkt über den Augenbrauen. Pulsieren unter Augen und Schläfen. Kopfschmerz quer über der Stirn. Otorrhoe. Ohrleiden mit Schmerzen in den Augäpfeln. Würmer bei Kindern."},{"t":"Enuresis; milchiger Urin."},{"t":"Dyspnoe in Schwangerschaft."},{"t":"Verlangen: Fleisch; Frühstück."},{"t":"Agg.: kalte Luft."}],"rem":1,"orig":"Viola odorata"},{"label":"Viola tricolor","short":"Viola tricolor","group":"Arzneimittellehre","paras":[{"t":"Viola tricolor, Stiefmütterchen. Kinderekzeme, Impetigo, unerträgliches Jucken. Ausschlag besonders an Gesicht und Kopf mit Brennen, Jucken, Agg.: nachts. Große Funkel bei Kindern."},{"t":"Kopfhautekzem mit geschwollenen Drüsen."},{"t":"Folliculitis; feuchte, honigartige Absonderung, verfilzt das Haar."},{"t":"Dicke Borken, die aufreißen und zähen, gelben Eiter absondern."},{"t":"Gesicht heiß und schwitzend nach dem Essen."},{"t":"Verschleimung im Hals verursacht Räuspern, Agg.: im Freien. Schluckbeschwerden."},{"t":"Urin stinkend, riecht wie Katzenurin."},{"t":"Vorhaut geschwollen, Brennen der Eichel, Jucken;"},{"t":"unwillkürlicher Samenerguß beim Stuhlgang."},{"t":"Agg.: Winter; 11 Uhr."}],"rem":1,"orig":"Viola tricolor"},{"label":"Vipera berus","short":"Vipera berus","group":"Arzneimittellehre","paras":[{"t":"Vipera berus, Kreuzotter. Varikose und Phlebitis der Beine mit berstenden Schmerzen, Agg.: Nachuntenhängenlassen, Amel.: Hochlagern."},{"t":"Herzsynchrones Pulsieren in den Extremitäten."},{"t":"Nasenbluten mit Schwindel, Agg.: beim Stillen. Schwellung von Gesicht, Lippen und Zunge, die hervortritt."},{"t":"Schmerz im Epigastrium, Agg.: Druck. Lebervergrößerung, sehr schmerzhaft mit Fieber und Ikterus."},{"t":"Blutungen. Aufsteigende Lähmung, die in den Füßen beginnt. Akute, aufsteigende (Landry) Paralyse. Poliomyelitis. Polyneuropathie."},{"t":"Agg.: Glieder nach unten hängen lassen; Kälte; jährlich; Berührung; Wetterwechsel."},{"t":"Amel.: Hochlagern."}],"rem":1,"orig":"Vipera berus"},{"label":"Viscum album","short":"Viscum album","group":"Arzneimittellehre","paras":[{"t":"Viscum album, Leimmistel. Renale Hypertonie mit Albuminurie. Dyspnoe/Asthma mit Gicht oder Rheumatismus; mit Erstickungsgefühl beim Liegen auf der linken Seite."},{"t":"Chorea durch Schreck. Konvulsionen mit Hitzewelle, die von den Füßen zum Kopf aufsteigt."},{"t":"Gefühl, als ob die Schädeldecke hochgehoben würde. Blaue Ringe um die Augen, Doppeltsehen."},{"t":"Rheumatische Taubheit."},{"t":"Herzklappenerkrankungen mit Hypertrophie und Störung der Sexualsphäre. Herzklopfen während Koitus bei Männern."},{"t":"Plazentaretention (Sec.). Chronische Endometritis. Ovarialgie, besonders links."},{"t":"@Menometrorrhagie, Blut teils flüssig, teils verklumpt."},{"t":"Gefühl, eine Spinne krabbelt über Hand- und Fußrücken."},{"t":"Rheumatische Schmerzen abwechselnd Knie/Sprunggelenk mit Schulter/Ellbogen."},{"t":"Ischias mit Ohrabsonderung."},{"t":"Agg.: Linksliegen; Kälte; Winter; Bewegung; Unterkühlung nach Überhitzung."}],"rem":1,"orig":"Viscum album"},{"label":"Wyethia helenoides","short":"Wyethia helenoides","group":"Arzneimittellehre","paras":[{"t":"Wyethia helenoides. Kopfschmerz mit Blutandrang, Schwindel. Nervös, unruhig, deprimiert. Heufieber mit Juckreiz retronasal, Gaumen, Nase und Rachen."},{"t":"Follikuläre Pharyngitis. Reizungen im Rachen bei Sängern und Rednern."},{"t":"Heiserkeit. Dauerndes Räuspern. Retronasale Trockenheit, keine Erleichterung durch Räuspern. Hals heiß und trocken. Gefühl von Schwellung im Rachen. Epiglottis trocken und brennend. Muß dauernd Speichel schlucken."},{"t":"Trockener, hackender Husten durch Kitzeln an der Epiglottis. Gefühl des Brennens in den Bronchien. Trockenes Asthma."}],"rem":1,"orig":"Wyethia helenoides"},{"label":"Xanthoxylum fraxineum","short":"Xanthoxylum fraxineum","group":"Arzneimittellehre","paras":[{"t":"Xanthoxylon fraxineum, Zahnwehbaum. Nervös, schreckhaft, depressiv."},{"t":"Neuralgische Dysmenorrhoe mit rotem Gesicht und neuralgischem Kopfschmerz; mit Rückenschmerz und Schmerz die Beine hinunter."},{"t":"Menses zu früh und stark, fast schwarz. Endometriose. Ovarialgie mit Schmerz in Lenden und Unterbauch, links, die Beine hinunter ausstrahlend."},{"t":"Migräne mit Übelkeit, Schwindel und Flatulenz. Völlegefühl des Kopfes, Gewicht und Schmerz auf dem Scheitel. Schmerz über den Augen, pulsierender Druck über der Nase, Druck in der Stirn. Ohrenklingen."},{"t":"Verdauungsstörungen vom exzessiven Essen und Trinken. Tympanie, Tenesmus."},{"t":"Ischias, Agg.: heißes Wetter. Lähmung, Hemiplegie links nach Wirbelsäulenschäden. Links Taubheit; Taubheit linker Arm."},{"t":"Neuralgische Schmerzen wie von elektrischem Schlag in allen Gliedern. Nackenschmerz in den Rücken ausstrahlend. Neuralgie der vorderen Unterschenkelnerven."},{"t":"Schlaflosigkeit mit Hinterkopfschmerz. Unerquicklich. Träumt vom Fliegen."},{"t":"Agg.: Schlaf; unterdrückte Menses; nasse Füße."},{"t":"Amel.: Trinken von Eiswasser."}],"rem":1,"orig":"Xanthoxylum fraxineum"},{"label":"Zincum metallicum","short":"Zincum metallicum","group":"Arzneimittellehre","paras":[{"t":"Zincum met., Zink. Steigender Hirndruck; fürchterliches, aggressives, markerschütterndes Kreischen."},{"t":"Kind nach Polioimpfung; liegt ruhelos im Bett, schreit furchterregend, wie das Schreien eines Tieres; dabei ständige Bewegung der Füße, rund um die Uhr, entsetzter Blick. Chorea nach unterdrücktem Ausschlag, durch Schrecken. Tics. Spinale Reizung. Brennen entlang der der Wirbelsäule."},{"t":"Zincum ist Intensität. Nervensystem in totaler Erregung (egal ob Herzanfall oder Pneumonie). Geräuschempfindlich, besonders auf Sprechen. Krämpfe die ganze Nacht; Zuckungen; Vibrieren; Anfälle bis zur Bewußtlosigkeit."},{"t":"Schwacher Abwehrmechanismus, deshalb so erregbar. Krämpfe nach unterdrücktem Hautausschlag. Nervöse Unzufriedenheit; kann Gefühle nicht mehr ausdrücken; Weinen; quält jeden."},{"t":"Haut sieht vertrocknet aus; Gesicht runzelig, fahl, ungesund."},{"t":"Muß Fragen wiederholen (Caust.; Sulph.). Verspricht sich, kommt nicht mehr mit. Anfangs Hirn sehr aktiv; Reizbarkeit, gewaltige Wutausbrüche; später verlangsamt, Stumpfsinn."},{"t":"Abergläubisch. Empfindlich für Magie. Verfolgungswahn."},{"t":"Krämpfe, Zuckungen, Depression infolge unterdrückter Menses, Amel.: abends. Suizidgedanken. Libido sehr stark. Ejaculatio praecox (Hauptmittel Lyc.; Graph.)."},{"t":"Kopfrollen (Hell.). Gesicht abwechselnd blaß und rot. Kopfschmerz Hinterhaupt. Konvulsionen beim Zahnen mit blassem, kühlem Gesicht (eventuell Hinterkopf heiß). Augenrollen; Strabismus; Zähneknirschen. Blindheit bei Kopfschmerz. Jedesmal Diarrhoe bei Kopfschmerz. Stechen im Augenwinkel, Konjunktivitis bei Menses (Ars.)."},{"t":"Zähne verfallen schnell. Gastritis, Agg.: Wein, Brot, Kaffee, Milch, Kalb. Saures Erbrechen, Leere im Magen 11/12 Uhr (Sulph.); große Gier beim Essen (beginnende Gehirnerkrankung bei Kindern). Erbrechen sofort nach dem Essen; Kolikschmerz, Agg.: Sprechen. Schmerz im linken Ovar."},{"t":"Blasenlähmung, muß sich entspannen, zurücklehnen. Harnabgang beim Husten, Niesen. Verstopfung nach Weingenuß."},{"t":"Husten, Agg.: Süßigkeiten. Bei Hunger Beine schwach und zittrig; Schwäche beim Klavierspielen; Zucken 11 Uhr, Schmerz in den Fersen nach Wein. Wenn Hautausschlag nicht herauskommt (Masern)."},{"t":"Taubheit der Extremitäten beim Liegen im Bett."},{"t":"Abneigung: Fisch; Fleisch; Kalb; Süßigkeiten; warmes Essen."},{"t":"Agg.: Wein; saure Getränke; Zitronen; Brot; Kälte; Kaltbaden; Erschöpfung; Lärm; Berührung; Unterdrückung."},{"t":"Amel.: Bewegung; Menses; herauskommende Absonderungen oder Ausschläge."}],"rem":1,"orig":"Zincum metallicum"},{"label":"Zingiber officinale","short":"Zingiber officinale","group":"Arzneimittellehre","paras":[{"t":"Zingiber officinale, Ingwer. Verdauungsstörungen oder andere Beschwerden von Melonen und schmutzigem Wasser. Kolik, Durchfall, Blähsucht, schneidender Schmerz, Sphinktererschlaffung."},{"t":"Heißer, wunder Anus in Schwangerschaft. Anus rot, entzündet. Hämorrhoiden heiß, schmerzhaft, wund (Aloe). Melonenallergie."},{"t":"Fröhlich bei Atemnot. Heiserkeit. Schmerz unter Kehlkopf. Asthma ohne Angst."},{"t":"Lumbago, Amel.: Lehnen gegen einen Stuhl."},{"t":"Jucken der Vorhaut, schmerzhafte Erektionen. Ergüsse. Gesteigerte Libido."}],"rem":1,"orig":"Zingiber officinale"}]);